import { useState, useEffect } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import { NAV } from '../config/nav'
import { useAuth } from '../context/AuthContext'
import {
  ChevronRight, ChevronDown, User, LogOut,
} from 'lucide-react'

const PATH_TO_GROUP = {}
for (const item of NAV) {
  if (item.children) {
    for (const child of item.children) {
      if (child.id) {
        PATH_TO_GROUP['/' + item.id + '/' + child.id] = item.id
      }
    }
  }
}

export default function Layout({ children }) {
  const navigate = useNavigate()
  const { pathname } = useLocation()
  const { auth, logout } = useAuth()

  const userRole = auth?.user?.role || 'user'
  const userName = auth?.user?.name || 'User'

  const [openGroup, setOpenGroup] = useState(() => PATH_TO_GROUP[pathname] ?? null)

  useEffect(() => {
    const group = PATH_TO_GROUP[pathname]
    if (group) setOpenGroup(group)
  }, [pathname])

  const toggle = id => setOpenGroup(p => (p === id ? null : id))

  const handleLogout = () => {
    logout()
  }

  // Filter nav items based on hiddenRoles
  const visibleNav = NAV.map(item => {
    if (item.hiddenRoles?.includes(userRole)) return null
    if (item.children) {
      const visibleChildren = item.children.filter(
        child => !child.hiddenRoles?.includes(userRole)
      )
      if (item.children.length > 0 && visibleChildren.length === 0) return null
      return { ...item, children: visibleChildren }
    }
    return item
  }).filter(Boolean)

  return (
    <div className="flex h-screen bg-[#f4f6f8] overflow-hidden">

      {/* ── Sidebar ─────────────────────────────── */}
      <aside className="w-[210px] flex-shrink-0 bg-[#1e242e] flex flex-col overflow-y-auto scrollbar-thin">
        {/* Brand */}
        <div className="sticky top-0 px-4 py-[8.9px] bg-[#1e242e] border-b border-white/10 flex-shrink-0">
          <p className="text-white font-extrabold text-[13px] tracking-wide leading-tight">VELSON</p>
          <p className="text-white/40 text-[9px] font-medium tracking-widest uppercase">ERP WEB APPLICATION</p>
        </div>

        <nav className="flex-1 py-1">
          {visibleNav.map(item => {
            const hasChildren = item.children && item.children.length > 0
            const isOpen = openGroup === item.id
            const Icon = item.icon

            if (!hasChildren) {
              const topPath = item.page
                ? '/' + item.id.replace(/-top$/, '')
                : null
              const isActive = topPath && pathname === topPath

              return (
                <button
                  key={item.id}
                  onClick={() => topPath && navigate(topPath)}
                  className={`w-full text-left flex items-center gap-2.5 px-4 py-2.5 text-[12.5px] transition-colors
                    ${isActive ? 'bg-[#0097A7] text-white' : 'text-white/70 hover:bg-white/10 hover:text-white'}`}
                >
                  <Icon size={14} className="flex-shrink-0" />
                  {item.label}
                </button>
              )
            }

            return (
              <div key={item.id}>
                <button
                  onClick={() => toggle(item.id)}
                  className={`w-full text-left flex items-center justify-between px-4 py-2.5 text-[12.5px] transition-colors
                    ${isOpen ? 'bg-[#0097A7] text-white' : 'text-white/70 hover:bg-white/10 hover:text-white'}`}
                >
                  <span className="flex items-center gap-2.5">
                    <Icon size={14} className="flex-shrink-0" />
                    {item.label}
                  </span>
                  {isOpen ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
                </button>

                {isOpen && item.children.map(child => {
                  const childPath = '/' + item.id + '/' + child.id
                  const isChildActive = pathname === childPath

                  return (
                    <button
                      key={child.id + '-' + item.id}
                      onClick={() => navigate(childPath)}
                      className={`w-full text-left flex items-center gap-2 pl-8 pr-3 py-2 text-[12px] border-l-[3px] transition-colors
                        ${isChildActive
                          ? 'border-[#00BCD4] bg-[#0097A7]/25 text-white font-semibold'
                          : 'border-transparent text-white/55 hover:bg-white/8 hover:text-white/90'}`}
                    >
                      <span className="w-1.5 h-1.5 rounded-full bg-current opacity-70 flex-shrink-0" />
                      {child.label}
                    </button>
                  )
                })}
              </div>
            )
          })}
        </nav>
      </aside>

      {/* ── Right panel ─────────────────────────── */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">

        {/* Header */}
        <header className="h-[46px] bg-[#1e242e] flex items-center justify-between px-6 flex-shrink-0 shadow-md z-10">
          <span className="text-white font-bold text-[13px] tracking-wider uppercase select-none">
            VELSON - ERP WEB APPLICATION
          </span>
          <div className="flex items-center gap-3">
            <span className="text-white/75 text-[13px]">
              Hi <span className="font-semibold text-white">{userName}</span> !
            </span>
            <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-[#0097A7]/40 text-[#7dd3fc] tracking-wide">
              {userRole}
            </span>
            <div className="w-8 h-8 bg-[#0097A7] rounded-full flex items-center justify-center">
              <User size={15} className="text-white" />
            </div>
            <button
              onClick={handleLogout}
              title="Logout"
              className="w-8 h-8 bg-red-600/70 hover:bg-red-600 rounded-full flex items-center justify-center transition-colors"
            >
              <LogOut size={14} className="text-white" />
            </button>
          </div>
        </header>

        {/* Page content */}
        <main className="flex-1 overflow-y-auto overflow-x-hidden bg-[#f4f6f8]">
          {children}
        </main>
      </div>
    </div>
  )
}

import { useState, useEffect, useCallback, createContext, useContext } from 'react'
import { AlertTriangle, CheckCircle, Info, X, XCircle } from 'lucide-react'

const ToastContext = createContext(null)

const ICONS = {
  warning: <AlertTriangle size={18} className="text-amber-500 flex-shrink-0" />,
  success: <CheckCircle size={18} className="text-emerald-500 flex-shrink-0" />,
  error: <XCircle size={18} className="text-red-500 flex-shrink-0" />,
  info: <Info size={18} className="text-sky-500 flex-shrink-0" />,
}

const STYLES = {
  warning: 'border-amber-300 bg-amber-50',
  success: 'border-emerald-300 bg-emerald-50',
  error: 'border-red-300 bg-red-50',
  info: 'border-sky-300 bg-sky-50',
}

const PROGRESS = {
  warning: 'bg-amber-400',
  success: 'bg-emerald-400',
  error: 'bg-red-400',
  info: 'bg-sky-400',
}

function ToastItem({ toast, onRemove }) {
  const [exiting, setExiting] = useState(false)

  useEffect(() => {
    const timer = setTimeout(() => {
      setExiting(true)
      setTimeout(() => onRemove(toast.id), 300)
    }, toast.duration || 3500)
    return () => clearTimeout(timer)
  }, [toast, onRemove])

  return (
    <div
      className={`relative flex items-start gap-3 px-4 py-3 rounded-xl border shadow-lg backdrop-blur-sm min-w-[320px] max-w-[420px] transition-all duration-300 ${STYLES[toast.type] || STYLES.info} ${exiting ? 'opacity-0 translate-x-8' : 'opacity-100 translate-x-0'}`}
      style={{ animation: exiting ? 'none' : 'slideIn 0.3s ease-out' }}
    >
      {ICONS[toast.type] || ICONS.info}
      <div className="flex-1 min-w-0 pt-[1px]">
        {toast.title && (
          <p className="text-[12px] font-bold text-slate-800 mb-0.5">{toast.title}</p>
        )}
        <p className="text-[12px] text-slate-600 leading-relaxed">{toast.message}</p>
      </div>
      <button
        onClick={() => { setExiting(true); setTimeout(() => onRemove(toast.id), 300) }}
        className="text-slate-400 hover:text-slate-600 transition-colors flex-shrink-0 mt-0.5"
      >
        <X size={14} />
      </button>
      {/* Progress bar */}
      <div className="absolute bottom-0 left-0 right-0 h-[3px] rounded-b-xl overflow-hidden">
        <div
          className={`h-full ${PROGRESS[toast.type] || PROGRESS.info} rounded-b-xl`}
          style={{ animation: `shrink ${toast.duration || 3500}ms linear forwards` }}
        />
      </div>
    </div>
  )
}

export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([])

  const removeToast = useCallback((id) => {
    setToasts(prev => prev.filter(t => t.id !== id))
  }, [])

  const addToast = useCallback((message, type = 'warning', title = '', duration = 3500) => {
    const id = Date.now() + Math.random()
    setToasts(prev => {
      // 1. Prevent duplicate toast messages from displaying concurrently
      if (prev.some(t => t.message === message)) {
        return prev
      }
      // 2. If there is an active "Network Error" toast, suppress other error toasts
      if (type === 'error' && prev.some(t => t.message === 'Network Error')) {
        return prev
      }
      return [...prev, { id, message, type, title, duration }]
    })
  }, [])

  const toast = useCallback({
    warning: (msg, title) => addToast(msg, 'warning', title || 'Required Field'),
    success: (msg, title) => addToast(msg, 'success', title || 'Success'),
    error: (msg, title) => addToast(msg, 'error', title || 'Error'),
    info: (msg, title) => addToast(msg, 'info', title || 'Info'),
  }, [addToast])

  useEffect(() => {
    const handleEvent = (e) => {
      const { message, type, title, duration } = e.detail || {}
      addToast(message, type, title, duration)
    }
    window.addEventListener('app-toast', handleEvent)
    return () => window.removeEventListener('app-toast', handleEvent)
  }, [addToast])

  return (
    <ToastContext.Provider value={toast}>
      {children}
      {/* Toast container */}
      <div className="fixed top-4 right-4 z-[9999] flex flex-col gap-2.5 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto">
            <ToastItem toast={t} onRemove={removeToast} />
          </div>
        ))}
      </div>
      <style>{`
        @keyframes slideIn {
          from { opacity: 0; transform: translateX(40px); }
          to   { opacity: 1; transform: translateX(0); }
        }
        @keyframes shrink {
          from { width: 100%; }
          to   { width: 0%; }
        }
      `}</style>
    </ToastContext.Provider>
  )
}

export function useToast() {
  const ctx = useContext(ToastContext)
  if (!ctx) throw new Error('useToast must be used within ToastProvider')
  return ctx
}

