// Build { pageKey: urlPath } from NAV — first occurrence wins for duplicate page keys
export const PAGE_TO_PATH = (() => {
  const map = {}
  for (const item of NAV) {
    const hasChildren = item.children && item.children.length > 0
    if (!hasChildren) {
      if (item.page && !map[item.page]) {
        map[item.page] = '/' + item.id.replace(/-top$/, '')
      }
    } else {
      for (const child of item.children) {
        if (child.page && !map[child.page]) {
          map[child.page] = '/' + item.id + '/' + child.id
        }
      }
    }
  }
  return map
})()

import { createContext, useContext, useState, useCallback } from 'react'

const AuthContext = createContext(null)

const STORAGE_KEY = 'velson_auth'

function loadFromStorage() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    return raw ? JSON.parse(raw) : null
  } catch {
    return null
  }
}

export function AuthProvider({ children }) {
  const [auth, setAuth] = useState(() => loadFromStorage())

  const login = useCallback((data) => {
    // data: { token, user: { id, name, email, role } }
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data))
    setAuth(data)
  }, [])

  const logout = useCallback(() => {
    localStorage.removeItem(STORAGE_KEY)
    setAuth(null)
  }, [])

  return (
    <AuthContext.Provider value={{ auth, login, logout }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  return useContext(AuthContext)
}

// Returns the Authorization header value for fetch/axios calls
export function authHeader() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return {}
    const { token } = JSON.parse(raw)
    return token ? { Authorization: `Bearer ${token}` } : {}
  } catch {
    return {}
  }
}

import { useState, useCallback, useEffect, createContext, useContext } from 'react'
import { Loader2 } from 'lucide-react'
import { DotmTriangle6 } from '../components/ui/dotm-triangle-6'
import { registerLoader } from '../services/api'

const LoadingContext = createContext(null)

export function LoadingProvider({ children }) {
  const [state, setState] = useState({ visible: false, message: '' })

  const show = useCallback((message = '') => {
    // console.log('LoadingContext: show called with message:', message)
    setState({ visible: true, message })
  }, [])

  const hide = useCallback(() => {
    // console.log('LoadingContext: hide called')
    setState({ visible: false, message: '' })
  }, [])

  // Bridge: wire the axios interceptors in api.js to this React context.
  // show/hide are stable references (useCallback with no deps), so this
  // effect runs once on mount and cleans up on unmount.
  useEffect(() => {
    registerLoader(show, hide)
    return () => registerLoader(null, null)
  }, [show, hide])

  return (
    <LoadingContext.Provider value={{ show, hide }}>
      {children}
      {state.visible && (
        <div
          className="fixed inset-0 flex flex-col items-center justify-center"
          style={{ zIndex: 9998, backgroundColor: 'rgba(0,0,0,0.45)' }}
          aria-live="polite"
          aria-label="Loading"
        >
          <div className="bg-white/95 backdrop-blur-sm rounded-2xl shadow-2xl px-10 py-8 flex flex-col items-center gap-4 min-w-[180px]">
            {/* Old spinner loader: */}
            {/* <Loader2
              size={35}
              className="animate-spin"
              style={{ color: '#0097A7' }}
            /> */}

            <DotmTriangle6
              size={35}
              dotSize={5}
              color="#0097A7"
              bloom={true}
              halo={0.3}
            />
            <p
              className="text-center leading-snug"
              style={{
                fontSize: '13px',
                fontWeight: '600',
                color: '#475569',
                marginTop: '4px',
              }}
            >
              {state.message || 'Loading...'}
            </p>
          </div>
        </div>
      )}
    </LoadingContext.Provider>
  )
}

export function useLoading() {
  const ctx = useContext(LoadingContext)
  if (!ctx) throw new Error('useLoading must be used within LoadingProvider')
  return ctx
}

