      'H': 'w n n n n w w n n',
      'I': 'n n w n n w w n n',
      'J': 'n n n n w w w n n',
      'K': 'w n n n n n n w w',
      'L': 'n n w n n n n w w',
      'M': 'w n w n n n n w n',
      'N': 'n n n n w n n w w',
      'O': 'w n n n w n n w n',
      'P': 'n n w n w n n w n',
      'Q': 'n n n n n n w w w',
      'R': 'w n n n n n w w n',
      'S': 'n n w n n n w w n',
      'T': 'n n n n w n w w n',
      'U': 'w w n n n n n n w',
      'V': 'n w w n n n n n w',
      'W': 'w w w n n n n n n',
      'X': 'n w n n w n n n w',
      'Y': 'w w n n w n n n n',
      'Z': 'n w w n w n n n n',
      '-': 'n w n n n n w n w',
      '.': 'w w n n n n w n n',
      ' ': 'n w w n n n w n n',
      '*': 'n w n n w n w n n',
      '$': 'n w n w n w n n n',
      '/': 'n w n w n n n w n',
      '+': 'n w n n n w n w n',
      '%': 'n n n w n w n w n'
    };

    let x = 0;
    const narrowWidth = 1;
    const wideWidth = 2.5;
    const gap = 1;

    const bars = [];
    for (let i = 0; i < code.length; i++) {
      const char = code[i];
      const pattern = patterns[char] || patterns[' '];
      const elements = pattern.split(' ');

      for (let j = 0; j < 9; j++) {
        const isBar = (j % 2 === 0);
        const isWide = (elements[j] === 'w');
        const w = isWide ? wideWidth : narrowWidth;

        if (isBar) {
          bars.push(`<rect x="${x}" y="0" width="${w}" height="40" fill="black" />`);
        }
        x += w;
      }
      x += gap;
    }

    return `<svg width="100%" height="100%" viewBox="0 0 ${x} 40" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">${bars.join('')}</svg>`;
  };

