              display: flex;
              flex-direction: column;
              justify-content: space-between;
              align-items: center;
              padding: 1.5mm 1mm;
              text-align: center;
              overflow: hidden;
            }
            .header-text {
              font-family: Arial, sans-serif;
              font-size: 5px;
              font-weight: 800;
              text-transform: uppercase;
              letter-spacing: 0.5px;
              color: #000;
              margin: 0;
              line-height: 1;
            }
            .barcode-wrapper {
              width: 32mm;
              height: 11mm;
              display: flex;
              align-items: center;
              justify-content: center;
            }
            .barcode-wrapper svg {
              width: 100% !important;
              height: 100% !important;
            }
            .barcode-text {
              font-family: 'Courier New', Courier, monospace;
              font-size: 6.5px;
              font-weight: bold;
              letter-spacing: 0.5px;
              color: #000;
              margin: 0;
              line-height: 1;
            }
          </style>
        </head>
        <body>
          <div class="label-container">
            <div class="header-text">Velson Service</div>
            <div class="barcode-wrapper">
              ${barcodeHtml}
            </div>
            <div class="barcode-text">${form.serviceJobNo}</div>
          </div>
        </body>
      </html>
    `)
    iframe.contentWindow.document.close()

    // Safely remove the iframe after the print dialog is finished or cancelled
    iframe.contentWindow.onafterprint = () => {
      document.body.removeChild(iframe)
    }

    iframe.contentWindow.focus()
    setTimeout(() => {
      iframe.contentWindow.print()
    }, 200)

    toast.success(`Triggered barcode print flow for Job: ${form.serviceJobNo}`)
  }

  const handleExportExcel = () => {
    if (filteredBookings.length === 0) {
      toast.warning('No bookings data available to export.')
      return
    }

    // Construct real Excel rows
    const data = filteredBookings.map((b, idx) => ({
      'S.No': idx + 1,
      'Booking Date': b.bookingDate,
      'Customer Name': b.customerName,
      'Customer Code': b.customerCode || '—',
      'Vehicle Count': b.customerVehicleCount || 1,
      'Serial No': b.vehicleSerialNo || b.serialNo || '—',
      'Vehicle No': b.vehicleNo || '—',
      'Service Job No': b.serviceJobNo,
      'Model No': b.vehicleModelNo,
      'Sub Type': b.modelSubType,
      'Vehicle Name': b.vehicleName,
      'Status': b.status,
      'Remarks': b.remarks || '',
      'Created By': b.createdBy || '—',
      'Created Date': b.createdAt ? new Date(b.createdAt).toLocaleDateString() : '—'
    }))

    const worksheet = XLSX.utils.json_to_sheet(data)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Bookings')

    // Download as a real binary Excel spreadsheet
    XLSX.writeFile(workbook, `bookings_list_${new Date().toISOString().split('T')[0]}.xlsx`)
    toast.success('Successfully downloaded Bookings Excel spreadsheet!')
  }

  const handlePrintBookingList = () => {
    if (filteredBookings.length === 0) {
      toast.warning('No bookings in search list to print.')
      return
    }

    // Use a hidden iframe to print safely and prevent popup-based browser freezes/crashes
    const iframe = document.createElement('iframe')
    iframe.style.position = 'fixed'
    iframe.style.right = '0'
    iframe.style.bottom = '0'
    iframe.style.width = '0'
    iframe.style.height = '0'
    iframe.style.border = '0'
    document.body.appendChild(iframe)

    iframe.contentWindow.document.write(`
      <html>
        <head>
          <title>Bookings List Report</title>
          <style>
            body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; padding: 30px; color: #333; }
            .header { display: flex; justify-content: space-between; border-bottom: 2px solid #0097A7; padding-bottom: 15px; margin-bottom: 20px; }
            h1 { margin: 0; color: #0097A7; font-size: 24px; text-transform: uppercase; font-weight: 800; }
            p { margin: 3px 0; font-size: 12px; color: #666; }
            table { width: 100%; border-collapse: collapse; margin-top: 15px; }
            th { background: #0097A7; color: white; font-size: 12px; text-transform: uppercase; font-weight: bold; padding: 8px; border: 1px solid #334155; }
            td { padding: 8px; border: 1px solid #e2e8f0; font-size: 12px; }
            .text-center { text-align: center; }
            .status-badge { font-weight: bold; text-transform: uppercase; font-size: 9px; padding: 2px 6px; border-radius: 4px; display: inline-block; }
            .status-Open { background: #ecfdf5; color: #059669; }
            .status-Close { background: #f1f5f9; color: #64748b; }
            .footer { text-align: center; margin-top: 40px; font-size: 12px; color: #94a3b8; border-top: 1px solid #e2e8f0; padding-top: 10px; }
          </style>
        </head>
        <body>
          <div class="header">
            <div>
              <h1>Velson ERP</h1>
              <p>Service Department bookings registry</p>
            </div>
            <div style="text-align: right;">
              <h2 style="margin:0; font-size:16px; color:#475569;">Bookings List</h2>
              <p>Total Records: ${filteredBookings.length}</p>
              <p>Generated: ${new Date().toLocaleString()}</p>
            </div>
          </div>
          <table>
            <thead>
              <tr>
                <th style="width: 5%">S.No</th>
                <th style="width: 10%">Date</th>
                <th style="width: 20%">Customer Name</th>
                <th style="width: 8%">Veh. Count</th>
                <th style="width: 10%">Vehicle No</th>
                <th style="width: 10%">Job No</th>
                <th style="width: 9%">Model No</th>
                <th style="width: 9%">Vehicle Name</th>
                <th style="width: 9%">Status</th>
                <th style="width: 9%">Created By</th>
                <th style="width: 10%">Created Date</th>
              </tr>
            </thead>
            <tbody>
              \${filteredBookings.map((b, idx) => \`
                <tr>
                  <td class="text-center">\${idx + 1}</td>
                  <td class="text-center">\${b.bookingDate}</td>
                  <td><b>\${b.customerName}</b><br/><small style="color:#777;">\${b.customerCode || 'No code'}</small></td>
                  <td class="text-center">\${b.customerVehicleCount || 1}</td>
                  <td class="text-center font-mono">\${b.vehicleNo || '—'}</td>
                  <td class="text-center">\${b.serviceJobNo}</td>
                  <td class="text-center">\${b.vehicleModelNo}</td>
                  <td>\${b.vehicleName}</td>
                  <td class="text-center"><span class="status-badge status-\${b.status}">\${b.status}</span></td>
                  <td class="text-center">\${b.createdBy || '—'}</td>
                  <td class="text-center">\${b.createdAt ? new Date(b.createdAt).toLocaleDateString() : '—'}</td>
                </tr>
              \`).join('')}
            </tbody>
          </table>
          <div class="footer">
            VELSON ERP - System Generated Report - Confidentially Printed
          </div>
        </body>
      </html>
    `)
    iframe.contentWindow.document.close()

    iframe.contentWindow.onafterprint = () => {
      document.body.removeChild(iframe)
    }

    iframe.contentWindow.focus()
    setTimeout(() => {
      iframe.contentWindow.print()
    }, 200)

    toast.success('Successfully loaded Bookings registry print-out.')
  }

  const handleExportPdf = () => {
    if (filteredBookings.length === 0) {
      toast.warning('No bookings to export.')
      return
    }

    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    })

    // Title & Header background banner
    doc.setFillColor(0, 151, 167) // Teal
    doc.rect(0, 0, 297, 25, 'F')

    doc.setTextColor(255, 255, 255)
    doc.setFont('Helvetica', 'bold')
    doc.setFontSize(16)
    doc.text('VELSON ERP - BOOKINGS REGISTRY REPORT', 15, 16)

    doc.setTextColor(100, 116, 139)
    doc.setFont('Helvetica', 'normal')
    doc.setFontSize(9)
    doc.text(`Total Bookings: ${filteredBookings.length}`, 240, 32)
    doc.text(`Generated: ${new Date().toLocaleString()}`, 20, 32)

    // Table Headers
    let startY = 38
    doc.setFillColor(44, 62, 80) // Dark slate
    doc.rect(15, startY, 267, 8, 'F')

    doc.setFontSize(8.5)
    doc.text('S.No', 17, startY + 5.5)
    doc.text('Date', 27, startY + 5.5)
    doc.text('Customer Name', 45, startY + 5.5)
    doc.text('Veh. Count', 95, startY + 5.5)
    doc.text('Vehicle No', 113, startY + 5.5)
    doc.text('Job No', 135, startY + 5.5)
    doc.text('Model No', 163, startY + 5.5)
    doc.text('Vehicle Name', 185, startY + 5.5)
    doc.text('Status', 210, startY + 5.5)
    doc.text('Created By', 228, startY + 5.5)
    doc.text('Created Date', 252, startY + 5.5)

    let currentY = startY + 8
    doc.setFont('Helvetica', 'normal')
    doc.setFontSize(8)

    filteredBookings.forEach((b, idx) => {
      // Alternating row colors
      if (idx % 2 === 1) {
        doc.setFillColor(248, 250, 252)
        doc.rect(15, currentY, 267, 7, 'F')
      }

      doc.setTextColor(51, 65, 85)
      doc.text(String(idx + 1), 17, currentY + 4.5)

      doc.setTextColor(100, 116, 139)
      doc.setFont('Helvetica', 'normal')
      doc.text(b.bookingDate, 27, currentY + 4.5)

      doc.setTextColor(15, 23, 42)
      doc.setFont('Helvetica', 'bold')
      const truncatedCustomer = b.customerName.length > 22 ? b.customerName.substring(0, 22) + '...' : b.customerName
      doc.text(truncatedCustomer, 45, currentY + 4.5)

      doc.setTextColor(51, 65, 85)
      doc.setFont('Helvetica', 'normal')
      doc.text(String(b.customerVehicleCount || 1), 95, currentY + 4.5)
      doc.text(b.vehicleNo || '—', 113, currentY + 4.5)
      doc.text(b.serviceJobNo, 135, currentY + 4.5)
      doc.text(b.vehicleModelNo, 163, currentY + 4.5)
      doc.text(b.vehicleName, 185, currentY + 4.5)

      if (b.status === 'Open') {
        doc.setTextColor(5, 150, 105)
      } else if (b.status === 'Close') {
        doc.setTextColor(100, 116, 139)
      } else {
        doc.setTextColor(37, 99, 235)
      }
      doc.setFont('Helvetica', 'bold')
      doc.text(b.status || '—', 210, currentY + 4.5)

      doc.setTextColor(51, 65, 85)
      doc.setFont('Helvetica', 'normal')
      doc.text(b.createdBy || '—', 228, currentY + 4.5)
      doc.text(b.createdAt ? new Date(b.createdAt).toLocaleDateString() : '—', 252, currentY + 4.5)

      doc.setDrawColor(241, 245, 249)
      doc.line(15, currentY + 7, 282, currentY + 7)

      currentY += 7

      if (currentY > 185) {
        doc.addPage()
        doc.setFillColor(44, 62, 80)
        doc.rect(15, 10, 267, 8, 'F')
        doc.setTextColor(255, 255, 255)
        doc.setFont('Helvetica', 'bold')
        doc.text('S.No', 17, 15.5)
        doc.text('Date', 27, 15.5)
        doc.text('Customer Name', 45, 15.5)
        doc.text('Veh. Count', 95, 15.5)
        doc.text('Vehicle No', 113, 15.5)
        doc.text('Job No', 135, 15.5)
        doc.text('Model No', 163, 15.5)
        doc.text('Vehicle Name', 185, 15.5)
        doc.text('Status', 210, 15.5)
        doc.text('Created By', 228, 15.5)
        doc.text('Created Date', 252, 15.5)
        currentY = 18
        doc.setFont('Helvetica', 'normal')
        doc.setFontSize(8)
      }
    })

    doc.save(`bookings_list_${new Date().toISOString().split('T')[0]}.pdf`)
    toast.success('Successfully downloaded Bookings PDF registry!')
  }

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden bg-[#f4f6f8] min-h-full pb-6">
      {/* Breadcrumb matching Vehicle Master (No Dashboard >) */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        <span className="hover:text-[#0097A7] cursor-pointer">Service</span>
        <ChevronRight className="w-3 h-3 text-slate-400" />
        <span className="text-[#0097A7] font-semibold">Booking Entry new</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        {/* Solid teal banner header matching legacy screenshots */}
        <div className="flex items-center justify-between bg-[#0097A7] text-white px-4 py-2.5 rounded-t-xl">
          <span className="font-bold text-[13px] uppercase tracking-wider">
            {editingId !== null ? 'Edit - Booking Entry Details' : 'Create - Booking Entry Details'}
          </span>
          <div className="flex items-center gap-2">
            <button
              onClick={handlePrintBarcode}
              className="bg-[#007a87] hover:bg-[#006873] border border-white/20 text-[12px] px-3 py-1 rounded transition-colors font-bold uppercase tracking-wider flex items-center gap-1"
            >
              Print Barcode
            </button>
            {/* <button
              onClick={handleExportExcel}
              className="bg-[#007a87] hover:bg-[#006873] border border-white/20 text-[12px] px-3 py-1 rounded transition-colors font-bold uppercase tracking-wider flex items-center gap-1"
            >
              Excel
            </button> */}
            <button
              onClick={() => window.history.back()}
              className="bg-[#007a87] hover:bg-[#006873] border border-white/20 text-[12px] px-3 py-1 rounded transition-colors font-bold uppercase tracking-wider"
            >
              Close
            </button>
          </div>
        </div>

        <div className="p-4">
          {/* Highly compact form fields */}
          <div className="grid grid-cols-12 gap-x-8 gap-y-2.5 mb-5 max-w-7xl mx-auto">

            {/* Left Column Fields */}
            <div className="col-span-6 space-y-2.5">
              {/* Row 1: Booking ID & Booking Date */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label>Booking ID :</Label>
                </div>
                <div className="col-span-3">
                  <Input value={form.bookingId} readOnly className="!font-bold text-[#0097A7] text-center" />
                </div>
                <div className="col-span-2 text-right pr-0.5">
                  <Label>Date :</Label>
                </div>
                <div className="col-span-3">
                  <Input type="date" value={form.bookingDate} readOnly={true} />
                </div>
              </div>
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label required>Customer Name :</Label>
                </div>
                <div className="col-span-8">
                  <Combobox
                    options={customers.map(c => c.customerName)}
                    placeholder="Search Customer..."
                    value={form.customerName}
                    onChange={handleCustomerChange}
                    readOnly={!isFormEditable}
                  />
                </div>
              </div>


              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label>Customer Code :</Label>
                </div>
                <div className="col-span-8">
                  <Input
                    value={form.customerCode}
                    readOnly
                    className="!font-bold !text-[#0097A7] bg-slate-50"
                    placeholder="Customer Code"
                  />
                </div>
              </div>
              {/* Row 2: Customer Name */}
              {/* Row 3: Customer Vehicle Count */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label>Customer Vehicle Count :</Label>
                </div>
                <div className="col-span-2">
                  <Input type="number" value={form.customerVehicleCount} readOnly className="!font-bold text-slate-600 bg-slate-50" placeholder="Customer Vehicle Count" />
                </div>

                {/* <div className="grid grid-cols-12 gap-2 items-center"> */}
                <div className="col-span-4 text-right pl-2">
                  <Label>Choose Vehicle Count :</Label>
                </div>
                <div className="col-span-2">
                  <Select
                    options={chooseOptions}
                    placeholder="Choose Option..."
                    value={form.chooseOption || ''}
                    onChange={e => handleChooseOptionChange(e.target.value)}
                    disabled={!isFormEditable}
                  />
                  {/* </div> */}
                </div>
              </div>


              {/* Row 6: Serial No (Manual field) */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label>Serial No :</Label>
                </div>
                <div className="col-span-8">
                  <Input value={form.serialNo} onChange={u('serialNo')} placeholder="Serial No" readOnly={!isFormEditable} className='!text-[#0097A7] font-bold' />
                </div>
              </div>

              {/* Row 7: Vehicle No */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label>Vehicle No :</Label>
                </div>
                <div className="col-span-8">
                  <Input value={form.vehicleNo} onChange={u('vehicleNo')} placeholder="Vehicle No" readOnly={isVehicleNoReadOnly || !isFormEditable} />
                </div>
              </div>
            </div>

            {/* Right Column Fields */}
            <div className="col-span-6 space-y-2.5 border-l border-slate-100 pl-6">
              {/* Row 1: Service Job No */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label>Service Job No :</Label>
                </div>
                <div className="col-span-8">
                  <Select
                    options={jobNoOptions}
                    placeholder="Select Service Job No..."
                    value={form.serviceJobNo}
                    className='!text-[#0097A7] font-bold'
                    onChange={e => handleServiceJobNoChange(e.target.value)}
                    disabled={!isFormEditable && editingId !== null}
                  />
                </div>
              </div>

              {/* Row 2: Vehicle Model No */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label required>Vehicle Model No :</Label>
                </div>
                <div className="col-span-8">
                  <Input value={form.vehicleModelNo} readOnly className="!font-bold text-slate-600 bg-slate-50" placeholder="Vehicle Model No" />
                </div>
              </div>

              {/* Row 3: Model Sub Type */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label required>Model Subtype :</Label>
                </div>
                <div className="col-span-8">
                  <Input value={form.modelSubType} readOnly className="!font-bold text-slate-600 bg-slate-50" placeholder="Model Subtype" />
                </div>
              </div>

              {/* Row 4: Vehicle Name */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label required>Vehicle Name :</Label>
                </div>
                <div className="col-span-8">
                  <Input value={form.vehicleName} readOnly className="!font-bold text-slate-600 bg-slate-50" placeholder="Vehicle Name" />
                </div>
              </div>

              {/* Row 5: Status Dropdown */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label>Status :</Label>
                </div>
                <div className="col-span-8">
                  <Select
                    options={statuses}
                    value={form.status}
                    onChange={u('status')}
                    disabled={!isFormEditable}
                  />
                </div>
              </div>

              {/* Row 5.5: Temp Status Radio Buttons */}
              <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-4 text-left pr-1">
                  <Label>Temp Status :</Label>
                </div>
                <div className="col-span-8 flex items-center gap-6">
                  <label className={`inline-flex items-center text-[13px] text-slate-700 font-semibold cursor-pointer ${!isFormEditable ? 'opacity-60 cursor-not-allowed' : ''}`}>
                    <input
                      type="radio"
                      name="tempStatus"
                      value="Open"
                      checked={form.tempStatus === 'Open'}
                      onChange={() => setForm(f => ({ ...f, tempStatus: 'Open' }))}
                      disabled={!isFormEditable}
                      className="mr-2 h-4 w-4 text-[#0097A7] border-slate-300 focus:ring-[#0097A7] cursor-pointer"
                    />
                    Open
                  </label>
                  <label className={`inline-flex items-center text-[13px] text-slate-700 font-semibold cursor-pointer ${!isFormEditable ? 'opacity-60 cursor-not-allowed' : ''}`}>
                    <input
                      type="radio"
                      name="tempStatus"
                      value="Close"
                      checked={form.tempStatus === 'Close'}
                      onChange={() => setForm(f => ({ ...f, tempStatus: 'Close' }))}
                      disabled={!isFormEditable}
                      className="mr-2 h-4 w-4 text-[#0097A7] border-slate-300 focus:ring-[#0097A7] cursor-pointer"
                    />
                    Close
                  </label>
                </div>
              </div>

              {/* Row 6: Remarks */}
              <div className="grid grid-cols-12 gap-2 items-start">
                <div className="col-span-4 text-left pr-1 pt-1">
                  <Label>Remarks :</Label>
                </div>
                <div className="col-span-8">
                  <textarea
                    value={form.remarks}
                    onChange={u('remarks')}
                    placeholder="Enter Remarks here..."
                    disabled={!isFormEditable}
                    className={`w-full h-[50px] px-2.5 py-1 text-[12px] border border-slate-300 rounded bg-white text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] transition-all hover:border-slate-400 resize-none ${!isFormEditable ? 'bg-slate-50 cursor-not-allowed text-slate-500 font-bold' : ''}`}
                  />
                </div>
              </div>

            </div>
          </div>

          {/* Compact Action Toolbar containing only form action operations */}
          <div className="flex flex-wrap items-center justify-between border border-slate-200 py-1.5 mb-4 bg-slate-50/50 px-3 rounded-lg max-w-7xl mx-auto shadow-sm gap-2">
            <div className="flex items-center gap-2">
              <input
                type="text"
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                placeholder="Search Booking..."
                className="px-2.5 py-1 text-[13px] h-[32px] border border-slate-300 rounded w-60 bg-white text-slate-800 focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7]"
              />
              <button
                onClick={handleSearch}
                className="flex items-center gap-1 px-3 py-1 bg-[#0097A7] hover:bg-[#007a87] text-white text-[12px] font-bold rounded shadow-sm h-[28px] transition-all active:scale-95"
              >
                <Search size={12} /> Search
              </button>
              {/* <button
                onClick={() => { setSearchQuery(''); setFilteredBookings(bookings); }}
                className="text-slate-400 hover:text-[#0097A7] text-[12px] font-bold uppercase tracking-wider ml-1"
              >
                Display All
              </button> */}
            </div>

            <div className="flex items-center gap-1.5 flex-wrap">
              <button
                onClick={handleSave}
                className="flex items-center gap-1 px-3 py-1 bg-[#27ae60] hover:bg-[#229954] text-white text-[12px] font-bold rounded shadow-sm h-[28px] transition-all active:scale-95 whitespace-nowrap"
              >
                <Save size={12} /> {editingId !== null ? 'Update' : 'Create'}
              </button>
              <button
                onClick={handleEditClick}
                className="flex items-center gap-1 px-3 py-1 bg-white hover:bg-slate-50 border border-slate-200 text-slate-600 text-[12px] font-bold rounded shadow-sm h-[28px] transition-all active:scale-95 whitespace-nowrap"
              >
                <Edit size={12} className="text-[#0097A7]" /> Edit
              </button>
              <button
                onClick={() => {
                  const idToDelete = editingId !== null ? editingId : selectedRow?.id;
                  if (idToDelete) {
                    handleDelete(idToDelete);
                  } else {
                    toast.warning('Please select/edit a record to delete.');
                  }
                }}
                className="flex items-center gap-1 px-3 py-1 bg-rose-600 hover:bg-rose-700 text-white text-[12px] font-bold rounded shadow-sm h-[28px] transition-all active:scale-95 whitespace-nowrap"
              >
                <Trash2 size={12} /> Delete
              </button>
              <button
                onClick={handleClear}
                className="flex items-center gap-1 px-3 py-1 bg-white hover:bg-slate-50 border border-slate-200 text-slate-600 text-[12px] font-bold rounded shadow-sm h-[28px] transition-all active:scale-95 whitespace-nowrap"
              >
                <RotateCcw size={12} /> Clear
              </button>
            </div>
          </div>

          {/* Advanced Filter Panel */}
          {showFilterPanel && (
            <div className="max-w-7xl mx-auto mb-4 p-4 bg-slate-50 border border-slate-200 rounded-lg shadow-inner grid grid-cols-12 gap-4 items-end transition-all duration-300">
              <div className="col-span-3">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Filter by Customer</label>
                <select
                  value={filterCustomer}
                  onChange={e => setFilterCustomer(e.target.value)}
                  className="w-full px-2 py-1 text-[13px] h-[32px] border border-slate-300 rounded bg-white text-slate-700 focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] transition-all"
                >
                  <option value="">All Customers</option>
                  {uniqueCustomerNames.map(name => (
                    <option key={name} value={name}>{name}</option>
                  ))}
                </select>
              </div>

              <div className="col-span-3">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Filter by Booking Date</label>
                <input
                  type="date"
                  value={filterBookingDate}
                  onChange={e => setFilterBookingDate(e.target.value)}
                  className="w-full px-2.5 py-1 text-[13px] h-[32px] border border-slate-300 rounded bg-white text-slate-800 focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] transition-all"
                />
              </div>

              <div className="col-span-2">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Filter by Status</label>
                <select
                  value={filterStatus}
                  onChange={e => setFilterStatus(e.target.value)}
                  className="w-full px-2 py-1 text-[13px] h-[32px] border border-slate-300 rounded bg-white text-slate-700 focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] transition-all"
                >
                  <option value="">All Statuses</option>
                  {statuses.map(st => (
                    <option key={st} value={st}>{st}</option>
                  ))}
                </select>
              </div>

              <div className="col-span-2">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Filter by Vehicle Model no</label>
                <select
                  value={filterModel}
                  onChange={e => setFilterModel(e.target.value)}
                  className="w-full px-2 py-1 text-[13px] h-[32px] border border-slate-300 rounded bg-white text-slate-700 focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] transition-all"
                >
                  <option value="">All Models</option>
                  {uniqueModels.map(md => (
                    <option key={md} value={md}>{md}</option>
                  ))}
                </select>
              </div>

              <div className="col-span-2">
                <button
                  onClick={() => {
                    setFilterCustomer('')
                    setFilterBookingDate('')
                    setFilterStatus('')
                    setFilterModel('')
                  }}
                  className="w-full h-[32px] bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold text-[12px] uppercase rounded transition-all active:scale-95 flex items-center justify-center gap-1"
                >
                  <RotateCcw size={12} /> Reset
                </button>
              </div>
            </div>
          )}

          {/* Solid sub-banner for Booking list */}
          <div className="max-w-7xl mx-auto bg-[#0097A7] text-white px-5 py-2 rounded-t-lg font-bold text-xs uppercase tracking-wider shadow-sm flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">

            <div>
              <h3>  Bookings List</h3>
            </div>
            <div className="flex items-center justify-end gap-3">
              <div className="flex items-center gap-2">
                <span className="text-[13px] font-bold text-white uppercase tracking-wide">LS</span>
                <input
                  type="number"
                  value={pageLimit}
                  onChange={e => setPageLimit(e.target.value)}
                  className="w-10 text-center py-[2px] border border-slate-200 rounded text-[13px] font-bold text-slate-700 bg-white h-[26px] focus:outline-none focus:border-[#0097A7] focus:ring-1 focus:ring-[#0097A7]"
                />
              </div>
              <div className="flex items-center gap-1">
                {[
                  { icon: <Printer size={12} />, l: 'Dos' },
                  { icon: <FileSpreadsheet size={12} className="text-green-600" />, l: 'Excel' },
                  { icon: <Download size={12} className="text-red-500" />, l: 'Pdf' },
                  { icon: <Filter size={12} className="text-[#0097A7]" />, l: 'Filter' },
                  //   { icon: <Settings size={12} className="text-slate-500" />, l: 'Setting' },
                ].map(tool => (
                  <button
                    key={tool.l}
                    onClick={() => {
                      if (tool.l === 'Dos') handlePrintBookingList();
                      else if (tool.l === 'Excel') handleExportExcel();
                      else if (tool.l === 'Pdf') handleExportPdf();
                      else if (tool.l === 'Filter') setShowFilterPanel(prev => !prev);
                      else toast.success(`${tool.l} tool activated.`);
                    }}
                    className="flex items-center gap-0.5 px-2.5 py-1 bg-white hover:bg-slate-50 border border-slate-200 text-slate-600 text-[12px] font-bold uppercase rounded shadow-sm transition-all active:scale-95"
                  >
                    {tool.icon} {tool.l}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Table Section with compact elements */}
          <div className="max-w-7xl mx-auto border border-slate-200 rounded-b-lg overflow-hidden shadow-sm bg-white mb-3">

            <div className="overflow-x-auto">
              <table className="w-full table-fixed text-left border-collapse min-w-[2180px]">
                <thead className="bg-slate-50 text-[12px] uppercase text-slate-400 font-bold border-b border-slate-200">
                  <tr className="h-8">
                    <th className="px-3 py-1 border-r border-slate-100 w-16 text-center whitespace-nowrap">S.No</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-28 text-center whitespace-nowrap">Booking Date</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-[240px] whitespace-nowrap">Customer Name</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-32 whitespace-nowrap">Customer Code</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-40 whitespace-nowrap">Serial No</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-28 text-center whitespace-nowrap">Vehicle Count</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-36 whitespace-nowrap">Vehicle No</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-44 whitespace-nowrap">Service Job.No</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-28 whitespace-nowrap">Model No</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-28 whitespace-nowrap">Sub Model</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-[150px] whitespace-nowrap">Vehicle Name</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-[180px] whitespace-nowrap">Remarks</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-32 text-center whitespace-nowrap">Financial Year</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-[110px] text-center whitespace-nowrap">Status</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-28 text-center whitespace-nowrap">Temp Status</th>
                    <th className="px-3 py-1 border-r border-slate-100 w-28 text-center whitespace-nowrap">Created By</th>
                    <th className="px-3 py-1 w-32 text-center whitespace-nowrap">Created Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[12.5px]">
                  {filteredBookings.length === 0 ? (
                    <tr>
                      <td colSpan={16} className="py-16 text-center text-slate-300 italic">
                        No Booking records found.
                      </td>
                    </tr>
                  ) : (
                    filteredBookings.map((row, idx) => (
                      <tr
                        key={row.id}
                        onClick={() => handleRowSelect(row)}
                        className={`hover:bg-[#0097A7]/5 cursor-pointer transition-colors h-9 ${(editingId === row.id || selectedRow?.id === row.id) ? 'bg-[#0097A7]/10 font-semibold' : ''}`}
                      >
                        <td className="px-3 py-1 border-r border-slate-50 text-center text-slate-500 font-bold bg-slate-50/50 whitespace-nowrap">{idx + 1}</td>
                        <td className="px-3 py-1 border-r border-slate-50 font-bold text-slate-500 text-center whitespace-nowrap">{row.bookingDate}</td>
                        <td className="px-3 py-1 border-r border-slate-50 font-bold text-slate-700 whitespace-nowrap overflow-hidden text-ellipsis">{row.customerName}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-slate-600 font-medium whitespace-nowrap overflow-hidden text-ellipsis">{row.customerCode || '—'}</td>
                        <td className="px-3 py-1 border-r border-slate-50 font-semibold text-slate-600 whitespace-nowrap overflow-hidden text-ellipsis">{row.serialNo || '—'}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-center font-bold text-[#0097A7] whitespace-nowrap">{row.customerVehicleCount || 1}</td>
                        <td className="px-3 py-1 border-r border-slate-50 font-mono text-slate-700 whitespace-nowrap overflow-hidden text-ellipsis">{row.vehicleNo || '—'}</td>
                        <td className="px-3 py-1 border-r border-slate-50 font-bold text-[#0097A7] whitespace-nowrap overflow-hidden text-ellipsis">{row.serviceJobNo}</td>
                        <td className="px-3 py-1 border-r border-slate-50 font-bold text-slate-500 whitespace-nowrap overflow-hidden text-ellipsis">{row.vehicleModelNo}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-slate-600 whitespace-nowrap overflow-hidden text-ellipsis">{row.modelSubType || '—'}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-slate-700 font-medium whitespace-nowrap overflow-hidden text-ellipsis">{row.vehicleName || '—'}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-slate-600 truncate max-w-[150px] whitespace-nowrap overflow-hidden text-ellipsis">{row.remarks || '—'}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-center text-slate-500 font-medium whitespace-nowrap">{getFinancialYear(row.bookingDate)}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-center text-slate-600 font-semibold whitespace-nowrap">{row.status || '—'}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-center text-slate-600 font-semibold whitespace-nowrap">{row.tempStatus || '—'}</td>
                        <td className="px-3 py-1 border-r border-slate-50 text-center text-slate-500 whitespace-nowrap overflow-hidden text-ellipsis">{row.createdBy || '—'}</td>
                        <td className="px-3 py-1 text-slate-500 text-center whitespace-nowrap">{row.createdAt ? new Date(row.createdAt).toLocaleDateString() : '—'}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>

          {/* Status bar */}
          <div className="flex items-center justify-between px-2.5 max-w-7xl mx-auto text-[12px] text-slate-400 font-bold uppercase tracking-wider">
            <span>Row : {filteredBookings.length}</span>
          </div>

          {/* Hidden barcode container for printing */}
          <div id="barcode-label" style={{ position: 'absolute', left: '-9999px', top: '-9999px' }}>
            <BarcodeGenerator value={form.serviceJobNo} />
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import {
  ChevronRight, X, Search, Download, FileSpreadsheet, FileJson, Filter, Settings, Wrench, Calendar, RotateCcw, CheckCircle2
} from 'lucide-react'
import * as XLSX from 'xlsx'
import { jsPDF } from 'jspdf'
import { useToast } from '../components/Toast'
import api from '../services/api'

// ── Shared UI primitives ──
const Label = ({ children }) => (
  <label className="block text-[11px] font-semibold text-slate-600 mb-1 uppercase tracking-wider whitespace-nowrap">
    {children}
  </label>
)

const Input = ({ type = 'text', value, onChange, className = "" }) => (
  <input
    type={type}
    value={value}
    onChange={onChange}
    className={`px-3 py-[7px] text-sm border border-slate-200 rounded-lg bg-white text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#0097A7]/25 focus:border-[#0097A7] transition-all duration-200 hover:border-slate-300 ${className}`}
  />
)

export default function BreakDownApprovalList() {
  const toast = useToast()
  const [fromDate, setFromDate] = useState(new Date().toISOString().split('T')[0])
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0])
  const [data, setData] = useState([])
  const [filteredData, setFilteredData] = useState([])
  const [searching, setSearching] = useState(false)

  const fetchAllBreakdowns = () => {
    setSearching(true)
    api.get('/api/machine-breakdown')
      .then(res => {
        if (res.data?.success) {
          setData(res.data.data || [])
          setFilteredData(res.data.data || [])
        }
        setSearching(false)
      })
      .catch(err => {
        console.error('Failed to fetch breakdowns for ledger:', err)
        setSearching(false)
      })
  }

  useEffect(() => {
    fetchAllBreakdowns()
  }, [])

  const parseTicketDate = (dateStr) => {
    if (!dateStr) return null
    if (dateStr instanceof Date) return dateStr
    const d = new Date(dateStr)
    if (!isNaN(d.getTime())) return d
    
    try {
      const parts = dateStr.trim().split(/\s+/)
      if (parts.length < 2) return null
      
      const datePart = parts[0]
      const timePart = parts[1]
      const ampm = parts[2]
      
      const [day, monthStr, year] = datePart.split('-')
      const [hoursStr, minutesStr] = timePart.split(':')
      
      let hours = parseInt(hoursStr, 10)
      const minutes = parseInt(minutesStr, 10)
      
      const months = {
        jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
        jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11
      }
      const month = months[monthStr.toLowerCase().substring(0, 3)]
      
      if (ampm && ampm.toUpperCase() === 'PM' && hours < 12) {
        hours += 12
      } else if (ampm && ampm.toUpperCase() === 'AM' && hours === 12) {
        hours = 0
      }
      
      return new Date(parseInt(year, 10), month, parseInt(day, 10), hours, minutes, 0, 0)
    } catch (e) {
      console.error('Failed to parse date string:', dateStr, e)
      return null
    }
  }

  const handleSearch = () => {
    if (!fromDate || !toDate) {
      toast.warning('Please select both Filter From and Filter To dates.')
      return
    }

    const [fYear, fMonth, fDay] = fromDate.split('-').map(Number)
    const [tYear, tMonth, tDay] = toDate.split('-').map(Number)
    
    const start = new Date(fYear, fMonth - 1, fDay, 0, 0, 0, 0)
    const end = new Date(tYear, tMonth - 1, tDay, 23, 59, 59, 999)
    
    if (start > end) {
      toast.error('From Date cannot be greater than To Date.')
      return
    }

    setSearching(true)
    setFilteredData([]) // Clear previous results before loading new search results
    
    setTimeout(() => {
      try {
        const result = data.filter(r => {
          const ticketDate = parseTicketDate(r.date)
          if (!ticketDate) return false
          return ticketDate >= start && ticketDate <= end
        })
        setFilteredData(result)
        setSearching(false)
        if (result.length === 0) {
          toast.info('No approval records found for the selected date range.')
        } else {
          toast.success(`Found ${result.length} approval record(s).`)
        }
      } catch (err) {
        console.error('Failed to filter approval records:', err)
        toast.error('An error occurred while processing approval records.')
        setSearching(false)
      }
    }, 600)
  }

  const handleExportExcel = () => {
    if (filteredData.length === 0) {
      toast.warning('No records to export.')
      return
    }
    const exportData = filteredData.map((row, i) => ({
      'S.No': i + 1,
      'MachineName': row.machineName || '',
      'Item Name': row.partNo || '',
      'Process Stage': row.processStage || '',
      'Description': row.location || '',
      'Date': row.date || '',
      'Reason': row.problemDescription || '',
      'Action Taken': row.actionTaken || '',
      'Remark': row.remark || '',
      'ReportedBy': row.reportedBy || '',
      'SolvedBy': row.solvedBy || ''
    }))
    const ws = XLSX.utils.json_to_sheet(exportData)
    const wb = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(wb, ws, 'Approvals')
    XLSX.writeFile(wb, `breakdown_approvals_${new Date().toISOString().split('T')[0]}.xlsx`)
    toast.success('Excel spreadsheet downloaded successfully.')
  }

  const handleExportPdf = () => {
    if (filteredData.length === 0) {
      toast.warning('No records to export.')
      return
    }
    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    })

    // Teal Header Block
    doc.setFillColor(0, 151, 167)
    doc.rect(0, 0, 297, 24, 'F')

    doc.setTextColor(255, 255, 255)
    doc.setFont('Helvetica', 'bold')
    doc.setFontSize(15)
    doc.text('VELSON ERP - POST-MAINTENANCE APPROVAL LEDGER', 15, 15)

    doc.setTextColor(100, 116, 139)
    doc.setFont('Helvetica', 'normal')
    doc.setFontSize(9)
    doc.text(`Total Records: ${filteredData.length}`, 240, 31)
    doc.text(`Generated Date: ${new Date().toLocaleDateString('en-IN')}`, 20, 31)

    // Table Headers
    let startY = 36
    doc.setFillColor(44, 62, 80)
    doc.rect(15, startY, 267, 8, 'F')

    doc.setTextColor(255, 255, 255)
    doc.setFont('Helvetica', 'bold')
    doc.setFontSize(7)
    doc.text('S.No', 16, startY + 5.5)
    doc.text('Machine Name', 25, startY + 5.5)
    doc.text('Item Name', 55, startY + 5.5)
    doc.text('Stage', 85, startY + 5.5)
    doc.text('Description', 105, startY + 5.5)
    doc.text('Date', 125, startY + 5.5)
    doc.text('Reason', 145, startY + 5.5)
    doc.text('Action Taken', 185, startY + 5.5)
    doc.text('Remark', 220, startY + 5.5)
    doc.text('Reported', 245, startY + 5.5)
    doc.text('Solved By', 265, startY + 5.5)

    let currentY = startY + 8
    doc.setFont('Helvetica', 'normal')
    doc.setFontSize(6.5)

    filteredData.forEach((row, idx) => {
      if (idx % 2 === 1) {
        doc.setFillColor(248, 250, 252)
        doc.rect(15, currentY, 267, 7, 'F')
      }

      doc.setTextColor(51, 65, 85)
      doc.text(String(idx + 1), 16, currentY + 4.5)
      doc.text(row.machineName || '', 25, currentY + 4.5)
      doc.text(row.partNo || '', 55, currentY + 4.5)
      doc.text(row.processStage || '', 85, currentY + 4.5)
      doc.text(row.location || '', 105, currentY + 4.5)
      doc.text(row.date || '', 125, currentY + 4.5)

      const trReason = (row.problemDescription || '').substring(0, 20)
      doc.text(trReason, 145, currentY + 4.5)

      const trAction = (row.actionTaken || '').substring(0, 18)
      doc.text(trAction, 185, currentY + 4.5)

      const trRemark = (row.remark || '').substring(0, 15)
      doc.text(trRemark, 220, currentY + 4.5)

      doc.text(row.reportedBy || '', 245, currentY + 4.5)
      doc.text(row.solvedBy || '', 265, currentY + 4.5)

      doc.setDrawColor(241, 245, 249)
      doc.line(15, currentY + 7, 282, currentY + 7)

      currentY += 7

      if (currentY > 185) {
        doc.addPage()
        doc.setFillColor(44, 62, 80)
        doc.rect(15, 10, 267, 8, 'F')
        doc.setTextColor(255, 255, 255)
        doc.setFont('Helvetica', 'bold')
        doc.text('S.No', 16, 15.5)
        doc.text('Machine Name', 25, 15.5)
        doc.text('Part No', 55, 15.5)
        doc.text('Stage', 85, 15.5)
        doc.text('Description', 105, 15.5)
        doc.text('Date', 125, 15.5)
        doc.text('Reason', 145, 15.5)
        doc.text('Action Taken', 185, 15.5)
        doc.text('Remark', 220, 15.5)
        doc.text('Reported', 245, 15.5)
        doc.text('Solved By', 265, 15.5)
        currentY = 18
        doc.setFont('Helvetica', 'normal')
        doc.setFontSize(6.5)
      }
    })

    doc.save(`breakdown_approvals_${new Date().toISOString().split('T')[0]}.pdf`)
    toast.success('PDF downloaded successfully.')
  }

  return (
    <div className="bg-[#f4f6f8] min-h-full pb-10">
      <div className="px-6 py-6">
        <div className="flex items-center gap-2 text-[12px] text-slate-400 mb-5 uppercase font-black tracking-tight">
          {/* <span>Dashboard</span> <ChevronRight size={12} />  */}
          <span>Maintenance</span> <ChevronRight size={12} /> <span className="text-[#0097A7]">Maintenance Approval Hub</span>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[850px]">
          <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-6 py-4">
            <div className="flex items-center gap-3">
              <div className="w-4 h-4 bg-green-600 rounded" />
              <h2 className="text-[14px] font-black text-slate-800 uppercase tracking-widest">Post-Maintenance Approval Ledger</h2>
            </div>
            <div className="flex items-center gap-2">
              <button 
                onClick={handleExportExcel}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white text-[11px] font-black rounded-lg transition-all shadow-sm"
              >
                <FileSpreadsheet size={14} /> Excel
              </button>
              <button 
                onClick={handleExportPdf}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-rose-600 hover:bg-rose-700 text-white text-[11px] font-black rounded-lg transition-all shadow-sm"
              >
                <Download size={14} /> PDF
              </button>
              <button onClick={() => window.history.back()} className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-500 hover:bg-slate-600 text-white text-[11px] font-black rounded-lg transition-all shadow-sm">
                <X size={14} strokeWidth={2.5} /> Close
              </button>
            </div>
          </div>

          <div className="p-8 flex-1 flex flex-col space-y-8">
            {/* Filter Hub */}
            <div className="flex items-center gap-8 bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100 shadow-inner">
              <div className="flex items-center gap-4">
                <Label>Filter From</Label>
                <Input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className="w-44" />
              </div>
              <div className="flex items-center gap-4">
                <Label>Filter To</Label>
                <Input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className="w-44" />
              </div>
              <button
                onClick={handleSearch}
                className="flex items-center gap-3 px-5 py-2 bg-[#0097A7] hover:bg-green-700 text-white text-[13px] font-black rounded-xl shadow-md transition-all active:scale-95 uppercase tracking-widest"
              >
                {searching ? <RotateCcw size={18} className="animate-spin" /> : <Search size={18} />}
                Search Approvals
              </button>
            </div>

            <div className="flex-1 border border-slate-200 rounded-2xl overflow-hidden shadow-sm bg-white">
              <table className="w-full table-fixed text-left border-collapse">
                <thead className="bg-[#fcfdfe] text-[9.5px] uppercase text-slate-400 font-black border-b border-slate-200">
                  <tr className="divide-x divide-slate-200">
                    <th className="px-1 py-3 w-[3%] text-center whitespace-normal break-words">S.No</th>
                    <th className="px-1.5 py-3 w-[11%] whitespace-normal break-words">MachineName</th>
                    <th className="px-1.5 py-3 w-[9%] whitespace-normal break-words">Item Name</th>
                    <th className="px-1.5 py-3 w-[10%] whitespace-normal break-words">Process Stage</th>
                    <th className="px-1.5 py-3 w-[9%] whitespace-normal break-words">Description</th>
                    <th className="px-1.5 py-3 w-[11%] text-center whitespace-normal break-words">Date</th>
                    <th className="px-1.5 py-3 w-[12%] whitespace-normal break-words">Reason</th>
                    <th className="px-1.5 py-3 w-[11%] whitespace-normal break-words">Action Taken</th>
                    <th className="px-1.5 py-3 w-[10%] whitespace-normal break-words">Remark</th>
                    <th className="px-1.5 py-3 w-[7%] whitespace-normal break-words">ReportedBy</th>
                    <th className="px-1.5 py-3 w-[7%] whitespace-normal break-words">SolvedBy</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 text-[11px]">
                  {searching ? (
                    <tr>
                      <td colSpan={11} className="py-24 text-center">
                        <div className="flex flex-col items-center justify-center gap-3">
                          <RotateCcw size={28} className="animate-spin text-[#0097A7]" />
                          <span className="text-[11px] font-black uppercase tracking-[0.2em] text-[#0097A7]">Searching Records...</span>
                        </div>
                      </td>
                    </tr>
                  ) : filteredData.length === 0 ? (
                    <tr>
                      <td colSpan={11} className="py-24 text-center text-slate-400 italic font-medium uppercase tracking-[0.15em]">
                        No approval records found for the selected date range.
                      </td>
                    </tr>
                  ) : (
                    filteredData.map((row, idx) => (
                      <tr key={row.id} className="hover:bg-green-50/20 transition-colors h-14 group divide-x divide-slate-200 border-b border-slate-200">
                        <td className="px-1 py-2 text-center text-slate-300 font-bold whitespace-normal break-words">{idx + 1}</td>
                        <td className="px-1.5 py-2 font-bold text-[#0097A7] uppercase whitespace-normal break-words">{row.machineName}</td>
                        <td className="px-1.5 py-2 font-semibold text-slate-700 whitespace-normal break-words">{row.partNo || '-'}</td>
                        <td className="px-1.5 py-2 text-slate-500 whitespace-normal break-words">{row.processStage || 'Direct'}</td>
                        <td className="px-1.5 py-2 text-slate-500 whitespace-normal break-words">{row.location || '-'}</td>
                        <td className="px-1.5 py-2 text-center text-slate-400 font-medium whitespace-normal break-words">{row.date}</td>
                        <td className="px-1.5 py-2 text-slate-600 italic whitespace-normal break-words">{row.problemDescription}</td>
                        <td className="px-1.5 py-2 text-slate-600 whitespace-normal break-words">{row.actionTaken || '-'}</td>
                        <td className="px-1.5 py-2 text-slate-600 whitespace-normal break-words">{row.remark || '-'}</td>
                        <td className="px-1.5 py-2 font-bold text-slate-400 uppercase text-[9px] whitespace-normal break-words">{row.reportedBy}</td>
                        <td className="px-1.5 py-2 text-slate-600 whitespace-normal break-words">{row.solvedBy || '-'}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>

            {/* Premium Aggregate Footer */}
            {/* <div className="mt-8 bg-slate-900 rounded-[2.5rem] p-10 flex items-center justify-between shadow-2xl relative overflow-hidden border border-slate-800">
              <div className="absolute inset-0 bg-gradient-to-r from-green-500/10 to-transparent pointer-events-none" />
              <div className="flex items-center gap-20 relative z-10">
                <div>
                  <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] mb-2">Total Approvals</p>
                  <p className="text-[32px] font-black text-white leading-none">{filteredData.length}</p>
                </div>
                <div className="w-[1px] h-12 bg-white/10" />
                <div>
                  <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] mb-2">Pending Clearances</p>
                  <p className="text-[32px] font-black text-green-500 leading-none">{filteredData.filter(d => d.status !== 'Accepted').length}</p>
                </div>
              </div>
              <div className="text-right relative z-10 opacity-20">
                <div className="flex items-center gap-2">
                  <Calendar size={18} className="text-white" />
                  <span className="text-white text-[11px] font-black uppercase tracking-[0.3em]">Compliance History Stream</span>
                </div>
              </div>
            </div> */}
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import {
  ChevronRight, X, Download, FileSpreadsheet, FileText, Filter, Settings, Search, CheckCircle2, RotateCcw, Printer
} from 'lucide-react'
import { useToast } from '../components/Toast'
import * as XLSX from 'xlsx'
import { jsPDF } from 'jspdf'
import api from '../services/api'

// ── Shared UI primitives ──
const Label = ({ children }) => (
  <label className="block text-[11px] font-bold text-slate-500 mb-0 uppercase tracking-wider whitespace-nowrap">
    {children}
  </label>
)

export default function BreakDownClearence() {
  const toast = useToast()
  const [data, setData] = useState([])
  const [filteredData, setFilteredData] = useState([])
  const [selectedRowDetails, setSelectedRowDetails] = useState(null)

  const [formProblemReason, setFormProblemReason] = useState('')
  const [formActionTaken, setFormActionTaken] = useState('')
  const [formRemarks, setFormRemarks] = useState('')
  const [formSolvedBy, setFormSolvedBy] = useState('')
  const [formDate, setFormDate] = useState('')
  const [errorMsg, setErrorMsg] = useState('')

  const [filterOpen, setFilterOpen] = useState(false)
  const [filterText, setFilterText] = useState('')

  const displayRows = filterText.trim()
    ? filteredData.filter(r => {
      const q = filterText.toLowerCase()
      return (
        (r.machineName || '').toLowerCase().includes(q) ||
        (r.partNo || '').toLowerCase().includes(q) ||
        (r.processStage || '').toLowerCase().includes(q) ||
        (r.problemDescription || '').toLowerCase().includes(q) ||
        (r.reportedBy || '').toLowerCase().includes(q)
      )
    })
    : filteredData

  const handleExportDOS = () => {
    if (displayRows.length === 0) {
      toast.warning('No records to export.')
      return
    }
    const cols = [
      { label: 'S.No', width: 6, getVal: (r, i) => String(i + 1) },
      { label: 'Machine Name', width: 22, getVal: r => r.machineName || '' },
      { label: 'Part No', width: 20, getVal: r => r.partNo || '' },
      { label: 'Process Stage', width: 18, getVal: r => r.processStage || '' },
      { label: 'Date', width: 12, getVal: r => r.date || '' },
      { label: 'Problem', width: 30, getVal: r => r.problemDescription || '' },
      { label: 'Reported By', width: 15, getVal: r => r.reportedBy || '' }
    ]
    let lines = []
    lines.push('='.repeat(130))
    lines.push('VELSON ERP - MACHINE BREAKDOWN CLEARANCE LIST'.padStart(85))
    lines.push('='.repeat(130))
    lines.push(cols.map(c => c.label.padEnd(c.width)).join(' '))
    lines.push('-'.repeat(130))
    displayRows.forEach((r, idx) => {
      lines.push(cols.map(c => {
        const val = c.getVal(r, idx)
        return val.substring(0, c.width).padEnd(c.width)
      }).join(' '))
    })
    lines.push('='.repeat(130))
    lines.push(`Total Records: ${displayRows.length}   |   Exported: ${new Date().toLocaleString()}`)
    const blob = new Blob([lines.join('\r\n')], { type: 'text/plain;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `breakdown_clearance_${new Date().toISOString().split('T')[0]}.txt`
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)
    toast.success('DOS text file downloaded successfully.')
  }

  const handleExportExcel = () => {
    if (displayRows.length === 0) {
      toast.warning('No records to export.')
      return
    }
    const exportData = displayRows.map((r, i) => ({
      'S.No': i + 1,
      'Machine Name': r.machineName || '',
      'Part No': r.partNo || '',
      'Process Stage': r.processStage || '',
      'Date': r.date || '',
      'Problem': r.problemDescription || '',
      'Reported By': r.reportedBy || '',
      'Status': r.status || 'waiting_clearance'
    }))
    const ws = XLSX.utils.json_to_sheet(exportData)
    const wb = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(wb, ws, 'Clearance Queue')
    XLSX.writeFile(wb, `breakdown_clearance_${new Date().toISOString().split('T')[0]}.xlsx`)
    toast.success('Excel spreadsheet downloaded successfully.')
  }

  const handleExportPdf = () => {
    if (displayRows.length === 0) {
      toast.warning('No records to export.')
      return
    }
    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    })

    // Teal Header Block
    doc.setFillColor(0, 151, 167)
    doc.rect(0, 0, 297, 24, 'F')

    doc.setTextColor(255, 255, 255)
    doc.setFont('Helvetica', 'bold')
    doc.setFontSize(15)
    doc.text('VELSON ERP - MACHINE BREAKDOWN CLEARANCE QUEUE', 15, 15)

    doc.setTextColor(100, 116, 139)
    doc.setFont('Helvetica', 'normal')
    doc.setFontSize(9)
    doc.text(`Total Records: ${displayRows.length}`, 240, 31)
    doc.text(`Generated Date: ${new Date().toLocaleDateString('en-IN')}`, 20, 31)

    // Table Headers
    let startY = 36
    doc.setFillColor(44, 62, 80)
    doc.rect(15, startY, 267, 8, 'F')

    doc.setTextColor(255, 255, 255)
    doc.setFont('Helvetica', 'bold')
    doc.setFontSize(8)
    doc.text('S.No', 17, startY + 5.5)
    doc.text('Machine Name', 28, startY + 5.5)
    doc.text('Part No', 78, startY + 5.5)
    doc.text('Process Stage', 118, startY + 5.5)
    doc.text('Date', 158, startY + 5.5)
    doc.text('Problem Description', 188, startY + 5.5)
    doc.text('Reported By', 250, startY + 5.5)

    let currentY = startY + 8
    doc.setFont('Helvetica', 'normal')
    doc.setFontSize(7.5)

    displayRows.forEach((row, idx) => {
      if (idx % 2 === 1) {
        doc.setFillColor(248, 250, 252)
        doc.rect(15, currentY, 267, 7, 'F')
      }

      doc.setTextColor(51, 65, 85)
      doc.text(String(idx + 1), 17, currentY + 4.5)
      doc.text(row.machineName || '', 28, currentY + 4.5)
      doc.text(row.partNo || '', 78, currentY + 4.5)
      doc.text(row.processStage || '', 118, currentY + 4.5)
      doc.text(row.date || '', 158, currentY + 4.5)

      const truncatedProblem = (row.problemDescription || '').length > 35
        ? (row.problemDescription || '').substring(0, 35) + '...'
        : (row.problemDescription || '')
      doc.text(truncatedProblem, 188, currentY + 4.5)

      doc.text(row.reportedBy || '', 250, currentY + 4.5)

      doc.setDrawColor(241, 245, 249)
      doc.line(15, currentY + 7, 282, currentY + 7)

      currentY += 7

      if (currentY > 185) {
        doc.addPage()
        doc.setFillColor(44, 62, 80)
        doc.rect(15, 10, 267, 8, 'F')
        doc.setTextColor(255, 255, 255)
        doc.setFont('Helvetica', 'bold')
        doc.text('S.No', 17, 15.5)
        doc.text('Machine Name', 28, 15.5)
        doc.text('Part No', 78, 15.5)
        doc.text('Process Stage', 118, 15.5)
        doc.text('Date', 158, 15.5)
        doc.text('Problem Description', 188, 15.5)
        doc.text('Reported By', 250, 15.5)
        currentY = 18
        doc.setFont('Helvetica', 'normal')
        doc.setFontSize(7.5)
      }
    })

    doc.save(`breakdown_clearance_${new Date().toISOString().split('T')[0]}.pdf`)
    toast.success('PDF downloaded successfully.')
  }

  const getLocalDateTimeString = () => {
    const tzoffset = (new Date()).getTimezoneOffset() * 60000;
    return (new Date(Date.now() - tzoffset)).toISOString().slice(0, 16);
  }

  useEffect(() => {
    if (selectedRowDetails) {
      setFormProblemReason(selectedRowDetails.problemDescription || '')
      setFormActionTaken(selectedRowDetails.actionTaken || '')
      setFormRemarks(selectedRowDetails.remark || '')
      setFormSolvedBy(selectedRowDetails.solvedBy || '')
      setFormDate(selectedRowDetails.solvedDate || getLocalDateTimeString())
      setErrorMsg('')
    }
  }, [selectedRowDetails])

  const fetchPendingBreakdowns = () => {
    api.get('/api/machine-breakdown')
      .then(res => {
        if (res.data?.success) {
          const list = res.data.data || []
          setData(list)
          const pending = list.filter(b => !b.status || b.status === 'Pending' || b.status === 'waiting_clearance')
          setFilteredData(pending)
        }
      })
      .catch(err => console.error('Failed to fetch breakdowns for clearance:', err))
  }

  useEffect(() => {
    fetchPendingBreakdowns()
  }, [])

  const handleClearForm = () => {
    setFormActionTaken('')
    setFormRemarks('')
    setFormSolvedBy('')
    setFormDate(getLocalDateTimeString())
    setErrorMsg('')
  }

  const handleSaveClearance = () => {
    if (!formProblemReason.trim()) {
      setErrorMsg('Problem Reason is required.');
      return;
    }
    if (!formActionTaken.trim()) {
      setErrorMsg('Action Taken is required.');
      return;
    }
    if (!formSolvedBy.trim()) {
      setErrorMsg('Problem Solved By is required.');
      return;
    }

    const payload = {
      problemDescription: formProblemReason,
      actionTaken: formActionTaken,
      remark: formRemarks,
      solvedBy: formSolvedBy,
      solvedDate: formDate,
      status: 'waiting_acceptance'
    }

    api.put(`/api/machine-breakdown/${selectedRowDetails.id}`, payload)
      .then(res => {
        if (res.data?.success) {
          toast.success('Breakdown ticket cleared & moved to Acceptance queue.')
          fetchPendingBreakdowns()
          setSelectedRowDetails(null)
        }
      })
      .catch(err => {
        console.error(err)
        toast.error(err.response?.data?.message || 'Failed to clear breakdown ticket.')
      })
  }

  return (
    <div className="bg-[#f1f5f9] min-h-screen">
      <div className="p-4">
        <div className="bg-white border border-slate-300 rounded shadow-sm overflow-hidden flex flex-col min-h-[90vh]">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-slate-300 bg-[#f8fafc] px-3 py-1.5">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-red-700 rounded-sm" />
              <h2 className="text-[12px] font-bold text-slate-800 uppercase tracking-tight">BreakDown Clearance</h2>
            </div>

            <div className="flex items-center gap-1.5">
              <button onClick={() => window.history.back()} className="flex items-center gap-1 px-3 py-1 border border-slate-200 bg-white text-slate-600 text-[11px] font-bold rounded shadow-sm hover:bg-rose-50 hover:text-rose-600 transition-all active:scale-95">
                <X size={16} strokeWidth={3} /> Close
              </button>
            </div>
          </div>

          {/* Analytical Toolbar */}
          <div className="flex items-center justify-end gap-6 bg-white border-b border-slate-200 px-4 py-2 text-slate-500">
            <div className="flex items-center gap-1.5 border-r border-slate-200 pr-6">
              <span className="text-[11px] font-bold">LS</span>
              <input type="text" value={displayRows.length} readOnly className="w-8 px-1 py-0.5 border border-slate-300 rounded text-center text-[#0097A7] font-black text-[12px]" />
            </div>

            <div className="flex items-center gap-4">
              <button onClick={handleExportDOS} className="hover:text-slate-800 flex items-center gap-1 text-[11px] font-bold transition-colors">
                <Printer size={14} className="text-slate-400" /> Dos
              </button>
              <button onClick={handleExportExcel} className="hover:text-emerald-600 flex items-center gap-1 text-[11px] font-bold transition-colors">
                <FileSpreadsheet size={14} className="text-emerald-500" /> Excel
              </button>
              <button onClick={handleExportPdf} className="hover:text-rose-600 flex items-center gap-1 text-[11px] font-bold transition-colors">
                <FileText size={14} className="text-rose-500" /> Pdf
              </button>
              <button onClick={() => { setFilterOpen(!filterOpen); if (filterOpen) setFilterText(''); }} className={`hover:text-[#0097A7] flex items-center gap-1 text-[11px] font-bold transition-colors ${filterOpen ? 'text-[#0097A7]' : ''}`}>
                <Filter size={14} /> Filter
              </button>
            </div>
          </div>

          {/* Text filter panel */}
          {filterOpen && (
            <div className="px-4 py-2 border-b border-slate-200 bg-slate-50 flex items-center gap-2">
              <Search size={14} className="text-slate-400" />
              <input
                autoFocus
                type="text"
                value={filterText}
                onChange={e => setFilterText(e.target.value)}
                placeholder="Search by machine, part no, stage, problem description, reported by..."
                className="flex-1 bg-white border border-slate-300 rounded px-2 py-1 text-[12px] focus:outline-none focus:border-[#0097A7]"
              />
              {filterText && (
                <button onClick={() => setFilterText('')} className="text-slate-400 hover:text-slate-600 font-bold text-[11px]">
                  Clear
                </button>
              )}
            </div>
          )}

          {/* High-Density Table */}
          <div className="flex-1 overflow-auto">
            <table className="w-full table-fixed text-left border-collapse">
              <thead className="bg-[#f8fafc] text-[9.5px] uppercase text-slate-500 font-bold border-b border-slate-300 sticky top-0 z-10">
                <tr className="divide-x divide-slate-300">
                  <th className="px-1 py-1.5 w-[3%] text-center whitespace-normal break-words">S.No</th>
                  <th className="px-1.5 py-1.5 w-[11%] whitespace-normal break-words">Machine Name</th>
                  <th className="px-1.5 py-1.5 w-[9%] whitespace-normal break-words">Item Name</th>
                  <th className="px-1.5 py-1.5 w-[10%] whitespace-normal break-words">Description</th>
                  <th className="px-1.5 py-1.5 w-[11%] text-center whitespace-normal break-words">Date</th>
                  <th className="px-1.5 py-1.5 w-[16%] whitespace-normal break-words">Problem</th>
                  <th className="px-1.5 py-1.5 w-[10%] whitespace-normal break-words">Action Taken</th>
                  <th className="px-1.5 py-1.5 w-[10%] whitespace-normal break-words">Remark</th>
                  <th className="px-1.5 py-1.5 w-[7%] whitespace-normal break-words">Reported By</th>
                  <th className="px-1.5 py-1.5 w-[7%] whitespace-normal break-words">Cleared By</th>
                  <th className="px-1.5 py-1.5 w-[6%] text-center whitespace-normal break-words">Cleared Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 text-[10.5px]">
                {displayRows.length === 0 ? (
                  <tr>
                    <td colSpan={11} className="py-24 text-center text-slate-300 italic uppercase font-black text-[10px] tracking-widest opacity-40">
                      No tickets awaiting clearance
                    </td>
                  </tr>
                ) : (
                  displayRows.map((row, idx) => (
                    <tr
                      key={row.id}
                      onClick={() => setSelectedRowDetails(row)}
                      className="hover:bg-[#f0f9fa]/40 transition-colors divide-x divide-slate-200 group cursor-pointer border-b border-slate-200"
                    >
                      <td className="px-1 py-1 text-center text-slate-300 font-bold whitespace-normal break-words">{idx + 1}</td>
                      <td className="px-1.5 py-1 font-bold text-[#0097A7] uppercase whitespace-normal break-words">{row.machineName}</td>
                      <td className="px-1.5 py-1 font-semibold text-slate-700 whitespace-normal break-words">{row.partNo}</td>
                      <td className="px-1.5 py-1 text-slate-500 whitespace-normal break-words">{row.processStage}</td>
                      <td className="px-1.5 py-1 text-center text-slate-400 font-medium whitespace-normal break-words">{row.date}</td>
                      <td className="px-1.5 py-1 text-slate-600 italic whitespace-normal break-words">{row.problemDescription}</td>
                      <td className="px-1.5 py-1 text-slate-500 whitespace-normal break-words">-</td>
                      <td className="px-1.5 py-1 text-slate-500 whitespace-normal break-words">-</td>
                      <td className="px-1.5 py-1 font-bold text-slate-400 uppercase text-[9px] whitespace-normal break-words">{row.reportedBy}</td>
                      <td className="px-1.5 py-1 text-slate-400 whitespace-normal break-words">-</td>
                      <td className="px-1.5 py-1 text-center text-slate-300 whitespace-normal break-words">N/A</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Details Popup Modal Form */}
      {selectedRowDetails && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-[#f0f9fb] border border-slate-300 rounded shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            {/* Modal Header */}
            <div className="flex items-center justify-between border-b border-slate-300 bg-[#f0f9fb] px-4 py-2">
              <div className="flex items-center gap-2">
                <div className="w-2.5 h-2.5 bg-[#4285f4] rounded-sm" />
                <h3 className="text-[11px] font-black text-slate-700 uppercase tracking-wider">Clear Breakdown</h3>
              </div>
              <button
                onClick={() => {
                  setSelectedRowDetails(null)
                  setErrorMsg('')
                }}
                className="text-slate-400 hover:text-slate-600 transition-colors p-1 hover:bg-white/50 rounded-full"
              >
                <X size={16} />
              </button>
            </div>

            {/* Modal Content */}
            <div className="p-6 space-y-4 text-[12px] text-slate-800">
              {errorMsg && (
                <div className="bg-rose-50 border border-rose-200 text-rose-600 px-3 py-1.5 rounded text-[11px]">
                  {errorMsg}
                </div>
              )}

              {/* Problem Reason */}
              <div className="flex gap-2">
                <div className="w-36 text-right font-medium pt-1.5 shrink-0">
                  <span className="text-red-600 font-bold mr-1">*</span>Problem Reason :
                </div>
                <textarea
                  value={formProblemReason}
                  onChange={(e) => setFormProblemReason(e.target.value)}
                  className="flex-1 px-2 py-1.5 border border-slate-400 rounded bg-white text-slate-800 focus:outline-none focus:ring-1 focus:ring-blue-500 h-16 resize-none"
                />
              </div>

              {/* Action Taken */}
              <div className="flex gap-2">
                <div className="w-36 text-right font-medium pt-1.5 shrink-0">
                  <span className="text-red-600 font-bold mr-1">*</span>Action Taken:
                </div>
                <textarea
                  value={formActionTaken}
                  onChange={(e) => setFormActionTaken(e.target.value)}
                  className="flex-1 px-2 py-1.5 border border-slate-400 rounded bg-white text-slate-800 focus:outline-none focus:ring-1 focus:ring-blue-500 h-16 resize-none"
                />
              </div>

              {/* Remarks */}
              <div className="flex gap-2">
                <div className="w-36 text-right font-medium pt-1.5 shrink-0">
                  Remark's :
                </div>
                <textarea
                  value={formRemarks}
                  onChange={(e) => setFormRemarks(e.target.value)}
                  className="flex-1 px-2 py-1.5 border border-slate-400 rounded bg-white text-slate-800 focus:outline-none focus:ring-1 focus:ring-blue-500 h-16 resize-none"
                />
              </div>

              {/* Solved By */}
              <div className="flex items-center gap-2">
                <div className="w-36 text-right font-medium shrink-0">
                  <span className="text-red-600 font-bold mr-1">*</span>Problem Sloved By :
                </div>
                <input
                  type="text"
                  value={formSolvedBy}
                  onChange={(e) => setFormSolvedBy(e.target.value)}
                  className="flex-1 px-2 py-1 border border-slate-400 rounded bg-white text-slate-800 focus:outline-none focus:ring-1 focus:ring-blue-500"
                />
              </div>

              {/* Date */}
              <div className="flex items-center gap-2">
                <div className="w-36 text-right font-medium shrink-0">
                  Date :
                </div>
                <input
                  type="datetime-local"
                  value={formDate}
                  onChange={(e) => setFormDate(e.target.value)}
                  className="px-2 py-1 border border-slate-400 rounded bg-white text-slate-800 focus:outline-none focus:ring-1 focus:ring-blue-500 w-52"
                />
              </div>
            </div>

            {/* Modal Footer */}
            <div className="flex justify-end gap-2 border-t border-slate-300 px-4 py-3 bg-[#f0f9fb]">
              <button
                onClick={handleSaveClearance}
                className="px-6 py-1 bg-[#4285f4] hover:bg-blue-600 text-white font-semibold rounded shadow-sm border border-blue-700/20 active:scale-95 transition-all text-xs"
              >
                Save
              </button>
              <button
                onClick={handleClearForm}
                className="px-6 py-1 bg-[#4285f4] hover:bg-blue-600 text-white font-semibold rounded shadow-sm border border-blue-700/20 active:scale-95 transition-all text-xs"
              >
                Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { ChevronRight, FileText, FileSpreadsheet, File as FilePdf, Filter, Settings, X, Trash2, Pencil, Search, Plus, Eye, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import ConfirmDialog from '../components/ConfirmDialog'
import api from '../services/api'
import { SpinnerLoader } from '../components/LocalLoader'



const inp = 'border border-slate-300 rounded px-2 py-1 text-[11.5px] focus:outline-none focus:border-[#0097A7] bg-white h-7 w-full'
const lbl = 'text-[11px] font-bold text-slate-600 whitespace-nowrap'
const iconBtn = 'flex items-center gap-1.5 text-[11px] font-bold text-slate-600 hover:text-[#0097A7] transition-colors cursor-pointer'

export default function CCMSEntryDetails() {
  const toast = useToast()
  
  const getTodayDateStr = () => {
    const today = new Date();
    return today.toISOString().split('T')[0];
  };

  const getOneYearAgoDateStr = () => {
    const d = new Date();
    d.setFullYear(d.getFullYear() - 1);
    return d.toISOString().split('T')[0];
  };

  const [fromDate, setFromDate] = useState(getOneYearAgoDateStr())
  const [toDate, setToDate] = useState(getTodayDateStr())
  
  const [customerName, setCustomerName] = useState('')
  const [customerCode, setCustomerCode] = useState('')
  const [serviceType, setServiceType] = useState('')
  const [modelNo, setModelNo] = useState('')
  const [statusFilter, setStatusFilter] = useState('Open')
  
  const [allRows, setAllRows] = useState([])
  const [filteredRows, setFilteredRows] = useState([])
  const [activeRowId, setActiveRowId] = useState(null)
  const [deleteTarget, setDeleteTarget] = useState(null)
  const [deleting, setDeleting] = useState(false)
  const [loading, setLoading] = useState(false)
  const [filterText, setFilterText] = useState('')
  const [filterOpen, setFilterOpen] = useState(false)

  // Fetch / Load complaints
  const loadComplaints = async () => {
    setLoading(true)
    try {
      const res = await api.get('/api/customer-complaint')
      if (res.data?.success && res.data.data) {
        setAllRows(res.data.data)
        // Default to filtering by status 'Open' initially
        const openComplaints = res.data.data.filter(r => (r.status || 'Open') === 'Open')
        setFilteredRows(openComplaints)
      }
    } catch (err) {
      console.error(err)
      toast.error('Failed to load customer complaints.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadComplaints()
  }, [])

  // Options for filtering derived from actual data
  const customerNames = [...new Set(allRows.map(r => r.customerName).filter(Boolean))]
  const customerCodes = [...new Set(allRows.map(r => r.customerCode).filter(Boolean))]
  const serviceTypes = [...new Set(allRows.map(r => r.serviceType).filter(Boolean))]
  const modelNos = [...new Set(allRows.map(r => r.modelNo).filter(Boolean))]

  const handleSearch = () => {
    let result = allRows

    // Filter by Date range (recDate conversion or raw matching)
    if (fromDate || toDate) {
      result = result.filter(r => {
        if (!r.recDate) return true
        // format is DD/MM/YYYY or DD-MMM-YYYY. Let's parse both
        let dateVal
        if (r.recDate.includes('/')) {
          const [d, m, y] = r.recDate.split('/')
          dateVal = new Date(`${y}-${m}-${d}`)
        } else {
          dateVal = new Date(r.recDate)
        }
        
        if (isNaN(dateVal.getTime())) return true
        
        const fDate = fromDate ? new Date(fromDate) : null
        const tDate = toDate ? new Date(toDate) : null
        
        if (fDate && dateVal < fDate) return false
        if (tDate && dateVal > tDate) return false
        return true
      })
    }

    if (customerName) {
      result = result.filter(r => r.customerName === customerName)
    }
    if (customerCode) {
      result = result.filter(r => r.customerCode === customerCode)
    }
    if (serviceType) {
      result = result.filter(r => r.serviceType === serviceType)
    }
    if (modelNo) {
      result = result.filter(r => r.modelNo === modelNo)
    }
    if (statusFilter) {
      result = result.filter(r => (r.status || 'Open') === statusFilter)
    }

    setFilteredRows(result)
    setActiveRowId(null)
  }

  const handleEdit = () => {
    if (!activeRowId) return
    localStorage.setItem('velson:complaint-edit', activeRowId)
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'CustomerComplaintEntry' } }))
  }

  const handleDeleteClick = () => {
    if (!activeRowId) return
    const target = allRows.find(r => String(r.id) === String(activeRowId))
    if (target) setDeleteTarget(target)
  }

  const handleDeleteConfirm = async () => {
    setDeleting(true)
    try {
      const res = await api.delete(`/api/customer-complaint/${activeRowId}`)
      if (res.data?.success) {
        setAllRows(prev => prev.filter(r => String(r.id) !== String(activeRowId)))
        setFilteredRows(prev => prev.filter(r => String(r.id) !== String(activeRowId)))
        setActiveRowId(null)
        setDeleteTarget(null)
        toast.success("Complaint deleted successfully.")
      }
    } catch (err) {
      console.error(err)
      toast.error(err.response?.data?.message || 'Failed to delete complaint.')
    } finally {
      setDeleting(false)
    }
  }


  // Export functions
  const buildExportRows = data => data.map(r => ({
    'S.No': r.id,
    'CCMC No': r.ccNo || '',
    'Customer Name': r.customerName || '',
    'Customer Code': r.customerCode || '',
    'Complainant Name': r.complainantName || '',
    'Mobile No': r.mobileNo || '',
    'Complaint Type': r.complaintType || '',
    'Complaint Date': r.recDate || '',
    'Service Type': r.serviceType || '',
    'Model Name': r.modelNo || '',
    'Complaint Status': r.status || '',
    'Approval Status': r.approvalStatus || ''
  }))

  const downloadBlob = (blob, filename) => {
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url; a.download = filename
    document.body.appendChild(a); a.click()
    document.body.removeChild(a); URL.revokeObjectURL(url)
  }

  const doExcelExport = () => {
    const rows = buildExportRows(filteredRows)
    if (!rows.length) return
    const cols = Object.keys(rows[0])
    const lines = [cols.join(','), ...rows.map(r => cols.map(c => `"${String(r[c]).replace(/"/g,'""')}"`).join(','))]
    downloadBlob(new Blob(['\ufeff' + lines.join('\n')], { type: 'text/csv;charset=utf-8;' }), 'ccms-details.csv')
  }

  const doDocExport = () => {
    const rows = buildExportRows(filteredRows)
    if (!rows.length) return
    const cols = Object.keys(rows[0])
    const thead = cols.map(c => `<th style="padding:5px 8px;background:#0097A7;color:#fff;font-size:11px;">${c}</th>`).join('')
    const tbody = rows.map((r, i) => `<tr style="${i%2?'background:#f8fafc;':''}">
      ${cols.map(c => `<td style="padding:4px 8px;border:1px solid #e2e8f0;font-size:11px;">${r[c]}</td>`).join('')}</tr>`).join('')
    const html = `<html><head><meta charset="utf-8"></head><body>
      <h2>CCMS Entry Details</h2>
      <table border="1" style="border-collapse:collapse;width:100%"><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
    </body></html>`
    downloadBlob(new Blob([html], { type: 'application/msword' }), 'ccms-details.doc')
  }

  const doPrint = () => {
    const rows = buildExportRows(filteredRows)
    const cols = Object.keys(rows[0] || {})
    const thead = cols.map(c => `<th>${c}</th>`).join('')
    const tbody = rows.map((r, i) => `<tr class="${i%2?'alt':''}"><td>${cols.map(c=>r[c]).join('</td><td>')}</td></tr>`).join('')
    const win = window.open('', '_blank', 'width=1100,height=750')
    win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>CCMS Entry Details</title>
    <style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:11px;margin:16px}
    h2{font-size:15px}table{width:100%;border-collapse:collapse}
    th{background:#0097A7;color:#fff;padding:5px 7px;text-align:left;font-size:10px}
    td{padding:4px 7px;border-bottom:1px solid #e2e8f0;font-size:10px}
    tr.alt td{background:#f8fafc}@media print{@page{margin:1cm}}</style></head>
    <body><h2>CCMS Entry Details</h2>
    <table><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
    </body></html>`)
    win.document.close(); win.focus()
    setTimeout(() => win.print(), 400)
  }

  const displayRows = filterText.trim()
    ? filteredRows.filter(r => {
        const q = filterText.toLowerCase()
        return (
          (r.customerName || '').toLowerCase().includes(q) ||
          (r.customerCode || '').toLowerCase().includes(q) ||
          (r.ccNo || '').toLowerCase().includes(q) ||
          (r.complainantName || '').toLowerCase().includes(q) ||
          (r.status || '').toLowerCase().includes(q)
        )
      })
    : filteredRows

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden h-screen flex flex-col bg-[#e0f7fa] relative">
      {/* Centralized Fullscreen Loader Overlay */}
      {loading && (
        <div className="absolute inset-0 bg-white/60 backdrop-blur-sm z-50 flex items-center justify-center">
          <SpinnerLoader size={30} message="Loading Data..." />
        </div>
      )}
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400 shrink-0">
        <span className="hover:text-[#0097A7] cursor-pointer">CCMS</span>
        <ChevronRight className="w-3 h-3"/>
        <span className="text-[#0097A7] font-semibold">CCMS Entry Details</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm flex flex-col flex-1 overflow-hidden">
        {/* Header Block */}
        <div className="px-4 py-2 bg-white border-b border-slate-200 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 bg-red-700 rounded-sm" />
            <h1 className="text-[12px] font-bold text-slate-700">CCMS Entry Details</h1>
          </div>
          
          <div className="flex items-center gap-2">
            <button
              onClick={handleEdit}
              disabled={!activeRowId}
              className="px-2.5 py-1 bg-white hover:bg-slate-50 disabled:opacity-40 border border-slate-200 rounded text-[11px] font-bold text-slate-700 flex items-center gap-1 transition-colors"
            >
              <Pencil className="w-3 h-3 text-emerald-600" /> Edit
            </button>
            <button
              onClick={handleDeleteClick}
              disabled={!activeRowId}
              className="px-2.5 py-1 bg-white hover:bg-slate-50 disabled:opacity-40 border border-slate-200 rounded text-[11px] font-bold text-slate-700 flex items-center gap-1 transition-colors"
            >
              <X className="w-3 h-3 text-red-500" /> Delete
            </button>
            <button
              onClick={() => window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'Dashboard' } }))}
              className="px-2.5 py-1 bg-white hover:bg-slate-50 border border-slate-200 rounded text-[11px] font-bold text-slate-700 flex items-center gap-1 transition-colors"
            >
              <X className="w-3 h-3 text-slate-500" /> Close
            </button>
          </div>
        </div>

        {/* Filters and Search Fields */}
        <div className="p-4 border-b border-slate-200 bg-slate-50/50 shrink-0 space-y-3">
          <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">
            {/* Dates row */}
            <div className="md:col-span-3 flex items-center gap-2">
              <label className={lbl}>From Date :</label>
              <input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className={inp}/>
            </div>
            
            <div className="md:col-span-3 flex items-center gap-2">
              <label className={lbl}>To Date :</label>
              <input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className={inp}/>
            </div>
            
            <div className="md:col-span-6 flex gap-2 justify-start md:justify-end">
              <button
                onClick={handleSearch}
                className="flex items-center gap-1.5 px-3 py-1 border border-[#0097A7] text-[#0097A7] bg-white hover:bg-[#0097A7]/10 rounded text-[11.5px] font-bold transition-colors shadow-sm"
              >
                <span className="w-2 h-2 rounded-full bg-orange-500"></span> Search
              </button>
              
              <button
                onClick={handleSearch}
                className="flex items-center gap-1.5 px-3 py-1 border border-[#0097A7] text-[#0097A7] bg-white hover:bg-[#0097A7]/10 rounded text-[11.5px] font-bold transition-colors shadow-sm"
              >
                <span className="w-2 h-2 rounded-full bg-[#f57c00]"></span> Details
              </button>

              <button
                onClick={doPrint}
                className="flex items-center gap-1.5 px-3 py-1 border border-[#0097A7] text-[#0097A7] bg-white hover:bg-[#0097A7]/10 rounded text-[11.5px] font-bold transition-colors shadow-sm"
              >
                <FilePdf className="w-3.5 h-3.5 text-red-500" /> View PDF
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-5 gap-3 pt-3 pb-3">
            <div className="space-y-1">
              <label className={lbl}>Customer Name :</label>
              <select value={customerName} onChange={e => setCustomerName(e.target.value)} className={inp}>
                <option value="">-- Select Customer --</option>
                {customerNames.map(name => <option key={name} value={name}>{name}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className={lbl}>Customer Code :</label>
              <select value={customerCode} onChange={e => setCustomerCode(e.target.value)} className={inp}>
                <option value="">-- Select Code --</option>
                {customerCodes.map(code => <option key={code} value={code}>{code}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className={lbl}>Service Type :</label>
              <select value={serviceType} onChange={e => setServiceType(e.target.value)} className={inp}>
                <option value="">-- Select Service Type --</option>
                {serviceTypes.map(type => <option key={type} value={type}>{type}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className={lbl}>Model No :</label>
              <select value={modelNo} onChange={e => setModelNo(e.target.value)} className={inp}>
                <option value="">-- Select Model No --</option>
                {modelNos.map(model => <option key={model} value={model}>{model}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className={lbl}>Complaint Status :</label>
              <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className={inp}>
                <option value="">-- All --</option>
                <option value="Open">Open</option>
                <option value="Closed">Closed</option>
              </select>
            </div>
          </div>

          {/* Quick Actions Bar */}
          <div className="flex items-center justify-between pt-1 border-t border-slate-100">
            <div className="flex items-center gap-3">
              <button
                onClick={() => { setFilteredRows(allRows.filter(r => (r.status || 'Open') === 'Open')); setActiveRowId(null); setFilterText(''); setCustomerName(''); setCustomerCode(''); setServiceType(''); setModelNo(''); setStatusFilter('Open') }}
                className="text-[11px] font-bold text-slate-500 hover:text-[#0097A7] transition-colors"
              >
                Clear Filters
              </button>
              <div className="h-4 w-px bg-slate-200" />
              <button
                onClick={() => {
                  localStorage.removeItem('velson:complaint-edit')
                  window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'CustomerComplaintEntry' } }))
                }}
                className="flex items-center gap-1 text-[11px] font-bold text-[#0097A7] hover:text-[#007a87]"
              >
                <Plus className="w-3.5 h-3.5" /> Add New Complaint
              </button>
            </div>

            <div className="flex items-center gap-4">
              <div className="flex items-center gap-1.5">
                <span className="text-[11px] font-bold text-slate-500">LS</span>
                <input value={displayRows.length} readOnly className="w-10 text-center border border-slate-300 rounded text-[11px] py-0.5 bg-slate-50 font-bold"/>
              </div>
              <div className="h-4 w-px bg-slate-300"/>
              <button onClick={doDocExport} className={iconBtn}><FileText className="w-4 h-4 text-[#0097A7]"/> Dos</button>
              <button onClick={doExcelExport} className={iconBtn}><FileSpreadsheet className="w-4 h-4 text-[#0097A7]"/> Excel</button>
              <button onClick={doPrint} className={iconBtn}><FilePdf className="w-4 h-4 text-red-500"/> Pdf</button>
              <button
                onClick={() => { setFilterOpen(o => !o); if (filterOpen) setFilterText('') }}
                className={`${iconBtn} ${filterOpen ? 'text-[#0097A7]' : ''}`}
              >
                <Filter className="w-4 h-4 text-blue-500"/> Filter
              </button>
            </div>
          </div>
        </div>

        {/* Text Filter input */}
        {filterOpen && (
          <div className="px-3 py-2 border-b border-slate-200 bg-blue-50/40 flex items-center gap-3 shrink-0">
            <Filter className="w-3.5 h-3.5 text-blue-400 shrink-0"/>
            <input autoFocus type="text" value={filterText} onChange={e => setFilterText(e.target.value)}
              placeholder="Search CC No, Customer Name, Complainant, Status..."
              className="flex-1 border border-blue-200 rounded px-3 py-1 text-[11.5px] focus:outline-none focus:border-[#0097A7] bg-white"/>
            {filterText && (
              <button onClick={() => setFilterText('')} className="text-slate-400 hover:text-slate-600">
                <X className="w-3.5 h-3.5"/>
              </button>
            )}
            <span className="text-[11px] text-slate-400 shrink-0">{displayRows.length} results</span>
          </div>
        )}

        {/* Data Grid / Table */}
        <div className="flex-1 overflow-auto relative">
          <table className="w-full min-w-max text-[11.5px] text-left border-collapse">
            <thead className="bg-slate-800 text-white sticky top-0 z-10">
              <tr>
                <th className="p-2 font-medium border-x border-slate-700 text-center w-10">S.No</th>
                {/* <th className="p-2 font-medium border-x border-slate-700 text-center w-10">ID</th> */}
                <th className="p-2 font-medium border-x border-slate-700">CCMC No</th>
                <th className="p-2 font-medium border-x border-slate-700">Customer Name</th>
                <th className="p-2 font-medium border-x border-slate-700">Customer Code</th>
                <th className="p-2 font-medium border-x border-slate-700">Complainted Name</th>
                <th className="p-2 font-medium border-x border-slate-700 text-center">Mobile No</th>
                <th className="p-2 font-medium border-x border-slate-700">Complaint Type</th>
                <th className="p-2 font-medium border-x border-slate-700 text-center">Complaint Date</th>
                <th className="p-2 font-medium border-x border-slate-700 text-center">Service Type</th>
                <th className="p-2 font-medium border-x border-slate-700 text-center">Model Name</th>
                <th className="p-2 font-medium border-x border-slate-700 text-center">Complaint Status</th>
                <th className="p-2 font-medium border-x border-slate-700 text-center">Approval Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 bg-white">
              {displayRows.length === 0 ? (
                <tr>
                  <td colSpan={13} className="p-8 text-center text-slate-400 text-[12px]">
                    No matching records found.
                  </td>
                </tr>
              ) : displayRows.map((row, i) => (
                <tr
                  key={row.id || i}
                  onClick={() => setActiveRowId(row.id)}
                  className={`cursor-pointer transition-colors ${String(activeRowId) === String(row.id) ? 'bg-[#0097A7]/20 font-semibold text-slate-900' : (i % 2 === 1 ? 'bg-slate-50/40 text-rose-600' : 'bg-white text-slate-700')}`}
                >
                  <td className="p-1.5 border-x border-slate-200 text-center">{i + 1}</td>
                  {/* <td className="p-1.5 border-x border-slate-200 text-center">{row.id}</td> */}
                  <td className="p-1.5 border-x border-slate-200 text-[#0097A7] font-semibold">{row.ccNo}</td>
                  <td className="p-1.5 border-x border-slate-200 uppercase whitespace-nowrap">{row.customerName || '—'}</td>
                  <td className="p-1.5 border-x border-slate-200">{row.customerCode || '—'}</td>
                  <td className="p-1.5 border-x border-slate-200 uppercase">{row.complainantName || '—'}</td>
                  <td className="p-1.5 border-x border-slate-200 text-center">{row.mobileNo || '—'}</td>
                  <td className="p-1.5 border-x border-slate-200">{row.complaintType || '—'}</td>
                  <td className="p-1.5 border-x border-slate-200 text-center">{row.recDate || '—'}</td>
                  <td className="p-1.5 border-x border-slate-200 text-center">{row.serviceType || '—'}</td>
                  <td className="p-1.5 border-x border-slate-200 text-center">{row.modelNo || '—'}</td>
                  <td className="p-1.5 border-x border-slate-200 text-center font-bold">
                    <span className={row.status === 'Closed' ? 'text-emerald-600' : 'text-rose-600'}>
                      {row.status || 'Open'}
                    </span>
                  </td>
                  <td className="p-1.5 border-x border-slate-200 text-center">
                    <span className="text-emerald-600 font-bold">{row.approvalStatus || '—'}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <ConfirmDialog
        open={!!deleteTarget}
        message={`Delete customer complaint with CC No: ${deleteTarget?.ccNo}? This action cannot be undone.`}
        onCancel={() => { if (!deleting) setDeleteTarget(null) }}
        onConfirm={handleDeleteConfirm}
        confirming={deleting}
      />
    </div>
  )
}

import { useState, useRef, useEffect, useCallback } from 'react'
import api from '../services/api'
import { X, Save, RotateCcw, List, Edit, Trash2, Info, ChevronRight, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import ConfirmDialog from '../components/ConfirmDialog'
import { TableSkeleton } from '../components/LocalLoader'

const PAGE_SIZES = [5, 10, 25, 50]

const emptyForm = {
  companyCode: '', companyName: '', companyType: '',
  doorNumber: '', street: '', place: '', post: '', city: '', taluk: '',
  district: '', districtCode: '', state: '', stateCode: '', country: 'India', pinCode: '', address: '',
  gstin: '', panNo: '',
  companyPhone: '', companyEmail: '', companyWebsite: '',
  marketingPhone: '', marketingEmail: '', marketingWebsite: '',
  purchasePhone: '', purchaseEmail: '', purchaseWebsite: '',
  salesPhone: '', salesEmail: '', salesWebsite: '',
  servicePhone: '', serviceEmail: '', serviceWebsite: '',
  bankName: '', bankBranch: '', bankAccountType: '', bankAccountName: '',
  bankAccountNumber: '', bankIfscCode: '', bankMicrCode: '',
  bankDistrict: '', bankState: '', bankPinCode: '', bankCountry: '', bankAddress: '',
  logo: null,
}

const inp = (err) =>
  `w-full border rounded px-2 py-1 text-[13px] focus:outline-none focus:ring-1 transition-colors bg-white ${
    err ? 'border-red-400 focus:ring-red-300' : 'border-slate-300 focus:ring-[#0097A7] focus:border-[#0097A7]'
  }`

// ── Field: label on top, input below ─────────────────────────────────────────
function F({ label, fk, required, readOnly, placeholder, type = 'text', form, sf, errors }) {
  return (
    <div>
      <label className="block text-[12.5px] font-semibold text-slate-600 mb-0.5">
        {required && <span className="text-red-500">*</span>}{label}
      </label>
      <input
        type={type}
        value={form[fk] || ''}
        onChange={e => sf(fk, e.target.value)}
        readOnly={readOnly}
        placeholder={placeholder || label}
        className={readOnly ? `${inp(false)} bg-slate-50` : inp(errors[fk])}
      />
      {errors[fk] && <p className="text-[11px] text-red-500 mt-0.5">{errors[fk]}</p>}
    </div>
  )
}

// ── Two fields side by side ───────────────────────────────────────────────────
function F2({ l1, f1, l2, f2, req1, req2, ph1, ph2, form, sf, errors }) {
  return (
    <div className="grid grid-cols-2 gap-2">
      <div>
        <label className="block text-[12.5px] font-semibold text-slate-600 mb-0.5">
          {req1 && <span className="text-red-500">*</span>}{l1}
        </label>
        <input value={form[f1] || ''} onChange={e => sf(f1, e.target.value)}
          placeholder={ph1 || l1} className={inp(errors[f1])} />
        {errors[f1] && <p className="text-[11px] text-red-500 mt-0.5">{errors[f1]}</p>}
      </div>
      <div>
        <label className="block text-[12.5px] font-semibold text-slate-600 mb-0.5">
          {req2 && <span className="text-red-500">*</span>}{l2}
        </label>
        <input value={form[f2] || ''} onChange={e => sf(f2, e.target.value)}
          placeholder={ph2 || l2} className={inp(errors[f2])} />
        {errors[f2] && <p className="text-[11px] text-red-500 mt-0.5">{errors[f2]}</p>}
      </div>
    </div>
  )
}

// ── Bordered panel ────────────────────────────────────────────────────────────
function Panel({ children }) {
  return (
    <div className="border border-[#0097A7] rounded overflow-hidden">
      <div className="h-[5px] bg-[#0097A7]" />
      <div className="p-3 space-y-2">{children}</div>
    </div>
  )
}

// ── Detail Modal ──────────────────────────────────────────────────────────────
function DetailModal({ row, onClose }) {
  return (
    <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden">
        <div className="bg-gradient-to-r from-[#0097A7] to-[#00BCD4] px-6 py-4 flex items-center justify-between">
          <h2 className="text-white font-bold text-[15px]">Company Details</h2>
          <button onClick={onClose} className="text-white/80 hover:text-white"><X className="w-5 h-5" /></button>
        </div>
        <div className="p-5 max-h-[70vh] overflow-y-auto">
          {row.logoData && (
            <div className="flex justify-center mb-4 border border-slate-105 p-2 rounded bg-slate-50 w-fit mx-auto shadow-sm animate-fadeIn">
              <img
                src={`/api/company-master/${row.id}/download-logo`}
                alt={`${row.companyName} Logo`}
                className="max-h-28 max-w-full object-contain rounded"
              />
            </div>
          )}
          <div className="grid grid-cols-2 gap-x-6 gap-y-1.5">
            {[
              ['Company Code', row.companyCode], ['Company Name', row.companyName],
              ['Company Type', row.companyType], ['GSTIN', row.gstin],
              ['PAN No', row.panNo], ['City', row.city],
              ['State', row.state], ['Country', row.country],
              ['Pin Code', row.pinCode], ['Company Phone', row.companyPhone],
              ['Company Email', row.companyEmail], ['Bank Name', row.bankName],
              ['Bank Branch', row.bankBranch], ['Account Number', row.bankAccountNumber],
              ['IFSC Code', row.bankIfscCode], ['MICR Code', row.bankMicrCode],
            ].map(([l, v]) => (
              <div key={l} className="flex flex-col py-1 border-b border-slate-100">
                <span className="text-[11px] font-semibold text-slate-400 uppercase tracking-wider">{l}</span>
                <span className="text-[13px] text-slate-800 font-medium">{v || '—'}</span>
              </div>
            ))}
          </div>
        </div>
        <div className="px-6 pb-5 flex justify-end">
          <button onClick={onClose} className="px-5 py-2 text-sm font-semibold text-white bg-[#0097A7] hover:bg-[#007a87] rounded-lg transition-colors">Close</button>
        </div>
      </div>
    </div>
  )
}

// ── Main Component ────────────────────────────────────────────────────────────
export default function CompanyMaster() {
  const toast = useToast()
  const fileRef = useRef(null)

  const [rows, setRows] = useState([])
  const [companyTypes, setCompanyTypes] = useState([])
  const [tableLoading, setTableLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [deleting, setDeleting] = useState(false)

  const [form, setForm] = useState({ ...emptyForm })
  const [errors, setErrors] = useState({})
  const [editId, setEditId] = useState(null)
  const [logoPreview, setLogoPreview] = useState(null)
  const [search, setSearch] = useState('')
  const [pageSize, setPageSize] = useState(5)
  const [page, setPage] = useState(1)
  const [detailRow, setDetailRow] = useState(null)
  const [confirmDelete, setConfirmDelete] = useState(null)

  const fetchCompanyTypes = useCallback(async () => {
    try {
      const res = await api.get('/api/reference-master/Company_Type')
      setCompanyTypes(res.data.data || [])
    } catch (err) {
      console.error('[CompanyMaster] fetchCompanyTypes:', err)
    }
  }, [])

  const fetchAll = useCallback(async () => {
    setTableLoading(true)
    try {
      const res = await api.get('/api/company-master')
      setRows(res.data.data || [])
    } catch (err) {
      console.error('[CompanyMaster] fetchAll:', err)
      toast.error('Failed to load company records')
    } finally {
      setTableLoading(false)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const fetchNextCode = useCallback(async () => {
    try {
      const res = await api.get('/api/company-master/next-code')
      setForm(f => ({ ...f, companyCode: res.data.nextCode || '' }))
    } catch (err) {
      console.error('[CompanyMaster] fetchNextCode:', err)
    }
  }, [])

  useEffect(() => { fetchAll(); fetchNextCode(); fetchCompanyTypes() }, [fetchAll, fetchNextCode, fetchCompanyTypes])

  const sf = (k, v) => {
    setForm(f => ({ ...f, [k]: v }))
    setErrors(e => ({ ...e, [k]: '' }))
    if (k === 'logo') {
      if (v) {
        if (logoPreview && !logoPreview.startsWith('/api')) {
          URL.revokeObjectURL(logoPreview)
        }
        setLogoPreview(URL.createObjectURL(v))
      } else {
        if (logoPreview && !logoPreview.startsWith('/api')) {
          URL.revokeObjectURL(logoPreview)
        }
        setLogoPreview(null)
      }
    }
  }

  const validate = () => {
    const errs = {}
    if (!form.companyName.trim()) errs.companyName = 'Required'
    if (!form.companyType) errs.companyType = 'Required'
    setErrors(errs)
    return Object.keys(errs).length === 0
  }

  const handleSave = async () => {
    if (!validate()) return
    setSaving(true)
    try {
      const fd = new FormData()
      Object.entries(form).forEach(([k, v]) => { if (k !== 'logo') fd.append(k, v ?? '') })
      if (form.logo) fd.append('logo', form.logo)
      if (editId !== null) {
        await api.put(`/api/company-master/${editId}`, fd, {
          headers: { 'Content-Type': 'multipart/form-data' }
        })
        toast.success('Company updated successfully.')
      } else {
        await api.post('/api/company-master', fd, {
          headers: { 'Content-Type': 'multipart/form-data' }
        })
        toast.success('Company created successfully.')
      }
      setForm({ ...emptyForm }); setErrors({}); setEditId(null); setPage(1)
      if (logoPreview && !logoPreview.startsWith('/api')) {
        URL.revokeObjectURL(logoPreview)
      }
      setLogoPreview(null)
      if (fileRef.current) fileRef.current.value = ''
      await fetchAll(); await fetchNextCode()
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to save company.')
    } finally {
      setSaving(false)
    }
  }

  const handleEdit = row => {
    const f = { ...emptyForm }
    Object.keys(emptyForm).forEach(k => { if (k !== 'logo') f[k] = row[k] ?? '' })
    setForm(f); setErrors({}); setEditId(row.id)
    if (logoPreview && !logoPreview.startsWith('/api')) {
      URL.revokeObjectURL(logoPreview)
    }
    if (row.logoData) {
      setLogoPreview(`/api/company-master/${row.id}/download-logo`)
    } else {
      setLogoPreview(null)
    }
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handleDelete = async () => {
    if (!confirmDelete) return
    setDeleting(true)
    try {
      await api.delete(`/api/company-master/${confirmDelete}`)
      toast.success('Company deleted.')
      setConfirmDelete(null)
      if (editId === confirmDelete) {
        setForm({ ...emptyForm })
        if (logoPreview && !logoPreview.startsWith('/api')) {
          URL.revokeObjectURL(logoPreview)
        }
        setLogoPreview(null)
        setEditId(null)
      }
      await fetchAll()
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to delete.')
    } finally {
      setDeleting(false)
    }
  }

  const handleClear = async () => {
    setForm({ ...emptyForm }); setErrors({}); setEditId(null)
    if (logoPreview && !logoPreview.startsWith('/api')) {
      URL.revokeObjectURL(logoPreview)
    }
    setLogoPreview(null)
    if (fileRef.current) fileRef.current.value = ''
    await fetchNextCode()
  }

  const filtered = rows.filter(r =>
    [r.companyCode, r.companyName, r.companyType, r.city, r.state, r.gstin]
      .some(v => String(v || '').toLowerCase().includes(search.toLowerCase()))
  )
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)
  const pageNums = () => {
    if (totalPages <= 7) return Array.from({ length: totalPages }, (_, i) => i + 1)
    const ps = [1]
    if (page > 3) ps.push('...')
    for (let i = Math.max(2, page - 1); i <= Math.min(totalPages - 1, page + 1); i++) ps.push(i)
    if (page < totalPages - 2) ps.push('...')
    ps.push(totalPages)
    return ps
  }

  // shared props passed to every F / F2
  const fp = { form, sf, errors }

  return (
    <div className="p-4 space-y-4 w-full min-w-0">

      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3" /> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Masters</span>
        <ChevronRight className="w-3 h-3" />
        <span className="text-[#0097A7] font-semibold">Company Master</span>
      </div>

      {/* ── Form Card ── */}
      <div className="bg-white rounded border border-slate-300 shadow-sm overflow-hidden">
        <div className="bg-[#0097A7] px-4 py-2">
          <h2 className="text-white text-center font-semibold text-[14px]">New Company Master Details Entry</h2>
        </div>

        <div className="p-3">
          <div className="grid grid-cols-3 gap-3">

            {/* ── Panel 1: Company Info ── */}
            <Panel>
              <F {...fp} label="Company Code" fk="companyCode" required readOnly placeholder="Auto-generated" />
              <F {...fp} label="Company Name" fk="companyName" required />
              <div>
                <label className="block text-[12.5px] font-semibold text-slate-600 mb-0.5">
                  CompanyType
                </label>
                <select value={form.companyType} onChange={e => sf('companyType', e.target.value)}
                  className={inp(errors.companyType)}>
                  <option value=""></option>
                  {companyTypes.map(t => <option key={t.id} value={t.description}>{t.description}</option>)}
                </select>
                {errors.companyType && <p className="text-[11px] text-red-500 mt-0.5">{errors.companyType}</p>}
              </div>
              <F2 {...fp} l1="Door Number" f1="doorNumber" l2="Street" f2="street" />
              <F {...fp} label="Place" fk="place" />
              <F {...fp} label="Post" fk="post" />
              <F {...fp} label="City" fk="city" />
              <F {...fp} label="Taluk" fk="taluk" />
              <F2 {...fp} l1="District" f1="district" l2="District Code" f2="districtCode" />
              <F2 {...fp} l1="State" f1="state" l2="State Code" f2="stateCode" />
              <F2 {...fp} l1="Country" f1="country" l2="PinCode" f2="pinCode" />
              <F {...fp} label="Address" fk="address" />
            </Panel>

            {/* ── Panel 2: Tax & Contacts ── */}
            <Panel>
              <F {...fp} label="GSTIN" fk="gstin" placeholder="GSTIN" />
              <F {...fp} label="PanNo" fk="panNo" placeholder="PanNo" />
              <F2 {...fp} l1="Company Phone Number" f1="companyPhone" ph1="Company Phone Number"
                l2="Company EMail Id" f2="companyEmail" ph2="Company EMail Id" />
              <F {...fp} label="Company Website URL" fk="companyWebsite" placeholder="Company Website URL" />
              <F2 {...fp} l1="Marketing Phone Number" f1="marketingPhone" ph1="Marketing Phone Number"
                l2="Marketing EMail Id" f2="marketingEmail" ph2="Marketing EMail Id" />
              <F {...fp} label="Marketing Website URL" fk="marketingWebsite" placeholder="Marketing Website URL" />
              <F2 {...fp} l1="Purchase Phone Number" f1="purchasePhone" ph1="Purchase Phone Number"
                l2="Purchase EMail Id" f2="purchaseEmail" ph2="Purchase EMail Id" />
              <F {...fp} label="Purchase Website URL" fk="purchaseWebsite" placeholder="Purchase Website URL" />
              <F2 {...fp} l1="Sales Phone Number" f1="salesPhone" ph1="Sales Phone Number"
                l2="Sales EMail Id" f2="salesEmail" ph2="Sales EMail Id" />
              <F {...fp} label="Sales Website URL" fk="salesWebsite" placeholder="Sales Website URL" />
              <F2 {...fp} l1="Service Phone Number" f1="servicePhone" ph1="Service Phone Number"
                l2="Service EMail Id" f2="serviceEmail" ph2="Service EMail Id" />
              <F {...fp} label="Service Website URL" fk="serviceWebsite" placeholder="Service Website URL" />
            </Panel>

            {/* ── Panel 3: Bank ── */}
            <Panel>
              <F {...fp} label="Bank Name" fk="bankName" placeholder="Bank Name" />
              <F2 {...fp} l1="Bank Branch" f1="bankBranch" l2="Bank Account Type" f2="bankAccountType" />
              <F {...fp} label="Bank Account Name" fk="bankAccountName" placeholder="Bank Account Name" />
              <F {...fp} label="Bank Account Number" fk="bankAccountNumber" placeholder="Bank Account Number" />
              <F2 {...fp} l1="Bank IFSCCode" f1="bankIfscCode" l2="Bank MICRCode" f2="bankMicrCode" />
              <F2 {...fp} l1="Bank District" f1="bankDistrict" l2="Bank State" f2="bankState" />
              <F2 {...fp} l1="Bank PinCode" f1="bankPinCode" l2="Bank Country" f2="bankCountry" />
              <F {...fp} label="Bank Address" fk="bankAddress" placeholder="Bank Address" />

              {/* Logo Upload */}
              <div>
                <label className="block text-[12.5px] font-semibold text-slate-600 mb-0.5">Upload Company Logo</label>
                <input
                  ref={fileRef}
                  type="file"
                  accept="image/*"
                  onChange={e => sf('logo', e.target.files[0] || null)}
                  className="w-full text-[12px] border border-slate-300 rounded px-2 py-1 file:mr-2 file:py-0.5 file:px-2 file:text-[11px] file:border-0 file:bg-slate-100 file:rounded cursor-pointer bg-white"
                />
              </div>

              {/* Logo Preview */}
              {logoPreview && (
                <div className="mt-2 border border-slate-200 rounded p-2 bg-slate-50 relative group w-fit shadow-sm animate-fadeIn">
                  <img
                    src={logoPreview}
                    alt="Logo Preview"
                    className="max-h-24 max-w-full object-contain rounded"
                  />
                  <button
                    type="button"
                    onClick={() => {
                      sf('logo', null)
                      if (fileRef.current) fileRef.current.value = ''
                    }}
                    className="absolute -top-1.5 -right-1.5 bg-red-500 hover:bg-red-600 text-white rounded-full p-0.5 shadow transition-colors flex items-center justify-center w-5 h-5"
                    title="Remove Logo"
                  >
                    <X className="w-3.5 h-3.5" />
                  </button>
                </div>
              )}

              {/* Buttons */}
              <div className="flex gap-2 pt-1">
                <button onClick={handleSave} disabled={saving}
                  className="flex items-center gap-1.5 px-4 py-1.5 bg-[#27ae60] hover:bg-[#229954] text-white text-[13px] font-semibold rounded transition-colors shadow-sm disabled:opacity-60">
                  {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                  {editId !== null ? 'Update' : 'Create'}
                </button>
                <button onClick={handleClear} disabled={saving}
                  className="flex items-center gap-1.5 px-4 py-1.5 bg-red-500 hover:bg-red-600 text-white text-[13px] font-semibold rounded transition-colors shadow-sm disabled:opacity-60">
                  <RotateCcw className="w-4 h-4" /> Clear
                </button>
              </div>
              <button onClick={() => { fetchAll(); setPage(1) }} disabled={tableLoading}
                className="text-[#0097A7] hover:underline text-[13px] font-semibold flex items-center gap-1 disabled:opacity-60">
                {tableLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <List className="w-3.5 h-3.5" />}
                Display All
              </button>
            </Panel>

          </div>
        </div>
      </div>

      {/* ── Table ── */}
      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-[--color-main] px-4 py-2.5">
          <h2 className="text-white text-center font-semibold text-[14px]">Company Master Details</h2>
        </div>
        <div className="flex items-center justify-between px-4 py-3 border-b border-slate-200">
          <div className="flex items-center gap-2 text-[13px] text-slate-600">
            Search:
            <input value={search} onChange={e => { setSearch(e.target.value); setPage(1) }}
              className="border border-slate-300 rounded px-3 py-1 text-[13px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] w-40" />
          </div>
          <div className="flex items-center gap-2 text-[13px] text-slate-600">
            Show
            <select value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setPage(1) }}
              className="border border-slate-300 rounded px-2 py-1 text-[13px]">
              {PAGE_SIZES.map(s => <option key={s}>{s}</option>)}
            </select>
            entries
          </div>
        </div>

        {tableLoading ? (
          <TableSkeleton rows={5} cols={['5%', '8%', '8%', '18%', '10%', '10%', '10%', '13%', '6%', '6%', '6%']} />
        ) : (
        <div className="overflow-x-auto w-full">
          <table className="min-w-full text-[13px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                {['S.No', 'Code', 'Logo', 'Company Name', 'Type', 'City', 'State', 'GSTIN', 'Edit', 'Delete', 'Details'].map(h => (
                  <th key={h} className="text-center px-3 py-2.5 font-semibold text-slate-600 text-[12px] uppercase tracking-wide whitespace-nowrap">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {paged.length === 0 ? (
                <tr><td colSpan={11} className="text-center py-8 text-slate-400">No records found</td></tr>
              ) : paged.map((row, idx) => (
                <tr key={row.id} className={`border-b border-slate-100 hover:bg-slate-50 transition-colors ${idx % 2 === 1 ? 'bg-slate-50/50' : ''}`}>
                  <td className="px-3 py-2 text-center">{(page - 1) * pageSize + idx + 1}</td>
                  <td className="px-3 py-2 text-center font-medium text-[#0097A7]">{row.companyCode}</td>
                  <td className="px-3 py-2 text-center">
                    {row.logoData ? (
                      <img
                        src={`/api/company-master/${row.id}/download-logo`}
                        alt="logo"
                        className="w-8 h-8 rounded-full border border-slate-200 object-cover mx-auto"
                      />
                    ) : (
                      <span className="text-slate-300 text-xs">—</span>
                    )}
                  </td>
                  <td className="px-3 py-2 text-center font-medium">{row.companyName}</td>
                  <td className="px-3 py-2 text-center">{row.companyType}</td>
                  <td className="px-3 py-2 text-center">{row.city}</td>
                  <td className="px-3 py-2 text-center">{row.state}</td>
                  <td className="px-3 py-2 text-center font-mono text-[12px]">{row.gstin}</td>
                  <td className="px-3 py-2 text-center">
                    <button onClick={() => handleEdit(row)}
                      className="px-3 py-1.5 bg-[--color-main] hover:bg-[#3498db] text-white text-[12px] rounded transition-colors">
                      <Edit className="w-4 h-4" />
                    </button>
                  </td>
                  <td className="px-3 py-2 text-center">
                    <button onClick={() => setConfirmDelete(row.id)} disabled={deleting}
                      className="px-3 py-1.5 bg-red-500 hover:bg-red-600 text-white text-[12px] rounded transition-colors disabled:opacity-60">
                      {deleting && confirmDelete === row.id ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                    </button>
                  </td>
                  <td className="px-3 py-2 text-center">
                    <button onClick={() => setDetailRow(row)}
                      className="px-3 py-1.5 bg-[#0097A7] hover:bg-[#007a87] text-white text-[12px] rounded transition-colors">
                      <Info className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        )}

        <div className="flex items-center justify-between px-4 py-3 border-t border-slate-200">
          <span className="text-[12px] text-slate-500">
            Showing {filtered.length === 0 ? 0 : (page - 1) * pageSize + 1} to {Math.min(page * pageSize, filtered.length)} of {filtered.length} entries
          </span>
          <div className="flex items-center gap-1">
            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
              className="px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 transition-colors">Previous</button>
            {pageNums().map((n, i) =>
              n === '...'
                ? <span key={`e${i}`} className="px-2 text-slate-400 text-[12px]">…</span>
                : <button key={n} onClick={() => setPage(n)}
                    className={`w-8 h-8 text-[12px] rounded border transition-colors ${page === n ? 'bg-[#0097A7] text-white border-[#0097A7]' : 'border-slate-300 hover:bg-slate-100 text-slate-600'}`}>
                    {n}
                  </button>
            )}
            <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}
              className="px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 transition-colors">Next</button>
          </div>
        </div>
      </div>

      {detailRow && <DetailModal row={detailRow} onClose={() => setDetailRow(null)} />}
      <ConfirmDialog open={!!confirmDelete} title="Confirm Delete"
        message="Delete this company? This action cannot be undone."
        onConfirm={handleDelete} onCancel={() => setConfirmDelete(null)} />
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import axios from 'axios'
import { X, Save, RotateCcw, List, Edit, Trash2, Info, ChevronRight, Search, Users, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import ConfirmDialog from '../components/ConfirmDialog'

const PAGE_SIZES = [4, 10, 25, 50]
const empty = { Contract_Code: '', Contract_Name: '', Address: '', Phone: '', Email: '', Status: 'Active' }

export default function ContractorMaster() {
  const toast = useToast()
  const [rows, setRows]           = useState([])
  const [form, setForm]           = useState({ ...empty })
  const [errors, setErrors]       = useState({})
  const [editId, setEditId]       = useState(null)
  const [search, setSearch]       = useState('')
  const [pageSize, setPageSize]   = useState(4)
  const [page, setPage]           = useState(1)
  const [detailRow, setDetailRow] = useState(null)
  const [tableLoading, setTableLoading] = useState(false)
  const [saving, setSaving]       = useState(false)
  const [confirmDelete, setConfirmDelete] = useState(null)

  const fetchAll = useCallback(async () => {
    setTableLoading(true)
    try {
      const res = await axios.get('/api/contractor-master')
      setRows(res.data.data || [])
    } catch (err) {
      console.error('[ContractorMaster] fetchAll:', err)
    } finally {
      setTableLoading(false)
    }
  }, [])

  const fetchNextCode = useCallback(async () => {
    try {
      const res = await axios.get('/api/contractor-master/next-code')
      setForm(f => ({ ...f, Contract_Code: res.data.nextCode || '' }))
    } catch (err) {
      console.error('[ContractorMaster] fetchNextCode:', err)
    }
  }, [])

  useEffect(() => { fetchAll(); fetchNextCode() }, [fetchAll, fetchNextCode])

  const sf = (k, v) => { setForm(f => ({ ...f, [k]: v })); setErrors(e => ({ ...e, [k]: '' })) }

  const validate = () => {
    const e = {}
    if (!form.Contract_Name.trim()) e.Contract_Name = 'Required'
    setErrors(e)
    return !Object.keys(e).length
  }

  const handleSave = async () => {
    if (!validate()) return
    setSaving(true)
    try {
      const payload = {
        contractCode:  form.Contract_Code,
        contractName:  form.Contract_Name,
        address:       form.Address,
        phone:         form.Phone,
        email:         form.Email,
        status:        form.Status,
        createdBy:     'Admin',
        updatedBy:     'Admin',
      }
      if (editId !== null) {
        await axios.put(`/api/contractor-master/${editId}`, payload)
        toast.success('Contractor updated successfully.')
      } else {
        await axios.post('/api/contractor-master', payload)
        toast.success('Contractor created successfully.')
      }
      setForm({ ...empty }); setErrors({}); setEditId(null); setPage(1)
      await fetchAll(); await fetchNextCode()
    } catch (err) {
      const status = err?.response?.status
      if (status === 409) {
        toast.error('Contractor code already exists. Please use a different code.')
      } else {
        toast.error(err?.response?.data?.message || 'Failed to save contractor.')
      }
    } finally {
      setSaving(false)
    }
  }

  const handleEdit = r => {
    setForm({
      Contract_Code: r.contractCode,
      Contract_Name: r.contractName,
      Address:       r.address  || '',
      Phone:         r.phone    || '',
      Email:         r.email    || '',
      Status:        r.status   || 'Active',
    })
    setErrors({}); setEditId(r.id)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handleDelete = async () => {
    if (!confirmDelete) return
    try {
      await axios.delete(`/api/contractor-master/${confirmDelete}`)
      toast.success('Contractor deleted.')
      setConfirmDelete(null)
      if (editId === confirmDelete) { setForm({ ...empty }); setEditId(null) }
      await fetchAll()
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to delete contractor.')
    }
  }

  const handleClear = async () => {
    setForm({ ...empty }); setErrors({}); setEditId(null)
    await fetchNextCode()
  }

  const filtered = rows.filter(r =>
    [r.contractCode, r.contractName, r.phone, r.email, r.status, r.address].some(v =>
      String(v || '').toLowerCase().includes(search.toLowerCase())
    )
  )
  const total = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)
  const pNums = () => {
    if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1)
    const ps = [1]
    if (page > 3) ps.push('...')
    for (let i = Math.max(2, page - 1); i <= Math.min(total - 1, page + 1); i++) ps.push(i)
    if (page < total - 2) ps.push('...')
    ps.push(total)
    return ps
  }

  const inputCls = (err) =>
    `w-full border rounded-md px-3 py-1.5 text-[13px] focus:outline-none focus:ring-2 transition-all bg-white ${err
      ? 'border-red-400 focus:ring-red-200'
      : 'border-slate-300 focus:ring-[#0097A7]/30 focus:border-[#0097A7]'
    }`

  const COLS = ['#', 'Code', 'Contractor Name', 'Phone Number', 'Address', 'Status', 'Created Date', 'Created By', 'Edit', 'Delete', 'Details']

  return (
    <div className="p-5 space-y-5 w-full min-w-0 bg-slate-50 min-h-screen">

      {/* Breadcrumb */}
      <div className="flex items-center gap-1.5 text-[12px] text-slate-400">
        {/* <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3" /> */}
        <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Masters</span>
        <ChevronRight className="w-3 h-3" />
        <span className="text-[#0097A7] font-semibold">Contractor Master</span>
      </div>

      {/* Form Card */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-gradient-to-r from-[#0097A7] to-[#00BCD4] px-5 py-3 flex items-center gap-3">
          <div className="w-7 h-7 rounded-full bg-white/20 flex items-center justify-center">
            <Users className="w-4 h-4 text-white" />
          </div>
          <h2 className="text-white font-semibold text-[14px] tracking-wide">
            {editId !== null ? 'Edit' : 'Create'} — Contractor Master Details
          </h2>
          {editId !== null && (
            <span className="ml-auto text-[11px] bg-white/20 text-white px-2.5 py-0.5 rounded-full font-medium">
              Editing ID #{editId}
            </span>
          )}
        </div>

        <div className="p-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-2 max-w-4xl">

            {/* Contractor Code — read-only, auto-generated */}
            <div className="space-y-0.5">
              <label className="text-[12px] font-semibold text-slate-600 flex items-center gap-1">
                Contractor Code
              </label>
              <input
                value={form.Contract_Code}
                readOnly
                className={`${inputCls(false)} bg-slate-50 cursor-not-allowed text-slate-500`}
              />
            </div>

            {/* Contractor Name */}
            <div className="space-y-0.5">
              <label className="text-[12px] font-semibold text-slate-600 flex items-center gap-1">
                <span className="text-red-500">*</span>Contractor Name
              </label>
              <input
                value={form.Contract_Name}
                onChange={e => sf('Contract_Name', e.target.value)}
                placeholder="Enter contractor name"
                className={inputCls(errors.Contract_Name)}
              />
              {errors.Contract_Name && <p className="text-[11px] text-red-500">{errors.Contract_Name}</p>}
            </div>

            {/* Phone */}
            <div className="space-y-0.5">
              <label className="text-[12px] font-semibold text-slate-600">Phone Number</label>
              <input
                value={form.Phone}
                onChange={e => sf('Phone', e.target.value)}
                placeholder="e.g. 9876543210"
                className={inputCls(false)}
              />
            </div>

            {/* Email */}
            <div className="space-y-0.5">
              <label className="text-[12px] font-semibold text-slate-600">Email</label>
              <input
                type="email"
                value={form.Email}
                onChange={e => sf('Email', e.target.value)}
                placeholder="e.g. name@example.com"
                className={inputCls(false)}
              />
            </div>

            {/* Address */}
            <div className="sm:col-span-2 space-y-0.5">
              <label className="text-[12px] font-semibold text-slate-600">Address</label>
              <textarea
                value={form.Address}
                onChange={e => sf('Address', e.target.value)}
                rows={2}
                placeholder="Enter full address"
                className="w-full border border-slate-300 rounded-md px-3 py-1.5 text-[13px] focus:outline-none focus:ring-2 focus:ring-[#0097A7]/30 focus:border-[#0097A7] transition-all resize-none"
              />
            </div>

            {/* Status */}
            <div className="space-y-0.5">
              <label className="text-[12px] font-semibold text-slate-600">Status</label>
              <select value={form.Status} onChange={e => sf('Status', e.target.value)} className={inputCls(false)}>
                <option>Active</option>
                <option>Inactive</option>
              </select>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-2.5 pt-3 mt-3 border-t border-slate-100 justify-start">
            <button onClick={handleSave} disabled={saving}
              className="flex items-center gap-2 px-5 py-2 bg-[#27ae60] hover:bg-[#229954] text-white text-[13px] font-semibold rounded-lg transition-colors shadow-sm disabled:opacity-60">
              {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
              {editId !== null ? 'Update' : 'Create'}
            </button>
            <button onClick={handleClear} disabled={saving}
              className="flex items-center gap-2 px-5 py-2 bg-red-500 hover:bg-red-600 text-white text-[13px] font-semibold rounded-lg transition-colors shadow-sm disabled:opacity-60">
              <RotateCcw className="w-4 h-4" />Clear
            </button>
            <button onClick={() => { fetchAll(); setPage(1) }} disabled={tableLoading}
              className="flex items-center gap-2 px-5 py-2 bg-[#0097A7] hover:bg-[#007a87] text-white text-[13px] font-semibold rounded-lg transition-colors shadow-sm disabled:opacity-60">
              {tableLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <List className="w-4 h-4" />}
              Display All
            </button>
          </div>
        </div>
      </div>

      {/* Table Card */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-gradient-to-r from-[#0097A7] to-[#00BCD4] px-5 py-3">
          <h2 className="text-white font-semibold text-[14px] tracking-wide text-center">Contractor Master Details</h2>
        </div>

        <div className="flex flex-wrap items-center justify-between gap-3 px-5 py-3 border-b border-slate-100 bg-slate-50/60">
          <div className="relative">
            <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
            <input value={search} onChange={e => { setSearch(e.target.value); setPage(1) }}
              placeholder="Search contractors..."
              className="pl-8 pr-3 py-1.5 border border-slate-300 rounded-lg text-[13px] focus:outline-none focus:ring-2 focus:ring-[#0097A7]/30 focus:border-[#0097A7] w-52 transition-all" />
          </div>
          <div className="flex items-center gap-2 text-[13px] text-slate-500">
            <span>Show</span>
            <select value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setPage(1) }}
              className="border border-slate-300 rounded-lg px-2.5 py-1.5 text-[13px] focus:outline-none focus:ring-2 focus:ring-[#0097A7]/30">
              {PAGE_SIZES.map(s => <option key={s}>{s}</option>)}
            </select>
            <span>entries</span>
          </div>
        </div>

        <div className="overflow-x-auto w-full">
          <table className="min-w-full text-[13px]">
            <thead>
              <tr className="bg-slate-50 border-b-2 border-slate-200">
                {COLS.map(h => (
                  <th key={h} className="text-center px-3 py-3 font-bold text-slate-600 text-[11.5px] uppercase tracking-wider whitespace-nowrap">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {tableLoading ? (
                <tr><td colSpan={COLS.length} className="text-center py-12 text-slate-400">
                  <div className="flex items-center justify-center gap-2">
                    <Loader2 className="w-4 h-4 animate-spin text-[#0097A7]" /> Loading...
                  </div>
                </td></tr>
              ) : paged.length === 0 ? (
                <tr><td colSpan={COLS.length} className="text-center py-12 text-slate-400">
                  <div className="flex flex-col items-center gap-2">
                    <Users className="w-8 h-8 text-slate-200" /><span>No records found</span>
                  </div>
                </td></tr>
              ) : paged.map((r, idx) => (
                <tr key={r.id} className={`border-b border-slate-100 hover:bg-[#0097A7]/5 transition-colors ${idx % 2 === 1 ? 'bg-slate-50/40' : ''}`}>
                  <td className="px-3 py-2.5 text-center text-slate-500 font-medium">{(page - 1) * pageSize + idx + 1}</td>
                  <td className="px-3 py-2.5 text-center"><span className="font-semibold text-[#0097A7]">{r.contractCode}</span></td>
                  <td className="px-3 py-2.5 text-center font-medium text-slate-700">{r.contractName}</td>
                  <td className="px-3 py-2.5 text-center text-slate-600">{r.phone || '—'}</td>
                  <td className="px-3 py-2.5 text-center text-slate-600 max-w-[160px] truncate" title={r.address}>{r.address || '—'}</td>
                  <td className="px-3 py-2.5 text-center">
                    <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-semibold gap-1 ${r.status === 'Active'
                      ? 'bg-emerald-100 text-emerald-700 ring-1 ring-emerald-200'
                      : 'bg-slate-100 text-slate-500 ring-1 ring-slate-200'}`}>
                      <span className={`w-1.5 h-1.5 rounded-full ${r.status === 'Active' ? 'bg-emerald-500' : 'bg-slate-400'}`} />
                      {r.status}
                    </span>
                  </td>
                  <td className="px-3 py-2.5 text-center text-slate-500">{r.createdAt ? new Date(r.createdAt).toLocaleDateString() : '—'}</td>
                  <td className="px-3 py-2.5 text-center text-slate-500">{r.createdBy || '—'}</td>
                  <td className="px-3 py-2.5 text-center">
                    <button onClick={() => handleEdit(r)} title="Edit"
                      className="inline-flex items-center justify-center w-8 h-8 bg-[#0097A7] hover:bg-[#007a87] text-white rounded-lg transition-colors shadow-sm">
                      <Edit className="w-3.5 h-3.5" />
                    </button>
                  </td>
                  <td className="px-3 py-2.5 text-center">
                    <button onClick={() => setConfirmDelete(r.id)} title="Delete"
                      className="inline-flex items-center justify-center w-8 h-8 bg-red-500 hover:bg-red-600 text-white rounded-lg transition-colors shadow-sm">
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </td>
                  <td className="px-3 py-2.5 text-center">
                    <button onClick={() => setDetailRow(r)} title="View Details"
                      className="inline-flex items-center justify-center w-8 h-8 bg-slate-600 hover:bg-slate-700 text-white rounded-lg transition-colors shadow-sm">
                      <Info className="w-3.5 h-3.5" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="flex flex-wrap items-center justify-between gap-3 px-5 py-3 border-t border-slate-100 bg-slate-50/60">
          <span className="text-[12px] text-slate-500">
            Showing <span className="font-semibold text-slate-700">{filtered.length === 0 ? 0 : (page - 1) * pageSize + 1}</span> to{' '}
            <span className="font-semibold text-slate-700">{Math.min(page * pageSize, filtered.length)}</span> of{' '}
            <span className="font-semibold text-slate-700">{filtered.length}</span> entries
          </span>
          <div className="flex items-center gap-1">
            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
              className="px-3 py-1.5 text-[12px] border border-slate-300 rounded-lg hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed font-medium text-slate-600 transition-colors">
              Previous
            </button>
            {pNums().map((n, i) =>
              n === '...'
                ? <span key={`e${i}`} className="px-1.5 text-slate-400 text-[13px]">…</span>
                : <button key={n} onClick={() => setPage(n)}
                    className={`w-8 h-8 text-[12px] rounded-lg border font-semibold transition-colors ${page === n ? 'bg-[#0097A7] text-white border-[#0097A7] shadow-sm' : 'border-slate-300 hover:bg-slate-100 text-slate-600'}`}>
                    {n}
                  </button>
            )}
            <button onClick={() => setPage(p => Math.min(total, p + 1))} disabled={page === total}
              className="px-3 py-1.5 text-[12px] border border-slate-300 rounded-lg hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed font-medium text-slate-600 transition-colors">
              Next
            </button>
          </div>
        </div>
      </div>

      {/* Detail Modal */}
      {detailRow && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="bg-gradient-to-r from-[#0097A7] to-[#00BCD4] px-6 py-4 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center">
                  <Users className="w-4 h-4 text-white" />
                </div>
                <h2 className="text-white font-bold text-[15px]">Contractor Details</h2>
              </div>
              <button onClick={() => setDetailRow(null)} className="text-white/70 hover:text-white transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="p-5 space-y-0">
              {[
                ['Code',           detailRow.contractCode],
                ['Contractor Name',detailRow.contractName],
                ['Phone Number',   detailRow.phone],
                ['Email',          detailRow.email],
                ['Address',        detailRow.address],
                ['Status',         detailRow.status],
                ['Created Date',   detailRow.createdAt ? new Date(detailRow.createdAt).toLocaleDateString() : '—'],
                ['Created By',     detailRow.createdBy],
              ].map(([label, value]) => (
                <div key={label} className="flex items-start justify-between py-2.5 border-b border-slate-100 last:border-0">
                  <span className="text-[12px] font-semibold text-slate-400 uppercase tracking-wider w-32 shrink-0">{label}</span>
                  {label === 'Status'
                    ? <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] font-semibold ${value === 'Active' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>
                        <span className={`w-1.5 h-1.5 rounded-full ${value === 'Active' ? 'bg-emerald-500' : 'bg-slate-400'}`} />
                        {value}
                      </span>
                    : <span className="text-[13px] text-slate-800 font-medium text-right flex-1">{value || '—'}</span>
                  }
                </div>
              ))}
            </div>
            <div className="px-6 pb-5 pt-2">
              <button onClick={() => setDetailRow(null)}
                className="w-full py-2.5 text-sm font-semibold text-white bg-[#0097A7] hover:bg-[#007a87] rounded-xl transition-colors">
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!confirmDelete}
        title="Confirm Delete"
        message="Delete this contractor? This action cannot be undone."
        onConfirm={handleDelete}
        onCancel={() => setConfirmDelete(null)}
      />
    </div>
  )
}

