              <button
                onClick={() => setActiveStep(prev => Math.min(5, prev + 1))}
                className="px-4 py-2 border border-[#0097A7] text-[#0097A7] hover:bg-[#0097A7]/10 rounded text-[11px] font-bold transition-all shadow-sm active:scale-95 bg-white"
