import { useState } from 'react'
import {
  Plus, ArrowLeft, Pencil, Trash2, Info, Search,
  ChevronLeft, ChevronRight, ArrowUpDown, CheckCircle2, XCircle,
} from 'lucide-react'
import { useToast } from '../components/Toast'

// ── Seed data (mirrors screenshot rows) ──────────────────────────────────────
const DROPDOWN_NAMES = [
  'Account Type', 'Area', 'Bank', 'Brand', 'Category', 'Country', 'Currency',
  'Department', 'District', 'Division', 'Godown', 'Item Group', 'Item Type',
  'Location', 'Model', 'Payment Mode', 'Prefix', 'QC Type', 'Route',
  'State', 'Status', 'Store', 'Sub Group', 'Tax Ledger', 'UOM', 'Vehicle Type',
]

const SEED = [
  { id: 1, dropdownName: 'Account Type', dropdownList: 'ACCOUNTS', status: 'A' },
  { id: 2, dropdownName: 'Account Type', dropdownList: 'GODOWN', status: 'A' },
  { id: 3, dropdownName: 'Account Type', dropdownList: 'LIABILITIES', status: 'A' },
  { id: 4, dropdownName: 'Account Type', dropdownList: 'OTHER STAFF', status: 'A' },
  { id: 5, dropdownName: 'Account Type', dropdownList: 'BANK COLLECTION', status: 'A' },
  { id: 6, dropdownName: 'Area', dropdownList: 'Valasaraivakkam', status: 'A' },
  { id: 7, dropdownName: 'Area', dropdownList: 'Chennai', status: 'A' },
  { id: 8, dropdownName: 'Area', dropdownList: 'Kanchipuram', status: 'A' },
  { id: 9, dropdownName: 'Brand', dropdownList: 'FAG', status: 'A' },
  { id: 10, dropdownName: 'Brand', dropdownList: 'SKF', status: 'A' },
  { id: 11, dropdownName: 'Currency', dropdownList: 'INR', status: 'A' },
  { id: 12, dropdownName: 'Currency', dropdownList: 'USD', status: 'A' },
  { id: 13, dropdownName: 'UOM', dropdownList: 'NOS', status: 'A' },
  { id: 14, dropdownName: 'UOM', dropdownList: 'KG', status: 'A' },
  { id: 15, dropdownName: 'UOM', dropdownList: 'MTR', status: 'A' },
]

const PAGE_SIZES = [8, 25, 50, 100]

const emptyForm = { dropdownName: '', dropdownList: '' }

// ── Detail Modal ─────────────────────────────────────────────────────────────
function DetailModal({ row, onClose }) {
  return (
    <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden animate-fadeIn">
        <div className="bg-gradient-to-r from-[#0097A7] to-[#00BCD4] px-6 py-4 flex items-center justify-between">
          <h2 className="text-white font-bold text-[15px]">Drop Down List Details</h2>
          <button onClick={onClose}
            className="text-white/80 hover:text-white hover:bg-white/20 rounded-full p-1 transition-colors">
            <XCircle size={20} />
          </button>
        </div>
        <div className="p-6 space-y-2">
          {[
            ['S.No.', row.id],
            ['Drop Down Name', row.dropdownName],
            ['Drop Down List', row.dropdownList],
            ['Status', row.status === 'A' ? 'Active' : 'Inactive'],
          ].map(([lbl, val]) => (
            <div key={lbl} className="flex justify-between py-2 border-b border-slate-100 last:border-0">
              <span className="text-[12px] font-semibold text-slate-500 uppercase tracking-wider">{lbl}</span>
              <span className="text-[13px] text-slate-800 font-medium">{val}</span>
            </div>
          ))}
        </div>
        <div className="px-6 pb-5 flex justify-end">
          <button onClick={onClose}
            className="px-5 py-2 text-sm font-semibold text-white bg-[#0097A7] hover:bg-[#007a87] rounded-lg transition-colors">
            Close
          </button>
        </div>
      </div>
    </div>
  )
}

// ── Main Component ────────────────────────────────────────────────────────────
export default function DropDownListMaster() {
  const toast = useToast()
  const [rows, setRows] = useState(SEED)
  const [form, setForm] = useState(emptyForm)
  const [editId, setEditId] = useState(null)
  const [search, setSearch] = useState('')
  const [pageSize, setPageSize] = useState(8)
  const [page, setPage] = useState(1)
  const [detailRow, setDetailRow] = useState(null)
  const [sortKey, setSortKey] = useState(null)
  const [sortDir, setSortDir] = useState('asc')

  // ── Helpers ────────────────────────────────────────────────────────────────
  const setField = (k, v) => setForm(f => ({ ...f, [k]: v }))

  const handleCreate = () => {
    if (!form.dropdownName) return toast.warning('Drop Down Name is required')
    if (!form.dropdownList) return toast.warning('Drop Down List value is required')

    if (editId !== null) {
      setRows(r => r.map(x => x.id === editId
        ? { ...x, dropdownName: form.dropdownName, dropdownList: form.dropdownList }
        : x))
      setEditId(null)
    } else {
      const newId = Math.max(0, ...rows.map(r => r.id)) + 1
      setRows(r => [...r, { id: newId, dropdownName: form.dropdownName, dropdownList: form.dropdownList, status: 'A' }])
    }
    setForm(emptyForm)
    setPage(1)
  }

  const handleEdit = row => {
    setForm({ dropdownName: row.dropdownName, dropdownList: row.dropdownList })
    setEditId(row.id)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handleDelete = id => {
    if (window.confirm('Delete this record?')) setRows(r => r.filter(x => x.id !== id))
  }

  const handleBackToList = () => { setForm(emptyForm); setEditId(null) }

  const handleSort = key => {
    if (sortKey === key) setSortDir(d => d === 'asc' ? 'desc' : 'asc')
    else { setSortKey(key); setSortDir('asc') }
  }

  // ── Filter + Sort + Paginate ───────────────────────────────────────────────
  let filtered = rows.filter(r =>
    Object.values(r).some(v => String(v).toLowerCase().includes(search.toLowerCase()))
  )
  if (sortKey) {
    filtered = [...filtered].sort((a, b) => {
      const av = String(a[sortKey]).toLowerCase()
      const bv = String(b[sortKey]).toLowerCase()
      return sortDir === 'asc' ? av.localeCompare(bv) : bv.localeCompare(av)
    })
  }
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)

  // Renumber S.No. within paged view
  const startIdx = (page - 1) * pageSize

  // Compact group count by dropdownName for paged rows
  const groupCount = {}
  filtered.forEach(r => { groupCount[r.dropdownName] = (groupCount[r.dropdownName] || 0) + 1 })

  // ── UI helpers ─────────────────────────────────────────────────────────────
  const inputCls = 'w-full border border-slate-300 rounded px-3 py-1.5 text-[13px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] bg-white'
  const selectCls = 'w-full border border-slate-300 rounded px-3 py-1.5 text-[13px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] bg-white'

  const SortIcon = ({ col }) => (
    <ArrowUpDown size={11} className={`inline ml-1 ${sortKey === col ? 'text-[#0097A7]' : 'text-slate-400'}`} />
  )

  return (
    <div className="p-6 space-y-5 w-full min-w-0">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        {/* <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3" /> */}
        <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Item Masters</span>
        <ChevronRight className="w-3 h-3" />
        <span className="text-[#0097A7] font-semibold">Drop Down List Master</span>
      </div>

      {/* ── Create / Edit Form ──────────────────────────────────────────────── */}
      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-[--color-main] px-4 py-2.5">
          <h2 className="text-white text-center font-semibold text-[14px]">
            {editId !== null ? 'Edit - Drop Down List' : 'Create - Drop Down List'}
          </h2>
        </div>

        <div className="p-4 space-y-3">
          {/* Drop Down Name */}
          <div className="flex items-center gap-3">
            <label className="text-[13px] font-semibold text-slate-700 w-36 shrink-0">
              Drop Down Name :
            </label>
            <div className="flex-1 relative">
              <select
                value={form.dropdownName}
                onChange={e => setField('dropdownName', e.target.value)}
                className={selectCls}
              >
                <option value="">---Select---</option>
                {DROPDOWN_NAMES.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </div>
          </div>

          {/* Drop Down List */}
          <div className="flex items-center gap-3">
            <label className="text-[13px] font-semibold text-slate-700 w-36 shrink-0">
              Drop Down List :
            </label>
            <input
              type="text"
              value={form.dropdownList}
              onChange={e => setField('dropdownList', e.target.value)}
              placeholder="Enter drop down list value"
              className="flex-1 border border-slate-300 rounded px-3 py-1.5 text-[13px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] bg-white"
            />
          </div>

          {/* Action buttons */}
          <div className="flex gap-2 pt-1">
            <button
              onClick={handleCreate}
              className="flex items-center gap-1.5 px-4 py-1.5 bg-[#27ae60] hover:bg-[#229954] text-white text-[13px] font-semibold rounded transition-colors shadow-sm"
            >
              <CheckCircle2 size={15} />
              {editId !== null ? 'Update' : 'Create'}
            </button>
            <button
              onClick={handleBackToList}
              className="flex items-center gap-1.5 px-4 py-1.5 bg-[#0097A7] hover:bg-[#007a87] text-white text-[13px] font-semibold rounded transition-colors shadow-sm"
            >
              <ArrowLeft size={15} />
              Back to List
            </button>
            {editId !== null && (
              <button
                onClick={() => { setForm(emptyForm); setEditId(null) }}
                className="px-4 py-1.5 bg-slate-500 hover:bg-slate-600 text-white text-[13px] font-semibold rounded transition-colors"
              >
                Cancel
              </button>
            )}
          </div>
        </div>
      </div>

      {/* ── Data Table ──────────────────────────────────────────────────────── */}
      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-[--color-main] px-4 py-2.5">
          <h2 className="text-white text-center font-semibold text-[14px]">Drop Down List Details</h2>
        </div>

        {/* Controls */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-slate-200">
          <div className="flex items-center gap-2 text-[13px] text-slate-600">
            <Search size={14} className="text-slate-400" />
            Search:
            <input
              value={search}
              onChange={e => { setSearch(e.target.value); setPage(1) }}
              className="border border-slate-300 rounded px-3 py-1 text-[13px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] w-40"
            />
          </div>
          <div className="flex items-center gap-2 text-[13px] text-slate-600">
            Show
            <select
              value={pageSize}
              onChange={e => { setPageSize(Number(e.target.value)); setPage(1) }}
              className="border border-slate-300 rounded px-2 py-1 text-[13px] focus:outline-none focus:ring-1 focus:ring-[#0097A7]"
            >
              {PAGE_SIZES.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
            entries
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto w-full">
          <table className="min-w-full text-[13px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="text-center px-3 py-2.5 font-semibold text-slate-600 text-[12px] uppercase tracking-wide w-14">
                  S.No.
                </th>
                {[
                  { key: 'dropdownName', label: 'Drop Down Name' },
                  { key: 'dropdownList', label: 'Drop Down List' },
                  { key: 'status', label: 'Status' },
                ].map(({ key, label }) => (
                  <th
                    key={key}
                    onClick={() => handleSort(key)}
                    className="text-center px-3 py-2.5 font-semibold text-slate-600 text-[12px] uppercase tracking-wide cursor-pointer hover:bg-slate-100 transition-colors select-none"
                  >
                    {label}
                    <SortIcon col={key} />
                  </th>
                ))}
                {['Edit', 'Delete', 'Details'].map(h => (
                  <th key={h} className="text-center px-3 py-2.5 font-semibold text-slate-600 text-[12px] uppercase tracking-wide w-20">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {paged.length === 0 ? (
                <tr>
                  <td colSpan={7} className="text-center py-10 text-slate-400 text-[13px]">
                    No records found
                  </td>
                </tr>
              ) : paged.map((row, idx) => (
                <tr
                  key={row.id}
                  className={`border-b border-slate-100 hover:bg-[#f0f9fa] transition-colors ${idx % 2 === 1 ? 'bg-slate-50/50' : ''}`}
                >
                  <td className="px-3 py-2.5 text-center text-slate-500">{startIdx + idx + 1}</td>
                  <td className="px-3 py-2.5 text-center font-medium text-slate-700">{row.dropdownName}</td>
                  <td className="px-3 py-2.5 text-center text-slate-600">{row.dropdownList}</td>
                  <td className="px-3 py-2.5 text-center">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded text-[11px] font-bold tracking-wide
                      ${row.status === 'A' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-600'}`}>
                      {row.status}
                    </span>
                  </td>
                  <td className="px-3 py-2.5 text-center">
                    <button
                      onClick={() => handleEdit(row)}
                      title="Edit"
                      className="inline-flex items-center justify-center w-8 h-8 bg-[#0097A7] hover:bg-[#007a87] text-white rounded transition-colors shadow-sm"
                    >
                      <Pencil size={13} />
                    </button>
                  </td>
                  <td className="px-3 py-2.5 text-center">
                    <button
                      onClick={() => handleDelete(row.id)}
                      title="Delete"
                      className="inline-flex items-center justify-center w-8 h-8 bg-red-500 hover:bg-red-600 text-white rounded transition-colors shadow-sm"
                    >
                      <Trash2 size={13} />
                    </button>
                  </td>
                  <td className="px-3 py-2.5 text-center">
                    <button
                      onClick={() => setDetailRow(row)}
                      title="Details"
                      className="inline-flex items-center justify-center w-8 h-8 bg-[#0097A7] hover:bg-[#007a87] text-white rounded transition-colors shadow-sm"
                    >
                      <Info size={13} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-slate-200">
          <span className="text-[12px] text-slate-500">
            Showing {filtered.length === 0 ? 0 : (page - 1) * pageSize + 1} to {Math.min(page * pageSize, filtered.length)} of {filtered.length} entries
          </span>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setPage(p => Math.max(1, p - 1))}
              disabled={page === 1}
              className="flex items-center gap-1 px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft size={13} /> Previous
            </button>
            {Array.from({ length: Math.min(totalPages, 7) }, (_, i) => {
              // smart window around current page
              let n
              if (totalPages <= 7) n = i + 1
              else if (page <= 4) n = i + 1
              else if (page >= totalPages - 3) n = totalPages - 6 + i
              else n = page - 3 + i
              return (
                <button
                  key={n}
                  onClick={() => setPage(n)}
                  className={`w-8 h-8 text-[12px] rounded border transition-colors
                    ${page === n ? 'bg-[#0097A7] text-white border-[#0097A7]' : 'border-slate-300 hover:bg-slate-100 text-slate-600'}`}
                >
                  {n}
                </button>
              )
            })}
            {totalPages > 7 && <span className="text-slate-400 text-[12px] px-1">…</span>}
            {totalPages > 7 && (
              <button
                onClick={() => setPage(totalPages)}
                className={`w-8 h-8 text-[12px] rounded border transition-colors
                  ${page === totalPages ? 'bg-[#0097A7] text-white border-[#0097A7]' : 'border-slate-300 hover:bg-slate-100 text-slate-600'}`}
              >
                {totalPages}
              </button>
            )}
            <button
              onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="flex items-center gap-1 px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              Next <ChevronRight size={13} />
            </button>
          </div>
        </div>
      </div>

      {detailRow && <DetailModal row={detailRow} onClose={() => setDetailRow(null)} />}
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import api from '../services/api'
import { X, Save, RotateCcw, List, Edit, Trash2, Info, ChevronRight, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import ConfirmDialog from '../components/ConfirmDialog'
import { TableSkeleton } from '../components/LocalLoader'

const PAGE_SIZES = [5, 10, 25, 50]

const emptyForm = {
  empCode: '', empName: '', address: '', contactNo: '', adharNo: '',
  joinDate: new Date().toISOString().slice(0, 10), relevingDate: '',
  department: '', designation: '', contractPerson: '', companyName: '',
  team: '', emailId: '', repPerson: '', status: 'Active',
}

const inp = (err) =>
  `w-full border rounded px-2 py-1 text-[13px] focus:outline-none focus:ring-1 transition-colors bg-white ${err ? 'border-red-400 focus:ring-red-300' : 'border-slate-300 focus:ring-[#0097A7] focus:border-[#0097A7]'
  }`
const lbl = 'text-[12.5px] font-semibold text-slate-600 whitespace-nowrap w-36 shrink-0'

// ── Field: label LEFT, input RIGHT ───────────────────────────────────────────
function FI({ label, fk, type = 'text', required, readOnly, form, sf, errors }) {
  return (
    <div className="flex items-center gap-2">
      <label className={lbl}>{required && <span className="text-red-500">*</span>}{label} :</label>
      <div className="flex-1">
        <input type={type} value={form[fk] || ''} onChange={e => sf(fk, e.target.value)}
          readOnly={readOnly}
          className={readOnly ? `${inp(false)} bg-slate-50` : inp(errors[fk])} />
        {errors[fk] && <p className="text-[11px] text-red-500 mt-0.5">{errors[fk]}</p>}
      </div>
    </div>
  )
}

// ── Select: label LEFT, select RIGHT ─────────────────────────────────────────
function FS({ label, fk, opts, required, placeholder, form, sf, errors }) {
  return (
    <div className="flex items-center gap-2">
      <label className={lbl}>{required && <span className="text-red-500">*</span>}{label} :</label>
      <div className="flex-1">
        <select value={form[fk] || ''} onChange={e => sf(fk, e.target.value)} className={inp(errors[fk])}>
          <option value="">{placeholder || `---Select ${label}---`}</option>
          {opts.map(o => <option key={o}>{o}</option>)}
        </select>
        {errors[fk] && <p className="text-[11px] text-red-500 mt-0.5">{errors[fk]}</p>}
      </div>
    </div>
  )
}

// ── Blue-bordered panel ───────────────────────────────────────────────────────
function Panel({ children }) {
  return (
    <div className="border border-[#1a6fa8] rounded overflow-hidden">
      <div className="h-[5px] bg-[#0097A7]" />
      <div className="p-3 h-full flex flex-col justify-evenly gap-2">
        {children}</div>
    </div>
  )
}

// ── Detail Modal ──────────────────────────────────────────────────────────────
function DetailModal({ row, onClose }) {
  const fmt = (v) => {
    if (!v) return '—'
    if (v instanceof Date || (typeof v === 'string' && v.includes('T')))
      return new Date(v).toLocaleDateString('en-IN')
    return v
  }
  return (
    <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden">
        <div className="bg-gradient-to-r from-[#0097A7] to-[#00BCD4] px-6 py-4 flex items-center justify-between">
          <h2 className="text-white font-bold text-[15px]">Employee Details</h2>
          <button onClick={onClose} className="text-white/80 hover:text-white"><X className="w-5 h-5" /></button>
        </div>
        <div className="p-5 grid grid-cols-2 gap-x-6 gap-y-1.5 max-h-[70vh] overflow-y-auto">
          {[
            ['Code', row.empCode], ['Name', row.empName],
            ['Department', row.department], ['Designation', row.designation],
            ['Contractor', row.contractPerson], ['Company', row.companyName],
            ['Contact No', row.contactNo], ['Aadhaar No', row.adharNo],
            ['Join Date', fmt(row.joinDate)], ['Releving Date', fmt(row.relevingDate)],
            ['Team', row.team], ['Email ID', row.emailId],
            ['Reporting Person', row.repPerson], ['Status', row.status],
          ].map(([l, v]) => (
            <div key={l} className="flex flex-col py-1 border-b border-slate-100">
              <span className="text-[11px] font-semibold text-slate-400 uppercase tracking-wider">{l}</span>
              <span className="text-[13px] text-slate-800 font-medium">{v || '—'}</span>
            </div>
          ))}
        </div>
        <div className="px-6 pb-5 flex justify-end">
          <button onClick={onClose} className="px-5 py-2 text-sm font-semibold text-white bg-[#0097A7] hover:bg-[#007a87] rounded-lg transition-colors">Close</button>
        </div>
      </div>
    </div>
  )
}

// ── Main Component ────────────────────────────────────────────────────────────
export default function EmployeeMaster() {
  const toast = useToast()

  const [rows, setRows] = useState([])
  const [companies, setCompanies] = useState([])
  const [departments, setDepartments] = useState([])
  const [designations, setDesignations] = useState([])
  const [contractors, setContractors] = useState([])
  const [tableLoading, setTableLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [deleting, setDeleting] = useState(false)

  const [form, setForm] = useState({ ...emptyForm })
  const [errors, setErrors] = useState({})
  const [editId, setEditId] = useState(null)
  const [search, setSearch] = useState('')
  const [pageSize, setPageSize] = useState(5)
  const [page, setPage] = useState(1)
  const [detailRow, setDetailRow] = useState(null)
  const [confirmDelete, setConfirmDelete] = useState(null)

  const fetchAll = useCallback(async () => {
    setTableLoading(true)
    try {
      const res = await api.get('/api/employee-master')
      setRows(res.data.data || [])
    } catch (err) {
      console.error('[EmployeeMaster] fetchAll:', err)
      toast.error('Failed to load employee records')
    } finally {
      setTableLoading(false)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const fetchNextCode = useCallback(async () => {
    try {
      const res = await api.get('/api/employee-master/next-code')
      setForm(f => ({ ...f, empCode: res.data.nextCode || '' }))
    } catch (err) {
      console.error('[EmployeeMaster] fetchNextCode:', err)
    }
  }, [])

  const fetchCompanies = useCallback(async () => {
    try {
      const res = await api.get('/api/company-master')
      setCompanies((res.data.data || []).map(c => c.companyName))
    } catch {
      setCompanies([])
    }
  }, [])

  const fetchDepartments = useCallback(async () => {
    try {
      const res = await api.get('/api/reference-master/Department')
      setDepartments((res.data.data || []).map(d => d.description))
    } catch {
      setDepartments([])
    }
  }, [])

  const fetchDesignations = useCallback(async () => {
    try {
      const res = await api.get('/api/reference-master/Designation')
      setDesignations((res.data.data || []).map(d => d.description))
    } catch {
      setDesignations([])
    }
  }, [])

  const fetchContractors = useCallback(async () => {
    try {
      const res = await api.get('/api/contractor-master')
      setContractors((res.data.data || []).map(c => c.contractName))
    } catch {
      setContractors([])
    }
  }, [])

  useEffect(() => {
    fetchAll(); fetchNextCode(); fetchCompanies()
    fetchDepartments(); fetchDesignations(); fetchContractors()
  }, [fetchAll, fetchNextCode, fetchCompanies, fetchDepartments, fetchDesignations, fetchContractors])

  const sf = (k, v) => { setForm(f => ({ ...f, [k]: v })); setErrors(e => ({ ...e, [k]: '' })) }

  const validate = () => {
    const errs = {}
    if (!form.empName.trim()) errs.empName = 'Required'
    if (!form.department) errs.department = 'Required'
    if (!form.designation) errs.designation = 'Required'
    if (!form.companyName) errs.companyName = 'Required'
    setErrors(errs)
    return Object.keys(errs).length === 0
  }

  const handleSave = async () => {
    if (!validate()) return
    setSaving(true)
    try {
      if (editId !== null) {
        await api.put(`/api/employee-master/${editId}`, form)
        toast.success('Employee updated successfully.')
      } else {
        await api.post('/api/employee-master', form)
        toast.success('Employee created successfully.')
      }
      setForm({ ...emptyForm }); setErrors({}); setEditId(null); setPage(1)
      await fetchAll(); await fetchNextCode()
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to save employee.')
    } finally {
      setSaving(false)
    }
  }

  const handleEdit = row => {
    const toDateStr = (v) => v ? new Date(v).toISOString().slice(0, 10) : ''
    setForm({
      empCode: row.empCode || '',
      empName: row.empName || '',
      address: row.address || '',
      contactNo: row.contactNo || '',
      adharNo: row.adharNo || '',
      joinDate: toDateStr(row.joinDate),
      relevingDate: toDateStr(row.relevingDate),
      department: row.department || '',
      designation: row.designation || '',
      contractPerson: row.contractPerson || '',
      companyName: row.companyName || '',
      team: row.team || '',
      emailId: row.emailId || '',
      repPerson: row.repPerson || '',
      status: row.status || 'Active',
    })
    setErrors({}); setEditId(row.id)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handleDelete = async () => {
    if (!confirmDelete) return
    setDeleting(true)
    try {
      await api.delete(`/api/employee-master/${confirmDelete}`)
      toast.success('Employee deleted.')
      setConfirmDelete(null)
      if (editId === confirmDelete) { setForm({ ...emptyForm }); setEditId(null) }
      await fetchAll()
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to delete.')
    } finally {
      setDeleting(false)
    }
  }

  const handleClear = async () => {
    setForm({ ...emptyForm }); setErrors({}); setEditId(null)
    await fetchNextCode()
  }

  const filtered = rows.filter(r =>
    [r.empCode, r.empName, r.department, r.designation, r.contactNo, r.status]
      .some(v => String(v || '').toLowerCase().includes(search.toLowerCase()))
  )
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)
  const pageNums = () => {
    if (totalPages <= 7) return Array.from({ length: totalPages }, (_, i) => i + 1)
    const ps = [1]
    if (page > 3) ps.push('...')
    for (let i = Math.max(2, page - 1); i <= Math.min(totalPages - 1, page + 1); i++) ps.push(i)
    if (page < totalPages - 2) ps.push('...')
    ps.push(totalPages)
    return ps
  }

  const fmt = (v) => v ? new Date(v).toLocaleDateString('en-IN') : '—'
  const fp = { form, sf, errors }

  return (
    <div className="p-4 space-y-4 w-full min-w-0">

      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3" /> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Masters</span>
        <ChevronRight className="w-3 h-3" />
        <span className="text-[#0097A7] font-semibold">Employee Master</span>
      </div>

      {/* ── Title ── */}
      <h2 className="text-center text-[15px] font-bold text-[#0097A7]">Employee Master Details</h2>

      {/* ── Form: 3 panels ── */}
      <div className="grid grid-cols-3 gap-3">

        {/* Panel 1 */}
        <Panel>
          <FI {...fp} label="Employee Code" fk="empCode" required readOnly />
          <FI {...fp} label="Employee Name" fk="empName" required />
          <FI {...fp} label="Address" fk="address" />
          <FI {...fp} label="Contact No" fk="contactNo" />
        </Panel>

        {/* Panel 2 */}
        <Panel>
          <FI {...fp} label="Adhar No" fk="adharNo" />
          <FI {...fp} label="Join Date" fk="joinDate" type="date" />
          <FI {...fp} label="Releving Date" fk="relevingDate" type="date" />
          <FS {...fp} label="Department Name" fk="department" opts={departments} required
            placeholder="---Select Department Name---" />
        </Panel>

        {/* Panel 3 */}
        <Panel>
          <FS {...fp} label="Designation Name" fk="designation" opts={designations} required
            placeholder="---Select Designation Name---" />
          <FS {...fp} label="Contract Person" fk="contractPerson" opts={contractors}
            placeholder="---Select Contractor Name---" />
          <FS {...fp} label="Company Name" fk="companyName"
            opts={companies.length ? companies : ['VELSON INDUSTRIES PVT LTD', 'VELSON SERVICES LLP']}
            required placeholder="---Select Company Name---" />

        </Panel>

      </div>
      {/* Buttons */}
      <div className="flex items-center gap-2 pt-1 justify-end">
        <button onClick={handleSave} disabled={saving}
          className="flex items-center gap-1.5 px-4 py-1.5 bg-[#27ae60] hover:bg-[#229954] text-white text-[13px] font-semibold rounded transition-colors shadow-sm disabled:opacity-60">
          {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
          {editId !== null ? 'Update' : 'Create'}
        </button>
        <button onClick={handleClear} disabled={saving}
          className="flex items-center gap-1.5 px-4 py-1.5 bg-red-500 hover:bg-red-600 text-white text-[13px] font-semibold rounded transition-colors shadow-sm disabled:opacity-60">
          <RotateCcw className="w-4 h-4" /> Clear
        </button>
        <button onClick={() => { fetchAll(); setPage(1) }} disabled={tableLoading}
          className="flex items-center gap-1.5 px-4 py-1.5 bg-[#0097A7] hover:bg-[#007a87] text-white text-[13px] font-semibold rounded transition-colors shadow-sm disabled:opacity-60">
          {tableLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <List className="w-4 h-4" />}
          Display All
        </button>
      </div>

      {/* ── Table ── */}
      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-[#0097A7] px-4 py-2.5">
          <h2 className="text-white text-center font-semibold text-[14px]">Employee Master Details</h2>
        </div>
        <div className="flex items-center justify-between px-4 py-3 border-b border-slate-200">
          <div className="flex items-center gap-2 text-[13px] text-slate-600">
            Search:
            <input value={search} onChange={e => { setSearch(e.target.value); setPage(1) }}
              className="border border-slate-300 rounded px-3 py-1 text-[13px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] w-40" />
          </div>
          <div className="flex items-center gap-2 text-[13px] text-slate-600">
            Show
            <select value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setPage(1) }}
              className="border border-slate-300 rounded px-2 py-1 text-[13px]">
              {PAGE_SIZES.map(s => <option key={s}>{s}</option>)}
            </select>
            entries
          </div>
        </div>

        {tableLoading ? (
          <TableSkeleton rows={5} cols={['5%', '7%', '12%', '10%', '8%', '8%', '8%', '8%', '7%', '7%', '7%', '8%', '7%', '7%', '7%']} />
        ) : (
          <div className="overflow-x-auto w-full">
            <table className="min-w-full text-[12px]">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-200">
                  {['Code', 'EmployeeName', 'Address', 'ContactNo', 'AdharNo', 'JoinDate', 'RelevingDate',
                    'Department', 'Designation', 'Team', 'EmailID', 'ContractName', 'CreatedBy', 'CreatedDate',
                    'Status', 'Edit', 'Delete', 'Details'].map(h => (
                      <th key={h} className="text-center px-2 py-2.5 font-semibold text-slate-600 text-[11px] uppercase tracking-wide whitespace-nowrap">{h}</th>
                    ))}
                </tr>
              </thead>
              <tbody>
                {paged.length === 0 ? (
                  <tr><td colSpan={19} className="text-center py-8 text-slate-400">No records found</td></tr>
                ) : paged.map((row, idx) => (
                  <tr key={row.id} className={`border-b border-slate-100 hover:bg-slate-50 transition-colors ${idx % 2 === 1 ? 'bg-slate-50/50' : ''}`}>
                    {/* <td className="px-2 py-2 text-center">{row.id}</td> */}
                    <td className="px-2 py-2 text-center font-medium text-[#0097A7]">{row.empCode}</td>
                    <td className="px-2 py-2 text-center font-medium">{row.empName}</td>
                    <td className="px-2 py-2 text-center">{row.address}</td>
                    <td className="px-2 py-2 text-center">{row.contactNo}</td>
                    <td className="px-2 py-2 text-center">{row.adharNo}</td>
                    <td className="px-2 py-2 text-center whitespace-nowrap">{fmt(row.joinDate)}</td>
                    <td className="px-2 py-2 text-center whitespace-nowrap">{fmt(row.relevingDate)}</td>
                    <td className="px-2 py-2 text-center">{row.department}</td>
                    <td className="px-2 py-2 text-center">{row.designation}</td>
                    <td className="px-2 py-2 text-center">{row.team}</td>
                    <td className="px-2 py-2 text-center">{row.emailId}</td>
                    <td className="px-2 py-2 text-center">{row.contractPerson}</td>
                    <td className="px-2 py-2 text-center">{row.createdBy}</td>
                    <td className="px-2 py-2 text-center whitespace-nowrap">{fmt(row.createdAt)}</td>
                    <td className="px-2 py-2 text-center">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] font-semibold ${row.status === 'Active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-600'}`}>
                        {row.status}
                      </span>
                    </td>
                    <td className="px-2 py-2 text-center">
                      <button onClick={() => handleEdit(row)}
                        className="px-2.5 py-1.5 bg-[--color-main] hover:bg-[#3498db] text-white rounded transition-colors">
                        <Edit className="w-3.5 h-3.5" />
                      </button>
                    </td>
                    <td className="px-2 py-2 text-center">
                      <button onClick={() => setConfirmDelete(row.id)} disabled={deleting}
                        className="px-2.5 py-1.5 bg-red-500 hover:bg-red-600 text-white rounded transition-colors disabled:opacity-60">
                        {deleting && confirmDelete === row.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
                      </button>
                    </td>
                    <td className="px-2 py-2 text-center">
                      <button onClick={() => setDetailRow(row)}
                        className="px-2.5 py-1.5 bg-[#0097A7] hover:bg-[#007a87] text-white rounded transition-colors">
                        <Info className="w-3.5 h-3.5" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        <div className="flex items-center justify-between px-4 py-3 border-t border-slate-200">
          <span className="text-[12px] text-slate-500">
            Showing {filtered.length === 0 ? 0 : (page - 1) * pageSize + 1} to {Math.min(page * pageSize, filtered.length)} of {filtered.length} entries
          </span>
          <div className="flex items-center gap-1">
            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
              className="px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 transition-colors">Previous</button>
            {pageNums().map((n, i) =>
              n === '...'
                ? <span key={`e${i}`} className="px-2 text-slate-400 text-[12px]">…</span>
                : <button key={n} onClick={() => setPage(n)}
                  className={`w-8 h-8 text-[12px] rounded border transition-colors ${page === n ? 'bg-[#0097A7] text-white border-[#0097A7]' : 'border-slate-300 hover:bg-slate-100 text-slate-600'}`}>
                  {n}
                </button>
            )}
            <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}
              className="px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 transition-colors">Next</button>
          </div>
        </div>
      </div>

      {detailRow && <DetailModal row={detailRow} onClose={() => setDetailRow(null)} />}
      <ConfirmDialog open={!!confirmDelete} title="Confirm Delete"
        message="Delete this employee? This action cannot be undone."
        onConfirm={handleDelete} onCancel={() => setConfirmDelete(null)} />
    </div>
  )
}

import { useState, useEffect } from 'react'
import api from '../services/api'
import { ChevronRight, Plus, Trash2, Send, X, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import { SpinnerLoader } from '../components/LocalLoader'

// Currencies fetched from reference master
const CURRENCY_TYPES = ['EXPORT','DOMESTIC']
// Tax Types are fetched dynamically from reference master (see useEffect below)
// Default tax % per Tax Type description (case-insensitive match)
const TAX_RATE_MAP = { 'LOCAL': 18, 'INTER': 28 }
// QC Types fetched from reference master

const today = new Date().toISOString().split('T')[0]

const emptyItem = () => ({ itemCode:'', itemName:'', supplierPartNo:'', description:'', hsnCode:'', unit:'', stockQty:'', orderQty:'', qty:'', unitPrice:'', total:'', discPer:'', discAmt:'', finalPrice:'', taxPer:'', netAmt:'' })
const emptyFreightRow = () => ({ freightName:'', amount:'', taxPer:'', gstAmt:'0', igstAmt:'0', netTotal:'0' })

const DEFAULT_FREIGHT_NAMES = [
  'Freight Inward',
  'Freight Outward',
  'Gas cutting Charge',
  'HANDLING CHARGES',
  'OTHERS',
  'Packing and forwading',
  'TESTING CHARGES',
  'Accommodation Charges',
]
const defaultFreightRows = () => DEFAULT_FREIGHT_NAMES.map(name => ({ ...emptyFreightRow(), freightName: name }))

const inp = (err='') => `w-full border rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 transition-colors bg-white ${err?'border-red-400 focus:ring-red-300':'border-slate-300 focus:ring-[#0097A7] focus:border-[#0097A7]'}`
const lbl = 'text-[12px] font-semibold text-slate-600 whitespace-nowrap'

export default function GRNEntry() {
  const toast = useToast()
  const [grnTypes, setGrnTypes] = useState([])
  const [taxTypes, setTaxTypes] = useState([])
  const [purchaseLedgers, setPurchaseLedgers] = useState([])
  const [purchaseTypes, setPurchaseTypes] = useState([])
  const [qcTypes, setQcTypes] = useState([])
  const [currencies, setCurrencies] = useState([])
  const [submitting, setSubmitting] = useState(false)
  const [refLoading, setRefLoading] = useState(true)
  const [itemsLoading, setItemsLoading] = useState(false)
  const [editId, setEditId] = useState(null)
  const [suppliersData, setSuppliersData] = useState([])

  useEffect(() => {
    setRefLoading(true)
    const fetches = [
      api.get(`/api/reference-master/${encodeURIComponent('GRN_Type')}`, { skipGlobalLoader: true })
        .then(res => {
          const types = (res.data.data || []).map(r => r.description || r.code).filter(Boolean)
          setGrnTypes(types)
          if (types.length) setForm(f => ({ ...f, grnType: f.grnType || types[0] }))
        }).catch(() => {}),

      api.get(`/api/reference-master/${encodeURIComponent('Tax Type')}`, { skipGlobalLoader: true })
        .then(res => {
          const types = (res.data.data || []).map(r => r.description || r.code).filter(Boolean)
          setTaxTypes(types)
          if (types.length) setForm(f => ({ ...f, taxType: f.taxType || types[0] }))
        }).catch(() => {}),

      api.get(`/api/reference-master/${encodeURIComponent('Purchase_Ledger')}`, { skipGlobalLoader: true })
        .then(res => {
          const types = (res.data.data || []).map(r => r.description || r.code).filter(Boolean)
          setPurchaseLedgers(types)
          if (types.length) setForm(f => ({ ...f, purchaseLedger: f.purchaseLedger || types[0] }))
        }).catch(() => {}),

      api.get('/api/supplier-master', { skipGlobalLoader: true })
        .then(res => {
          setSuppliersData(res.data.data || [])
        }).catch(() => {}),

      api.get(`/api/reference-master/${encodeURIComponent('PAYMODE')}`, { skipGlobalLoader: true })
        .then(res => {
          const types = (res.data.data || []).map(r => r.description || r.code).filter(Boolean)
          setPurchaseTypes(types)
          if (types.length) setForm(f => ({ ...f, purchaseType: f.purchaseType || types[0] }))
        }).catch(() => {}),

      api.get(`/api/reference-master/${encodeURIComponent('QC_Type')}`, { skipGlobalLoader: true })
        .then(res => {
          const types = (res.data.data || []).map(r => r.description || r.code).filter(Boolean)
          setQcTypes(types)
          if (types.length) setForm(f => ({ ...f, qcType: f.qcType || types[0] }))
        }).catch(() => {}),

      api.get(`/api/reference-master/${encodeURIComponent('Currency')}`, { skipGlobalLoader: true })
        .then(res => {
          const types = (res.data.data || []).map(r => r.description || r.code).filter(Boolean)
          setCurrencies(types)
          if (types.length) setForm(f => ({ ...f, currency: f.currency || types[0] }))
        }).catch(() => {}),
    ]

    const nav = window.__velsonNav || {}
    window.__velsonNav = null
    if (nav.editId) {
      Promise.allSettled(fetches).finally(() => loadForEdit(nav.editId))
    } else {
      // Fetch next GRN number for new entry
      api.get('/api/grn-master/next-no', { skipGlobalLoader: true })
        .then(res => {
          if (res.data.grnNo) {
            setForm(f => ({ ...f, grnNo: res.data.grnNo, financialYear: res.data.financialYear || '' }))
          }
        })
        .catch(() => {})
      Promise.allSettled(fetches).finally(() => setRefLoading(false))
    }
  }, [])

  const loadForEdit = async (id) => {
    try {
      const res = await api.get(`/api/grn-master/${id}`, { skipGlobalLoader: true })
      const grn = res.data.data
      if (!grn) return
      setEditId(grn.id)
      setForm({
        grnType:       grn.grnType       || '',
        gateEntryNo:   grn.gateEntryNo   || '',
        supplierName:  grn.supplierName  || '',
        purchaseLedger:grn.purchaseLedger|| '',
        purchaseType:  grn.purchaseType  || '',
        currency:      grn.currency      || '',
        currencyType:  grn.currencyType  || 'EXPORT',
        contactPerson: grn.contactPerson || '',
        contactNo:     grn.contactNo     || '',
        poNo:          grn.poNo          || '',
        poDate:        grn.poDate ? grn.poDate.split('T')[0] : today,
        taxType:       grn.taxType       || '',
        exchangeRate:  grn.exchangeRate != null ? String(grn.exchangeRate) : '',
        grnNo:         grn.grnNo,
        financialYear: grn.financialYear || '',
        grnDate:       grn.grnDate ? grn.grnDate.split('T')[0] : today,
        invoiceNo:     grn.invoiceNo     || '0',
        invoiceDate:   grn.invoiceDate ? grn.invoiceDate.split('T')[0] : today,
        qcType:        grn.qcType        || '',
        discountType:  grn.discountType  || 'Dis_Per',
      })
      setRemarks(grn.remarks || '')
      setCurrencyTotal(grn.currencyTotal != null ? String(grn.currencyTotal) : '')
      setRoundOff(grn.roundOff != null ? String(grn.roundOff) : '')
      setFreightLedger(grn.freightLedger || 'FREIGHT A/C')
      setTcsLedger(grn.tcsLedger || 'TCS A/C')
      setOthersAmt(grn.othersAmt != null ? String(grn.othersAmt) : '')
      setOgstAmtVal(grn.ogstAmt != null ? String(grn.ogstAmt) : '')
      setTcsAmtVal(grn.tcsAmt != null ? String(grn.tcsAmt) : '')
      setItems(grn.details?.length > 0 ? grn.details.map(d => ({
        itemCode:       d.itemCode       || '',
        itemName:       d.itemName       || '',
        supplierPartNo: d.supplierPartNo || '',
        description:    d.description   || '',
        hsnCode:        d.hsnCode        || '',
        unit:           d.unit           || '',
        stockQty:       d.stockQty != null ? String(d.stockQty) : '',
        orderQty:       d.orderQty != null ? String(d.orderQty) : '',
        qty:            d.qty      != null ? String(d.qty)      : '',
        unitPrice:      d.unitPrice!= null ? String(d.unitPrice): '',
        total:          d.total    != null ? String(d.total)    : '',
        discPer:        d.discPer  != null ? String(d.discPer)  : '',
        discAmt:        d.discAmt  != null ? String(d.discAmt)  : '',
        finalPrice:     d.finalPrice!=null ? String(d.finalPrice): '',
        taxPer:         d.taxPer   != null ? String(d.taxPer)   : '',
        netAmt:         d.netAmt   != null ? String(d.netAmt)   : '',
      })) : [emptyItem()])
    } catch {
      toast.error('Failed to load GRN entry for editing')
    } finally {
      setRefLoading(false)
    }
  }

  const [form, setForm] = useState({
    grnType:'', gateEntryNo:'', supplierName:'', purchaseLedger:'',
    purchaseType:'', currency:'', currencyType:'EXPORT',
    contactPerson:'', contactNo:'', poNo:'', poDate:today, taxType:'', exchangeRate:'',
    grnNo:'', financialYear:'', grnDate:today, invoiceNo:'0', invoiceDate:today, qcType:'',
    discountType:'Dis_Per',
  })
  const [items, setItems] = useState([emptyItem()])
  const [remarks, setRemarks] = useState('')
  const [currencyTotal, setCurrencyTotal] = useState('')
  const [roundOff, setRoundOff] = useState('')
  const [freightLedger, setFreightLedger] = useState('FREIGHT A/C')
  const [tcsLedger, setTcsLedger] = useState('TCS A/C')

  const [showFreightPopup, setShowFreightPopup] = useState(false)
  const [freightRows, setFreightRows] = useState(defaultFreightRows())
  const [othersAmt, setOthersAmt] = useState('')
  const [ogstAmtVal, setOgstAmtVal] = useState('')
  const [tcsAmtVal, setTcsAmtVal] = useState('')

  const [showGateModal, setShowGateModal] = useState(false)
  const [gateEntries, setGateEntries] = useState([])
  const [gateSearch, setGateSearch] = useState('')
  const [gateLoading, setGateLoading] = useState(false)

  const openGateSearch = () => {
    setShowGateModal(true)
    setGateSearch('')
    setGateLoading(true)
    api.get('/api/gate-master', { skipGlobalLoader: true })
      .then(res => setGateEntries(res.data.data || []))
      .catch(() => setGateEntries([]))
      .finally(() => setGateLoading(false))
  }

  const calcItemRow = (row) => {
    const q = parseFloat(row.qty) || 0
    const up = parseFloat(row.unitPrice) || 0
    const tot = q * up
    const dp = parseFloat(row.discPer) || 0
    const da = tot * dp / 100
    const tp = parseFloat(row.taxPer) || 0
    return { ...row, total: tot.toFixed(2), discAmt: da.toFixed(2), finalPrice: (tot - da).toFixed(2), netAmt: ((tot - da) * (1 + tp / 100)).toFixed(2) }
  }

  const handleSupplierChange = (name) => {
    const sup = suppliersData.find(s => s.supplierName === name)
    setForm(f => ({
      ...f,
      supplierName: name,
      ...(sup ? {
        contactPerson: sup.contactPerson || f.contactPerson,
        contactNo: sup.mobile || sup.phone || f.contactNo,
        purchaseLedger: sup.purchaseLedger || f.purchaseLedger,
      } : {})
    }))
  }

  const selectGateEntry = (entry) => {
    const gateSupplierName = entry.supplierName || ''
    const sup = suppliersData.find(s => s.supplierName === gateSupplierName)

    setForm(f => ({
      ...f,
      gateEntryNo: entry.gateEntryNo,
      supplierName: gateSupplierName,
      poNo: entry.poNo || '',
      invoiceNo: entry.invoiceNo || '',
      invoiceDate: entry.invoiceDate ? entry.invoiceDate.split('T')[0] : f.invoiceDate,
      ...(sup ? {
        purchaseLedger: sup.purchaseLedger || f.purchaseLedger,
      } : {})
    }))
    const gateItems = (entry.details || []).map(d => ({
      ...emptyItem(),
      itemCode: d.itemCode || '',
      itemName: d.itemName || '',
      supplierPartNo: d.supplierPartNo || '',
      description: d.description || '',
      hsnCode: d.hsnCode || '',
      unit: d.unit || '',
      orderQty: String(d.qty || ''),
      qty: String(d.recQty || ''),
    }))
    if (entry.poId) {
      setItemsLoading(true)
      api.get(`/api/purchase-master/${entry.poId}`, { skipGlobalLoader: true })
        .then(res => {
          const po = res.data.data
          if (!po) { if (gateItems.length) setItems(gateItems); return }
          setForm(f => ({
            ...f,
            contactPerson: po.contactPerson || '',
            contactNo: po.contactNumber || po.supplier?.mobile || po.supplier?.phone || '',
            poDate: po.poDate ? po.poDate.split('T')[0] : f.poDate,
            purchaseLedger: po.supplier?.purchaseLedger || f.purchaseLedger,
            supplierName: po.supplier?.supplierName || f.supplierName,
          }))
          // Enrich gate items with unitPrice, discPer, taxPer from PO details
          if (po.details && po.details.length && gateItems.length) {
            setItems(gateItems.map(gi => {
              const pd = po.details.find(d => d.itemCode === gi.itemCode)
              if (!pd) return gi
              return calcItemRow({
                ...gi,
                unitPrice: String(pd.unitPrice || ''),
                discPer: String(pd.discPer || ''),
                taxPer: String(pd.gstPer || ''),
              })
            }))
          } else if (gateItems.length) {
            setItems(gateItems)
          }
        })
        .catch(() => { if (gateItems.length) setItems(gateItems) })
        .finally(() => setItemsLoading(false))
    } else if (gateItems.length) {
      setItems(gateItems)
    }
    setShowGateModal(false)
  }

  const filteredGateEntries = gateEntries.filter(e => {
    const q = gateSearch.toLowerCase()
    return !q || (e.gateEntryNo||'').toLowerCase().includes(q)
      || (e.supplierName||'').toLowerCase().includes(q)
      || (e.poNo||'').toLowerCase().includes(q)
      || (e.invoiceNo||'').toLowerCase().includes(q)
  })

  const [showPoModal, setShowPoModal] = useState(false)
  const [poList, setPoList] = useState([])
  const [poSearch, setPoSearch] = useState('')
  const [poLoading, setPoLoading] = useState(false)

  const openPoSearch = () => {
    setShowPoModal(true)
    setPoSearch('')
    setPoLoading(true)
    api.get('/api/purchase-master', { skipGlobalLoader: true })
      .then(res => setPoList(res.data.data || []))
      .catch(() => setPoList([]))
      .finally(() => setPoLoading(false))
  }

  const selectPo = (po) => {
    setForm(f => ({
      ...f,
      poNo: po.poNo || '',
      poDate: po.poDate ? po.poDate.split('T')[0] : f.poDate,
      contactPerson: po.contactPerson || '',
      contactNo: po.contactNumber || po.supplier?.mobile || po.supplier?.phone || '',
      supplierName: po.supplier?.supplierName || f.supplierName,
      purchaseLedger: po.supplier?.purchaseLedger || f.purchaseLedger,
    }))
    // Populate items from PO details (itemCode, itemName, unitPrice, etc.)
    if (po.details && po.details.length) {
      setItems(po.details.map(d => calcItemRow({
        ...emptyItem(),
        itemCode: d.itemCode || '',
        itemName: d.itemName || '',
        supplierPartNo: d.supplierPartNo || '',
        description: d.description || '',
        hsnCode: d.hsnCode || '',
        unit: d.uom || '',
        orderQty: String(d.qty || ''),
        qty: String(d.qty || ''),
        unitPrice: String(d.unitPrice || ''),
        discPer: String(d.discPer || ''),
        taxPer: String(d.gstPer || ''),
      })))
    }
    setShowPoModal(false)
  }

  const filteredPoList = poList.filter(p => {
    const q = poSearch.toLowerCase()
    return !q || (p.poNo||'').toLowerCase().includes(q)
      || (p.supplier?.supplierName||'').toLowerCase().includes(q)
      || (p.contactPerson||'').toLowerCase().includes(q)
  })

  const applyTaxRate = (rate) => {
    setItems(rows => rows.map(r => {
      const q = parseFloat(r.qty) || 0
      const p = parseFloat(r.unitPrice) || 0
      const tot = q * p
      const dp = parseFloat(r.discPer) || 0
      const da = tot * dp / 100
      const finalPrice = (tot - da).toFixed(2)
      const netAmt = ((tot - da) * (1 + rate / 100)).toFixed(2)
      return { ...r, taxPer: String(rate), finalPrice, netAmt }
    }))
  }

  const setField = (k, v) => {
    setForm(f => ({ ...f, [k]: v }))
    if (k === 'taxType') {
      const rate = TAX_RATE_MAP[v.toUpperCase()]
      if (rate !== undefined) applyTaxRate(rate)
    }
  }

  const setItemField = (idx,k,v) => {
    setItems(rows=>rows.map((r,i)=>{
      if(i!==idx) return r
      const u={...r,[k]:v}
      const q=parseFloat(k==='qty'?v:u.qty)||0
      const p=parseFloat(k==='unitPrice'?v:u.unitPrice)||0
      const tot=q*p; u.total=tot.toFixed(2)
      const dp=parseFloat(k==='discPer'?v:u.discPer)||0
      const da=tot*dp/100; u.discAmt=da.toFixed(2)
      u.finalPrice=(tot-da).toFixed(2)
      const tp=parseFloat(k==='taxPer'?v:u.taxPer)||0
      u.netAmt=((tot-da)*(1+tp/100)).toFixed(2)
      return u
    }))
  }

  const addRow = () => setItems(r=>[...r,emptyItem()])
  const removeRow = idx => setItems(r=>r.filter((_,i)=>i!==idx))

  const subTotal = items.reduce((s,r)=>s+(parseFloat(r.finalPrice)||0),0)

  const isInterTax = (form.taxType || '').toUpperCase().includes('INTER')
  const totalItemTaxAmt = items.reduce((s,r) => s + ((parseFloat(r.netAmt)||0) - (parseFloat(r.finalPrice)||0)), 0)
  const computedGstAmt = isInterTax ? 0 : totalItemTaxAmt
  const computedIgstAmt = isInterTax ? totalItemTaxAmt : 0
  const grandTotal = subTotal + computedGstAmt + computedIgstAmt
    + parseFloat(ogstAmtVal || 0) + parseFloat(othersAmt || 0)
    + parseFloat(tcsAmtVal || 0) - parseFloat(roundOff || 0)

  const calcFreightRow = (row) => {
    const amt = parseFloat(row.amount) || 0
    const tp = parseFloat(row.taxPer) || 0
    const taxAmt = amt * tp / 100
    const gstAmt = isInterTax ? 0 : taxAmt
    const igstAmt = isInterTax ? taxAmt : 0
    return { ...row, gstAmt: gstAmt.toFixed(2), igstAmt: igstAmt.toFixed(2), netTotal: (amt + gstAmt + igstAmt).toFixed(2) }
  }

  const setFreightRowField = (idx, k, v) => {
    setFreightRows(rows => rows.map((r, i) => {
      if (i !== idx) return r
      const updated = { ...r, [k]: v }
      return (k === 'amount' || k === 'taxPer') ? calcFreightRow(updated) : updated
    }))
  }

  const freightPopupTotal = freightRows.reduce((s, r) => s + (parseFloat(r.netTotal) || 0), 0)

  const freightBaseTotal = freightRows.reduce((s, r) => s + (parseFloat(r.amount) || 0), 0)

  const applyFreightCharges = () => {
    setOthersAmt(freightBaseTotal.toFixed(2))
    setOgstAmtVal((freightPopupTotal - freightBaseTotal).toFixed(2))
    setShowFreightPopup(false)
  }

  const handleSubmit = async () => {
    if (!form.grnNo) {
      toast.error('GRN number is required')
      return
    }
    if (!form.supplierName) {
      toast.error('Supplier Name is required')
      return
    }
    const validItems = items.filter(r => r.itemCode || r.itemName)
    if (validItems.length === 0) {
      toast.error('Add at least one item')
      return
    }

    setSubmitting(true)
    try {
      const payload = {
        ...form,
        remarks,
        currencyTotal,
        roundOff,
        freightLedger,
        tcsLedger,
        subTotal: subTotal.toFixed(2),
        gstAmt: computedGstAmt.toFixed(2),
        igstAmt: computedIgstAmt.toFixed(2),
        othersAmt,
        ogstAmt: ogstAmtVal,
        tcsAmt: tcsAmtVal,
        grandTotal: grandTotal.toFixed(2),
        totalAmount: grandTotal.toFixed(2),
        items: validItems,
      }
      if (editId) {
        await api.put(`/api/grn-master/${editId}`, payload, { loadingMessage: 'Updating GRN entry...' })
        toast.success('GRN Entry updated successfully!')
        setEditId(null)
      } else {
        await api.post('/api/grn-master', payload, { loadingMessage: 'Saving GRN entry...' })
        toast.success('GRN Entry saved successfully!')
      }

      // Fetch new GRN number for next entry
      const nextRes = await api.get('/api/grn-master/next-no', { skipGlobalLoader: true })
      setForm(f => ({
        grnType: f.grnType,
        gateEntryNo: '',
        supplierName: '',
        purchaseLedger: f.purchaseLedger,
        purchaseType: f.purchaseType,
        currency: f.currency,
        currencyType: 'EXPORT',
        contactPerson: '',
        contactNo: '',
        poNo: '',
        poDate: today,
        taxType: f.taxType,
        exchangeRate: '',
        grnNo: nextRes.data.grnNo || f.grnNo,
        financialYear: nextRes.data.financialYear || f.financialYear,
        grnDate: today,
        invoiceNo: '0',
        invoiceDate: today,
        qcType: f.qcType,
        discountType: 'Dis_Per',
      }))
      setItems([emptyItem()])
      setRemarks('')
      setCurrencyTotal('')
      setRoundOff('')
      setOthersAmt('')
      setFreightRows(defaultFreightRows())
      setOgstAmtVal('')
      setTcsAmtVal('')
    } catch (err) {
      const msg = err.response?.data?.message || 'Failed to save GRN entry'
      toast.error(msg)
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden">
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3"/> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Stores</span>
        <ChevronRight className="w-3 h-3"/>
        <span className="text-[#0097A7] font-semibold">GRN Entry</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-[--color-main] px-4 py-2.5 flex items-center justify-between">
          <h2 className="text-white font-semibold text-[14px]">{editId ? 'Edit' : 'Create'} - GRN Entry</h2>
          <button className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors">Close</button>
        </div>

        {refLoading && (
          <div className="bg-slate-50 border-b border-slate-200">
            <SpinnerLoader size={16} message="Loading reference data..." className="py-3" />
          </div>
        )}

        <div className="p-4 space-y-3">
          <div className="grid grid-cols-3 gap-4">
            {/* Col 1 */}
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>GRN Type :</label>
                <select value={form.grnType} onChange={e=>setField('grnType',e.target.value)} className={inp()}>{grnTypes.map(t=><option key={t}>{t}</option>)}</select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Gate Entry No :</label>
                <input value={form.gateEntryNo} readOnly className={`${inp()} flex-1 bg-slate-50`}/>
                <button onClick={openGateSearch} disabled={gateLoading} className="px-3 py-1 bg-slate-700 hover:bg-slate-600 text-white text-[12px] rounded transition-colors shrink-0 flex items-center gap-1 disabled:opacity-60">
                  {gateLoading ? <Loader2 className="w-3 h-3 animate-spin"/> : null}Search
                </button>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Supplier Name:</label>
                <select value={form.supplierName} onChange={e=>handleSupplierChange(e.target.value)} className={inp()}>
                  <option value="">Select Supplier</option>
                  {suppliersData.map(s=><option key={s.id} value={s.supplierName}>{s.supplierName}</option>)}
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Purchase Ledger :</label>
                <select value={form.purchaseLedger} onChange={e=>setField('purchaseLedger',e.target.value)} className={inp()}>
                  {purchaseLedgers.length === 0 && <option value="">Loading...</option>}
                  {purchaseLedgers.map(l=><option key={l} value={l}>{l}</option>)}
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Purchase Type :</label>
                <select value={form.purchaseType} onChange={e=>setField('purchaseType',e.target.value)} className={inp()}>
                  {purchaseTypes.length === 0 && <option value="">Loading...</option>}
                  {purchaseTypes.map(t=><option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Currency :</label>
                <select value={form.currency} onChange={e=>setField('currency',e.target.value)} className={`${inp()} w-20`}>
                  {currencies.length === 0 && <option value="">Loading...</option>}
                  {currencies.map(c=><option key={c} value={c}>{c}</option>)}
                </select>
                <select value={form.currencyType} onChange={e=>setField('currencyType',e.target.value)} className={`${inp()} w-24`}>{CURRENCY_TYPES.map(c=><option key={c}>{c}</option>)}</select>
              </div>
            </div>
            {/* Col 2 */}
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Contact Person:</label>
                <input value={form.contactPerson} onChange={e=>setField('contactPerson',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Contact No. :</label>
                <input value={form.contactNo} onChange={e=>setField('contactNo',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>PO No :</label>
                <input value={form.poNo} readOnly className={`${inp()} flex-1 bg-slate-50`}/>
                <button onClick={openPoSearch} disabled={poLoading} className="px-3 py-1 bg-slate-700 hover:bg-slate-600 text-white text-[12px] rounded transition-colors shrink-0 flex items-center gap-1 disabled:opacity-60">
                  {poLoading ? <Loader2 className="w-3 h-3 animate-spin"/> : null}Search
                </button>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>PO Date :</label>
                <input type="date" value={form.poDate} onChange={e=>setField('poDate',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Tax Type :</label>
                <select value={form.taxType} onChange={e=>setField('taxType',e.target.value)} className={inp()}>
                  {taxTypes.length === 0 && <option value="">Loading...</option>}
                  {taxTypes.map(t=><option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Exchange Rate (Rs.):</label>
                <input value={form.exchangeRate} onChange={e=>setField('exchangeRate',e.target.value)} className={inp()}/>
              </div>
            </div>
            {/* Col 3 */}
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[110px] shrink-0`}>GRN No :</label>
                <input value={form.grnNo} readOnly className={`${inp()} bg-slate-50`}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[110px] shrink-0`}>GRN Date :</label>
                <input type="date" value={form.grnDate} onChange={e=>setField('grnDate',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[110px] shrink-0`}>Invoice No :</label>
                <input value={form.invoiceNo} onChange={e=>setField('invoiceNo',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[110px] shrink-0`}>Invoice Date :</label>
                <input type="date" value={form.invoiceDate} onChange={e=>setField('invoiceDate',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[110px] shrink-0`}>QC Type :</label>
                <select value={form.qcType} onChange={e=>setField('qcType',e.target.value)} className={inp()}>
                  {qcTypes.length === 0 && <option value="">Loading...</option>}
                  {qcTypes.map(q=><option key={q} value={q}>{q}</option>)}
