import { useState, useEffect } from 'react'
import api from '../services/api'
import { ChevronRight, Search, Edit, Trash2, Printer, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import { TableSkeleton } from '../components/LocalLoader'

const today = new Date().toISOString().split('T')[0]
const ago30 = new Date(Date.now()-30*24*60*60*1000).toISOString().split('T')[0]

const PAGE_SIZES = [5,10,25,50]
const statusColor = s => ({ Completed:'bg-green-100 text-green-700', Pending:'bg-amber-100 text-amber-700', 'QC Pending':'bg-blue-100 text-blue-700', Open:'bg-green-100 text-green-700' }[s]??'bg-slate-100 text-slate-600')
const inp = 'border border-slate-300 rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] bg-white'

const fmtDate = (d) => {
  if (!d) return '-'
  const dt = new Date(d)
  if (isNaN(dt)) return d
  return `${String(dt.getDate()).padStart(2,'0')}/${String(dt.getMonth()+1).padStart(2,'0')}/${dt.getFullYear()}`
}

const fmtAmt = (v) => {
  const n = parseFloat(v)
  if (isNaN(n)) return '-'
  return n.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}

export default function GRNEntryReport() {
  const toast = useToast()
  const [fromDate, setFromDate] = useState(ago30)
  const [toDate, setToDate] = useState(today)
  const [searchText, setSearchText] = useState('')
  const [allRows, setAllRows] = useState([])
  const [filtered, setFiltered] = useState([])
  const [pageSize, setPageSize] = useState(10)
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [deletingId, setDeletingId] = useState(null)
  const [printingId, setPrintingId] = useState(null)

  const applyFilter = (rows, from, to, search) => {
    let r = rows
    if (from) r = r.filter(x => x.grnDate && new Date(x.grnDate) >= new Date(from))
    if (to)   r = r.filter(x => x.grnDate && new Date(x.grnDate) <= new Date(to + 'T23:59:59'))
    if (search.trim()) {
      const q = search.toLowerCase()
      r = r.filter(x =>
        (x.grnNo||'').toLowerCase().includes(q) ||
        (x.supplierName||'').toLowerCase().includes(q) ||
        (x.poNo||'').toLowerCase().includes(q) ||
        (x.invoiceNo||'').toLowerCase().includes(q)
      )
    }
    return r
  }

  useEffect(() => {
    setLoading(true)
    api.get('/api/grn-master')
      .then(res => {
        const data = res.data.data || []
        setAllRows(data)
        setFiltered(applyFilter(data, ago30, today, ''))
      })
      .catch(() => toast.error('Failed to load GRN entries'))
      .finally(() => setLoading(false))
  }, [])

  const handleSearch = () => {
    setFiltered(applyFilter(allRows, fromDate, toDate, searchText))
    setPage(1)
  }

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this GRN entry?')) return
    setDeletingId(id)
    try {
      await api.delete(`/api/grn-master/${id}`)
      const updated = allRows.filter(r => r.id !== id)
      setAllRows(updated)
      setFiltered(f => f.filter(r => r.id !== id))
      toast.success('GRN entry deleted')
    } catch {
      toast.error('Failed to delete GRN entry')
    } finally {
      setDeletingId(null)
    }
  }

  const handleEdit = (row) => {
    window.__velsonNav = { editId: row.id }
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'GRNEntry' } }))
  }

  const handlePrint = async (row) => {
    setPrintingId(row.id)
    let grn = row
    try {
      const res = await api.get(`/api/grn-master/${row.id}`, { skipGlobalLoader: true })
      if (res.data.data) grn = res.data.data
    } catch { /* use cached row data */ }
    finally { setPrintingId(null) }

    const fmtD = (d) => { if (!d) return '-'; const dt = new Date(d); if (isNaN(dt)) return d; return `${String(dt.getDate()).padStart(2,'0')}/${String(dt.getMonth()+1).padStart(2,'0')}/${dt.getFullYear()}` }
    const fmtN = (v) => { const n = parseFloat(v); return isNaN(n) ? '-' : n.toFixed(2) }
    const details = grn.details || []
    const itemRows = details.map((d, i) => `
      <tr class="${i%2?'alt':''}">
        <td>${i+1}</td><td>${d.itemCode||''}</td><td style="text-align:left">${d.itemName||''}</td>
        <td>${d.hsnCode||''}</td><td>${d.unit||''}</td><td>${fmtN(d.qty)}</td>
        <td>${fmtN(d.unitPrice)}</td><td>${fmtN(d.discPer)}</td>
        <td>${fmtN(d.finalPrice)}</td><td>${fmtN(d.taxPer)}</td><td>${fmtN(d.netAmt)}</td>
      </tr>`).join('')
    const win = window.open('', '_blank', 'width=1050,height=780')
    win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>GRN - ${grn.grnNo}</title>
    <style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:11px;margin:20px;color:#222}
    h2{text-align:center;font-size:15px;margin-bottom:4px}
    .sub{text-align:center;font-size:11px;color:#555;margin-bottom:12px}
    .info{display:grid;grid-template-columns:1fr 1fr;gap:4px 20px;margin-bottom:12px;border:1px solid #ccc;padding:8px;border-radius:4px}
    .info-row{display:flex;gap:6px}.info-lbl{font-weight:bold;width:130px;flex-shrink:0}
    table{width:100%;border-collapse:collapse;margin-top:8px}
    th{background:#0097A7;color:#fff;padding:5px 6px;text-align:center;font-size:10px}
    td{padding:3px 6px;border-bottom:1px solid #e2e8f0;font-size:10px;text-align:center}
    tr.alt td{background:#f8fafc}
    .totals{margin-top:8px;text-align:right;font-size:11px}
    .totals span{font-weight:bold}
    @media print{@page{margin:1cm}}</style></head>
    <body>
    <h2>GOODS RECEIPT NOTE</h2>
    <div class="sub">${grn.grnNo} &nbsp;|&nbsp; Date: ${fmtD(grn.grnDate)}</div>
    <div class="info">
      <div class="info-row"><span class="info-lbl">Supplier:</span>${grn.supplierName||'-'}</div>
      <div class="info-row"><span class="info-lbl">GRN Type:</span>${grn.grnType||'-'}</div>
      <div class="info-row"><span class="info-lbl">PO No:</span>${grn.poNo||'-'}</div>
      <div class="info-row"><span class="info-lbl">PO Date:</span>${fmtD(grn.poDate)}</div>
      <div class="info-row"><span class="info-lbl">Gate Entry No:</span>${grn.gateEntryNo||'-'}</div>
      <div class="info-row"><span class="info-lbl">Invoice No:</span>${grn.invoiceNo||'-'}</div>
      <div class="info-row"><span class="info-lbl">Invoice Date:</span>${fmtD(grn.invoiceDate)}</div>
      <div class="info-row"><span class="info-lbl">Tax Type:</span>${grn.taxType||'-'}</div>
      <div class="info-row"><span class="info-lbl">QC Type:</span>${grn.qcType||'-'}</div>
      <div class="info-row"><span class="info-lbl">Status:</span>${grn.status||'-'}</div>
    </div>
    <table>
      <thead><tr><th>#</th><th>Item Code</th><th>Item Name</th><th>HSN</th><th>Unit</th><th>Qty</th><th>Unit Price</th><th>Disc %</th><th>Final Price</th><th>Tax %</th><th>Net Amt</th></tr></thead>
      <tbody>${itemRows||'<tr><td colspan="11">No items</td></tr>'}</tbody>
    </table>
    <div class="totals">
      Sub Total: <span>${fmtN(grn.subTotal)}</span> &nbsp;&nbsp;
      Total Amount: <span>${fmtN(grn.totalAmount)}</span>
    </div>
    ${grn.remarks ? `<div style="margin-top:8px;font-size:11px"><b>Remarks:</b> ${grn.remarks}</div>` : ''}
    </body></html>`)
    win.document.close(); win.focus()
    setTimeout(() => win.print(), 400)
  }

  const taxableAmt = (row) => (row.details||[]).reduce((s,d) => s + (d.finalPrice||0), 0)
  const taxAmt = (row) => (row.details||[]).reduce((s,d) => s + ((d.netAmt||0) - (d.finalPrice||0)), 0)

  const totalPages = Math.max(1, Math.ceil(filtered.length/pageSize))
  const paged = filtered.slice((page-1)*pageSize, page*pageSize)
  const cols = ['GRN No','GRN Date','Gate Entry No','Supplier Name','PO No','Invoice No','Invoice Date','GRN Type','Taxable Amt','Tax Amt','Freight Tax Amt','TCS %','TCS Amt','Total Amount','Status','Edit','Delete','Print']

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden">
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3"/> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Stores</span>
        <ChevronRight className="w-3 h-3"/>
        <span className="text-[#0097A7] font-semibold">GRN Entry Report</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-[--color-main] px-4 py-2.5">
          <h2 className="text-white font-semibold text-[14px]">GRN Entry Report</h2>
        </div>

        <div className="px-4 py-3 flex flex-wrap items-center gap-3 border-b border-slate-200">
          <div className="flex items-center gap-1.5">
            <label className="text-[12px] font-semibold text-slate-600">From Date:</label>
            <input type="date" value={fromDate} onChange={e=>setFromDate(e.target.value)} className={inp}/>
          </div>
          <div className="flex items-center gap-1.5">
            <label className="text-[12px] font-semibold text-slate-600">To Date:</label>
            <input type="date" value={toDate} onChange={e=>setToDate(e.target.value)} className={inp}/>
          </div>
          <button onClick={handleSearch} disabled={loading} className="flex items-center gap-1.5 px-4 py-1.5 bg-[#0097A7] hover:bg-[#007a87] text-white text-[12.5px] font-semibold rounded transition-colors shadow-sm disabled:opacity-60">
            {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Search className="w-3.5 h-3.5"/>} Search
          </button>
        </div>

        <div className="flex items-center justify-between px-4 py-2 border-b border-slate-100">
          <div className="flex items-center gap-2 text-[12.5px] text-slate-600">Show <select value={pageSize} onChange={e=>{setPageSize(Number(e.target.value));setPage(1)}} className={`${inp} w-16`}>{PAGE_SIZES.map(s=><option key={s}>{s}</option>)}</select> entries</div>
          <div className="flex items-center gap-2"><label className="text-[12px] text-slate-600">Search:</label><input value={searchText} onChange={e=>setSearchText(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleSearch()} className={`${inp} w-40`}/></div>
        </div>

        {loading ? (
          <TableSkeleton rows={5} cols={['6%','7%','6%','12%','8%','7%','7%','7%','7%','7%','5%','5%','5%','7%','6%','4%','4%','4%']} />
        ) : (
        <div className="overflow-x-auto w-full">
          <table className="min-w-full text-[12.5px]">
            <thead><tr className="bg-slate-50 border-b border-slate-200">{cols.map(h=><th key={h} className="px-3 py-2 text-center font-bold text-slate-600 text-[11px] uppercase tracking-wide whitespace-nowrap">{h}</th>)}</tr></thead>
            <tbody>
              {paged.length===0 ? (
                <tr><td colSpan={18} className="text-center py-12 text-slate-400 text-[13px]">No GRN entries found.</td></tr>
              ) : paged.map((row,idx)=>(
                <tr key={row.id} className={`border-b border-slate-100 hover:bg-slate-50 transition-colors ${idx%2===1?'bg-slate-50/50':''}`}>
                  <td className="px-3 py-2 text-center font-medium text-[#0097A7]">{row.grnNo}</td>
                  <td className="px-3 py-2 text-center">{fmtDate(row.grnDate)}</td>
                  <td className="px-3 py-2 text-center">{row.gateEntryNo||'-'}</td>
                  <td className="px-3 py-2 text-center font-medium">{row.supplierName||'-'}</td>
                  <td className="px-3 py-2 text-center">{row.poNo||'—'}</td>
                  <td className="px-3 py-2 text-center">{row.invoiceNo||'-'}</td>
                  <td className="px-3 py-2 text-center">{fmtDate(row.invoiceDate)}</td>
                  <td className="px-3 py-2 text-center">{row.grnType||'-'}</td>
                  <td className="px-3 py-2 text-center font-semibold text-slate-700">{fmtAmt(taxableAmt(row))}</td>
                  <td className="px-3 py-2 text-center font-semibold text-slate-700">{fmtAmt(taxAmt(row))}</td>
                  <td className="px-3 py-2 text-center">-</td>
                  <td className="px-3 py-2 text-center">-</td>
                  <td className="px-3 py-2 text-center">-</td>
                  <td className="px-3 py-2 text-center font-semibold text-slate-700">{fmtAmt(row.totalAmount)}</td>
                  <td className="px-3 py-2 text-center"><span className={`px-2 py-0.5 rounded-full text-[11px] font-semibold ${statusColor(row.status)}`}>{row.status}</span></td>
                  <td className="px-3 py-2 text-center"><button onClick={()=>handleEdit(row)} className="px-2 py-1 bg-[#0097A7] hover:bg-[#007a87] text-white text-[11px] rounded transition-colors"><Edit className="w-3.5 h-3.5"/></button></td>
                  <td className="px-3 py-2 text-center">
                    <button
                      onClick={()=>handleDelete(row.id)}
                      disabled={deletingId===row.id}
                      className="px-2 py-1 bg-red-500 hover:bg-red-600 text-white text-[11px] rounded transition-colors disabled:opacity-60"
                    >
                      {deletingId===row.id ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Trash2 className="w-3.5 h-3.5"/>}
                    </button>
                  </td>
                  <td className="px-3 py-2 text-center"><button onClick={()=>handlePrint(row)} disabled={printingId===row.id} className="px-2 py-1 bg-purple-500 hover:bg-purple-600 text-white text-[11px] rounded transition-colors disabled:opacity-60">{printingId===row.id?<Loader2 className="w-3.5 h-3.5 animate-spin"/>:<Printer className="w-3.5 h-3.5"/>}</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        )}

        <div className="flex items-center justify-between px-4 py-3 border-t border-slate-200">
          <span className="text-[12px] text-slate-500">Showing {filtered.length===0?0:(page-1)*pageSize+1} to {Math.min(page*pageSize,filtered.length)} of {filtered.length} entries</span>
          <div className="flex items-center gap-1">
            <button onClick={()=>setPage(p=>Math.max(1,p-1))} disabled={page===1} className="px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed transition-colors">Previous</button>
            <button onClick={()=>setPage(p=>Math.min(totalPages,p+1))} disabled={page===totalPages} className="px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed transition-colors">Next</button>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { ChevronRight, Search, Send, X, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import { useLoading } from '../context/LoadingContext'
import { SpinnerLoader } from '../components/LocalLoader'

const BASE = 'http://localhost:3000'
const today = new Date().toISOString().split('T')[0]

const emptyForm = () => ({
  poNo: '', prqNo: '', supplierName: '', supplierAddress: '',
  gateNo: '', carrierName: '', vehicleNo: '', user: 'superadmin',
  gateEntryNo: '', financialYear: '', gateEntryDate: today,
  invoiceNo: '', invoiceDate: today, taxType: '',
})

const emptyItem = () => ({ poNo:'', itemCode:'', itemName:'', supplierPartNo:'', description:'', hsnCode:'', unit:'', qty:'', recQty:'' })

const inp = (err='') => `w-full border rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 transition-colors bg-white ${err?'border-red-400 focus:ring-red-300':'border-slate-300 focus:ring-[#0097A7] focus:border-[#0097A7]'}`
const lbl = 'text-[12px] font-semibold text-slate-600 whitespace-nowrap'

export default function GateEntry() {
  const toast = useToast()
  const { show: showLoader, hide: hideLoader } = useLoading()

  const [form, setForm] = useState(emptyForm())
  const [items, setItems] = useState([emptyItem()])
  const [remarks, setRemarks] = useState('')
  const [editId, setEditId] = useState(null)

  const [allPOs, setAllPOs] = useState([])
  const [suppliers, setSuppliers] = useState([])
  const [taxTypeOptions, setTaxTypeOptions] = useState([])
  const [poSearch, setPoSearch] = useState('')
  const [showPoModal, setShowPoModal] = useState(false)
  const [selectedPoId, setSelectedPoId] = useState(null)

  const [loadingInit, setLoadingInit] = useState(false)
  const [loadingPOItems, setLoadingPOItems] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [recQtyErrors, setRecQtyErrors] = useState({})

  /* ── on mount: next GE no + all POs ── */
  useEffect(() => {
    const init = async () => {
      setLoadingInit(true)
      try {
        const [noRes, poRes, supRes, taxRes] = await Promise.all([
          fetch(`${BASE}/api/gate-master/next-no`),
          fetch(`${BASE}/api/purchase-master`),
          fetch(`${BASE}/api/supplier-master`),
          fetch(`${BASE}/api/reference-master/${encodeURIComponent('Tax Type')}`),
        ])
        const [noJson, poJson, supJson, taxJson] = await Promise.all([noRes.json(), poRes.json(), supRes.json(), taxRes.json()])
        if (noJson.success) setForm(f => ({ ...f, gateEntryNo: noJson.gateEntryNo, financialYear: noJson.financialYear || '' }))
        if (poJson.success) setAllPOs(poJson.data)
        if (supJson.success) setSuppliers(supJson.data)
        if (taxJson.data) setTaxTypeOptions(taxJson.data)
      } catch { toast.error('Failed to load data') }
      finally { setLoadingInit(false) }
    }

    /* check for edit intent from GateEntryReport */
    const editId = localStorage.getItem('velson:gate-edit')
    if (editId) {
      localStorage.removeItem('velson:gate-edit')
      loadForEdit(parseInt(editId, 10))
    } else {
      init()
    }
  }, [])

  const loadForEdit = async (id) => {
    setLoadingInit(true)
    try {
      const [entryRes, poRes, supRes, taxRes] = await Promise.all([
        fetch(`${BASE}/api/gate-master/${id}`),
        fetch(`${BASE}/api/purchase-master`),
        fetch(`${BASE}/api/supplier-master`),
        fetch(`${BASE}/api/reference-master/${encodeURIComponent('Tax Type')}`),
      ])
      const [entryJson, poJson, supJson, taxJson] = await Promise.all([entryRes.json(), poRes.json(), supRes.json(), taxRes.json()])
      if (poJson.success) setAllPOs(poJson.data)
      if (supJson.success) setSuppliers(supJson.data)
      if (taxJson.data) setTaxTypeOptions(taxJson.data)
      if (entryJson.success) {
        const e = entryJson.data
        setEditId(e.id)
        setForm({
          poNo: e.poNo || '', prqNo: e.prqNo || '',
          supplierName: e.supplierName || '', supplierAddress: e.supplierAddress || '',
          gateNo: e.gateNo || '', carrierName: e.carrierName || '',
          vehicleNo: e.vehicleNo || '', user: e.createdBy || 'superadmin',
          gateEntryNo: e.gateEntryNo, financialYear: e.financialYear || '',
          gateEntryDate: e.gateEntryDate ? e.gateEntryDate.split('T')[0] : today,
          invoiceNo: e.invoiceNo || '', invoiceDate: e.invoiceDate ? e.invoiceDate.split('T')[0] : today,
          taxType: e.taxType || '',
        })
        setPoSearch(e.poNo || '')
        setSelectedPoId(e.poId || null)
        setRemarks(e.remarks || '')
        setItems(e.details?.length > 0 ? e.details.map(d => ({
          poNo: d.poNo || '', itemCode: d.itemCode || '', itemName: d.itemName || '',
          supplierPartNo: d.supplierPartNo || '', description: d.description || '',
          hsnCode: d.hsnCode || '', unit: d.unit || '',
          qty: d.qty != null ? String(d.qty) : '', recQty: d.recQty != null ? String(d.recQty) : '',
        })) : [emptyItem()])
      }
    } catch { toast.error('Failed to load entry') }
    finally { setLoadingInit(false) }
  }

  const filteredPOs = allPOs
    .filter(po => po.status === 'Approval' && po.poNo.toLowerCase().includes(poSearch.toLowerCase()))
    .sort((a, b) => a.poNo.localeCompare(b.poNo))

  const extractPrqNo = (details) => {
    const nos = [...new Set(details.map(d => d.purchaseReqNo).filter(Boolean))]
    return nos.join(', ')
  }

  const selectPO = async (po) => {
    setShowPoModal(false)
    setSelectedPoId(po.id)

    // Reset fields immediately so stale values never linger
    setForm(f => ({
      ...f,
      poNo: po.poNo,
      prqNo: '',
      supplierName: po.supplier?.supplierName || '',
      supplierAddress: po.supplierAddress || '',
    }))
    setItems([emptyItem()])
    setRecQtyErrors({})

    // Always fetch full PO from API to get accurate purchaseReqNo per detail row
    setLoadingPOItems(true)
    try {
      const res = await fetch(`${BASE}/api/purchase-master/${po.id}`)
      const json = await res.json()
      if (json.success) {
        const data = json.data
        const det = data.details || []
        setForm(f => ({
          ...f,
          prqNo: data.prNo || extractPrqNo(det) || '',
          supplierName: data.supplier?.supplierName || '',
          supplierAddress: data.supplierAddress || '',
        }))
        setItems(det.length > 0 ? det.map(d => ({
          poNo: data.poNo, itemCode: d.itemCode || '', itemName: d.itemName || '',
          supplierPartNo: d.supplierPartNo || data.supplierRefNo || '',
          description: d.description || '', hsnCode: d.hsnCode || '',
          unit: d.uom || '', qty: d.qty != null ? String(d.qty) : '', recQty: '',
        })) : [emptyItem()])
      }
    } catch { toast.error('Failed to fetch PO details') }
    finally { setLoadingPOItems(false) }
  }

  const setField = (k, v) => setForm(f => ({ ...f, [k]: v }))
  const setItemField = (idx, k, v) => {
    setItems(rows => {
      const updated = rows.map((r, i) => i !== idx ? r : { ...r, [k]: v })
      if (k === 'recQty') {
        const row = updated[idx]
        const recQ = parseFloat(v)
        const ordQ = parseFloat(row.qty)
        setRecQtyErrors(e => {
          const n = { ...e }
          if (v !== '' && !isNaN(recQ) && !isNaN(ordQ) && recQ > ordQ) n[idx] = true
          else delete n[idx]
          return n
        })
      }
      return updated
    })
  }
  const removeRow = idx => setItems(r => r.filter((_, i) => i !== idx))

  const handleSupplierChange = name => {
    const sup = suppliers.find(s => s.supplierName === name)
    const addr = sup ? [sup.address, sup.address2, sup.address3, sup.address4, sup.city].filter(Boolean).join(', ') : ''
    setForm(f => ({ ...f, supplierName: name, supplierAddress: addr }))
  }

  const fetchNextNo = async () => {
    try {
      const res = await fetch(`${BASE}/api/gate-master/next-no`)
      const json = await res.json()
      if (json.success) setForm(f => ({ ...f, gateEntryNo: json.gateEntryNo, financialYear: json.financialYear || '' }))
    } catch {}
  }

  const resetForm = async () => {
    setForm(emptyForm())
    setItems([emptyItem()])
    setRemarks('')
    setPoSearch('')
    setSelectedPoId(null)
    setEditId(null)
    setRecQtyErrors({})
    await fetchNextNo()
  }

  const validate = () => {
    const errors = {}
    items.forEach((row, idx) => {
      const recQ = parseFloat(row.recQty)
      const ordQ = parseFloat(row.qty)
      if (row.recQty !== '' && !isNaN(recQ) && !isNaN(ordQ) && recQ > ordQ) {
        errors[idx] = true
        toast.warning(`Received Qty for "${row.itemName || `Row ${idx + 1}`}" (${recQ}) exceeds ordered Qty (${ordQ}).`)
      }
    })
    setRecQtyErrors(errors)
    return Object.keys(errors).length === 0
  }

  const handleSubmit = async () => {
    if (!validate()) return
    setSubmitting(true)
    showLoader(editId ? 'Updating gate entry...' : 'Saving gate entry...')
    try {
      const url = editId ? `${BASE}/api/gate-master/${editId}` : `${BASE}/api/gate-master`
      const method = editId ? 'PUT' : 'POST'
      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...form,
          poId: selectedPoId,
          remarks,
          createdBy: form.user,
          updatedBy: form.user,
          items: items.filter(r => r.itemCode || r.itemName),
        }),
      })
      const json = await res.json()
      if (json.success) {
        toast.success(editId ? 'Gate Entry updated!' : 'Gate Entry submitted!')
        await resetForm()
      } else {
        toast.error(json.message || 'Operation failed')
      }
    } catch { toast.error('Server error. Please try again.') }
    finally { setSubmitting(false); hideLoader() }
  }

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden">
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3"/> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Stores</span>
        <ChevronRight className="w-3 h-3"/>
        <span className="text-[#0097A7] font-semibold">Gate Entry</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-[--color-main] px-4 py-2.5 flex items-center justify-between">
          <h2 className="text-white font-semibold text-[14px]">{editId ? 'Edit' : 'Create'} - Gate Entry</h2>
          <button onClick={resetForm} className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors">Close</button>
        </div>

        <div className="p-4 space-y-3">
          <div className="grid grid-cols-3 gap-4">
            {/* Col 1 */}
            <div className="space-y-2">
              {/* PO No with modal search */}
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>PO No :</label>
                <input value={form.poNo} readOnly placeholder="Select PO..." className={`${inp()} flex-1 bg-slate-50`}/>
                <button
                  onClick={() => { setPoSearch(''); setShowPoModal(true) }}
                  disabled={loadingInit}
                  className="px-3 py-1 bg-slate-700 hover:bg-slate-600 disabled:opacity-50 text-white text-[12px] rounded transition-colors shrink-0 flex items-center gap-1"
                >
                  <Search className="w-3 h-3"/> Search
                </button>
              </div>

              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>PRQ No :</label>
                <input value={form.prqNo} onChange={e=>setField('prqNo',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Supplier Name:</label>
                <select value={form.supplierName} onChange={e=>handleSupplierChange(e.target.value)} className={inp()}>
                  <option value="">Select Supplier</option>
                  {suppliers.map(s=><option key={s.id} value={s.supplierName}>{s.supplierName}</option>)}
                </select>
              </div>
              <div className="flex items-start gap-2">
                <label className={`${lbl} w-[130px] shrink-0 pt-1`}>Supplier Address :</label>
                <textarea rows={3} value={form.supplierAddress} onChange={e=>setField('supplierAddress',e.target.value)} className="flex-1 border border-slate-300 rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] resize-none bg-white"/>
              </div>
            </div>

            {/* Col 2 */}
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Gate No :</label>
                <input value={form.gateNo} onChange={e=>setField('gateNo',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Carrier Name :</label>
                <input value={form.carrierName} onChange={e=>setField('carrierName',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Vehicle No :</label>
                <input value={form.vehicleNo} onChange={e=>setField('vehicleNo',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>User :</label>
                <input value={form.user} readOnly className={`${inp()} bg-slate-50`}/>
              </div>
            </div>

            {/* Col 3 */}
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Gate Entry No :</label>
                <input value={form.gateEntryNo} readOnly className={`${inp()} bg-slate-50`}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Gate Entry Date :</label>
                <input type="date" value={form.gateEntryDate} onChange={e=>setField('gateEntryDate',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Invoice No :</label>
                <input value={form.invoiceNo} onChange={e=>setField('invoiceNo',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Invoice Date :</label>
                <input type="date" value={form.invoiceDate} onChange={e=>setField('invoiceDate',e.target.value)} className={inp()}/>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[120px] shrink-0`}>Tax Type :</label>
                <select value={form.taxType} onChange={e=>setField('taxType',e.target.value)} className={inp()}>
                  <option value="">Select Tax Type</option>
                  {taxTypeOptions.map(t=><option key={t.id} value={t.description}>{t.description}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Items */}
          <div className="mt-2">
            <div className="bg-slate-700 px-3 py-1.5 rounded-t"><h3 className="text-white text-[13px] font-semibold">Items</h3></div>
            <div className="overflow-x-auto border border-slate-200 rounded-b relative">
              {loadingPOItems && (
                <div className="absolute inset-0 bg-white/80 flex items-center justify-center z-10">
                  <SpinnerLoader message="Loading PO items..." />
                </div>
              )}
              <table className="min-w-full text-[12.5px]">
                <thead>
                  <tr className="bg-slate-50 border-b border-slate-200">
                    <th className="px-2 py-1.5 text-center font-bold text-slate-600 text-[11px] uppercase w-8"><input type="checkbox" className="accent-[#0097A7]"/></th>
                    <th className="px-2 py-1.5 text-center font-bold text-slate-600 text-[11px] uppercase w-8">#</th>
                    {['PO No','Item Code','Item Name','Supplier Part No','Description','HSN Code','Unit','Qty','Rec Qty','Action'].map(h=>(
                      <th key={h} className="px-2 py-1.5 text-center font-bold text-slate-600 text-[11px] uppercase whitespace-nowrap">{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {items.map((row,idx)=>(
                    <tr key={idx} className={`border-b border-slate-100 ${idx%2===1?'bg-slate-50/50':''}`}>
                      <td className="px-2 py-1 text-center"><input type="checkbox" className="accent-[#0097A7]"/></td>
                      <td className="px-2 py-1 text-center text-slate-500">{idx+1}</td>
                      <td className="px-1 py-1"><input value={row.poNo} onChange={e=>setItemField(idx,'poNo',e.target.value)} className={inp()}/></td>
                      <td className="px-1 py-1"><input value={row.itemCode} onChange={e=>setItemField(idx,'itemCode',e.target.value)} className={inp()}/></td>
                      <td className="px-1 py-1"><input value={row.itemName} onChange={e=>setItemField(idx,'itemName',e.target.value)} className={`${inp()} min-w-[140px]`}/></td>
                      <td className="px-1 py-1"><input value={row.supplierPartNo} readOnly className={`${inp()} bg-slate-50`}/></td>
                      <td className="px-1 py-1"><input value={row.description} onChange={e=>setItemField(idx,'description',e.target.value)} className={`${inp()} min-w-[120px]`}/></td>
                      <td className="px-1 py-1"><input value={row.hsnCode} onChange={e=>setItemField(idx,'hsnCode',e.target.value)} className={inp()}/></td>
                      <td className="px-1 py-1"><input value={row.unit} onChange={e=>setItemField(idx,'unit',e.target.value)} className={`${inp()} w-14`}/></td>
                      <td className="px-1 py-1"><input value={row.qty} readOnly className={`${inp()} w-16 bg-slate-50`}/></td>
                      <td className="px-1 py-1">
                        <input
                          value={row.recQty}
                          onChange={e=>setItemField(idx,'recQty',e.target.value)}
                          placeholder="0"
                          className={`${inp(recQtyErrors[idx])} w-16`}
                        />
                      </td>
                      <td className="px-2 py-1 text-center"><button onClick={()=>removeRow(idx)} className="px-2 py-1 bg-red-500 hover:bg-red-600 text-white text-[11px] rounded transition-colors">Remove</button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Remarks + Submit */}
          <div className="flex items-start gap-4 pt-2">
            <label className={`${lbl} w-[100px] shrink-0 pt-1`}>Remark's :</label>
            <textarea rows={2} value={remarks} onChange={e=>setRemarks(e.target.value)} className="flex-1 border border-slate-300 rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] resize-none bg-white"/>
          </div>
          <div className="flex gap-2 justify-center pt-1">
            <button
              onClick={handleSubmit}
              disabled={submitting || Object.keys(recQtyErrors).length > 0}
              className="flex items-center gap-1 px-5 py-1.5 bg-[#0097A7] hover:bg-[#007a87] disabled:opacity-60 text-white text-[12px] font-semibold rounded transition-colors shadow-sm"
            >
              <Send className="w-3.5 h-3.5"/>
              {editId ? 'Update' : 'Submit'}
            </button>
            <button onClick={resetForm} disabled={submitting} className="flex items-center gap-1 px-5 py-1.5 bg-slate-500 hover:bg-slate-600 disabled:opacity-60 text-white text-[12px] font-semibold rounded transition-colors shadow-sm">
              <X className="w-3.5 h-3.5"/> Cancel
            </button>
          </div>
        </div>
      </div>
      {/* PO Search Modal */}
      {showPoModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded shadow-xl w-[700px] max-h-[80vh] flex flex-col">
            <div className="bg-[--color-main] px-4 py-2.5 flex items-center justify-between rounded-t">
              <h3 className="text-white font-semibold text-[14px]">Select Purchase Order</h3>
              <button onClick={() => setShowPoModal(false)} className="text-white hover:text-white/70"><X className="w-4 h-4"/></button>
            </div>
            <div className="p-3 border-b border-slate-200">
              <input
                autoFocus
                value={poSearch}
                onChange={e => setPoSearch(e.target.value)}
                placeholder="Search by PO No, Supplier..."
                className={`${inp()} w-full`}
              />
            </div>
            <div className="overflow-auto flex-1">
              {filteredPOs.length === 0 ? (
                <div className="p-6 text-center text-slate-400 text-[13px]">No purchase orders found.</div>
              ) : (
                <table className="min-w-full text-[12.5px]">
                  <thead className="sticky top-0">
                    <tr className="bg-[#4472C4] text-white">
                      {['PO No','PO Date','Supplier Name','Status'].map(h => (
                        <th key={h} className="px-3 py-2 text-left font-semibold whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {filteredPOs.map((po, i) => (
                      <tr
                        key={po.id}
                        onClick={() => selectPO(po)}
                        className={`cursor-pointer border-b border-slate-100 hover:bg-[#0097A7]/10 ${i%2===1?'bg-slate-50/50':''}`}
                      >
                        <td className="px-3 py-1.5 font-medium text-[#0097A7]">{po.poNo}</td>
                        <td className="px-3 py-1.5">{po.poDate ? po.poDate.split('T')[0] : '-'}</td>
                        <td className="px-3 py-1.5">{po.supplier?.supplierName || '-'}</td>
                        <td className="px-3 py-1.5">
                          <span className="px-2 py-0.5 rounded text-[11px] font-semibold bg-green-100 text-green-700">{po.status}</span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
            <div className="px-4 py-2 border-t border-slate-200 text-[11px] text-slate-400 text-right">
              {filteredPOs.length} record{filteredPOs.length !== 1 ? 's' : ''}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { ChevronRight, FileText, FileSpreadsheet, File as FilePdf, Filter, Settings, X, Trash2, Eye, Pencil } from 'lucide-react'
import ConfirmDialog from '../components/ConfirmDialog'

const BASE = 'http://localhost:3000'
const today = new Date().toISOString().split('T')[0]
const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]

const inp = 'border border-slate-300 rounded px-2 py-1 text-[12.5px] focus:outline-none focus:border-[#0097A7] bg-white'
const lbl = 'text-[12px] font-semibold text-slate-600 whitespace-nowrap'
const iconBtn = 'flex items-center gap-1 text-[12px] text-slate-600 hover:text-[#0097A7] transition-colors cursor-pointer'

const Spinner = ({ cls = 'w-4 h-4' }) => (
  <span className={`${cls} border-2 border-current/30 border-t-current rounded-full animate-spin inline-block`}/>
)

const fmtDate = iso => {
  if (!iso) return '—'
  const d = new Date(iso)
  return `${String(d.getDate()).padStart(2,'0')}-${String(d.getMonth()+1).padStart(2,'0')}-${d.getFullYear()}`
}

/* ── export helpers ── */
const buildRows = data => data.map(r => ({
  'Gate Entry No': r.gateEntryNo || '',
  'Gate No':       r.gateNo || '',
  'Date':          fmtDate(r.gateEntryDate),
  'Invoice No':    r.invoiceNo || '',
  'PO No':         r.poNo || '',
  'Supplier Name': r.supplierName || '',
  'Carrier Name':  r.carrierName || '',
  'Vehicle No':    r.vehicleNo || '',
  'Status':        r.status || '',
}))

const downloadBlob = (blob, filename) => {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url; a.download = filename
  document.body.appendChild(a); a.click()
  document.body.removeChild(a); URL.revokeObjectURL(url)
}

const doExcelExport = data => {
  const rows = buildRows(data)
  if (!rows.length) return
  const cols = Object.keys(rows[0])
  const lines = [cols.join(','), ...rows.map(r => cols.map(c => `"${String(r[c]).replace(/"/g,'""')}"`).join(','))]
  downloadBlob(new Blob(['﻿' + lines.join('\n')], { type: 'text/csv;charset=utf-8;' }), 'gate-entries.csv')
}

const doDocExport = data => {
  const rows = buildRows(data)
  if (!rows.length) return
  const cols = Object.keys(rows[0])
  const thead = cols.map(c => `<th style="padding:5px 8px;background:#0097A7;color:#fff;font-size:11px;">${c}</th>`).join('')
  const tbody = rows.map((r, i) => `<tr style="${i%2?'background:#f8fafc;':''}">
    ${cols.map(c => `<td style="padding:4px 8px;border:1px solid #e2e8f0;font-size:11px;">${r[c]}</td>`).join('')}</tr>`).join('')
  const html = `<html><head><meta charset="utf-8"></head><body>
    <h2>Gate Entry Report</h2>
    <table border="1" style="border-collapse:collapse;width:100%"><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
  </body></html>`
  downloadBlob(new Blob([html], { type: 'application/msword' }), 'gate-entries.doc')
}

const doPrint = data => {
  const rows = buildRows(data)
  const cols = Object.keys(rows[0] || {})
  const thead = cols.map(c => `<th>${c}</th>`).join('')
  const tbody = rows.map((r, i) => `<tr class="${i%2?'alt':''}"><td>${cols.map(c=>r[c]).join('</td><td>')}</td></tr>`).join('')
  const win = window.open('', '_blank', 'width=1100,height=750')
  win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Gate Entry Report</title>
  <style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:11px;margin:16px}
  h2{font-size:15px}table{width:100%;border-collapse:collapse}
  th{background:#0097A7;color:#fff;padding:5px 7px;text-align:left;font-size:10px}
  td{padding:4px 7px;border-bottom:1px solid #e2e8f0;font-size:10px}
  tr.alt td{background:#f8fafc}@media print{@page{margin:1cm}}</style></head>
  <body><h2>Gate Entry Report</h2>
  <table><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
  </body></html>`)
  win.document.close(); win.focus()
  setTimeout(() => win.print(), 400)
}

export default function GateEntryReport() {
  const [fromDate, setFromDate] = useState(thirtyDaysAgo)
  const [toDate, setToDate] = useState(today)
  const [allRows, setAllRows] = useState([])
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [searching, setSearching] = useState(false)
  const [activeRow, setActiveRow] = useState(null)

  const [filterOpen, setFilterOpen] = useState(false)
  const [filterText, setFilterText] = useState('')
  const [settingsOpen, setSettingsOpen] = useState(false)
  const settingsRef = useRef(null)

  const [viewEntry, setViewEntry] = useState(null)
  const [deleteTarget, setDeleteTarget] = useState(null)
  const [deleting, setDeleting] = useState(false)

  const ALL_COLS = ['Gate Entry No', 'Gate No', 'Date', 'Invoice No', 'PO No', 'Supplier Name', 'Carrier Name', 'Vehicle No', 'Invoice Qty', 'Status']
  const [hiddenCols, setHiddenCols] = useState(new Set())
  const visibleCols = ALL_COLS.filter(c => !hiddenCols.has(c))
  const colSpanTotal = visibleCols.length + 3 // View + Edit + Delete

  useEffect(() => {
    const handler = e => { if (settingsRef.current && !settingsRef.current.contains(e.target)) setSettingsOpen(false) }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  const fetchAll = async () => {
    setLoading(true)
    try {
      const res = await fetch(`${BASE}/api/gate-master`)
      const json = await res.json()
      if (json.success) { setAllRows(json.data); setRows(json.data) }
    } catch (err) { console.error('Error fetching gate entries:', err) }
    finally { setLoading(false) }
  }

  useEffect(() => { fetchAll() }, [])

  const handleSearch = () => {
    setSearching(true)
    setTimeout(() => {
      const result = allRows.filter(r => {
        const d = r.gateEntryDate ? r.gateEntryDate.split('T')[0] : ''
        return d >= fromDate && d <= toDate
      })
      setRows(result)
      setActiveRow(null)
      setFilterText('')
      setSearching(false)
    }, 0)
  }

  const toggleCol = col => setHiddenCols(prev => {
    const next = new Set(prev); next.has(col) ? next.delete(col) : next.add(col); return next
  })

  const displayRows = filterText.trim()
    ? rows.filter(r => {
        const q = filterText.toLowerCase()
        return (
          (r.gateEntryNo || '').toLowerCase().includes(q) ||
          (r.poNo || '').toLowerCase().includes(q) ||
          (r.supplierName || '').toLowerCase().includes(q) ||
          (r.invoiceNo || '').toLowerCase().includes(q) ||
          (r.status || '').toLowerCase().includes(q)
        )
      })
    : rows

  const totalQty = displayRows.reduce((sum, r) => {
    const qty = r.details?.reduce((s, d) => s + (d.recQty || 0), 0) || 0
    return sum + qty
  }, 0)

  const handleEdit = (entry, e) => {
    e.stopPropagation()
    localStorage.setItem('velson:gate-edit', String(entry.id))
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'GateEntry' } }))
  }

  const headerDelete = () => {
    if (activeRow === null || !displayRows[activeRow]) return
    setDeleteTarget(displayRows[activeRow])
  }

  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return
    setDeleting(true)
    try {
      const res = await fetch(`${BASE}/api/gate-master/${deleteTarget.id}`, { method: 'DELETE' })
      const json = await res.json()
      if (json.success !== false) {
        const filter = r => r.id !== deleteTarget.id
        setAllRows(prev => prev.filter(filter))
        setRows(prev => prev.filter(filter))
        setActiveRow(null)
      }
    } catch (err) { console.error('Delete error:', err) }
    finally { setDeleting(false); setDeleteTarget(null) }
  }

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden h-screen flex flex-col">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400 shrink-0">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3"/> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Stores</span>
        <ChevronRight className="w-3 h-3"/>
        <span className="text-[#0097A7] font-semibold">Gate Entry Report</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm flex flex-col flex-1 overflow-hidden">
        {/* Header */}
        <div className="bg-[#0097A7] px-4 py-2.5 flex items-center justify-between shrink-0">
          <h2 className="text-white font-semibold text-[14px]">Gate Entry Report</h2>
          <div className="flex gap-2">
            <button
              onClick={headerDelete}
              disabled={activeRow === null}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1 disabled:opacity-40"
            >
              <Trash2 className="w-3 h-3"/> Delete
            </button>
            <button
              onClick={() => window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'Dashboard' } }))}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1"
            >
              <X className="w-3 h-3"/> Close
            </button>
          </div>
        </div>

        {/* Filter Bar */}
        <div className="p-3 border-b border-slate-200 flex items-center justify-between bg-slate-50/50 shrink-0">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <label className={lbl}>From Date :</label>
              <input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className={inp}/>
            </div>
            <div className="flex items-center gap-2">
              <label className={lbl}>To Date :</label>
              <input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className={inp}/>
            </div>
            <button
              onClick={handleSearch}
              disabled={searching || loading}
              className="flex items-center gap-1.5 px-3 py-1 border border-[#0097A7] text-[#0097A7] bg-white hover:bg-[#0097A7]/10 rounded text-[12px] font-medium transition-colors shadow-sm disabled:opacity-70"
            >
              <span className="w-2 h-2 rounded-full bg-orange-500"></span>
              {searching ? 'Searching...' : 'Search Details'}
            </button>
            <button
              onClick={() => { setRows(allRows); setActiveRow(null); setFilterText('') }}
              className="flex items-center gap-1.5 px-3 py-1 border border-[#0097A7] text-[#0097A7] bg-white hover:bg-[#0097A7]/10 rounded text-[12px] font-medium transition-colors shadow-sm"
            >
              <span className="w-2 h-2 rounded-full bg-red-500"></span> Search Summary
            </button>
          </div>

          {/* Export Controls */}
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-1.5">
              <span className="text-[12px] font-medium text-slate-500">LS</span>
              <input value={displayRows.length} readOnly className="w-10 text-center border border-slate-300 rounded text-[12px] py-0.5 bg-slate-50"/>
            </div>
            <div className="h-4 w-px bg-slate-300"/>
            <button onClick={() => doDocExport(displayRows)} className={iconBtn}><FileText className="w-4 h-4 text-[#0097A7]"/> Dos</button>
            <button onClick={() => doExcelExport(displayRows)} className={iconBtn}><FileSpreadsheet className="w-4 h-4 text-[#0097A7]"/> Excel</button>
            <button onClick={() => doPrint(displayRows)} className={iconBtn}><FilePdf className="w-4 h-4 text-red-500"/> Pdf</button>
            <button
              onClick={() => { setFilterOpen(o => !o); if (filterOpen) setFilterText('') }}
              className={`${iconBtn} ${filterOpen ? 'text-[#0097A7]' : ''}`}
            >
              <Filter className={`w-4 h-4 ${filterOpen ? 'text-[#0097A7]' : 'text-blue-500'}`}/> Filter
            </button>
            <div className="relative" ref={settingsRef}>
              <button onClick={() => setSettingsOpen(o => !o)} className={`${iconBtn} ${settingsOpen ? 'text-[#0097A7]' : ''}`}>
                <Settings className="w-4 h-4 text-slate-700"/> Setting
              </button>
              {settingsOpen && (
                <div className="absolute right-0 top-7 bg-white border border-slate-200 rounded-lg shadow-xl z-50 p-3 min-w-[180px]">
                  <p className="text-[11px] font-bold text-slate-500 uppercase mb-2 tracking-wide">Show / Hide Columns</p>
                  {ALL_COLS.map(col => (
                    <label key={col} className="flex items-center gap-2 py-1 cursor-pointer hover:text-[#0097A7]">
                      <input type="checkbox" checked={!hiddenCols.has(col)} onChange={() => toggleCol(col)} className="accent-[#0097A7]"/>
                      <span className="text-[12px] text-slate-700">{col}</span>
                    </label>
                  ))}
                  <button onClick={() => setHiddenCols(new Set())} className="mt-2 w-full text-[11px] py-1 bg-slate-100 hover:bg-slate-200 rounded text-slate-600 transition-colors">
                    Reset All
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Inline text filter */}
        {filterOpen && (
          <div className="px-3 py-2 border-b border-slate-200 bg-blue-50/40 flex items-center gap-3 shrink-0">
            <Filter className="w-3.5 h-3.5 text-blue-400 shrink-0"/>
            <input autoFocus type="text" value={filterText} onChange={e => setFilterText(e.target.value)}
              placeholder="Search Gate Entry No, PO No, Supplier, Invoice No…"
              className="flex-1 border border-blue-200 rounded px-3 py-1 text-[12.5px] focus:outline-none focus:border-[#0097A7] bg-white"/>
            {filterText && (
              <button onClick={() => setFilterText('')} className="text-slate-400 hover:text-slate-600">
                <X className="w-3.5 h-3.5"/>
              </button>
            )}
            <span className="text-[11px] text-slate-400 shrink-0">{displayRows.length} result{displayRows.length !== 1 ? 's' : ''}</span>
          </div>
        )}

        {/* Data Grid */}
        <div className="flex-1 overflow-auto relative">
          {loading ? (
            <div className="flex items-center justify-center h-32 gap-2.5 text-slate-500 text-[12px]">
              <Spinner cls="w-5 h-5 text-[#0097A7]"/> Loading…
            </div>
          ) : (
            <table className="w-full min-w-max text-[12px] text-left border-collapse">
              <thead className="bg-slate-800 text-white sticky top-0 z-10">
                <tr>
                  {visibleCols.map(h => (
                    <th key={h} className="p-2 font-medium border-x border-slate-700 whitespace-nowrap">{h}</th>
                  ))}
                  <th className="p-2 font-medium border-x border-slate-700 text-center">View</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Edit</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Delete</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 bg-white">
                {displayRows.length === 0 ? (
                  <tr>
                    <td colSpan={colSpanTotal} className="p-8 text-center text-slate-400 text-[12px]">
                      {filterText ? 'No matching records' : 'No gate entries found'}
                    </td>
                  </tr>
                ) : displayRows.map((row, i) => {
                  const rowQty = row.details?.reduce((s, d) => s + (d.recQty || 0), 0) || 0
                  return (
                    <tr
                      key={row.id}
                      onClick={() => setActiveRow(i)}
                      className={`cursor-pointer transition-colors ${activeRow === i ? 'bg-[#0097A7]/20' : 'hover:bg-slate-50'}`}
                    >
                      {visibleCols.map(col => {
                        switch (col) {
                          case 'Gate Entry No': return <td key={col} className="p-1.5 border-x border-slate-200 font-medium text-[#0097A7]">{row.gateEntryNo}</td>
                          case 'Gate No':       return <td key={col} className="p-1.5 border-x border-slate-200 text-center">{row.gateNo || '—'}</td>
                          case 'Date':          return <td key={col} className="p-1.5 border-x border-slate-200">{fmtDate(row.gateEntryDate)}</td>
                          case 'Invoice No':    return <td key={col} className="p-1.5 border-x border-slate-200">{row.invoiceNo || '—'}</td>
                          case 'PO No':         return <td key={col} className="p-1.5 border-x border-slate-200">{row.poNo || '—'}</td>
                          case 'Supplier Name': return <td key={col} className="p-1.5 border-x border-slate-200">{row.supplierName || '—'}</td>
                          case 'Carrier Name':  return <td key={col} className="p-1.5 border-x border-slate-200">{row.carrierName || '—'}</td>
                          case 'Vehicle No':    return <td key={col} className="p-1.5 border-x border-slate-200">{row.vehicleNo || '—'}</td>
                          case 'Invoice Qty':   return <td key={col} className="p-1.5 border-x border-slate-200 text-right">{rowQty.toFixed(2)}</td>
                          case 'Status':        return <td key={col} className="p-1.5 border-x border-slate-200">
                            <span className={`font-semibold ${row.status === 'Open' ? 'text-emerald-600' : 'text-slate-600'}`}>{row.status || '—'}</span>
                          </td>
                          default: return null
                        }
                      })}
                      <td className="p-1.5 border-x border-slate-200 text-center">
                        <button onClick={e => { e.stopPropagation(); setViewEntry(row) }}
                          className="text-[#0097A7] hover:text-[#007a87] transition-colors" title="View">
                          <Eye className="w-3.5 h-3.5"/>
                        </button>
                      </td>
                      <td className="p-1.5 border-x border-slate-200 text-center">
                        <button onClick={e => handleEdit(row, e)}
                          className="text-amber-500 hover:text-amber-600 transition-colors" title="Edit">
                          <Pencil className="w-3.5 h-3.5"/>
                        </button>
                      </td>
                      <td className="p-1.5 border-x border-slate-200 text-center">
                        <button onClick={e => { e.stopPropagation(); setDeleteTarget(row) }}
                          className="text-red-500 hover:text-red-600 transition-colors" title="Delete">
                          <Trash2 className="w-3.5 h-3.5"/>
                        </button>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
              <tfoot className="sticky bottom-0 bg-[#f4f6ce] font-semibold text-slate-800 border-t-2 border-slate-300">
                <tr>
                  <td colSpan={colSpanTotal - 1} className="p-2 border-x border-slate-300">
                    Row : {displayRows.length}{filterText ? ` (filtered from ${rows.length})` : ''}
                  </td>
                  <td className="p-2 border-x border-slate-300 text-right">{totalQty.toFixed(2)}</td>
                </tr>
              </tfoot>
            </table>
          )}
        </div>
      </div>

      {/* View Modal */}
      {viewEntry && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setViewEntry(null)}/>
          <div className="relative bg-white rounded-xl shadow-2xl border border-slate-200 w-[720px] max-h-[88vh] overflow-hidden flex flex-col">
            <div className="bg-[#0097A7] px-5 py-3 flex items-center justify-between shrink-0">
              <div>
                <h3 className="text-white font-semibold text-[14px]">Gate Entry Details</h3>
                <p className="text-white/70 text-[11px] mt-0.5">{viewEntry.gateEntryNo} &nbsp;·&nbsp; {viewEntry.status}</p>
              </div>
              <button onClick={() => setViewEntry(null)} className="text-white/80 hover:text-white transition-colors">
                <X className="w-4 h-4"/>
              </button>
            </div>

            <div className="px-5 pt-4 pb-3 grid grid-cols-2 gap-x-6 gap-y-2 text-[12.5px] shrink-0 border-b border-slate-100">
              {[
                ['Gate Entry No',    viewEntry.gateEntryNo],
                ['Gate Entry Date',  fmtDate(viewEntry.gateEntryDate)],
                ['PO No',            viewEntry.poNo],
                ['PRQ No',           viewEntry.prqNo],
                ['Supplier Name',    viewEntry.supplierName],
                ['Gate No',          viewEntry.gateNo],
                ['Carrier Name',     viewEntry.carrierName],
                ['Vehicle No',       viewEntry.vehicleNo],
                ['Invoice No',       viewEntry.invoiceNo],
                ['Invoice Date',     fmtDate(viewEntry.invoiceDate)],
                ['Status',           viewEntry.status],
                ['Remarks',          viewEntry.remarks],
              ].map(([label, value]) => (
                <div key={label} className="flex gap-2">
                  <span className="w-36 font-semibold text-slate-500 shrink-0">{label}</span>
                  <span className="text-slate-400 shrink-0">:</span>
                  <span className="text-slate-800">{value || '—'}</span>
                </div>
              ))}
            </div>

            <div className="flex-1 overflow-y-auto px-5 py-3">
              <p className="text-[12px] font-semibold text-slate-600 mb-2">Items</p>
              {viewEntry.details?.length > 0 ? (
                <table className="w-full text-[11.5px] border border-slate-200 rounded">
                  <thead className="bg-slate-100 sticky top-0">
                    <tr>
                      {['#','PO No','Item Code','Item Name','Supplier Part No','Description','HSN','Unit','Qty','Rec Qty'].map(h => (
                        <th key={h} className="px-2 py-1 text-left font-semibold text-slate-600 border-b border-slate-200 whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {viewEntry.details.map((it, idx) => (
                      <tr key={idx} className={`border-b border-slate-100 ${idx%2===1?'bg-slate-50/50':''}`}>
                        <td className="px-2 py-1">{idx+1}</td>
                        <td className="px-2 py-1">{it.poNo || '—'}</td>
                        <td className="px-2 py-1">{it.itemCode || '—'}</td>
                        <td className="px-2 py-1 whitespace-nowrap">{it.itemName || '—'}</td>
                        <td className="px-2 py-1">{it.supplierPartNo || '—'}</td>
                        <td className="px-2 py-1">{it.description || '—'}</td>
                        <td className="px-2 py-1">{it.hsnCode || '—'}</td>
                        <td className="px-2 py-1">{it.unit || '—'}</td>
                        <td className="px-2 py-1 text-right">{it.qty ?? '—'}</td>
                        <td className="px-2 py-1 text-right font-medium">{it.recQty ?? '—'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p className="text-[12px] text-slate-400 italic">No items</p>
              )}
            </div>

            <div className="px-5 py-3 border-t border-slate-100 flex items-center justify-between shrink-0">
              <span className="text-[11.5px] text-slate-400">{viewEntry.details?.length || 0} item(s)</span>
              <button onClick={() => setViewEntry(null)} className="px-4 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-[12px] font-semibold rounded-lg border border-slate-200 transition-colors">
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        message={`Delete gate entry ${deleteTarget?.gateEntryNo}? This action cannot be undone.`}
        onCancel={() => { if (!deleting) setDeleteTarget(null) }}
        onConfirm={handleDeleteConfirm}
        confirming={deleting}
      />
    </div>
  )
}

import { useState, useEffect, useCallback, useRef } from 'react'
import {
  ChevronRight, Package, Store, Settings, Paperclip,
  Pencil, Trash2, Eye, Download, Image as ImageIcon,
  FileImage, FileX, FileMinus, LayoutList, Loader2, X,
} from 'lucide-react'
import { useToast } from '../components/Toast'
import ConfirmDialog from '../components/ConfirmDialog'
import { SpinnerLoader } from '../components/LocalLoader'

const api = {
  get: (url) => fetch(url).then(r => r.json()),
  post: (url, data) => fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  }).then(r => r.json()),
  put: (url, data) => fetch(url, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  }).then(r => r.json()),
  del: (url) => fetch(url, { method: 'DELETE' }).then(r => r.json()),
}


const Label = ({ children, required }) => (
  <label className="block text-[11px] font-semibold text-slate-600 mb-1 uppercase tracking-wider">
    {required && <span className="text-red-500 mr-0.5">*</span>}
    {children}
  </label>
)

const Input = ({ placeholder, value, onChange, type = 'text', disabled, readOnly, list, hasError }) => (
  <input
    type={type}
    placeholder={placeholder}
    value={value}
    onChange={onChange}
    disabled={disabled}
    readOnly={readOnly}
    list={list}
    min={type === 'number' ? '0' : undefined}
    className={`w-full px-2.5 py-1.5 text-[13px] border rounded text-slate-800 placeholder-slate-400 focus:outline-none transition-all duration-200 disabled:bg-slate-50 disabled:text-slate-400 ${
      hasError
        ? 'border-red-500 focus:ring-2 focus:ring-red-500/20 focus:border-red-500'
        : 'border-slate-200 focus:ring-2 focus:ring-[#0097A7]/20 focus:border-[#0097A7] hover:border-slate-300'
    } ${readOnly ? 'bg-slate-50 cursor-not-allowed border-[#0097A7]/40' : 'bg-white'}`}
  />
)

const Select = ({ options = [], placeholder, value, onChange, loading, hasError }) => (
  <div className="relative">
    <select
      value={value}
      onChange={onChange}
      disabled={loading}
      className={`w-full px-2.5 py-1.5 pr-8 text-[13px] border rounded bg-white text-slate-700 appearance-none focus:outline-none transition-all duration-200 hover:border-slate-300 cursor-pointer disabled:bg-slate-50 disabled:text-slate-400 ${
        hasError
          ? 'border-red-500 focus:ring-2 focus:ring-red-500/20 focus:border-red-500'
          : 'border-slate-200 focus:ring-2 focus:ring-[#0097A7]/20 focus:border-[#0097A7]'
      }`}
    >
      <option value="">{loading ? 'Loading…' : placeholder}</option>
      {options.map(o => (
        <option key={o.value} value={String(o.value)}>{o.label}</option>
      ))}
    </select>
    <div className="pointer-events-none absolute inset-y-0 right-3 flex items-center">
      {loading
        ? <Loader2 className="w-3.5 h-3.5 text-slate-400 animate-spin" />
        : <svg className="w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
        </svg>
      }
    </div>
  </div>
)

const AutocompleteSelect = ({ options = [], placeholder, value, onChange, loading, dropdownAlign = 'bottom', allowCustom = false }) => {
  const [isOpen, setIsOpen] = useState(false)
  const [inputValue, setInputValue] = useState('')
  const [highlightedIndex, setHighlightedIndex] = useState(-1)
  const containerRef = useRef(null)

  const getSelectedLabel = useCallback(() => {
    const selected = options.find(o => String(o.value) === String(value))
    if (selected) return selected.label
    return allowCustom ? String(value || '') : ''
  }, [value, options, allowCustom])

  useEffect(() => {
    setInputValue(getSelectedLabel())
  }, [value, options, getSelectedLabel])

  useEffect(() => {
    if (!isOpen) return

    const handleOutsideClick = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsOpen(false)
        setInputValue(prev => {
          const matched = options.find(o => String(o.label || '').toLowerCase() === prev.toLowerCase())
          if (matched) {
            onChange(String(matched.value))
            return matched.label
          } else {
            if (allowCustom) {
              onChange(prev)
              return prev
            } else {
              return getSelectedLabel()
            }
          }
        })
      }
    }
    document.addEventListener('mousedown', handleOutsideClick)
    return () => document.removeEventListener('mousedown', handleOutsideClick)
  }, [isOpen, options, getSelectedLabel, onChange, allowCustom])

  const filtered = options.filter(o =>
    String(o.label || '').toLowerCase().includes(inputValue.toLowerCase())
  )

  const handleInputChange = (e) => {
    const val = e.target.value
    setInputValue(val)
    setIsOpen(true)
    setHighlightedIndex(-1)

    if (allowCustom) {
      onChange(val)
    } else {
      const matched = options.find(o => String(o.label || '').toLowerCase() === val.toLowerCase())
      if (matched) {
        onChange(String(matched.value))
      }
    }
  }

  const handleSelect = (option) => {
    setInputValue(option.label)
    onChange(String(option.value))
    setIsOpen(false)
  }

  const handleKeyDown = (e) => {
    if (!isOpen) {
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Enter') {
        setIsOpen(true)
        return
      }
    }

    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setHighlightedIndex(prev =>
        prev < filtered.length - 1 ? prev + 1 : 0
      )
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setHighlightedIndex(prev =>
        prev > 0 ? prev - 1 : filtered.length - 1
      )
    } else if (e.key === 'Enter') {
      e.preventDefault()
      if (highlightedIndex >= 0 && highlightedIndex < filtered.length) {
        handleSelect(filtered[highlightedIndex])
      } else {
        const matched = options.find(o => String(o.label || '').toLowerCase() === inputValue.toLowerCase())
        if (matched) {
          handleSelect(matched)
        } else {
          if (allowCustom) {
            onChange(inputValue)
            setIsOpen(false)
          } else {
            setInputValue(getSelectedLabel())
            setIsOpen(false)
          }
        }
      }
    } else if (e.key === 'Escape') {
      setInputValue(getSelectedLabel())
      setIsOpen(false)
    }
  }

  return (
    <div className="relative" ref={containerRef}>
      <div className="relative">
        <input
          type="text"
          value={inputValue}
          onChange={handleInputChange}
          onFocus={() => setIsOpen(true)}
          onKeyDown={handleKeyDown}
          placeholder={loading ? 'Loading…' : placeholder}
          disabled={loading}
          className="w-full px-2.5 py-1.5 pr-8 text-[13px] border border-slate-200 rounded bg-white text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#0097A7]/20 focus:border-[#0097A7] transition-all duration-200 hover:border-slate-300 disabled:bg-slate-50 disabled:text-slate-400"
        />
        <div
          onClick={() => !loading && setIsOpen(o => !o)}
          className="absolute inset-y-0 right-3 flex items-center cursor-pointer"
        >
          {loading ? (
            <Loader2 className="w-3.5 h-3.5 text-slate-400 animate-spin" />
          ) : (
            <svg className="w-4 h-4 text-slate-400 hover:text-[#0097A7] transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          )}
        </div>
      </div>
      {isOpen && !loading && (
        <div className={`absolute ${dropdownAlign === 'top' ? 'bottom-[100%] mb-1' : 'top-[100%] mt-1'} left-0 right-0 z-50 bg-white border border-slate-200 rounded shadow-lg max-h-52 overflow-y-auto`}>
          {filtered.length > 0 ? (
            filtered.map((opt, idx) => (
              <div
                key={opt.value}
                onClick={() => handleSelect(opt)}
                onMouseEnter={() => setHighlightedIndex(idx)}
                className={`px-3 py-2 text-[12.5px] cursor-pointer transition-colors ${highlightedIndex === idx
                    ? 'bg-[#0097A7] text-white'
                    : 'text-slate-700 hover:bg-slate-50'
                  }`}
              >
                {opt.label}
              </div>
            ))
          ) : (
            <div className="px-3 py-2 text-xs text-slate-400 italic">
              No matching options.
            </div>
          )}
        </div>
      )}
    </div>
  )
}

const SectionCard = ({ title, children, icon, className = '', bodyClassName = 'space-y-3' }) => (
  <div className={`bg-white rounded-xl border border-slate-100 shadow-[0_2px_8px_rgba(0,151,167,0.06)] overflow-hidden ${className}`}>
