    if (l.includes('electrical')) return 'text-amber-600'
    if (l.includes('gas') || l.includes('cutting')) return 'text-orange-600'
    if (l.includes('v10') || l.includes('groundhog')) return 'text-blue-600'
    return 'text-slate-600'
  }

