                    ) : (
                      records.map((row, idx) => {
                        const isSelected = selectedRecordId === row.id
                        return (
                          <tr
                            key={row.id}
                            onClick={() => setSelectedRecordId(isSelected ? null : row.id)}
                            className={`hover:bg-slate-50 transition-colors cursor-pointer h-12 ${isSelected ? 'bg-sky-50/70 border-l-[3px] border-l-[#0097A7] pl-[13px]' : ''}`}
                          >
                            <td className="px-4 py-2 border-r border-slate-200 text-center text-slate-400 font-bold text-[12px]">{idx + 1}</td>
                            <td className="px-4 py-2 border-r border-slate-200 font-semibold text-slate-800 text-[12px]">{row.ledgerName}</td>
                            <td className="px-4 py-2 border-r border-slate-200 text-[#0097A7] font-bold text-[12px]">{row.customerCode}</td>
                            <td className="px-4 py-2 border-r border-slate-200 text-center text-slate-500 text-[12px]">
                              {new Date(row.logDate).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })}
                            </td>
                            <td className="px-4 py-2 border-r border-slate-200 text-[12px]">
                              {row.documentPath ? (
                                <span className="inline-flex items-center gap-1.5 text-[#0097A7] font-semibold">
                                  <FileText size={13} /> {row.documentPath}
                                </span>
                              ) : (
                                <span className="text-slate-400 italic">No File</span>
                              )}
                            </td>
                            <td className="px-4 py-2 text-slate-600 text-[12px] truncate max-w-[200px]" title={row.remarks}>
                              {row.remarks || '—'}
                            </td>
                          </tr>
                        )
                      })
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>
      <ConfirmDialog
        open={showDeleteConfirm}
        title="Delete Document Log"
        message="Are you sure you want to delete this document upload log? This action cannot be undone."
        onConfirm={handleConfirmDelete}
        onCancel={() => setShowDeleteConfirm(false)}
        confirming={isDeleting}
      />
    </div>
  )
}

import { useState, useEffect } from 'react'
import { ChevronRight, Plus, Trash2, Send, X, Search, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import { TableSkeleton } from '../components/LocalLoader'
import api from '../services/api'

const today = new Date().toISOString().split('T')[0]
const tomorrow = new Date(Date.now() + 24*60*60*1000).toISOString().split('T')[0]

const getDaysDiff = (requiredDate, requestDate) => {
  if (!requiredDate || !requestDate) return ''
  const req = new Date(requiredDate)
  const reqst = new Date(requestDate)
  req.setHours(0, 0, 0, 0)
  reqst.setHours(0, 0, 0, 0)
  const diffTime = req - reqst
  const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24))
  return isNaN(diffDays) ? '' : String(diffDays)
}

const emptyItem = () => ({
  modelName:'', itemCode:'', itemName:'', requestedQty:'', materialGrade:'', unit:'', remarks:'',
})

const inp = (err='') =>
  `w-full border rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 transition-colors bg-white ${err ? 'border-red-400 focus:ring-red-300' : 'border-slate-300 focus:ring-[#0097A7] focus:border-[#0097A7]'}`
const lbl = 'text-[12px] font-semibold text-slate-600 whitespace-nowrap'

const fetchRefList = async (type) => {
  try {
    const res = await api.get(`/api/reference-master/${encodeURIComponent(type)}`, { skipGlobalLoader: true })
    return (res.data?.data || []).map(r => r.description).filter(Boolean)
  } catch {
    return []
  }
}

const LoadingSelect = ({ loading, value, onChange, className, children }) => (
  <div className="relative flex-1 min-w-0">
    <select
      value={value}
      onChange={onChange}
      disabled={loading}
      className={`${className} w-full ${loading ? 'opacity-60' : ''}`}
    >
      {children}
    </select>
    {loading && (
      <Loader2 size={11} className="animate-spin absolute right-7 top-1/2 -translate-y-1/2 text-[#0097A7] pointer-events-none" />
    )}
  </div>
)

