                 <span className="text-slate-400 mr-2 uppercase text-[10px]">Total Payment Amount</span>
                 <span className="text-[14px] text-[#0097A7]">
                   {filteredData.reduce((acc, r) => acc + parseFloat(r.amount), 0).toFixed(2)}
                 </span>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

/* eslint-disable */
import { useState, useEffect } from 'react'
import { ChevronRight, ChevronDown, Search, Trash2, Printer, X, RefreshCw, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import { SpinnerLoader } from '../components/LocalLoader'
import api from '../services/api'

const today    = new Date().toISOString().split('T')[0]
const ago30    = new Date(Date.now() - 30*24*60*60*1000).toISOString().split('T')[0]
const PAGE_SIZES = [5, 10, 25, 50]

const fmtDate = (d) => {
  if (!d) return '—'
  return new Date(d).toLocaleDateString('en-GB', { day:'2-digit', month:'2-digit', year:'numeric' })
}

const statusBadge = (s) => {
  const map = {
    Draft:    'bg-slate-100 text-slate-600',
    Pending:  'bg-amber-100 text-amber-700',
    Approved: 'bg-green-100 text-green-700',
    Rejected: 'bg-red-100 text-red-700',
  }
  return map[s] ?? 'bg-slate-100 text-slate-600'
}

const inp = 'border border-slate-300 rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] bg-white'

const HEADER_COLS_BASE = ['','Request No','Request Date','Department','Requesting User','Required Date','Status','Requesting For','Vehicle Name','Created By','Created Date']

export default function PrintMaterialRequest() {
  const toast = useToast()

  const pickMode = window.__velsonMrPickMode === true

  const [allRows,   setAllRows]   = useState([])
  const [loading,   setLoading]   = useState(false)
  const [fromDate,  setFromDate]  = useState(ago30)
  const [toDate,    setToDate]    = useState(today)
  const [search,    setSearch]    = useState('')
  const [pageSize,  setPageSize]  = useState(10)
  const [page,      setPage]      = useState(1)
  const [expanded,  setExpanded]  = useState(null)
  const [selected,  setSelected]  = useState(null)

  const handlePickSelect = (row) => {
    window.__velsonMrPickMode = false
    window.__velsonMrPickId = row.id
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'PurchaseRequestEntry' } }))
  }

  const fetchData = async () => {
    setLoading(true)
    try {
      const res = await api.get('/api/material-request', { skipGlobalLoader: true })
      setAllRows(res.data?.data || [])
    } catch {
      toast.error('Failed to load material requests')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { fetchData() }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const filtered = allRows.filter(r => {
    const rd = r.requestDate ? r.requestDate.slice(0, 10) : ''
    if (fromDate && rd < fromDate) return false
    if (toDate   && rd > toDate)   return false
    if (search.trim()) {
      const q = search.toLowerCase()
      return (
        (r.mrNo          || '').toLowerCase().includes(q) ||
        (r.departmentTo  || '').toLowerCase().includes(q) ||
        (r.requestingUser|| '').toLowerCase().includes(q) ||
        (r.requestingFor || '').toLowerCase().includes(q) ||
        (r.storeName     || '').toLowerCase().includes(q) ||
        (r.vehicleName   || '').toLowerCase().includes(q) ||
        (r.status        || '').toLowerCase().includes(q)
      )
    }
    return true
  })

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paged      = filtered.slice((page - 1) * pageSize, page * pageSize)

  const toggleExpand = (id) => setExpanded(prev => prev === id ? null : id)

  const handleDelete = async () => {
    if (!selected) { toast.warning('Select a row to delete.'); return }
    try {
      await api.delete(`/api/material-request/${selected}`)
      toast.success('Record deleted.')
      setSelected(null)
      setExpanded(null)
      fetchData()
    } catch {
      toast.error('Failed to delete.')
    }
  }

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        <span className="hover:text-[#0097A7] cursor-pointer">Stores</span>
        <ChevronRight className="w-3 h-3"/>
        <span className="text-[#0097A7] font-semibold">Print Material Request</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        {/* Toolbar */}
        <div className="bg-[--color-main] px-4 py-2.5 flex items-center justify-between">
          <h2 className="text-white font-semibold text-[14px]">
            {pickMode ? 'Select a Material Request' : 'Material Request List'}
          </h2>
          <div className="flex items-center gap-2">
            <button onClick={fetchData} className="flex items-center gap-1 px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors">
              <RefreshCw className="w-3 h-3"/> Refresh
            </button>
            {!pickMode && <>
              <button onClick={handleDelete} className="flex items-center gap-1 px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors">
                <Trash2 className="w-3 h-3"/> Delete
              </button>
              <button className="flex items-center gap-1 px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors">
                <Printer className="w-3 h-3"/> Print
              </button>
            </>}
            <button
              onClick={() => {
                if (pickMode) { window.__velsonMrPickMode = false }
                window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: pickMode ? 'PurchaseRequestEntry' : 'PrintMaterialRequest' } }))
              }}
              className="flex items-center gap-1 px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors"
            >
              <X className="w-3 h-3"/> {pickMode ? 'Cancel' : 'Close'}
            </button>
          </div>
        </div>

        {/* Filter bar */}
        <div className="px-4 py-3 flex flex-wrap items-center gap-3 border-b border-slate-200 bg-slate-50">
          <div className="flex items-center gap-1.5">
            <label className="text-[12px] font-semibold text-slate-600 whitespace-nowrap">From Date:</label>
            <input type="date" value={fromDate} onChange={e => { setFromDate(e.target.value); setPage(1) }} className={inp} />
          </div>
          <div className="flex items-center gap-1.5">
            <label className="text-[12px] font-semibold text-slate-600 whitespace-nowrap">To Date:</label>
            <input type="date" value={toDate} onChange={e => { setToDate(e.target.value); setPage(1) }} className={inp} />
          </div>
          <button onClick={() => setPage(1)} className="flex items-center gap-1.5 px-4 py-1.5 bg-[#0097A7] hover:bg-[#007a87] text-white text-[12.5px] font-semibold rounded transition-colors shadow-sm">
            <Search className="w-3.5 h-3.5"/> Search
          </button>
        </div>

        {/* Pagination controls */}
        <div className="flex items-center justify-between px-4 py-2 border-b border-slate-100">
          <div className="flex items-center gap-2 text-[12.5px] text-slate-600">
            Show
            <select value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setPage(1) }} className={`${inp} w-16`}>
              {PAGE_SIZES.map(s => <option key={s}>{s}</option>)}
            </select>
            entries
          </div>
          <div className="flex items-center gap-2">
            <label className="text-[12px] text-slate-600">Search:</label>
            <input value={search} onChange={e => { setSearch(e.target.value); setPage(1) }} className={`${inp} w-44`} placeholder="MR No / Dept / User…" />
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto w-full">
          {loading ? (
            <SpinnerLoader message="Loading material requests…" />
          ) : (
            <table className="min-w-full text-[12.5px]">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-200">
                  {[...HEADER_COLS_BASE, ...(pickMode ? [''] : [])].map(h => (
                    <th key={h} className="px-3 py-2 text-center font-bold text-slate-600 text-[11px] uppercase tracking-wide whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {paged.length === 0 ? (
                  <tr><td colSpan={HEADER_COLS_BASE.length + (pickMode ? 1 : 0)} className="text-center py-12 text-slate-400 text-[13px]">No data available</td></tr>
                ) : paged.map((row, idx) => {
                  const isSelected = selected === row.id
                  const isExpanded = expanded === row.id
                  const rowBg = isSelected
                    ? 'bg-[#e3f2fd] border-l-2 border-l-[#0097A7]'
                    : idx % 2 === 1 ? 'bg-slate-50/50' : ''

                  return [
                    /* Master row */
                    <tr
                      key={row.id}
                      onClick={() => { setSelected(row.id); toggleExpand(row.id) }}
                      className={`border-b border-slate-100 hover:bg-slate-50 cursor-pointer transition-colors ${rowBg}`}
                    >
                      <td className="px-2 py-2 text-center">
                        {isExpanded
                          ? <ChevronDown className="w-3.5 h-3.5 text-[#0097A7] mx-auto" />
                          : <ChevronRight className="w-3.5 h-3.5 text-slate-400 mx-auto" />}
                      </td>
                      <td className="px-3 py-2 text-center font-semibold text-[#0097A7] whitespace-nowrap">{row.mrNo}</td>
                      <td className="px-3 py-2 text-center whitespace-nowrap">{fmtDate(row.requestDate)}</td>
                      <td className="px-3 py-2 text-center">{row.departmentTo || '—'}</td>
                      <td className="px-3 py-2 text-center">{row.requestingUser || '—'}</td>
                      <td className="px-3 py-2 text-center whitespace-nowrap">{fmtDate(row.requiredDate)}</td>
                      <td className="px-3 py-2 text-center">
                        <span className={`px-2 py-0.5 rounded-full text-[11px] font-semibold ${statusBadge(row.status)}`}>{row.status}</span>
                      </td>
                      <td className="px-3 py-2 text-center">{row.requestingFor || '—'}</td>
                      {/* <td className="px-3 py-2 text-center">{row.storeName || '—'}</td> */}
                      <td className="px-3 py-2 text-center">{row.vehicleName || '—'}</td>
                      <td className="px-3 py-2 text-center">{row.createdBy || '—'}</td>
                      <td className="px-3 py-2 text-center whitespace-nowrap">{fmtDate(row.createdAt)}</td>
                      {pickMode && (
                        <td className="px-3 py-2 text-center" onClick={e => e.stopPropagation()}>
                          <button
                            onClick={() => handlePickSelect(row)}
                            className="px-3 py-1 bg-[#0097A7] hover:bg-[#007a87] text-white text-[11px] font-semibold rounded transition-colors"
                          >
                            Select
                          </button>
                        </td>
                      )}
                    </tr>,

                    /* Expanded detail rows */
                    isExpanded && (
                      <tr key={`detail-${row.id}`}>
                        <td colSpan={HEADER_COLS_BASE.length + (pickMode ? 1 : 0)} className="px-0 py-0 bg-blue-50 border-b border-blue-100">
                          <div className="px-6 py-3">
                            <p className="text-[11px] font-bold text-slate-500 uppercase tracking-wide mb-2">Items — {row.mrNo}</p>
                            {(!row.details || row.details.length === 0) ? (
                              <p className="text-[12px] text-slate-400 italic">No items recorded.</p>
                            ) : (
                              <table className="w-full text-[12px] border border-slate-200 rounded">
                                <thead>
                                  <tr className="bg-slate-100 text-slate-600 text-[11px] uppercase">
                                    {['S.NO','Model Name','Item Code','Item Name','Requested Qty','Material Grade','Unit','Remarks'].map(h => (
                                      <th key={h} className="px-2 py-1.5 text-center font-bold whitespace-nowrap">{h}</th>
                                    ))}
                                  </tr>
                                </thead>
                                <tbody>
                                  {row.details.map((d, i) => (
                                    <tr key={d.id} className={`border-t border-slate-100 ${i % 2 === 1 ? 'bg-white' : 'bg-blue-50/40'}`}>
                                      <td className="px-2 py-1 text-center text-slate-500">{d.slNo}</td>
                                      <td className="px-2 py-1 text-center">{d.modelName || '—'}</td>
                                      <td className="px-2 py-1 text-center font-medium text-[#0097A7]">{d.itemCode || '—'}</td>
                                      <td className="px-2 py-1">{d.itemName || '—'}</td>
                                      <td className="px-2 py-1 text-center font-semibold">{d.requestedQty ?? '—'}</td>
                                      <td className="px-2 py-1 text-center">{d.materialGrade || '—'}</td>
                                      <td className="px-2 py-1 text-center">{d.unit || '—'}</td>
                                      <td className="px-2 py-1">{d.remarks || '—'}</td>
                                    </tr>
                                  ))}
                                </tbody>
                              </table>
                            )}
                            {row.remarks && (
                              <p className="mt-2 text-[12px] text-slate-500"><span className="font-semibold">Remarks:</span> {row.remarks}</p>
                            )}
                          </div>
                        </td>
                      </tr>
                    ),
                  ]
                })}
              </tbody>
            </table>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-slate-200 bg-slate-50">
          <span className="text-[12px] text-slate-500">
            {filtered.length === 0
              ? 'No entries'
              : `Showing ${(page - 1) * pageSize + 1}–${Math.min(page * pageSize, filtered.length)} of ${filtered.length} entries`}
          </span>
          <div className="flex items-center gap-1">
            <button onClick={() => setPage(1)} disabled={page === 1} className="px-2 py-1.5 text-[11px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 transition-colors">«</button>
            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1} className="px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 transition-colors">Previous</button>
            <span className="px-3 py-1.5 text-[12px] text-slate-600 font-semibold">{page} / {totalPages}</span>
            <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages} className="px-3 py-1.5 text-[12px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 transition-colors">Next</button>
            <button onClick={() => setPage(totalPages)} disabled={page === totalPages} className="px-2 py-1.5 text-[11px] border border-slate-300 rounded hover:bg-slate-100 disabled:opacity-40 transition-colors">»</button>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { ChevronRight, FileText, FileSpreadsheet, File as FilePdf, Filter, Settings, X, Trash2, Printer, Eye, Pencil } from 'lucide-react'
import ConfirmDialog from '../components/ConfirmDialog'

const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
const fmtDate = d => {
  if (!d) return ''
  const dt = new Date(d)
  return `${String(dt.getDate()).padStart(2,'0')}-${months[dt.getMonth()]}-${dt.getFullYear()}`
}

const inp = 'border border-slate-300 rounded px-2 py-1 text-[12.5px] focus:outline-none focus:border-[#0097A7] bg-white'
const lbl = 'text-[12px] font-semibold text-slate-600 whitespace-nowrap'
const iconBtn = 'flex items-center gap-1 text-[12px] text-slate-600 hover:text-[#0097A7] transition-colors cursor-pointer select-none'

const applyFilter = (records, from, to) => {
  const f = from ? new Date(from) : null
  const t = to   ? new Date(to + 'T23:59:59') : null
  return records.filter(po => {
    const d = new Date(po.poDate)
    if (f && d < f) return false
    if (t && d > t) return false
    return true
  })
}

const ALL_COLS = [
  'PO No', 'PO Date', 'PO Type', 'Supplier Name', 'Contact Person',
  'ETA Date', 'Status', 'Total Amount',
]

const buildRows = (data) =>
  data.map(po => ({
    'PO No':          po.poNo || '',
    'PO Date':        fmtDate(po.poDate),
    'PO Type':        po.poType || '',
    'Supplier Name':  po.supplier?.supplierName || '',
    'Contact Person': po.contactPerson || '',
    'ETA Date':       fmtDate(po.etaDate),
    'Status':         po.status || '',
    'Total Amount':   po.totalAmount != null ? Number(po.totalAmount).toFixed(2) : '0.00',
  }))

const downloadBlob = (blob, filename) => {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url; a.download = filename
  document.body.appendChild(a); a.click()
  document.body.removeChild(a); URL.revokeObjectURL(url)
}

const doExcelExport = (data, from, to) => {
  const rows = buildRows(data)
  if (!rows.length) return
  const cols = Object.keys(rows[0])
  const lines = [
    cols.join(','),
    ...rows.map(r => cols.map(c => `"${String(r[c]).replace(/"/g,'""')}"`).join(','))
  ]
  const blob = new Blob(['﻿' + lines.join('\n')], { type: 'text/csv;charset=utf-8;' })
  downloadBlob(blob, `purchase-orders-${from}-${to}.csv`)
}

const doDocExport = (data, from, to) => {
  const rows = buildRows(data)
  if (!rows.length) return
  const cols = Object.keys(rows[0])
  const thead = cols.map(c => `<th style="padding:5px 8px;background:#0097A7;color:#fff;text-align:left;font-size:11px;">${c}</th>`).join('')
  const tbody = rows.map((r, i) =>
    `<tr style="${i%2?'background:#f8fafc;':''}">
      ${cols.map(c => `<td style="padding:4px 8px;border:1px solid #e2e8f0;font-size:11px;">${r[c]}</td>`).join('')}
    </tr>`
  ).join('')
  const html = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word'>
<head><meta charset='utf-8'><style>body{font-family:Arial;font-size:12px}h2{font-size:15px}p{font-size:11px;color:#555}</style></head>
<body>
<h2>Purchase Order List</h2>
<p>Date Range: ${from} to ${to} &nbsp;&nbsp; Generated: ${new Date().toLocaleDateString()}</p>
<table border="1" style="border-collapse:collapse;width:100%"><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
<p style="margin-top:8px">Total Records: ${rows.length}</p>
</body></html>`
  const blob = new Blob([html], { type: 'application/msword' })
  downloadBlob(blob, `purchase-orders-${from}-${to}.doc`)
}

const doPrintList = (data, from, to) => {
  const rows = buildRows(data)
  const cols = Object.keys(rows[0] || {})
  const thead = cols.map(c => `<th>${c}</th>`).join('')
  const tbody = rows.map((r, i) =>
    `<tr class="${i%2?'alt':''}"><td>${cols.map(c => r[c]).join('</td><td>')}</td></tr>`
  ).join('')
  const win = window.open('', '_blank', 'width=1100,height=750')
  win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Purchase Orders</title>
<style>
  *{box-sizing:border-box}
  body{font-family:Arial,sans-serif;font-size:11px;margin:16px;color:#222}
  h2{font-size:15px;margin:0 0 4px}
  .meta{font-size:10px;color:#666;margin-bottom:10px}
  table{width:100%;border-collapse:collapse}
  th{background:#0097A7;color:#fff;padding:5px 7px;text-align:left;font-size:10px;white-space:nowrap}
  td{padding:4px 7px;border-bottom:1px solid #e2e8f0;font-size:10px}
  tr.alt td{background:#f8fafc}
  .footer{margin-top:10px;font-size:10px;color:#777}
  @media print{@page{margin:1cm}button{display:none}}
</style></head><body>
<h2>Purchase Order List</h2>
<p class="meta">Date Range: ${from} to ${to} &nbsp;|&nbsp; Printed: ${new Date().toLocaleDateString()} &nbsp;|&nbsp; Records: ${rows.length}</p>
<table><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
<p class="footer">Total Rows: ${rows.length}</p>
</body></html>`)
  win.document.close()
  win.focus()
  setTimeout(() => { win.print() }, 400)
}

const doPrintSingle = (po) => {
  const win = window.open('', '_blank', 'width=900,height=750')
  const items = (po.details || []).map((d, i) =>
    `<tr class="${i%2?'alt':''}">
      <td>${i+1}</td><td>${d.itemCode||'-'}</td><td>${d.itemName||'-'}</td>
      <td>${d.description||'-'}</td><td>${d.hsnCode||'-'}</td>
      <td>${d.uom||'-'}</td><td>${d.qty||0}</td><td>${Number(d.unitPrice||0).toFixed(2)}</td>
      <td>${Number(d.discPer||0).toFixed(2)}</td><td>${Number(d.amount||0).toFixed(2)}</td>
      <td>${Number(d.gstPer||0).toFixed(2)}</td><td>${Number(d.gstAmt||0).toFixed(2)}</td>
      <td>${Number(d.netAmt||0).toFixed(2)}</td>
    </tr>`
  ).join('')
  win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>PO - ${po.poNo}</title>
<style>
  *{box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:11px;margin:20px;color:#222}
  .header{display:flex;justify-content:space-between;margin-bottom:12px;border-bottom:2px solid #0097A7;padding-bottom:8px}
  .company{font-size:16px;font-weight:bold;color:#0097A7}.sub{font-size:11px;color:#555}
  h3{font-size:13px;margin:0 0 2px}
  .info{display:grid;grid-template-columns:1fr 1fr;gap:4px 16px;margin-bottom:10px}
  .info-row{display:flex;gap:6px;font-size:11px}
  .info-row span:first-child{font-weight:600;width:130px;color:#555;flex-shrink:0}
  table{width:100%;border-collapse:collapse;margin-top:8px}
  th{background:#0097A7;color:#fff;padding:4px 6px;font-size:10px;text-align:left;white-space:nowrap}
  td{padding:3px 6px;border-bottom:1px solid #e2e8f0;font-size:10px}
  tr.alt td{background:#f8fafc}
  .totals{display:flex;justify-content:flex-end;margin-top:8px}
  .totals-box{width:280px}
  .tot-row{display:flex;justify-content:space-between;font-size:11px;padding:2px 0}
  .grand{font-weight:bold;font-size:13px;color:#0097A7;border-top:1px solid #ccc;padding-top:4px;margin-top:4px}
  @media print{@page{margin:1cm}button{display:none}}
</style></head><body>
<div class="header">
  <div><div class="company">PURCHASE ORDER</div><div class="sub">PO No: <strong>${po.poNo}</strong> &nbsp;|&nbsp; Date: ${fmtDate(po.poDate)}</div></div>
  <div style="text-align:right;font-size:11px;color:#555">Status: <strong>${po.status||''}</strong><br>ETA: ${fmtDate(po.etaDate)}</div>
</div>
<div class="info">
  <div class="info-row"><span>Supplier</span><span>: ${po.supplier?.supplierName||'-'}</span></div>
  <div class="info-row"><span>PO Type</span><span>: ${po.poType||'-'}</span></div>
  <div class="info-row"><span>Address</span><span>: ${po.supplierAddress||'-'}</span></div>
  <div class="info-row"><span>Contact Person</span><span>: ${po.contactPerson||'-'}</span></div>
  <div class="info-row"><span>GST No</span><span>: ${po.gstNo||'-'}</span></div>
  <div class="info-row"><span>Payment Terms</span><span>: ${po.paymentTerms||'-'}</span></div>
  <div class="info-row"><span>Freight</span><span>: ${po.freight||'-'}</span></div>
  <div class="info-row"><span>Delivery Period</span><span>: ${po.deliveryPeriod||'-'}</span></div>
  <div class="info-row"><span>Remarks</span><span>: ${po.remarks||'-'}</span></div>
</div>
<table>
  <thead><tr><th>#</th><th>Item Code</th><th>Item Name</th><th>Description</th><th>HSN</th><th>UOM</th><th>Qty</th><th>Unit Price</th><th>Disc%</th><th>Amount</th><th>GST%</th><th>GST Amt</th><th>Net Amt</th></tr></thead>
  <tbody>${items||'<tr><td colspan="13" style="text-align:center;padding:10px">No items</td></tr>'}</tbody>
</table>
<div class="totals"><div class="totals-box">
  <div class="tot-row"><span>Sub Total</span><span>${Number(po.subTotal||0).toFixed(2)}</span></div>
  ${po.cgstAmt > 0 ? `<div class="tot-row"><span>CGST (${po.cgstPer}%)</span><span>${Number(po.cgstAmt).toFixed(2)}</span></div>` : ''}
  ${po.sgstAmt > 0 ? `<div class="tot-row"><span>SGST (${po.sgstPer}%)</span><span>${Number(po.sgstAmt).toFixed(2)}</span></div>` : ''}
  ${po.igstAmt > 0 ? `<div class="tot-row"><span>IGST (${po.igstPer}%)</span><span>${Number(po.igstAmt).toFixed(2)}</span></div>` : ''}
  ${po.othersAmt > 0 ? `<div class="tot-row"><span>Others (${po.othersPer}%)</span><span>${Number(po.othersAmt).toFixed(2)}</span></div>` : ''}
  <div class="tot-row grand"><span>Grand Total</span><span>${Number(po.totalAmount||0).toFixed(2)}</span></div>
</div></div>
</body></html>`)
  win.document.close()
  win.focus()
  setTimeout(() => { win.print() }, 400)
}

export default function PrintPurchaseOrder() {
  const [fromDate, setFromDate]   = useState('2026-04-01')
  const [toDate, setToDate]       = useState(new Date().toISOString().split('T')[0])
  const [activeRow, setActiveRow] = useState(null)
  const [allData, setAllData]     = useState([])
  const [data, setData]           = useState([])
  const [loading, setLoading]     = useState(false)

  const [viewPO, setViewPO]               = useState(null)
  const [deleteTarget, setDeleteTarget]   = useState(null)
  const [deleting, setDeleting]           = useState(false)

  const [filterOpen, setFilterOpen]   = useState(false)
  const [filterText, setFilterText]   = useState('')
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [hiddenCols, setHiddenCols]   = useState(new Set())
  const settingsRef = useRef(null)

  useEffect(() => {
    const handler = e => {
      if (settingsRef.current && !settingsRef.current.contains(e.target)) setSettingsOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true)
      try {
        const res  = await fetch('http://localhost:3000/api/purchase-master')
        const json = await res.json()
        if (json.success && json.data) {
          setAllData(json.data)
          setData(applyFilter(json.data, fromDate, toDate))
        }
      } catch (err) {
        console.error('Error fetching purchase orders:', err)
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [])

  const handleSearch = () => {
    setData(applyFilter(allData, fromDate, toDate))
    setActiveRow(null)
    setFilterText('')
  }

  const displayData = filterText.trim()
    ? data.filter(po => {
        const q = filterText.toLowerCase()
        return (
          (po.poNo || '').toLowerCase().includes(q) ||
          (po.poType || '').toLowerCase().includes(q) ||
          (po.supplier?.supplierName || '').toLowerCase().includes(q) ||
          (po.status || '').toLowerCase().includes(q) ||
          (po.contactPerson || '').toLowerCase().includes(q)
        )
      })
    : data

  const toggleCol = col =>
    setHiddenCols(prev => {
      const next = new Set(prev)
      next.has(col) ? next.delete(col) : next.add(col)
      return next
    })
  const visibleCols = ALL_COLS.filter(c => !hiddenCols.has(c))

  const handleExcel = () => doExcelExport(displayData, fromDate, toDate)
  const handleDoc   = () => doDocExport(displayData, fromDate, toDate)
  const handlePrint = () => doPrintList(displayData, fromDate, toDate)

  const handleClose = () =>
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'Dashboard' } }))

  const handleHeaderDelete = () => {
    if (activeRow === null || !displayData[activeRow]) return
    setDeleteTarget(displayData[activeRow])
  }

  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return
    setDeleting(true)
    try {
      const res  = await fetch(`http://localhost:3000/api/purchase-master/${deleteTarget.id}`, { method: 'DELETE' })
      const json = await res.json()
      if (res.ok && json.success !== false) {
        const updated = allData.filter(r => r.id !== deleteTarget.id)
        setAllData(updated)
        setData(applyFilter(updated, fromDate, toDate))
        setActiveRow(null)
      }
    } catch (err) {
      console.error('Delete failed:', err)
    } finally {
      setDeleting(false)
      setDeleteTarget(null)
    }
  }

  const handleEdit = (po, e) => {
    e.stopPropagation()
    localStorage.setItem('velson:po-edit', String(po.id))
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'PurchaseOrderEntry' } }))
  }

  const renderCell = (po, col) => {
    switch (col) {
      case 'PO No':         return <td key={col} className="p-1.5 border-x border-slate-200 font-medium text-[#0097A7]">{po.poNo}</td>
      case 'PO Date':       return <td key={col} className="p-1.5 border-x border-slate-200">{fmtDate(po.poDate)}</td>
      case 'PO Type':       return <td key={col} className="p-1.5 border-x border-slate-200">{po.poType || ''}</td>
      case 'Supplier Name': return <td key={col} className="p-1.5 border-x border-slate-200">{po.supplier?.supplierName || ''}</td>
      case 'Contact Person':return <td key={col} className="p-1.5 border-x border-slate-200">{po.contactPerson || ''}</td>
      case 'ETA Date':      return <td key={col} className="p-1.5 border-x border-slate-200">{fmtDate(po.etaDate)}</td>
      case 'Status':        return (
        <td key={col} className="p-1.5 border-x border-slate-200">
          <span className={`font-medium ${po.status === 'Approval' ? 'text-green-600' : po.status === 'Rejected' ? 'text-red-500' : 'text-amber-600'}`}>
            {po.status}
          </span>
        </td>
      )
      case 'Total Amount':  return <td key={col} className="p-1.5 border-x border-slate-200 text-right font-medium">{Number(po.totalAmount||0).toFixed(2)}</td>
      default: return null
    }
  }

  const colSpanTotal = visibleCols.length + 3

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden h-screen flex flex-col">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400 shrink-0">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3" /> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Purchase</span>
        <ChevronRight className="w-3 h-3" />
        <span className="text-[#0097A7] font-semibold">Print Purchase Order</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm flex flex-col flex-1 overflow-hidden">
        {/* Header */}
        <div className="bg-[#0097A7] px-4 py-2.5 flex items-center justify-between shrink-0">
          <h2 className="text-white font-semibold text-[14px]">Print Purchase Order</h2>
          <div className="flex gap-2">
            <button
              onClick={handleHeaderDelete}
              disabled={activeRow === null}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1 disabled:opacity-40"
            >
              <Trash2 className="w-3 h-3" /> Delete
            </button>
            <button
              onClick={handlePrint}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1"
            >
              <Printer className="w-3 h-3" /> Print Purchase Order
            </button>
            <button
              onClick={handleClose}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1"
            >
              <X className="w-3 h-3" /> Close
            </button>
          </div>
        </div>

        {/* Filter Bar */}
        <div className="p-3 border-b border-slate-200 flex items-center justify-between bg-slate-50/50 shrink-0">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <label className={lbl}>From Date :</label>
              <input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className={inp} />
            </div>
            <div className="flex items-center gap-2">
              <label className={lbl}>To Date :</label>
              <input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className={inp} />
            </div>
            <button
              onClick={handleSearch}
              className="flex items-center gap-1.5 px-4 py-1 border border-[#0097A7] text-[#0097A7] bg-white hover:bg-[#0097A7]/10 rounded text-[12px] font-medium transition-colors shadow-sm"
            >
              <span className="w-2 h-2 rounded-full bg-red-500"></span> Search
            </button>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center gap-1.5">
              <span className="text-[12px] font-medium text-slate-500">LS</span>
              <input value={displayData.length} readOnly className="w-10 text-center border border-slate-300 rounded text-[12px] py-0.5 bg-slate-50" />
            </div>
            <div className="h-4 w-px bg-slate-300" />
            <button onClick={handleDoc} className={iconBtn} title="Export as Word document">
              <FileText className="w-4 h-4 text-[#0097A7]" /> Dos
            </button>
            <button onClick={handleExcel} className={iconBtn} title="Export as Excel/CSV">
              <FileSpreadsheet className="w-4 h-4 text-[#0097A7]" /> Excel
            </button>
            <button onClick={handlePrint} className={iconBtn} title="Export as PDF / Print">
              <FilePdf className="w-4 h-4 text-red-500" /> Pdf
            </button>
            <button
              onClick={() => { setFilterOpen(o => !o); if (filterOpen) setFilterText('') }}
              className={`${iconBtn} ${filterOpen ? 'text-[#0097A7]' : ''}`}
            >
              <Filter className={`w-4 h-4 ${filterOpen ? 'text-[#0097A7]' : 'text-blue-500'}`} /> Filter
            </button>
            <div className="relative" ref={settingsRef}>
              <button
                onClick={() => setSettingsOpen(o => !o)}
                className={`${iconBtn} ${settingsOpen ? 'text-[#0097A7]' : ''}`}
              >
                <Settings className="w-4 h-4 text-slate-700" /> Setting
              </button>
              {settingsOpen && (
                <div className="absolute right-0 top-7 bg-white border border-slate-200 rounded-lg shadow-xl z-50 p-3 min-w-[180px]">
                  <p className="text-[11px] font-bold text-slate-500 uppercase mb-2 tracking-wide">Show / Hide Columns</p>
                  {ALL_COLS.map(col => (
                    <label key={col} className="flex items-center gap-2 py-1 cursor-pointer hover:text-[#0097A7]">
                      <input type="checkbox" checked={!hiddenCols.has(col)} onChange={() => toggleCol(col)} className="accent-[#0097A7]" />
                      <span className="text-[12px] text-slate-700">{col}</span>
                    </label>
                  ))}
                  <button onClick={() => setHiddenCols(new Set())} className="mt-2 w-full text-[11px] py-1 bg-slate-100 hover:bg-slate-200 rounded text-slate-600 transition-colors">
                    Reset All
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Inline text filter */}
        {filterOpen && (
          <div className="px-3 py-2 border-b border-slate-200 bg-blue-50/40 flex items-center gap-3 shrink-0">
            <Filter className="w-3.5 h-3.5 text-blue-400 shrink-0" />
            <input
              autoFocus
              type="text"
              value={filterText}
              onChange={e => setFilterText(e.target.value)}
              placeholder="Search across PO No, Supplier, Type, Status…"
              className="flex-1 border border-blue-200 rounded px-3 py-1 text-[12.5px] focus:outline-none focus:border-[#0097A7] bg-white"
            />
            {filterText && (
              <button onClick={() => setFilterText('')} className="text-slate-400 hover:text-slate-600 transition-colors">
                <X className="w-3.5 h-3.5" />
              </button>
            )}
            <span className="text-[11px] text-slate-400 shrink-0">{displayData.length} result{displayData.length !== 1 ? 's' : ''}</span>
          </div>
        )}

        {/* Data Grid */}
        <div className="flex-1 overflow-auto relative">
          {loading ? (
            <div className="flex items-center justify-center h-32 gap-2.5 text-slate-500 text-[12px]">
              <span className="w-5 h-5 border-2 border-slate-200 border-t-[#0097A7] rounded-full animate-spin" />
              Loading…
            </div>
          ) : (
            <table className="w-full min-w-max text-[12px] text-left border-collapse">
              <thead className="bg-slate-800 text-white sticky top-0 z-10">
                <tr>
                  {visibleCols.map(h => (
                    <th key={h} className="p-2 font-medium border-x border-slate-700 whitespace-nowrap">{h}</th>
                  ))}
                  <th className="p-2 font-medium border-x border-slate-700 text-center">View</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Edit</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Delete</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 bg-white">
                {displayData.length === 0 ? (
                  <tr>
                    <td colSpan={colSpanTotal} className="p-8 text-center text-slate-400 text-[12px]">
                      {filterText ? 'No matching records' : 'No purchase orders found'}
                    </td>
                  </tr>
                ) : displayData.map((po, i) => (
                  <tr
                    key={po.id}
                    onClick={() => setActiveRow(i)}
                    className={`cursor-pointer transition-colors ${activeRow === i ? 'bg-[#0097A7]/20' : 'hover:bg-slate-50'}`}
                  >
                    {visibleCols.map(col => renderCell(po, col))}
                    <td className="p-1.5 border-x border-slate-200 text-center">
                      <button
                        onClick={e => { e.stopPropagation(); setViewPO(po) }}
                        className="text-[#0097A7] hover:text-[#007a87] transition-colors"
                        title="View details"
                      >
                        <Eye className="w-3.5 h-3.5" />
                      </button>
                    </td>
                    <td className="p-1.5 border-x border-slate-200 text-center">
                      <button
                        onClick={e => handleEdit(po, e)}
                        className="text-amber-500 hover:text-amber-600 transition-colors"
                        title="Edit"
                      >
                        <Pencil className="w-3.5 h-3.5" />
                      </button>
                    </td>
                    <td className="p-1.5 border-x border-slate-200 text-center">
                      <button
                        onClick={e => { e.stopPropagation(); setDeleteTarget(po) }}
                        className="text-red-500 hover:text-red-600 transition-colors"
                        title="Delete"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="sticky bottom-0 bg-[#f4f6ce] font-semibold text-slate-800 border-t-2 border-slate-300">
                <tr>
                  <td colSpan={colSpanTotal} className="p-2 border-x border-slate-300">
                    Row : {displayData.length}{filterText ? ` (filtered from ${data.length})` : ''}
                  </td>
                </tr>
              </tfoot>
            </table>
          )}
        </div>
      </div>

      {/* View Modal */}
      {viewPO && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setViewPO(null)} />
          <div className="relative bg-white rounded-xl shadow-2xl border border-slate-200 w-[720px] max-h-[88vh] overflow-hidden flex flex-col">
            <div className="px-5 py-3 flex items-center justify-between shrink-0 bg-[#0097A7]">
              <div>
                <h3 className="text-white font-semibold text-[14px]">Purchase Order Details</h3>
                <p className="text-white/70 text-[11px] mt-0.5">{viewPO.poNo} &nbsp;·&nbsp; {viewPO.status}</p>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => doPrintSingle(viewPO)}
                  className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1"
                >
                  <Printer className="w-3.5 h-3.5" /> Print
                </button>
                <button onClick={() => setViewPO(null)} className="text-white/80 hover:text-white transition-colors">
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>

            <div className="px-5 pt-4 pb-3 grid grid-cols-2 gap-x-6 gap-y-2 text-[12.5px] shrink-0 border-b border-slate-100">
              {[
                ['PO Number',     viewPO.poNo],
                ['PO Date',       fmtDate(viewPO.poDate)],
                ['PO Type',       viewPO.poType],
                ['ETA Date',      fmtDate(viewPO.etaDate)],
                ['Supplier',      viewPO.supplier?.supplierName],
                ['Contact Person',viewPO.contactPerson],
                ['GST No',        viewPO.gstNo],
                ['Status',        viewPO.status],
                ['Payment Terms', viewPO.paymentTerms],
                ['Freight',       viewPO.freight],
                ['Delivery Period',viewPO.deliveryPeriod],
                ['Remarks',       viewPO.remarks],
              ].map(([label, value]) => (
                <div key={label} className="flex gap-2">
                  <span className="w-32 font-semibold text-slate-500 shrink-0">{label}</span>
                  <span className="text-slate-400 shrink-0">:</span>
                  <span className="text-slate-800">{value || '-'}</span>
                </div>
              ))}
            </div>

            <div className="flex-1 overflow-y-auto px-5 py-3">
              <p className="text-[12px] font-semibold text-slate-600 mb-2">Items</p>
              {viewPO.details?.length > 0 ? (
                <table className="w-full text-[11.5px] border border-slate-200 rounded">
                  <thead className="bg-slate-100 sticky top-0">
                    <tr>
                      {['#','Item Code','Item Name','Description','HSN','UOM','Qty','Unit Price','Disc%','Amount','GST%','GST Amt','Net Amt'].map(h => (
                        <th key={h} className="px-2 py-1 text-left font-semibold text-slate-600 border-b border-slate-200 whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {viewPO.details.map((d, idx) => (
                      <tr key={idx} className={`border-b border-slate-100 ${idx % 2 === 1 ? 'bg-slate-50/50' : ''}`}>
                        <td className="px-2 py-1">{idx+1}</td>
                        <td className="px-2 py-1">{d.itemCode||'-'}</td>
                        <td className="px-2 py-1 whitespace-nowrap">{d.itemName||'-'}</td>
                        <td className="px-2 py-1">{d.description||'-'}</td>
                        <td className="px-2 py-1">{d.hsnCode||'-'}</td>
                        <td className="px-2 py-1">{d.uom||'-'}</td>
                        <td className="px-2 py-1 text-right">{d.qty||0}</td>
                        <td className="px-2 py-1 text-right">{Number(d.unitPrice||0).toFixed(2)}</td>
                        <td className="px-2 py-1 text-right">{Number(d.discPer||0).toFixed(2)}</td>
                        <td className="px-2 py-1 text-right">{Number(d.amount||0).toFixed(2)}</td>
                        <td className="px-2 py-1 text-right">{Number(d.gstPer||0).toFixed(2)}</td>
                        <td className="px-2 py-1 text-right">{Number(d.gstAmt||0).toFixed(2)}</td>
                        <td className="px-2 py-1 text-right font-medium">{Number(d.netAmt||0).toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p className="text-[12px] text-slate-400 italic">No items</p>
              )}
            </div>

            <div className="px-5 py-3 border-t border-slate-100 flex items-center justify-between shrink-0 bg-slate-50">
              <div className="flex gap-6 text-[12px]">
                <span><span className="font-semibold text-slate-500">Sub Total:</span> <span className="font-medium">{Number(viewPO.subTotal||0).toFixed(2)}</span></span>
                {viewPO.cgstAmt > 0 && <span><span className="font-semibold text-slate-500">CGST:</span> {Number(viewPO.cgstAmt).toFixed(2)}</span>}
                {viewPO.sgstAmt > 0 && <span><span className="font-semibold text-slate-500">SGST:</span> {Number(viewPO.sgstAmt).toFixed(2)}</span>}
                {viewPO.igstAmt > 0 && <span><span className="font-semibold text-slate-500">IGST:</span> {Number(viewPO.igstAmt).toFixed(2)}</span>}
              </div>
              <div className="flex items-center gap-4">
                <span className="text-[13px] font-bold text-[#0097A7]">Grand Total: {Number(viewPO.totalAmount||0).toFixed(2)}</span>
                <button onClick={() => setViewPO(null)} className="px-4 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-[12px] font-semibold rounded-lg border border-slate-200 transition-colors">
                  Close
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        message={`Delete purchase order ${deleteTarget?.poNo}? This action cannot be undone.`}
        onCancel={() => { if (!deleting) setDeleteTarget(null) }}
        onConfirm={handleDeleteConfirm}
        confirming={deleting}
      />
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { ChevronRight, FileText, FileSpreadsheet, File as FilePdf, Filter, Settings, X, Trash2, Printer, Eye, Pencil } from 'lucide-react'
import ConfirmDialog from '../components/ConfirmDialog'

const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
const fmtDate = d => {
  if (!d) return ''
  const dt = new Date(d)
  return `${String(dt.getDate()).padStart(2,'0')}-${months[dt.getMonth()]}-${dt.getFullYear()}`
}

const inp = 'border border-slate-300 rounded px-2 py-1 text-[12.5px] focus:outline-none focus:border-[#0097A7] bg-white'
const lbl = 'text-[12px] font-semibold text-slate-600 whitespace-nowrap'
const iconBtn = 'flex items-center gap-1 text-[12px] text-slate-600 hover:text-[#0097A7] transition-colors cursor-pointer select-none'

const applyFilter = (records, from, to) => {
  const f = from ? new Date(from) : null
  const t = to   ? new Date(to + 'T23:59:59') : null
  return records.filter(pr => {
    const d = new Date(pr.prDate)
    if (f && d < f) return false
    if (t && d > t) return false
    return true
  })
}

const ALL_COLS = [
  'Request No', 'Request Date', 'Department Name', 'Job No',
  'Request User', 'Required Date', 'Approval', 'PO No', 'PO Date',
]

/* ─── export helpers ──────────────────────────────────────── */
const buildRows = (data) =>
  data.map(pr => ({
    'Request No':    pr.prNo || '',
    'Request Date':  fmtDate(pr.prDate),
    'Department':    pr.department || '',
    'Job No':        pr.details?.map(d => d.jobNo).filter(Boolean).join('; ') || '',
    'Request User':  pr.requestingUser || '',
    'Required Date': fmtDate(pr.requiredDate),
    'Approval':      pr.status || '',
    'PO No':         pr.poNo || '',
    'PO Date':       pr.poDate ? fmtDate(pr.poDate) : '',
  }))

const downloadBlob = (blob, filename) => {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url; a.download = filename
  document.body.appendChild(a); a.click()
  document.body.removeChild(a); URL.revokeObjectURL(url)
}

const doExcelExport = (data, from, to) => {
  const rows = buildRows(data)
  if (!rows.length) return
  const cols = Object.keys(rows[0])
  const lines = [
    cols.join(','),
    ...rows.map(r => cols.map(c => `"${String(r[c]).replace(/"/g,'""')}"`).join(','))
  ]
  const blob = new Blob(['﻿' + lines.join('\n')], { type: 'text/csv;charset=utf-8;' })
  downloadBlob(blob, `purchase-requests-${from}-${to}.csv`)
}

const doDocExport = (data, from, to) => {
  const rows = buildRows(data)
  if (!rows.length) return
  const cols = Object.keys(rows[0])
  const thead = cols.map(c => `<th style="padding:5px 8px;background:#0097A7;color:#fff;text-align:left;font-size:11px;">${c}</th>`).join('')
  const tbody = rows.map((r, i) =>
    `<tr style="${i%2?'background:#f8fafc;':''}">
      ${cols.map(c => `<td style="padding:4px 8px;border:1px solid #e2e8f0;font-size:11px;">${r[c]}</td>`).join('')}
    </tr>`
  ).join('')
  const html = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word'>
<head><meta charset='utf-8'><style>body{font-family:Arial;font-size:12px}h2{font-size:15px}p{font-size:11px;color:#555}</style></head>
<body>
<h2>Purchase Request List</h2>
<p>Date Range: ${from} to ${to} &nbsp;&nbsp; Generated: ${new Date().toLocaleDateString()}</p>
<table border="1" style="border-collapse:collapse;width:100%"><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
<p style="margin-top:8px">Total Records: ${rows.length}</p>
</body></html>`
  const blob = new Blob([html], { type: 'application/msword' })
  downloadBlob(blob, `purchase-requests-${from}-${to}.doc`)
}

const doPrint = (data, from, to) => {
  const rows = buildRows(data)
  const cols = Object.keys(rows[0] || {})
  const thead = cols.map(c => `<th>${c}</th>`).join('')
  const tbody = rows.map((r, i) =>
    `<tr class="${i%2?'alt':''}"><td>${cols.map(c => r[c]).join('</td><td>')}</td></tr>`
  ).join('')
  const win = window.open('', '_blank', 'width=1100,height=750')
  win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Purchase Requests</title>
<style>
  *{box-sizing:border-box}
  body{font-family:Arial,sans-serif;font-size:11px;margin:16px;color:#222}
  h2{font-size:15px;margin:0 0 4px}
  .meta{font-size:10px;color:#666;margin-bottom:10px}
  table{width:100%;border-collapse:collapse}
  th{background:#0097A7;color:#fff;padding:5px 7px;text-align:left;font-size:10px;white-space:nowrap}
  td{padding:4px 7px;border-bottom:1px solid #e2e8f0;font-size:10px}
  tr.alt td{background:#f8fafc}
  .footer{margin-top:10px;font-size:10px;color:#777}
  @media print{@page{margin:1cm}button{display:none}}
</style></head><body>
<h2>Purchase Request List</h2>
<p class="meta">Date Range: ${from} to ${to} &nbsp;|&nbsp; Printed: ${new Date().toLocaleDateString()} &nbsp;|&nbsp; Records: ${rows.length}</p>
<table><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
<p class="footer">Total Rows: ${rows.length}</p>
</body></html>`)
  win.document.close()
  win.focus()
  setTimeout(() => { win.print() }, 400)
}

/* ─── component ───────────────────────────────────────────── */
export default function PrintPurchaseRequest() {
  const [fromDate, setFromDate]     = useState('2026-04-01')
  const [toDate, setToDate]         = useState(new Date().toISOString().split('T')[0])
  const [activeRow, setActiveRow]   = useState(null)
  const [allData, setAllData]       = useState([])
  const [data, setData]             = useState([])
  const [loading, setLoading]       = useState(false)

  // modals / dialogs
  const [viewPR, setViewPR]         = useState(null)
  const [deleteTarget, setDeleteTarget] = useState(null)
  const [deleting, setDeleting]     = useState(false)
  const [approving, setApproving]   = useState(false)
  const [rejecting, setRejecting]   = useState(false)

  // inline filter (Filter button)
  const [filterOpen, setFilterOpen] = useState(false)
  const [filterText, setFilterText] = useState('')

  // column visibility (Settings button)
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [hiddenCols, setHiddenCols]     = useState(new Set())
  const settingsRef = useRef(null)

  useEffect(() => {
    const handler = e => {
      if (settingsRef.current && !settingsRef.current.contains(e.target)) setSettingsOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true)
      try {
        const res  = await fetch('http://localhost:3000/api/purchase-request')
        const json = await res.json()
        if (json.success && json.data) {
          setAllData(json.data)
          setData(applyFilter(json.data, fromDate, toDate))
        }
      } catch (err) {
        console.error('Error fetching purchase requests:', err)
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [])

  /* ── date search ── */
  const handleSearch = () => {
    setData(applyFilter(allData, fromDate, toDate))
    setActiveRow(null)
    setFilterText('')
  }

  /* ── live column filter ── */
  const displayData = filterText.trim()
    ? data.filter(pr => {
        const q = filterText.toLowerCase()
        const jobNo = pr.details?.map(d => d.jobNo).filter(Boolean).join(' ') || ''
        return (
          (pr.prNo || '').toLowerCase().includes(q) ||
          (pr.department || '').toLowerCase().includes(q) ||
          (pr.requestingUser || '').toLowerCase().includes(q) ||
          (pr.status || '').toLowerCase().includes(q) ||
          (pr.poNo || '').toLowerCase().includes(q) ||
          jobNo.toLowerCase().includes(q)
        )
      })
    : data

  /* ── column visibility ── */
  const toggleCol = col =>
    setHiddenCols(prev => {
      const next = new Set(prev)
      next.has(col) ? next.delete(col) : next.add(col)
      return next
    })
  const visibleCols = ALL_COLS.filter(c => !hiddenCols.has(c))

  /* ── exports ── */
  const handleExcel = () => doExcelExport(displayData, fromDate, toDate)
  const handleDoc   = () => doDocExport(displayData, fromDate, toDate)
  const handlePrint = () => doPrint(displayData, fromDate, toDate)

  /* ── close ── */
  const handleClose = () =>
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'Dashboard' } }))

  /* ── header-level delete (deletes active row) ── */
  const handleHeaderDelete = () => {
    if (activeRow === null || !displayData[activeRow]) return
    setDeleteTarget(displayData[activeRow])
  }

  /* ── row delete confirm ── */
  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return
    setDeleting(true)
    try {
      const res  = await fetch(`http://localhost:3000/api/purchase-request/${deleteTarget.id}`, { method: 'DELETE' })
      const json = await res.json()
      if (res.ok && json.success !== false) {
        const updated = allData.filter(r => r.id !== deleteTarget.id)
        setAllData(updated)
        setData(applyFilter(updated, fromDate, toDate))
        setActiveRow(null)
      }
    } catch (err) {
      console.error('Delete failed:', err)
    } finally {
      setDeleting(false)
      setDeleteTarget(null)
    }
  }

  /* ── edit ── */
  const handleEdit = (pr, e) => {
    e.stopPropagation()
    localStorage.setItem('velson:pr-edit', String(pr.id))
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'PurchaseRequestEntry' } }))
  }

  /* ── approve ── */
  const handleApprove = async (pr) => {
    setApproving(true)
    try {
      // If PR already has a PO number, navigate to edit that existing PO
      if (pr.poNo) {
        const poListRes  = await fetch('http://localhost:3000/api/purchase-master')
        const poListJson = await poListRes.json()
        if (poListJson.success) {
          const existingPO = poListJson.data.find(p => p.poNo === pr.poNo)
          if (existingPO) {
            setViewPR(null)
            localStorage.setItem('velson:po-edit', String(existingPO.id))
            window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'PurchaseOrderEntry' } }))
            return
          }
        }
      }

      // First-time approval: generate a new PO number
      const nextRes  = await fetch('http://localhost:3000/api/purchase-master/next-no')
      const nextJson = await nextRes.json()
      if (!nextJson.success) throw new Error('Could not generate PO number')
      const poNo   = nextJson.poNo
      const poDate = new Date().toISOString().split('T')[0]

      // Update PR status to Approved and save the generated PO number
      const prRes = await fetch(`http://localhost:3000/api/purchase-request/${pr.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prDate: pr.prDate, requiredDate: pr.requiredDate,
          department: pr.department, departmentId: pr.departmentId,
          requestingUser: pr.requestingUser,
          team: pr.team, teamId: pr.teamId,
          requestingFor: pr.requestingFor, requestingForId: pr.requestingForId,
          remarks: pr.remarks,
          status: 'Approved', poNo, poDate,
          updatedBy: 'Admin',
          items: pr.details || [],
        }),
      })
      const prJson = await prRes.json()
      if (!prJson.success) throw new Error(prJson.message || 'Failed to approve request')

      const patch = r => r.id === pr.id ? { ...r, status: 'Approved', poNo, poDate } : r
      setAllData(prev => prev.map(patch))
      setData(prev => prev.map(patch))
      setViewPR(null)

      // Pre-fill PurchaseOrderEntry with PR data; PO will be created there
      localStorage.setItem('velson:po-prefill', JSON.stringify({
        poNo, poDate, prNo: pr.prNo, items: pr.details || [],
      }))
      window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'PurchaseOrderEntry' } }))
    } catch (err) {
      console.error('Approve failed:', err)
      alert('Approval failed: ' + err.message)
    } finally {
      setApproving(false)
    }
  }

  /* ── reject ── */
  const handleReject = async (pr) => {
    setRejecting(true)
    try {
      await fetch(`http://localhost:3000/api/purchase-request/${pr.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prDate: pr.prDate, requiredDate: pr.requiredDate,
          department: pr.department, departmentId: pr.departmentId,
          requestingUser: pr.requestingUser,
          team: pr.team, teamId: pr.teamId,
          requestingFor: pr.requestingFor, requestingForId: pr.requestingForId,
          remarks: pr.remarks,
          status: 'Rejected',
          updatedBy: 'Admin',
          items: pr.details || [],
        }),
      })
      const patch = r => r.id === pr.id ? { ...r, status: 'Rejected' } : r
      setAllData(prev => prev.map(patch))
      setData(prev => prev.map(patch))
      setViewPR(null)
    } catch (err) {
      console.error('Reject failed:', err)
    } finally {
      setRejecting(false)
    }
  }

  /* ── column cell renderer ── */
  const renderCell = (pr, col, jobNo) => {
    switch (col) {
      case 'Request No':    return <td key={col} className="p-1.5 border-x border-slate-200 font-medium text-[#0097A7]">{pr.prNo}</td>
      case 'Request Date':  return <td key={col} className="p-1.5 border-x border-slate-200">{fmtDate(pr.prDate)}</td>
      case 'Department Name': return <td key={col} className="p-1.5 border-x border-slate-200">{pr.department || ''}</td>
      case 'Job No':        return <td key={col} className="p-1.5 border-x border-slate-200">{jobNo}</td>
      case 'Request User':  return <td key={col} className="p-1.5 border-x border-slate-200">{pr.requestingUser || ''}</td>
      case 'Required Date': return <td key={col} className="p-1.5 border-x border-slate-200">{fmtDate(pr.requiredDate)}</td>
      case 'Approval':      return <td key={col} className="p-1.5 border-x border-slate-200"><span className={`font-medium ${pr.status === 'Approved' ? 'text-green-600' : pr.status === 'Rejected' ? 'text-red-500' : 'text-amber-600'}`}>{pr.status}</span></td>
      case 'PO No':         return <td key={col} className="p-1.5 border-x border-slate-200 font-medium text-[#0097A7]">{pr.poNo || ''}</td>
      case 'PO Date':       return <td key={col} className="p-1.5 border-x border-slate-200">{pr.poDate ? fmtDate(pr.poDate) : ''}</td>
      default: return null
    }
  }

  const totalActionCols = 3 // View + Edit + Delete always visible
  const colSpanTotal    = visibleCols.length + totalActionCols

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden h-screen flex flex-col">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400 shrink-0">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3" /> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Purchase</span>
        <ChevronRight className="w-3 h-3" />
        <span className="text-[#0097A7] font-semibold">Print Purchase Request</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm flex flex-col flex-1 overflow-hidden">
        {/* Header */}
        <div className="bg-[#0097A7] px-4 py-2.5 flex items-center justify-between shrink-0">
          <h2 className="text-white font-semibold text-[14px]">Print Purchase Request</h2>
          <div className="flex gap-2">
            <button
              onClick={handleHeaderDelete}
              disabled={activeRow === null}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1 disabled:opacity-40"
            >
              <Trash2 className="w-3 h-3" /> Delete
            </button>
            <button
              onClick={handlePrint}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1"
            >
              <Printer className="w-3 h-3" /> Print Purchase Request
            </button>
            <button
              onClick={handleClose}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1"
            >
              <X className="w-3 h-3" /> Close
            </button>
          </div>
        </div>

        {/* Filter Bar */}
        <div className="p-3 border-b border-slate-200 flex items-center justify-between bg-slate-50/50 shrink-0">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <label className={lbl}>From Date :</label>
              <input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className={inp} />
            </div>
            <div className="flex items-center gap-2">
              <label className={lbl}>To Date :</label>
              <input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className={inp} />
            </div>
            <button
              onClick={handleSearch}
              className="flex items-center gap-1.5 px-4 py-1 border border-[#0097A7] text-[#0097A7] bg-white hover:bg-[#0097A7]/10 rounded text-[12px] font-medium transition-colors shadow-sm"
            >
              <span className="w-2 h-2 rounded-full bg-red-500"></span> Search
            </button>
          </div>

          {/* Export + utility controls */}
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-1.5">
              <span className="text-[12px] font-medium text-slate-500">LS</span>
              <input value={displayData.length} readOnly className="w-10 text-center border border-slate-300 rounded text-[12px] py-0.5 bg-slate-50" />
            </div>
            <div className="h-4 w-px bg-slate-300" />
            <button onClick={handleDoc} className={iconBtn} title="Export as Word document">
              <FileText className="w-4 h-4 text-[#0097A7]" /> Dos
            </button>
            <button onClick={handleExcel} className={iconBtn} title="Export as Excel/CSV">
              <FileSpreadsheet className="w-4 h-4 text-[#0097A7]" /> Excel
            </button>
            <button onClick={handlePrint} className={iconBtn} title="Export as PDF / Print">
              <FilePdf className="w-4 h-4 text-red-500" /> Pdf
            </button>
            <button
              onClick={() => { setFilterOpen(o => !o); if (filterOpen) setFilterText('') }}
              className={`${iconBtn} ${filterOpen ? 'text-[#0097A7]' : ''}`}
              title="Toggle search filter"
            >
              <Filter className={`w-4 h-4 ${filterOpen ? 'text-[#0097A7]' : 'text-blue-500'}`} /> Filter
            </button>
            <div className="relative" ref={settingsRef}>
              <button
                onClick={() => setSettingsOpen(o => !o)}
                className={`${iconBtn} ${settingsOpen ? 'text-[#0097A7]' : ''}`}
                title="Column visibility settings"
              >
                <Settings className="w-4 h-4 text-slate-700" /> Setting
              </button>
              {settingsOpen && (
                <div className="absolute right-0 top-7 bg-white border border-slate-200 rounded-lg shadow-xl z-50 p-3 min-w-[180px]">
                  <p className="text-[11px] font-bold text-slate-500 uppercase mb-2 tracking-wide">Show / Hide Columns</p>
                  {ALL_COLS.map(col => (
                    <label key={col} className="flex items-center gap-2 py-1 cursor-pointer hover:text-[#0097A7]">
                      <input
                        type="checkbox"
                        checked={!hiddenCols.has(col)}
                        onChange={() => toggleCol(col)}
                        className="accent-[#0097A7]"
                      />
                      <span className="text-[12px] text-slate-700">{col}</span>
                    </label>
                  ))}
                  <button
                    onClick={() => setHiddenCols(new Set())}
                    className="mt-2 w-full text-[11px] py-1 bg-slate-100 hover:bg-slate-200 rounded text-slate-600 transition-colors"
                  >
                    Reset All
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Inline text filter bar */}
        {filterOpen && (
          <div className="px-3 py-2 border-b border-slate-200 bg-blue-50/40 flex items-center gap-3 shrink-0">
            <Filter className="w-3.5 h-3.5 text-blue-400 shrink-0" />
            <input
              autoFocus
              type="text"
              value={filterText}
              onChange={e => setFilterText(e.target.value)}
              placeholder="Search across Request No, Department, User, Status, PO No, Job No…"
              className="flex-1 border border-blue-200 rounded px-3 py-1 text-[12.5px] focus:outline-none focus:border-[#0097A7] bg-white"
            />
            {filterText && (
              <button onClick={() => setFilterText('')} className="text-slate-400 hover:text-slate-600 transition-colors">
                <X className="w-3.5 h-3.5" />
              </button>
            )}
            <span className="text-[11px] text-slate-400 shrink-0">{displayData.length} result{displayData.length !== 1 ? 's' : ''}</span>
          </div>
        )}

        {/* Data Grid */}
        <div className="flex-1 overflow-auto relative">
          {loading ? (
            <div className="flex items-center justify-center h-32 gap-2.5 text-slate-500 text-[12px]">
              <span className="w-5 h-5 border-2 border-slate-200 border-t-[#0097A7] rounded-full animate-spin" />
              Loading…
            </div>
          ) : (
            <table className="w-full min-w-max text-[12px] text-left border-collapse">
              <thead className="bg-slate-800 text-white sticky top-0 z-10">
                <tr>
                  {visibleCols.map(h => (
                    <th key={h} className="p-2 font-medium border-x border-slate-700 whitespace-nowrap">{h}</th>
                  ))}
                  {/* Action columns always visible */}
                  <th className="p-2 font-medium border-x border-slate-700 text-center">View</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Edit</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Delete</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 bg-white">
                {displayData.length === 0 ? (
                  <tr>
                    <td colSpan={colSpanTotal} className="p-8 text-center text-slate-400 text-[12px]">
                      {filterText ? 'No matching records' : 'No records found'}
                    </td>
                  </tr>
                ) : displayData.map((pr, i) => {
                  const jobNo = pr.details?.map(d => d.jobNo).filter(Boolean).join(', ') || ''
                  return (
                    <tr
                      key={pr.id}
                      onClick={() => setActiveRow(i)}
                      className={`cursor-pointer transition-colors ${activeRow === i ? 'bg-[#0097A7]/20' : 'hover:bg-slate-50'}`}
                    >
                      {visibleCols.map(col => renderCell(pr, col, jobNo))}
                      <td className="p-1.5 border-x border-slate-200 text-center">
                        <button
                          onClick={e => { e.stopPropagation(); setViewPR(pr) }}
                          className="text-[#0097A7] hover:text-[#007a87] transition-colors"
                          title="View details"
                        >
                          <Eye className="w-3.5 h-3.5" />
                        </button>
                      </td>
                      <td className="p-1.5 border-x border-slate-200 text-center">
                        <button
                          onClick={e => handleEdit(pr, e)}
                          className="text-amber-500 hover:text-amber-600 transition-colors"
                          title="Edit"
                        >
                          <Pencil className="w-3.5 h-3.5" />
                        </button>
                      </td>
                      <td className="p-1.5 border-x border-slate-200 text-center">
                        <button
                          onClick={e => { e.stopPropagation(); setDeleteTarget(pr) }}
                          className="text-red-500 hover:text-red-600 transition-colors"
                          title="Delete"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
              <tfoot className="sticky bottom-0 bg-[#f4f6ce] font-semibold text-slate-800 border-t-2 border-slate-300">
                <tr>
                  <td colSpan={colSpanTotal} className="p-2 border-x border-slate-300">
                    Row : {displayData.length}{filterText ? ` (filtered from ${data.length})` : ''}
                  </td>
                </tr>
              </tfoot>
            </table>
          )}
        </div>
      </div>

      {/* ── View Modal ── */}
      {viewPR && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => { if (!approving && !rejecting) setViewPR(null) }} />
          <div className="relative bg-white rounded-xl shadow-2xl border border-slate-200 w-[640px] max-h-[85vh] overflow-hidden flex flex-col">
            <div className={`px-5 py-3 flex items-center justify-between shrink-0 ${viewPR.status === 'Approved' ? 'bg-green-600' : viewPR.status === 'Rejected' ? 'bg-red-500' : 'bg-[#0097A7]'}`}>
              <div>
                <h3 className="text-white font-semibold text-[14px]">Purchase Request Details</h3>
                <p className="text-white/70 text-[11px] mt-0.5">{viewPR.prNo} &nbsp;·&nbsp; {viewPR.status}</p>
              </div>
              <button onClick={() => setViewPR(null)} disabled={approving || rejecting} className="text-white/80 hover:text-white transition-colors disabled:opacity-40">
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="px-5 pt-4 pb-3 grid grid-cols-2 gap-x-6 gap-y-2 text-[12.5px] shrink-0 border-b border-slate-100">
              {[
                ['Request No',      viewPR.prNo],
                ['Request Date',    fmtDate(viewPR.prDate)],
                ['Department',      viewPR.department],
                ['Requesting User', viewPR.requestingUser],
                ['Required Date',   fmtDate(viewPR.requiredDate)],
                ['Status',          viewPR.status],
                ['Team',            viewPR.team],
                ['Requesting For',  viewPR.requestingFor],
                ['Remarks',         viewPR.remarks],
                ['PO No',           viewPR.poNo],
                ['PO Date',         viewPR.poDate ? fmtDate(viewPR.poDate) : null],
              ].map(([label, value]) => (
                <div key={label} className="flex gap-2">
                  <span className="w-32 font-semibold text-slate-500 shrink-0">{label}</span>
                  <span className="text-slate-400 shrink-0">:</span>
                  <span className={`text-slate-800 ${label === 'Status' ? (viewPR.status === 'Approved' ? 'text-green-600 font-semibold' : viewPR.status === 'Rejected' ? 'text-red-500 font-semibold' : 'text-amber-600 font-semibold') : ''}`}>
                    {value || '-'}
                  </span>
                </div>
              ))}
            </div>

            <div className="flex-1 overflow-y-auto px-5 py-3">
              <p className="text-[12px] font-semibold text-slate-600 mb-2">Items</p>
              {viewPR.details?.length > 0 ? (
                <table className="w-full text-[11.5px] border border-slate-200 rounded">
                  <thead className="bg-slate-100 sticky top-0">
                    <tr>
                      {['#','Item Code','Item Name','Specification','Qty','UOM','Job No','Machine No','Purpose'].map(h => (
                        <th key={h} className="px-2 py-1 text-left font-semibold text-slate-600 border-b border-slate-200 whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {viewPR.details.map((d, idx) => (
                      <tr key={idx} className={`border-b border-slate-100 ${idx % 2 === 1 ? 'bg-slate-50/50' : ''}`}>
                        <td className="px-2 py-1">{idx + 1}</td>
                        <td className="px-2 py-1">{d.itemCode || '-'}</td>
                        <td className="px-2 py-1 whitespace-nowrap">{d.itemName || '-'}</td>
                        <td className="px-2 py-1">{d.specification || '-'}</td>
                        <td className="px-2 py-1">{d.qty ?? '-'}</td>
                        <td className="px-2 py-1">{d.uom || '-'}</td>
                        <td className="px-2 py-1">{d.jobNo || '-'}</td>
                        <td className="px-2 py-1">{d.machineNo || '-'}</td>
                        <td className="px-2 py-1">{d.purpose || '-'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p className="text-[12px] text-slate-400 italic">No items</p>
              )}
            </div>

            <div className="px-5 py-3 border-t border-slate-100 flex items-center justify-between shrink-0">
              <span className="text-[11.5px] text-slate-400">{viewPR.details?.length || 0} item(s)</span>
              <div className="flex gap-2">
                <button
                  onClick={() => setViewPR(null)}
                  disabled={approving || rejecting}
                  className="px-4 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-[12px] font-semibold rounded-lg border border-slate-200 transition-colors disabled:opacity-40"
                >
                  Close
                </button>

                {/* Reject — shown only when pending */}
                {viewPR.status !== 'Approved' && viewPR.status !== 'Rejected' && (
                  <button
                    onClick={() => handleReject(viewPR)}
                    disabled={approving || rejecting}
                    className="px-5 py-1.5 bg-red-500 hover:bg-red-600 text-white text-[12px] font-semibold rounded-lg transition-colors shadow-sm disabled:opacity-60 flex items-center gap-1.5"
                  >
                    {rejecting
                      ? <><span className="w-3 h-3 border-2 border-white/40 border-t-white rounded-full animate-spin inline-block" /> Rejecting…</>
                      : 'Reject'}
                  </button>
                )}

                {/* Approve — shown only when pending */}
                {viewPR.status !== 'Approved' && viewPR.status !== 'Rejected' && (
                  <button
                    onClick={() => handleApprove(viewPR)}
                    disabled={approving || rejecting}
                    className="px-5 py-1.5 bg-green-600 hover:bg-green-700 text-white text-[12px] font-semibold rounded-lg transition-colors shadow-sm disabled:opacity-60 flex items-center gap-1.5"
                  >
                    {approving
                      ? <><span className="w-3 h-3 border-2 border-white/40 border-t-white rounded-full animate-spin inline-block" /> Approving…</>
                      : 'Approve'}
                  </button>
                )}

                {/* Status badge when already actioned */}
                {viewPR.status === 'Approved' && (
                  <span className="px-4 py-1.5 bg-green-100 text-green-700 text-[12px] font-semibold rounded-lg border border-green-200">
                    ✓ Approved
                  </span>
                )}
                {viewPR.status === 'Rejected' && (
                  <span className="px-4 py-1.5 bg-red-100 text-red-600 text-[12px] font-semibold rounded-lg border border-red-200">
                    ✗ Rejected
                  </span>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        message={`Delete purchase request ${deleteTarget?.prNo}? This action cannot be undone.`}
        onCancel={() => { if (!deleting) setDeleteTarget(null) }}
        onConfirm={handleDeleteConfirm}
        confirming={deleting}
      />
    </div>
  )
}

import { useState, useEffect, Fragment, useRef } from 'react'
import { X, Save, RotateCcw, List, Edit, Trash2, Info, ChevronRight, ChevronDown, Search, Settings2, Image as ImageIcon, FileText, Plus, Loader2, AlertTriangle, XCircle } from 'lucide-react'
import { useToast } from '../components/Toast'
import api from '../services/api'

const PAGE_SIZES = [4, 10, 25, 50]

const empty = {
  PM_Part_No: '', PM_Part_Name: '', PM_Process_Name: '', PM_Process_Name1: '',
  PM_Process_Order: '1', TeamId: '', Machine_Code: '', Machine_Name: '',
  PM_Days: '', PM_Hours: '', Minutes: '',
  Setting_Time: '', Cycle_Time: '', Handling_Time: '', Idle_Time: '',
}

const today = () => new Date().toISOString().slice(0, 10)

const COLUMN_WIDTHS = {
  'S.No': 'w-[35px]',
  'Process Name': 'w-[19%]',
  'Process Order': 'w-[60px]',
  'Team': 'w-[80px]',
  'Machine Name': 'w-[17%]',
  'Days': 'w-[40px]',
  'Hours': 'w-[40px]',
  'minutes': 'w-[50px]',
  'Setting_Time': 'w-[70px]',
  'Cycle_Time': 'w-[70px]',
  'Handling_Time': 'w-[75px]',
  'Created by': 'w-[80px]',
  'Idel Time': 'w-[65px]',
}

const getHeaderDisplay = (h) => {
  if (h === 'Setting_Time') return 'Setting Time'
  if (h === 'Cycle_Time') return 'Cycle Time'
  if (h === 'Handling_Time') return 'Handling Time'
  if (h === 'Idel Time') return 'Idle Time'
  if (h === 'minutes') return 'Minutes'
  return h
}

export default function ProcessMaster() {
  const toast = useToast()
  const [rows, setRows] = useState([])
  const [form, setForm] = useState({ ...empty })
  const [editId, setEditId] = useState(null)
  const [isSaving, setIsSaving] = useState(false)
  const [search, setSearch] = useState('')
  const [pageSize, setPageSize] = useState(4)
  const [page, setPage] = useState(1)
  const [detailRow, setDetailRow] = useState(null)
  const [partItems, setPartItems] = useState([])
  const [partUploads, setPartUploads] = useState([])
  const [uploadsLoading, setUploadsLoading] = useState(false)
  const [zoomImage, setZoomImage] = useState(null)
  const [processTypes, setProcessTypes] = useState([])
  const [teams, setTeams] = useState([])
  const [machines, setMachines] = useState([])
  const [isAddMode, setIsAddMode] = useState(false)
  const [selectedRowId, setSelectedRowId] = useState(null)
  const [selectedItem, setSelectedItem] = useState(null)
  const [partFilter, setPartFilter] = useState('')
  const [expandedPart, setExpandedPart] = useState(null)
  const [deleteConfirm, setDeleteConfirm] = useState({
    isOpen: false,
    id: null,
    isDeleteAll: false,
    errorMsg: '',
    isDeleting: false
  })
  const [isPartNoDropdownOpen, setIsPartNoDropdownOpen] = useState(false)
  const [partNoHighlightedIndex, setPartNoHighlightedIndex] = useState(-1)
  const partNoDropdownRef = useRef(null)

  useEffect(() => {
    const handleOutsideClick = (e) => {
      if (partNoDropdownRef.current && !partNoDropdownRef.current.contains(e.target)) {
        setIsPartNoDropdownOpen(false)
      }
    }
    document.addEventListener('mousedown', handleOutsideClick)
    return () => document.removeEventListener('mousedown', handleOutsideClick)
  }, [])

  const filteredPartItems = partItems.filter(item =>
    (item.partNo || '').toLowerCase().includes((form.PM_Part_No || '').toLowerCase())
  )

  const handlePartNoKeyDown = (e) => {
    if (!isPartNoDropdownOpen) {
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Enter') {
        setIsPartNoDropdownOpen(true)
        return
      }
    }

    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setPartNoHighlightedIndex(prev =>
        prev < filteredPartItems.length - 1 ? prev + 1 : 0
      )
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setPartNoHighlightedIndex(prev =>
        prev > 0 ? prev - 1 : filteredPartItems.length - 1
      )
    } else if (e.key === 'Enter') {
      e.preventDefault()
      if (partNoHighlightedIndex >= 0 && partNoHighlightedIndex < filteredPartItems.length) {
        const selected = filteredPartItems[partNoHighlightedIndex]
        sf('PM_Part_No', selected.partNo)
        setIsPartNoDropdownOpen(false)
      } else {
        const matched = partItems.find(item => (item.partNo || '').toLowerCase() === (form.PM_Part_No || '').toLowerCase())
        if (matched) {
          sf('PM_Part_No', matched.partNo)
        }
        setIsPartNoDropdownOpen(false)
      }
    } else if (e.key === 'Escape') {
      setIsPartNoDropdownOpen(false)
    }
  }

  const fetchAllProcesses = () => {
    api.get('/api/process-master', { loadingMessage: 'Loading processes...' })
      .then(res => setRows(res.data.data || []))
      .catch(() => { })
  }

  useEffect(() => {
    fetchAllProcesses()

    api.get('/api/item-master?limit=99999', { loadingMessage: 'Loading parts...' })
      .then(res => setPartItems(res.data.data || []))
      .catch(() => { })

    Promise.allSettled([
      api.get(`/api/reference-master/${encodeURIComponent('Process_Type')}`, { loadingMessage: 'Loading references...' })
        .then(res => setProcessTypes((res.data.data || []).map(r => r.description || r.code).filter(Boolean)))
        .catch(() => { }),
      api.get(`/api/reference-master/${encodeURIComponent('Team')}`, { loadingMessage: 'Loading references...' })
        .then(res => setTeams((res.data.data || []).map(r => r.description || r.code).filter(Boolean)))
        .catch(() => { }),
      api.get('/api/machine-master', { loadingMessage: 'Loading machines...' })
        .then(res => setMachines((res.data.data || []).filter(m => m.machineCode)))
        .catch(() => { }),
    ])
  }, [])

  useEffect(() => {
    const item = partItems.find(i => i.partName === form.PM_Part_Name)
    if (!item) {
      setSelectedItem(null)
      setPartUploads([])
      return
    }
    setUploadsLoading(true)

    Promise.allSettled([
      api.get(`/api/item-master/${item.id}`, { loadingMessage: 'Loading item details...' }).then(r => r.data),
      api.get(`/api/item-master/${item.id}/uploads`, { loadingMessage: 'Loading item uploads...' }).then(r => r.data)
    ]).then(([resDetail, resUploads]) => {
      if (resDetail.status === 'fulfilled' && resDetail.value.success) {
        setSelectedItem({ ...item, ...resDetail.value.data })
      } else {
        setSelectedItem(item)
      }
      if (resUploads.status === 'fulfilled' && resUploads.value.success) {
        setPartUploads(resUploads.value.data || [])
      } else {
        setPartUploads([])
      }
    }).catch(() => {
      setSelectedItem(item)
      setPartUploads([])
    }).finally(() => {
      setUploadsLoading(false)
    })
  }, [form.PM_Part_Name, partItems])

  const sf = (k, v) => {
    if (k === 'PM_Part_No') {
      // Auto-populate Part Name from the selected Part No
      const item = partItems.find(i => i.partNo === v)
      const partName = item ? item.partName : ''
      const existing = rows.filter(r => r.PM_Part_Name === partName)
      const nextOrder = existing.length > 0
        ? Math.max(...existing.map(r => Number(r.PM_Process_Order || 0))) + 1
        : 1
      setForm(f => ({
        ...f,
        PM_Part_No: v,
        PM_Part_Name: partName,
        PM_Process_Order: String(nextOrder)
      }))
    } else if (k === 'PM_Part_Name') {
      const existing = rows.filter(r => r.PM_Part_Name === v)
      const nextOrder = existing.length > 0
        ? Math.max(...existing.map(r => Number(r.PM_Process_Order || 0))) + 1
        : 1
      setForm(f => ({
        ...f,
        PM_Part_Name: v,
        PM_Process_Order: String(nextOrder)
      }))
    } else if (k === 'Machine_Code') {
      const m = machines.find(x => x.machineCode === v)
      setForm(f => ({ ...f, Machine_Code: v, Machine_Name: m ? m.machineName : '' }))
    } else {
      setForm(f => ({ ...f, [k]: v }))
    }
  }

  const handleSave = () => {
    if (!form.PM_Part_Name.trim()) { toast.warning('Part Name is required.'); return }
    if (!form.PM_Process_Name) { toast.warning('Process Name is required.'); return }
    setIsSaving(true)

    const promise = (editId !== null && !isAddMode)
      ? api.put(`/api/process-master/${editId}`, form, { loadingMessage: 'Updating process...' })
      : api.post('/api/process-master', form, { loadingMessage: 'Saving process...' })

    promise
      .then(res => {
        toast.success(editId && !isAddMode ? 'Process Updated.' : 'Process Created.')
        api.get('/api/process-master', { loadingMessage: 'Refreshing processes...' })
          .then(listRes => {
            const updatedRows = listRes.data.data || []
            setRows(updatedRows)

            const currentPartName = form.PM_Part_Name
            const currentPartNo = form.PM_Part_No
            const existing = updatedRows.filter(r => r.PM_Part_Name === currentPartName)
            const nextOrder = existing.length > 0
              ? Math.max(...existing.map(r => Number(r.PM_Process_Order || 0))) + 1
              : 1

            setForm({
              ...empty,
              PM_Part_No: currentPartNo,
              PM_Part_Name: currentPartName,
              PM_Process_Order: String(nextOrder)
            })
            setEditId(null)
            setSelectedRowId(null)
            setIsAddMode(true)
            setPage(1)
          })
          .catch(() => { })
      })
      .catch(err => {
        const msg = err.response?.data?.message || 'Save failed'
        toast.error(msg)
      })
      .finally(() => {
        setIsSaving(false)
      })
  }

  const handleEdit = r => {
    const matchedItem = partItems.find(i => i.partName === r.PM_Part_Name)
    setForm({ ...r, PM_Part_No: matchedItem ? matchedItem.partNo : '' })
    setEditId(r.id)
    setIsAddMode(false)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }
  const handleAdd = r => {
    const existing = rows.filter(x => x.PM_Part_Name === r.PM_Part_Name)
    const nextOrder = existing.length > 0
      ? Math.max(...existing.map(x => Number(x.PM_Process_Order || 0))) + 1
      : 1

    setForm({
      ...r,
      PM_Process_Name: '',
      PM_Process_Order: String(nextOrder)
    })
    setEditId(r.id)
    setIsAddMode(true)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }
  const handleDelete = id => {
    setDeleteConfirm({
      isOpen: true,
      id,
      isDeleteAll: false,
      errorMsg: '',
      isDeleting: false
    })
  }
  const handleClear = () => {
    setForm({ ...empty })
    setEditId(null)
    setSelectedRowId(null)
    setIsAddMode(false)
    setPartUploads([])
    setSelectedItem(null)
  }

  const handleRowClick = r => {
    setSelectedRowId(selectedRowId === r.id ? null : r.id)
  }

  const sortedRows = [...rows].sort((a, b) => {
    const nameA = (a.PM_Part_Name || '').toLowerCase()
    const nameB = (b.PM_Part_Name || '').toLowerCase()
    if (nameA < nameB) return -1
    if (nameA > nameB) return 1
    const orderA = Number(a.PM_Process_Order || 0)
    const orderB = Number(b.PM_Process_Order || 0)
    return orderA - orderB
  })

  const filtered = sortedRows.filter(r => {
    const matchesSearch = [r.PM_Part_Name, r.PM_Process_Name, r.PM_Process_Name1, r.TeamId, r.Machine_Name, r.Machine_Code].some(v =>
      String(v || '').toLowerCase().includes(search.toLowerCase())
    )
    const matchesPart = partFilter ? r.PM_Part_Name === partFilter : true
    return matchesSearch && matchesPart
  })

  // Group the filtered rows by PM_Part_Name
  const grouped = filtered.reduce((acc, row) => {
    if (!row.PM_Part_Name) return acc;
    if (!acc[row.PM_Part_Name]) {
      acc[row.PM_Part_Name] = {
        partName: row.PM_Part_Name,
        createdBy: row.CreatedBy || 'Admin',
        processes: []
      }
    }
    acc[row.PM_Part_Name].processes.push(row)
    return acc;
  }, {})

  const mainTableRows = Object.values(grouped)

  const total = Math.max(1, Math.ceil(mainTableRows.length / pageSize))
  const paged = mainTableRows.slice((page - 1) * pageSize, page * pageSize)
  const pNums = () => {
    if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1)
    const ps = [1]
    if (page > 3) ps.push('...')
    for (let i = Math.max(2, page - 1); i <= Math.min(total - 1, page + 1); i++) ps.push(i)
    if (page < total - 2) ps.push('...')
    ps.push(total)
    return ps
  }

  const inp = (err) =>
    `w-full border rounded-md px-3 py-1.5 text-[13px] focus:outline-none focus:ring-2 transition-all bg-white ${err
      ? 'border-red-400 focus:ring-red-200'
      : 'border-slate-300 focus:ring-[#0097A7]/30 focus:border-[#0097A7]'
    }`
  const lbl = 'block text-[12px] font-semibold text-slate-600 mb-0.5'
  const isPartNameLocked = false
  const roOthers = false
  const roClass = `${inp(false)} bg-slate-50 cursor-not-allowed text-slate-400`

  const COLS = [
    'S.No', 'Process Name', 'Process Order', 'Team', 'Machine Name',
    'Days', 'Hours', 'minutes', 'Setting_Time', 'Cycle_Time', 'Handling_Time',
    'Created by', 'Idel Time'
  ]

  const latestUploadImage = [...partUploads].reverse().find(u => u.hasImage)
  const latestImage = latestUploadImage
    ? `/api/item-master/upload/${latestUploadImage.id}/download-image`
    : (selectedItem && selectedItem.imageMimeType)
      ? `/api/item-master/${selectedItem.id}/download-image`
      : null

  return (
    <div className="p-4 space-y-4 w-full min-w-0 bg-slate-50 min-h-screen antialiased text-slate-800">

      {/* Breadcrumb */}
      <div className="flex items-center gap-1.5 text-[12px] text-slate-400 font-medium">
        <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Masters</span>
        <ChevronRight className="w-3.5 h-3.5 text-slate-300" />
        <span className="text-[#0097A7] font-semibold">Process Master</span>
      </div>

      {/* Form Card (Top Section) */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-[0_1px_3px_rgba(0,0,0,0.02),0_4px_12px_rgba(15,23,42,0.03)] overflow-hidden">
        {/* Card Header Bar */}
        <div className="bg-gradient-to-r from-[#0097A7] to-[#00BCD4] px-5 py-3 flex items-center justify-between text-white rounded-t-xl">
          <div className="flex items-center gap-2">
            <Settings2 className="w-4 h-4 text-white" />
            <span className="text-[13px] font-bold text-white uppercase tracking-wider">
              {editId && !isAddMode ? `Edit Process (Part: ${form.PM_Part_Name})` : 'Process Master Details'}
            </span>
          </div>
          <div className="flex items-center gap-4 text-[11px] font-bold text-white/90 uppercase tracking-wider">
            <button
              onClick={() => {
                setDeleteConfirm({
                  isOpen: true,
                  id: null,
                  isDeleteAll: true,
                  errorMsg: '',
                  isDeleting: false
                })
              }}
              className="flex items-center gap-1.5 hover:text-red-100 transition-colors"
            >
              <Trash2 className="w-3.5 h-3.5 text-white" /> Delete All
            </button>
            <button
              onClick={() => {
                const headers = COLS;
                const csvContent = [
                  headers.join(','),
                  ...rows.map((r, idx) => [
                    idx + 1,
                    r.PM_Process_Name,
                    r.PM_Process_Order,
                    r.TeamId,
                    r.Machine_Name,
                    r.PM_Days,
                    r.PM_Hours,
                    r.Minutes,
                    r.Setting_Time,
                    r.Cycle_Time,
                    r.Handling_Time,
                    r.CreatedBy || 'admin',
                    r.Idle_Time
                  ].map(v => `"${String(v ?? '').replace(/"/g, '""')}"`).join(','))
                ].join('\r\n');

                const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
                const url = URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.href = url;
                link.setAttribute('download', `process-master-${new Date().toISOString().slice(0, 10)}.csv`);
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                toast.success('Exported to Excel successfully!');
              }}
              className="flex items-center gap-1.5 hover:text-emerald-100 transition-colors"
            >
              <FileText className="w-3.5 h-3.5 text-white" /> Excel
            </button>
            <button
              onClick={() => {
                window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'Dashboard' } }));
              }}
              className="flex items-center gap-1.5 hover:text-slate-100 transition-colors"
            >
              <X className="w-3.5 h-3.5 text-white" /> Close
            </button>
          </div>
        </div>

        {/* Card Body (Side-by-side Fields Grid) */}
        <div className="p-6">
          <div className="flex flex-col lg:flex-row gap-6 lg:gap-0 items-stretch w-full">

            {/* Column 1 (Left Form Inputs) */}
            <div className="flex-1 min-w-0 lg:pr-6 space-y-3">

              {/* Part No */}
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">
                  <span className="text-rose-500 mr-0.5">*</span>Part No
                </label>
                <div className="relative" ref={partNoDropdownRef}>
                  <input
                    type="text"
                    value={form.PM_Part_No}
                    onChange={e => {
                      sf('PM_Part_No', e.target.value)
                      setIsPartNoDropdownOpen(true)
                      setPartNoHighlightedIndex(-1)
                    }}
                    onFocus={() => {
                      setIsPartNoDropdownOpen(true)
                      setPartNoHighlightedIndex(-1)
                    }}
                    onKeyDown={handlePartNoKeyDown}
                    placeholder="Enter Part No..."
                    className={`${inp(false)} pr-8`}
                  />
                  <div
                    onClick={() => setIsPartNoDropdownOpen(o => !o)}
                    className="absolute inset-y-0 right-2 flex items-center cursor-pointer px-1"
                  >
                    <ChevronDown className={`w-4 h-4 text-slate-400 hover:text-[#0097A7] transition-all duration-200 ${isPartNoDropdownOpen ? 'rotate-180 text-[#0097A7]' : ''}`} />
                  </div>
                  {isPartNoDropdownOpen && filteredPartItems.length > 0 && (
                    <div className="absolute left-0 right-0 z-50 mt-1 bg-white border border-slate-200 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                      {filteredPartItems.map((item, idx) => (
                        <div
                          key={item.id}
                          onClick={() => {
                            sf('PM_Part_No', item.partNo)
                            setIsPartNoDropdownOpen(false)
                          }}
                          onMouseEnter={() => setPartNoHighlightedIndex(idx)}
                          className={`px-3 py-2 text-[13px] cursor-pointer border-b border-slate-100 last:border-0 text-left transition-colors ${
                            partNoHighlightedIndex === idx
                              ? 'bg-[#0097A7] text-white font-medium'
                              : 'text-slate-700 hover:bg-slate-50'
                          }`}
                        >
                          <span className={`${partNoHighlightedIndex === idx ? 'text-white' : 'text-slate-800'} font-semibold`}>
                            {item.partNo}
                          </span>
                          {item.partName && (
                            <span className={`${partNoHighlightedIndex === idx ? 'text-white/80' : 'text-slate-400'} text-[11px] ml-2 block lg:inline`}>
                              — {item.partName}
                            </span>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                  {isPartNoDropdownOpen && filteredPartItems.length === 0 && (
                    <div className="absolute left-0 right-0 z-50 mt-1 bg-white border border-slate-200 rounded-lg shadow-lg p-3 text-xs text-slate-400 italic text-center">
                      No matching parts.
                    </div>
                  )}
                </div>
              </div>

              {/* Part Name — auto-generated from Part No */}
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">
                  <span className="text-rose-500 mr-0.5">*</span>Part Name
                </label>
                <input
                  value={form.PM_Part_Name}
                  readOnly
                  placeholder="Auto-filled from Part No"
                  className={`${inp(false)} bg-slate-50 cursor-not-allowed text-slate-500`}
                />
              </div>

              {/* Process Name */}
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">
                  <span className="text-rose-500 mr-0.5">*</span>Process Name
                </label>
                <select
                  value={form.PM_Process_Name}
                  onChange={e => sf('PM_Process_Name', e.target.value)}
                  className={inp(false)}
                >
                  <option value="">---Select Process Type---</option>
                  {processTypes.map(o => <option key={o} value={o}>{o}</option>)}
                </select>
              </div>

              {/* Team */}
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">
                  <span className="text-rose-500 mr-0.5">*</span>Team
                </label>
                <select
                  value={form.TeamId}
                  onChange={e => sf('TeamId', e.target.value)}
                  disabled={roOthers}
                  className={roOthers ? roClass : inp(false)}
                >
                  <option value="">---Select Team---</option>
                  {teams.map(o => <option key={o} value={o}>{o}</option>)}
                </select>
              </div>

              {/* Machine Code */}
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">
                  Machine Code
                </label>
                <select
                  value={form.Machine_Code}
                  onChange={e => sf('Machine_Code', e.target.value)}
                  disabled={roOthers}
                  className={roOthers ? roClass : inp(false)}
                >
                  <option value="">---Select Machine---</option>
                  {machines.map(m => <option key={m.machineCode} value={m.machineCode}>{m.machineCode}</option>)}
                </select>
              </div>

              {/* Process Order & Machine Name side by side */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">
                    <span className="text-rose-500 mr-0.5">*</span>Machine Name
                  </label>
                  <input
                    value={form.Machine_Name}
                    readOnly
                    className={`${inp(false)} bg-slate-50 cursor-not-allowed text-slate-500`}
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">
                    Process Order
                  </label>
                  <input
                    type="number"
                    value={form.PM_Process_Order}
                    onChange={e => sf('PM_Process_Order', e.target.value)}
                    placeholder="e.g. 1"
                    disabled={roOthers}
                    readOnly={roOthers}
                    className={roOthers ? roClass : inp(false)}
                  />
                </div>
              </div>
            </div>

            {/* Column 2 (Time Inputs — 2-column grid) */}
            <div className="flex-1 min-w-0 lg:px-6 lg:border-l lg:border-slate-200">
              <span className="block text-[11px] font-bold text-slate-500 mb-2.5 uppercase tracking-wider">Time & Duration</span>
              <div className="grid grid-cols-2 gap-x-4 gap-y-3">

                {/* Days */}
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">Day's</label>
                  <input type="number" value={form.PM_Days} onChange={e => sf('PM_Days', e.target.value)}
                    placeholder="0" disabled={roOthers} readOnly={roOthers} className={roOthers ? roClass : inp(false)} />
                </div>

                {/* Hours */}
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">Hours</label>
                  <input type="number" value={form.PM_Hours} onChange={e => sf('PM_Hours', e.target.value)}
                    placeholder="0" disabled={roOthers} readOnly={roOthers} className={roOthers ? roClass : inp(false)} />
                </div>

                {/* Minutes */}
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">Minutes</label>
                  <input type="number" value={form.Minutes} onChange={e => sf('Minutes', e.target.value)}
                    placeholder="0" disabled={roOthers} readOnly={roOthers} className={roOthers ? roClass : inp(false)} />
                </div>

                {/* Setting Time */}
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">Setting Time</label>
                  <input type="number" value={form.Setting_Time} onChange={e => sf('Setting_Time', e.target.value)}
                    placeholder="0" disabled={roOthers} readOnly={roOthers} className={roOthers ? roClass : inp(false)} />
                </div>

                {/* Cycle Time */}
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">Cycle Time</label>
                  <input type="number" value={form.Cycle_Time} onChange={e => sf('Cycle_Time', e.target.value)}
                    placeholder="0" disabled={roOthers} readOnly={roOthers} className={roOthers ? roClass : inp(false)} />
                </div>

                {/* Handling Time */}
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">Handling Time</label>
                  <input type="number" value={form.Handling_Time} onChange={e => sf('Handling_Time', e.target.value)}
                    placeholder="0" disabled={roOthers} readOnly={roOthers} className={roOthers ? roClass : inp(false)} />
                </div>

                {/* Idle Time — spans full width */}
                <div className="col-span-2">
                  <label className="block text-[11px] font-bold text-slate-500 mb-1 uppercase tracking-wider">Idle Time</label>
                  <input type="number" value={form.Idle_Time} onChange={e => sf('Idle_Time', e.target.value)}
                    placeholder="0" disabled={roOthers} readOnly={roOthers} className={roOthers ? roClass : inp(false)} />
                  <span className="block text-[10px] font-medium text-slate-400 mt-0.5">Idle Time in minutes</span>
                </div>

              </div>
            </div>

            {/* Column 3 (Right Blueprint Image + Action Buttons) */}
            <div className="flex-1 min-w-0 flex flex-col lg:pl-6 lg:border-l lg:border-slate-200">
              <span className="block text-[11px] font-bold text-slate-500 mb-2 uppercase tracking-wider">Image</span>
              <div className="h-[240px] border border-slate-200 rounded-xl bg-slate-50/50 flex items-center justify-center p-3 relative group overflow-hidden shadow-inner">
                {uploadsLoading ? (
                  <Loader2 className="w-6 h-6 text-[#0097A7] animate-spin" />
                ) : latestImage ? (
                  <img
                    src={latestImage}
                    alt="blueprint"
                    onClick={() => setZoomImage(latestImage)}
                    className="max-h-full max-w-full object-contain cursor-zoom-in group-hover:scale-105 transition-transform duration-200"
                  />
                ) : (
                  <div className="flex flex-col items-center gap-1 text-slate-400">
                    <ImageIcon className="w-8 h-8 stroke-[1.2]" />
                    <span className="text-[10px] font-medium">No Blueprint Image</span>
                  </div>
                )}
              </div>
              {/* Action Buttons below the image */}
              <div className="mt-3 space-y-2 pt-3">
                <div className="grid grid-cols-2 gap-3">
                  <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="flex items-center justify-center gap-1 px-2 py-2 bg-[#2ecc71] hover:bg-[#27ae60] text-white text-[11px] font-bold rounded shadow transition-colors active:scale-95 disabled:opacity-60"
                  >
                    <Save className="w-5 h-3.5" /> {editId && !isAddMode ? 'Update' : 'Save'}
                  </button>
                  <button
                    onClick={() => {
                      if (selectedRowId) {
                        const r = rows.find(x => x.id === selectedRowId)
                        if (r) handleEdit(r)
                      } else {
                        toast.warning('Please click a row in the table first to select it for editing.')
                      }
                    }}
                    className="flex items-center justify-center gap-1 px-2 py-2 bg-[#3498db] hover:bg-[#2980b9] text-white text-[11px] font-bold rounded shadow transition-colors active:scale-95"
                  >
                    <Edit className="w-5 h-3.5" /> Edit
                  </button>
                  <button
                    onClick={() => {
                      if (selectedRowId) {
                        handleDelete(selectedRowId)
                        handleClear()
                      } else {
                        toast.warning('Please click a row in the table first to select it for deleting.')
                      }
                    }}
                    className="flex items-center justify-center gap-1 px-2 py-2 bg-[#e74c3c] hover:bg-[#c0392b] text-white text-[11px] font-bold rounded shadow transition-colors active:scale-95"
                  >
                    <Trash2 className="w-5 h-3.5" /> Delete
                  </button>
                  <button
                    onClick={handleClear}
                    className="flex items-center justify-center gap-1 px-2 py-2 bg-[#0097A7] hover:bg-[#007a87] text-white text-[11px] font-bold rounded shadow transition-colors active:scale-95"
                  >
                    <RotateCcw className="w-5 h-3.5" /> Clear
                  </button>
                </div>
                
                {/* <button
                  onClick={() => {
                    if (selectedRowId) {
                      const r = rows.find(x => x.id === selectedRowId)
                      if (r) handleAdd(r)
                    } else {
                      toast.warning('Please click a row in the table first to select it.')
                    }
                  }}
                  className="w-full flex items-center justify-center gap-1.5 px-3 py-2 bg-purple-600 hover:bg-purple-700 text-white text-[11px] font-bold rounded shadow transition-colors active:scale-95"
                >
                  <Plus className="w-4 h-4" /> Add Process
                </button> */}
              </div>
            </div>

          </div>
        </div>
      </div>

         {/* Table & Toolbar Section (Bottom Section) */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-[0_1px_3px_rgba(0,0,0,0.02),0_4px_12px_rgba(15,23,42,0.03)] overflow-hidden flex-1 flex flex-col min-h-0">
        
        {/* Table Gradient Card Header */}
        <div className="bg-gradient-to-r from-[#0097A7] to-[#00BCD4] px-5 py-3">
          <h2 className="text-white font-bold text-[13.5px] tracking-wide text-center uppercase">Process Master List</h2>
        </div>

        {/* Table Toolbar */}
        <div className="bg-slate-50 border-b border-slate-200 px-5 py-2 flex flex-wrap items-center justify-between gap-3">
          
          {/* Left: Search & Part Filter */}
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex items-center gap-2">
              <span className="text-[12.5px] font-bold text-slate-600">Search:</span>
              <div className="relative">
                <input
                  value={search}
                  onChange={e => { setSearch(e.target.value); setPage(1) }}
                  placeholder="Search..."
                  className="pl-3 pr-8 py-1 border border-slate-300 rounded text-xs focus:outline-none focus:ring-1 focus:ring-[#0097A7] w-48 bg-white"
                />
                <Search className="w-3.5 h-3.5 text-slate-400 absolute right-2.5 top-1/2 -translate-y-1/2" />
              </div>
            </div>

            <div className="flex items-center gap-2">
              <span className="text-[12.5px] font-bold text-slate-600">Part Filter:</span>
              <select
                value={partFilter}
                onChange={e => { setPartFilter(e.target.value); setPage(1) }}
                className="border border-slate-300 rounded text-xs px-2 py-1 focus:outline-none focus:ring-1 focus:ring-[#0097A7] bg-white max-w-[200px]"
              >
                <option value="">All Parts</option>
                {Array.from(new Set(rows.map(r => r.PM_Part_Name).filter(Boolean))).map(name => (
                  <option key={name} value={name}>{name}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Right: Save/Edit/Delete/Clear Actions with standard palette colors */}
          {/* <div className="flex items-center gap-2">
            <button
              onClick={handleSave}
              disabled={isSaving}
              className="flex items-center gap-1.5 px-4 py-1.5 bg-[#2ecc71] hover:bg-[#27ae60] text-white text-xs font-bold rounded shadow transition-colors active:scale-95 disabled:opacity-60"
            >
              <Save className="w-3.5 h-3.5" /> Save
            </button>
            <button
              onClick={() => {
                if (selectedRowId) {
                  const r = rows.find(x => x.id === selectedRowId)
                  if (r) handleEdit(r)
                } else {
                  toast.warning('Please click a row in the table first to select it for editing.')
                }
              }}
              className="flex items-center gap-1.5 px-4 py-1.5 bg-[#3498db] hover:bg-[#2980b9] text-white text-xs font-bold rounded shadow transition-colors active:scale-95"
            >
              <Edit className="w-3.5 h-3.5" /> Edit
            </button>
            <button
