              }}
              className="flex items-center gap-1.5 px-4 py-1.5 bg-[#e74c3c] hover:bg-[#c0392b] text-white text-xs font-bold rounded shadow transition-colors active:scale-95"
            >
              <Trash2 className="w-3.5 h-3.5" /> Delete
            </button>
            <button
