                  <span className="text-[13px] text-slate-800 font-medium">{value || '—'}</span>
                </div>
              ))}
            </div>
            <div className="px-6 pb-5 pt-2">
              <button onClick={() => setDetailRow(null)}
                className="w-full py-2.5 text-sm font-semibold text-white bg-[#0097A7] hover:bg-[#007a87] rounded-xl transition-colors">
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Image Zoom Lightbox */}
      {zoomImage && (
        <div
          className="fixed inset-0 bg-black/80 z-[60] flex items-center justify-center p-4 backdrop-blur-sm"
          onClick={() => setZoomImage(null)}
        >
          <div className="relative max-w-4xl max-h-[90vh] w-full flex items-center justify-center" onClick={e => e.stopPropagation()}>
            <button
              onClick={() => setZoomImage(null)}
              className="absolute -top-3 -right-3 z-10 w-8 h-8 bg-white rounded-full shadow-lg flex items-center justify-center text-slate-600 hover:text-red-500 hover:bg-red-50 transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
            <img
              src={zoomImage}
              alt="Zoomed"
              className="max-h-[85vh] max-w-full object-contain rounded-xl shadow-2xl"
            />
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal (Delete Theme & Error Handling) */}
      {deleteConfirm.isOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden border border-red-100 animate-in fade-in zoom-in-95 duration-200">
            {/* Header with Alert icon and Red theme */}
            <div className="bg-gradient-to-r from-red-600 to-rose-500 px-6 py-4 flex items-center gap-3 text-white">
              <div className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center animate-pulse">
                <Trash2 className="w-4 h-4 text-white" />
              </div>
              <h3 className="font-bold text-[15px] uppercase tracking-wide">
                {deleteConfirm.isDeleteAll ? 'Danger: Delete All Records' : 'Confirm Delete'}
              </h3>
            </div>

            {/* Content */}
            <div className="p-6 space-y-4">
              <div className="flex items-start gap-3">
                <div className="p-2 rounded-full bg-red-50 text-red-500 mt-0.5">
                  <AlertTriangle className="w-6 h-6 stroke-[2]" />
                </div>
                <div>
                  <h4 className="text-[14px] font-bold text-slate-800">
                    {deleteConfirm.isDeleteAll ? 'Delete All Process Master Records?' : 'Delete Process Master Record?'}
                  </h4>
                  <p className="text-[12.5px] text-slate-500 leading-relaxed mt-1">
                    {deleteConfirm.isDeleteAll
                      ? 'Are you absolutely sure you want to clear the entire process master list? This operation is permanent and cannot be undone.'
                      : 'Are you sure you want to delete this process master entry? This action is permanent and cannot be undone.'}
                  </p>
                </div>
              </div>

              {/* Error Alert Display inside Modal */}
              {deleteConfirm.errorMsg && (
                <div className="p-3 bg-red-50 border border-red-200 rounded-lg flex items-start gap-2 text-red-700 text-xs font-medium animate-in fade-in slide-in-from-top-1 duration-200">
                  <XCircle className="w-4 h-4 text-red-500 flex-shrink-0 mt-0.5" />
                  <div>
                    <span className="font-bold">Error:</span> {deleteConfirm.errorMsg}
                  </div>
                </div>
              )}
            </div>

            {/* Actions */}
            <div className="px-6 pb-6 pt-2 flex items-center justify-end gap-3">
              <button
                onClick={() => setDeleteConfirm(prev => ({ ...prev, isOpen: false }))}
                disabled={deleteConfirm.isDeleting}
                className="px-4 py-2 text-xs font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors active:scale-95 disabled:opacity-60"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  setDeleteConfirm(prev => ({ ...prev, isDeleting: true, errorMsg: '' }))
                  const promise = deleteConfirm.isDeleteAll
                    ? api.delete('/api/process-master/all', { loadingMessage: 'Deleting all processes...' })
                    : api.delete(`/api/process-master/${deleteConfirm.id}`, { loadingMessage: 'Deleting process...' })

                  promise
                    .then(() => {
                      toast.success(deleteConfirm.isDeleteAll ? 'All processes deleted.' : 'Process deleted.')
                      setDeleteConfirm(prev => ({ ...prev, isOpen: false }))
                      if (deleteConfirm.isDeleteAll) {
                        setRows([])
                        handleClear()
                      } else {
                        fetchAllProcesses()
                      }
                    })
                    .catch(err => {
                      const msg = err.response?.data?.message || (deleteConfirm.isDeleteAll ? 'Delete all failed' : 'Delete failed')
                      setDeleteConfirm(prev => ({ ...prev, isDeleting: false, errorMsg: msg }))
                      toast.error(msg)
                    })
                }}
                disabled={deleteConfirm.isDeleting}
                className="flex items-center gap-1.5 px-4 py-2 text-xs font-bold text-white bg-red-600 hover:bg-red-700 rounded-lg shadow-md transition-colors active:scale-95 disabled:opacity-60"
              >
                {deleteConfirm.isDeleting ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" /> Deleting...
                  </>
                ) : (
                  <>
                    <Trash2 className="w-3.5 h-3.5" /> Confirm Delete
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { ChevronRight, Save, Trash2, X, RotateCcw, Search, FileText, CheckSquare, Square, Image as ImageIcon, Upload } from 'lucide-react'
import { useToast } from '../components/Toast'
import api from '../services/api'

const Label = ({ children, required }) => (
  <label className="block text-[11px] font-semibold text-slate-600 mb-1 uppercase tracking-wider">
    {required && <span className="text-red-500 mr-0.5">*</span>}{children}
  </label>
)
const Input = ({ placeholder, value, onChange, type = 'text', readOnly = false, className = "", ...props }) => (
  <input type={type} placeholder={placeholder} value={value} onChange={onChange} readOnly={readOnly} {...props}
    className={`w-full px-3 py-[7px] text-sm border border-slate-200 rounded-lg bg-white text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-[#0097A7]/25 focus:border-[#0097A7] transition-all duration-200 ${readOnly ? 'bg-slate-50 cursor-not-allowed' : 'hover:border-slate-300'} ${className}`} />
)
const Select = ({ options, placeholder, value, onChange, className = "" }) => (
  <div className={`relative ${className}`}>
    <select value={value} onChange={onChange}
      className="w-full px-3 py-[7px] pr-8 text-sm border border-slate-200 rounded-lg bg-white text-slate-700 appearance-none focus:outline-none focus:ring-2 focus:ring-[#0097A7]/25 focus:border-[#0097A7] transition-all duration-200 hover:border-slate-300 cursor-pointer">
      <option value="">{placeholder}</option>
      {options.map(o => <option key={typeof o === 'object' ? o.value : o} value={typeof o === 'object' ? o.value : o}>{typeof o === 'object' ? o.label : o}</option>)}
    </select>
    <div className="pointer-events-none absolute inset-y-0 right-3 flex items-center">
      <svg className="w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
    </div>
  </div>
)

const SearchableSelect = ({ options, placeholder, value, onChange }) => {
  const [isOpen, setIsOpen] = useState(false)
  const [search, setSearch] = useState(value || '')
  const containerRef = useRef(null)

  useEffect(() => {
    setSearch(value || '')
  }, [value])

  useEffect(() => {
    const clickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsOpen(false)
        setSearch(value || '')
      }
    }
    document.addEventListener('mousedown', clickOutside)
    return () => document.removeEventListener('mousedown', clickOutside)
  }, [value])

  const filtered = options.filter(o => 
    (o.label || o.value || '').toLowerCase().includes(search.toLowerCase())
  )

  const handleSelect = (val) => {
    onChange({ target: { value: val } })
    setIsOpen(false)
  }

  return (
    <div ref={containerRef} className="relative flex-1">
      <div className="relative">
        <input
          type="text"
          placeholder={placeholder}
          value={search}
          onChange={(e) => {
            setSearch(e.target.value)
            setIsOpen(true)
            onChange({ target: { value: e.target.value } })
          }}
          onFocus={() => setIsOpen(true)}
          className="w-full px-3 py-[7px] pr-8 text-sm border border-slate-200 rounded-lg bg-white text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-[#0097A7]/25 focus:border-[#0097A7] transition-all duration-200 hover:border-slate-300"
        />
        <button
          type="button"
          onClick={() => setIsOpen(!isOpen)}
          className="absolute inset-y-0 right-0 px-2 flex items-center text-slate-400 hover:text-slate-600"
        >
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
        </button>
      </div>

      {isOpen && (
        <div className="absolute z-50 w-full mt-1 bg-white border border-slate-200 rounded-lg shadow-lg max-h-60 overflow-y-auto">
          {filtered.length === 0 ? (
            <div className="px-3 py-2 text-xs text-slate-400 italic">No matches found</div>
          ) : (
            filtered.map(o => (
              <div
                key={o.value}
                onClick={() => handleSelect(o.value)}
                className={`px-3 py-2 text-sm cursor-pointer hover:bg-[#0097A7]/10 transition-colors ${o.value === value ? 'bg-[#0097A7]/5 font-semibold text-[#0097A7]' : 'text-slate-700'}`}
              >
                {o.label || o.value}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  )
}

const STORAGE_KEY = 'velson_process_menu'



export default function ProcessMenu() {
  const toast = useToast()
  const [form, setForm] = useState({
    jobNo: '', itemName: '',
    planDate: new Date().toISOString().split('T')[0],
  })
  const [processes, setProcesses] = useState([])
  const [selectAll, setSelectAll] = useState(false)
  const [selectedIds, setSelectedIds] = useState(new Set())
  const [savedRecords, setSavedRecords] = useState([])
  const [activeTab, setActiveTab] = useState('check')
  const [drawingList, setDrawingList] = useState([])


  const [partImage, setPartImage] = useState(null)
  const imgInputRef = useRef(null)

  const handleImageUpload = (e) => {
    const file = e.target.files?.[0]
    if (file) {
      const reader = new FileReader()
      reader.onload = (ev) => setPartImage(ev.target.result)
      reader.readAsDataURL(file)
    }
  }
  const clearImage = () => { setPartImage(null); if (imgInputRef.current) imgInputRef.current.value = '' }

  const [jobCardsList, setJobCardsList] = useState([])
  const [processMasters, setProcessMasters] = useState([])

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]')
    setSavedRecords(saved)

    const fetchJobCards = async () => {
      try {
        const res = await api.get('/api/job-card')
        if (res.data?.success && res.data.data) {
          setJobCardsList(res.data.data)
        }
      } catch (err) {
        console.error('Failed to fetch job cards:', err)
      }
    }
    const fetchProcessMasters = async () => {
      try {
        const res = await api.get('/api/process-master')
        if (res.data?.success && res.data.data) {
          setProcessMasters(res.data.data)
        }
      } catch (err) {
        console.error('Failed to fetch process masters:', err)
      }
    }
    fetchJobCards()
    fetchProcessMasters()
  }, [])

  useEffect(() => {
    if (form.jobNo && jobCardsList.length > 0) {
      const matched = jobCardsList.find(jc => jc.jobNo === form.jobNo)
      if (matched) {
        const updates = {}
        if (matched.currentDate) {
          updates.planDate = matched.currentDate
        }
        if (matched.lineItems && matched.lineItems.length > 0) {
          updates.itemName = `${matched.lineItems[0].partNo} — ${matched.lineItems[0].partName}`
        }
        setForm(f => ({ ...f, ...updates }))
      }
    }
  }, [form.jobNo, jobCardsList])

  const u = k => e => setForm(f => ({ ...f, [k]: e.target.value }))

  const loadProcessesForItem = async (itemNameValue) => {
    if (!itemNameValue || !form.jobNo) {
      setProcesses([])
      return
    }
    try {
      const res = await api.get(`/api/job-process-menu?jobNo=${encodeURIComponent(form.jobNo)}`)
      if (res.data?.success && res.data.data) {
        const partName = itemNameValue.includes(' — ')
          ? itemNameValue.split(' — ')[1].trim().toLowerCase()
          : itemNameValue.trim().toLowerCase()

        const matchedList = res.data.data.filter(pm =>
          pm.partName && pm.partName.trim().toLowerCase() === partName
        )

        const sorted = [...matchedList].sort((a, b) => {
          const ordA = parseInt(a.processOrder, 10) || 0
          const ordB = parseInt(b.processOrder, 10) || 0
          return ordA - ordB
        })

        const mapped = sorted.map((pm, i) => ({
          id: pm.id,
          sno: i + 1,
          name: pm.processName,
          processOrder: pm.processOrder || '',
          teamId: pm.teamId || '',
          machineName: pm.machineName || '',
          days: pm.days || '0',
          hours: pm.hours || '0',
          minutes: pm.minutes || '0',
          settingTime: pm.settingTime || '0',
          cycleTime: pm.cycleTime || '0',
          handlingTime: pm.handlingTime || '0',
          createdBy: pm.createdBy || '',
          idleTime: pm.idleTime || '0',
          isActive: pm.isActive
        }))

        setProcesses(mapped)
        const activeIds = new Set(mapped.filter(p => p.isActive).map(p => p.id))
        setSelectedIds(activeIds)
        setSelectAll(activeIds.size === mapped.length && mapped.length > 0)
      } else {
        setProcesses([])
        setSelectedIds(new Set())
        setSelectAll(false)
      }
    } catch (err) {
      console.error('Failed to load job processes:', err)
      setProcesses([])
      setSelectedIds(new Set())
      setSelectAll(false)
    }
  }

  useEffect(() => {
    if (form.itemName && form.jobNo) {
      loadProcessesForItem(form.itemName)
    }
  }, [form.itemName, form.jobNo])

  useEffect(() => {
    const fetchItemMasterFiles = async () => {
      if (!form.itemName) {
        setPartImage(null)
        setDrawingList([])
        return
      }
      const partNo = form.itemName.includes(' — ')
        ? form.itemName.split(' — ')[0].trim()
        : form.itemName.trim()

      if (!partNo) {
        setPartImage(null)
        setDrawingList([])
        return
      }

      try {
        const res = await api.get(`/api/item-master?search=${encodeURIComponent(partNo)}`)
        if (res.data?.success && res.data.data && res.data.data.length > 0) {
          const matched = res.data.data.find(item => item.partNo === partNo)
          if (matched) {
            const detailRes = await api.get(`/api/item-master/${matched.id}`)
            if (detailRes.data?.success && detailRes.data.data) {
              const fullItem = detailRes.data.data

              if (fullItem.hasImage || fullItem.imageMimeType) {
                const imgRes = await api.get(`/api/item-master/${fullItem.id}/download-image`, { responseType: 'blob' })
                const imgBlob = new Blob([imgRes.data], { type: fullItem.imageMimeType || 'image/jpeg' })
                setPartImage(URL.createObjectURL(imgBlob))
              } else {
                setPartImage(null)
              }

              let drawings = []
              if (fullItem.hasPdf || fullItem.pdfMimeType) {
                drawings.push({
                  name: fullItem.pdfPath || `${fullItem.partNo}_Drawing.pdf`,
                  url: `/api/item-master/${fullItem.id}/download-pdf`
                })
              }
              setDrawingList(drawings)
            }
          } else {
            setPartImage(null)
            setDrawingList([])
          }
        } else {
          setPartImage(null)
          setDrawingList([])
        }
      } catch (err) {
        console.error('Failed to load item master details:', err)
        setPartImage(null)
        setDrawingList([])
      }
    }
    fetchItemMasterFiles()
  }, [form.itemName])

  const handleViewDrawing = async (url) => {
    try {
      const res = await api.get(url, { responseType: 'blob' })
      const blob = new Blob([res.data], { type: 'application/pdf' })
      const blobUrl = URL.createObjectURL(blob)
      window.open(blobUrl, '_blank')
    } catch (err) {
      console.error('Failed to open drawing:', err)
      toast.error('Could not open the drawing PDF.')
    }
  }

  // When job number is entered, simulate loading processes
  const handleLoadJob = () => {
    if (!form.jobNo) { toast.warning('Please enter a Job No.'); return }
    const matched = jobCardsList.find(jc => jc.jobNo === form.jobNo)
    if (matched) {
      const updates = {}
      if (matched.currentDate) {
        updates.planDate = matched.currentDate
      }
      if (matched.lineItems && matched.lineItems.length > 0) {
        updates.itemName = `${matched.lineItems[0].partNo} — ${matched.lineItems[0].partName}`
      }
      setForm(f => ({ ...f, ...updates }))
      if (matched.lineItems && matched.lineItems.length > 0) {
        loadProcessesForItem(`${matched.lineItems[0].partNo} — ${matched.lineItems[0].partName}`)
      }
    }
    setSelectedIds(new Set())
    setSelectAll(false)
  }

  const toggleSelect = (id) => {
    setSelectedIds(prev => {
      const next = new Set(prev)
      next.has(id) ? next.delete(id) : next.add(id)
      return next
    })
  }

  const handleSelectAll = () => {
    if (selectAll) {
      setSelectedIds(new Set())
    } else {
      setSelectedIds(new Set(processes.map(p => p.id)))
    }
    setSelectAll(!selectAll)
  }

  const handleSave = async () => {
    if (!form.jobNo || !form.itemName) { toast.warning('Please fill Job No and Item Name.'); return }

    const partNo = form.itemName.includes(' — ') ? form.itemName.split(' — ')[0].trim() : '';

    const processesPayload = processes.map(p => ({
      processName: p.name,
      processOrder: p.processOrder,
      isActive: selectedIds.has(p.id)
    }))

    try {
      const res = await api.put('/api/job-process-menu', {
        jobNo: form.jobNo,
        partNo,
        processes: processesPayload
      })

      if (res.data?.success) {
        toast.success('Process Menu saved successfully!')
        loadProcessesForItem(form.itemName)
      } else {
        toast.error(res.data?.message || 'Failed to save process menu.')
      }
    } catch (err) {
      console.error('Failed to save job processes:', err)
      toast.error('Error: ' + (err.response?.data?.message || err.message))
    }
  }

  const handleDeleteAll = () => {
    if (selectedIds.size === 0) { toast.warning('Please select processes to deselect.'); return }
    const nextSelected = new Set(selectedIds)
    processes.forEach(p => {
      if (selectedIds.has(p.id)) {
        nextSelected.delete(p.id)
      }
    })
    setSelectedIds(nextSelected)
    setSelectAll(false)
    toast.success(selectedIds.size + ' process(es) deselected. Click Save to record changes.')
  }



  const handleClear = () => {
    setForm({ jobNo: '', itemName: '', planDate: new Date().toISOString().split('T')[0] })
    setProcesses([])
    setSelectedIds(new Set())
    setSelectAll(false)
    setDrawingList([])
    clearImage()
  }

  return (
    <div className="bg-[#f4f6f8] min-h-full pb-6">
      <div className="px-6 py-6">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-[12px] text-slate-400 mb-5 uppercase font-bold tracking-tight">
          {/* <span>Dashboard</span><ChevronRight size={12} /> */}
          <span>Technical</span><ChevronRight size={12} /><span className="text-[#0097A7]">Process Menu</span>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-4 py-3">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-red-700 rounded-sm" />
              <h2 className="text-[13px] font-bold text-slate-700 uppercase tracking-tight">Process Menu</h2>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={handleClear} className="flex items-center gap-1.5 px-3 py-1.5 bg-white hover:bg-slate-50 text-slate-600 text-[12px] font-bold rounded-lg border border-slate-200 transition-all shadow-sm"><RotateCcw size={14} /> Clear</button>
              <button className="text-slate-400 hover:text-red-600 transition-colors ml-1"><X size={20} strokeWidth={2.5} /></button>
            </div>
          </div>

          <div className="p-5">
            {/* ── Top Form Row ── */}
            <div className="grid grid-cols-12 gap-4 items-end">
              <div className="col-span-3">
                <Label required>Job No</Label>
                <div className="flex gap-1 items-center">
                  <SearchableSelect
                    options={jobCardsList.map(jc => ({
                      value: jc.jobNo,
                      label: jc.jobNo
                    }))}
                    value={form.jobNo}
                    onChange={u('jobNo')}
                    placeholder="Enter or select Job No..."
                  />
                  <button onClick={handleLoadJob} className="px-2 py-[7px] bg-[#0097A7] hover:bg-[#007a87] text-white rounded-lg transition-all active:scale-95 flex-shrink-0" title="Load Job">
                    <Search size={14} />
                  </button>
                </div>
              </div>
              <div className="col-span-3">
                <Label required>Item Name</Label>
                <Select
                  options={
                    (() => {
                      const matched = jobCardsList.find(jc => jc.jobNo === form.jobNo)
                      return matched && matched.lineItems
                        ? matched.lineItems.map(item => `${item.partNo} — ${item.partName}`)
                        : []
                    })()
                  }
                  value={form.itemName}
                  onChange={u('itemName')}
                  placeholder="Select Item..."
                />
              </div>
              <div className="col-span-2">
                <Label>Plan Date</Label>
                <Input type="date" value={form.planDate} onChange={u('planDate')} />
              </div>
              <div className="col-span-4 flex items-end gap-2 justify-end">
                <button onClick={handleSave} className="flex items-center gap-1.5 px-4 py-[7px] bg-[#0097A7] hover:bg-[#007a87] text-white text-[12px] font-bold rounded-lg transition-all shadow-md active:scale-95"><Save size={14} /> Save</button>
                <button onClick={handleSelectAll} className="flex items-center gap-1.5 px-3 py-[7px] bg-white hover:bg-slate-50 text-slate-600 text-[12px] font-bold rounded-lg border border-slate-200 transition-all shadow-sm">
                  {selectAll ? <CheckSquare size={14} className="text-[#0097A7]" /> : <Square size={14} />} Select All
                </button>
                <button onClick={handleDeleteAll} className="flex items-center gap-1.5 px-3 py-[7px] bg-white hover:bg-red-50 text-red-600 text-[12px] font-bold rounded-lg border border-red-200 transition-all shadow-sm"><Trash2 size={14} /> Delete</button>
              </div>
            </div>

            {/* ── Main Content Area ── */}
            <div className="grid grid-cols-12 gap-4 mt-5">
              {/* Left: Process Table */}
              <div className="col-span-9">
                {/* Tab */}
                <div className="flex gap-1 mb-0">
                  <button
                    onClick={() => setActiveTab('check')}
                    className={`px-4 py-2 text-[12px] font-bold rounded-t-lg border border-b-0 transition-all ${activeTab === 'check' ? 'bg-white text-[#0097A7] border-slate-200' : 'bg-slate-100 text-slate-400 border-transparent hover:text-slate-600'}`}
                  >Check</button>
                </div>

                <div className="border border-slate-200 rounded-b-xl rounded-tr-xl overflow-hidden shadow-sm min-h-[350px] bg-white">
                  {processes.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-28 text-slate-300">
                      <FileText size={48} strokeWidth={1} className="mb-3 opacity-30" />
                      <p className="text-[12px] font-bold uppercase tracking-widest">No processes loaded</p>
                      <p className="text-[11px] text-slate-400 mt-1">Enter a Job No and click search to load processes</p>
                    </div>
                  ) : (
                    <table className="w-full text-left border-collapse">
                      <colgroup>
                        <col style={{ width: '3%' }} />   {/* checkbox */}
                        <col style={{ width: '4%' }} />   {/* S.No */}
                        <col style={{ width: '14%' }} />  {/* Process Name */}
                        <col style={{ width: '5%' }} />   {/* Process Order */}
                        <col style={{ width: '6%' }} />   {/* Team */}
                        <col style={{ width: '12%' }} />  {/* Machine Name */}
                        <col style={{ width: '5%' }} />   {/* Days */}
                        <col style={{ width: '5%' }} />   {/* Hours */}
                        <col style={{ width: '5%' }} />   {/* Minutes */}
                        <col style={{ width: '6%' }} />   {/* Setting Time */}
                        <col style={{ width: '6%' }} />   {/* Cycle Time */}
                        <col style={{ width: '7%' }} />   {/* Handling Time */}
                        <col style={{ width: '8%' }} />   {/* Created By */}
                        <col style={{ width: '5%' }} />   {/* Idle Time */}
                      </colgroup>
                      <thead className="bg-[#e3f2fd] border-b border-slate-200">
                        <tr>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-center">
                            <button onClick={handleSelectAll}>
                              {selectAll ? <CheckSquare size={13} className="text-[#0097A7]" /> : <Square size={13} className="text-slate-400" />}
                            </button>
                          </th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">S.No</th>
                          <th className="px-2 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold leading-tight">Process Name</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Order</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Team</th>
                          <th className="px-2 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold leading-tight">Machine Name</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Days</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Hours</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Mins</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Setting<br/>Time</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Cycle<br/>Time</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Handling<br/>Time</th>
                          <th className="px-1 py-2.5 border-r border-slate-200 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Created<br/>By</th>
                          <th className="px-1 py-2.5 text-[9px] uppercase text-slate-600 font-bold text-center leading-tight">Idle<br/>Time</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {processes.map(p => (
                          <tr key={p.id} className={`hover:bg-slate-50 transition-colors ${selectedIds.has(p.id) ? 'bg-[#0097A7]/5' : ''}`}>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center">
                              <button onClick={() => toggleSelect(p.id)}>
                                {selectedIds.has(p.id) ? <CheckSquare size={13} className="text-[#0097A7]" /> : <Square size={13} className="text-slate-300" />}
                              </button>
                            </td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-500 font-bold">{p.sno}</td>
                            <td className="px-2 py-1.5 border-r border-slate-200 text-[11px] font-semibold text-slate-700 truncate">{p.name}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-500">{p.processOrder}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-500">{p.teamId || '—'}</td>
                            <td className="px-2 py-1.5 border-r border-slate-200 text-[11px] text-slate-600 truncate">{p.machineName || '—'}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-600">{p.days}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-600">{p.hours}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-600">{p.minutes}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-600">{p.settingTime}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-600">{p.cycleTime}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-600">{p.handlingTime}</td>
                            <td className="px-1 py-1.5 border-r border-slate-200 text-center text-[11px] text-slate-500">{p.createdBy || '—'}</td>
                            <td className="px-1 py-1.5 text-center text-[11px] text-slate-600">{p.idleTime}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  )}
                </div>
              </div>

              {/* Right: Part Image + Drawing List */}
              <div className="col-span-3 space-y-4">
                <div>
                  <Label>Part Image</Label>
                  <input ref={imgInputRef} type="file" accept="image/*" onChange={handleImageUpload} className="hidden" />
                  {partImage ? (
                    <div className="relative bg-slate-50 border border-slate-200 rounded-xl overflow-hidden">
                      <img src={partImage} alt="Part" className="w-full h-[140px] object-contain p-2" />
                      <button onClick={clearImage} className="absolute top-1.5 right-1.5 bg-white/90 hover:bg-red-50 rounded-full p-0.5 text-slate-400 hover:text-red-600 transition-all shadow-sm"><X size={14} /></button>
                      <button onClick={() => imgInputRef.current?.click()} className="absolute bottom-1.5 right-1.5 bg-white/90 hover:bg-[#0097A7]/10 rounded-full p-1 text-slate-400 hover:text-[#0097A7] transition-all shadow-sm"><Upload size={12} /></button>
                    </div>
                  ) : (
                    <div onClick={() => imgInputRef.current?.click()} className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-xl flex flex-col items-center justify-center py-10 text-slate-300 hover:border-[#0097A7] hover:bg-[#0097A7]/5 transition-all cursor-pointer group">
                      <ImageIcon size={32} strokeWidth={1.2} className="group-hover:text-[#0097A7] transition-colors" />
                      <p className="text-[10px] font-black mt-2 uppercase tracking-widest text-slate-400 group-hover:text-[#0097A7]">Click to upload</p>
                    </div>
                  )}
                </div>

                {/* Drawing List */}
                <div>
                  <Label>Drawing List</Label>
                  <div className="border border-slate-200 rounded-xl overflow-hidden bg-white min-h-[180px]">
                    {drawingList.length === 0 ? (
                      <div className="flex flex-col items-center justify-center py-12 text-slate-300">
                        <FileText size={24} strokeWidth={1.2} className="opacity-30" />
                        <p className="text-[10px] font-bold mt-1 uppercase tracking-widest text-slate-400">No drawings</p>
                      </div>
                    ) : (
                      <div className="divide-y divide-slate-100">
                        {drawingList.map((d, i) => (
                          <div key={i} onClick={() => handleViewDrawing(d.url)} className="px-3 py-2.5 flex items-center gap-2 hover:bg-slate-50 transition-colors cursor-pointer group">
                            <FileText size={14} className="text-[#0097A7] flex-shrink-0" />
                            <span className="text-[11px] font-semibold text-slate-600 group-hover:text-[#0097A7] truncate">{d.name}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>

          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { ChevronRight, Search, Trash2, Printer, Eye, X, Pencil, Filter, Settings, FileText, FileSpreadsheet, File as FilePdf } from 'lucide-react'
import ConfirmDialog from '../components/ConfirmDialog'

const BASE = 'http://localhost:3000'
const today = new Date().toISOString().split('T')[0]
const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]

const STATUS_OPTIONS = [
  { value: '',         label: 'All' },
  { value: 'Pending',  label: 'P.O Pending' },
  { value: 'Approval', label: 'P.O Approved' },
  { value: 'Rejected', label: 'P.O Rejected' },
]

const statusColor = s => ({
  Pending:  'text-amber-600 font-semibold',
  Approval: 'text-green-600 font-semibold',
  Rejected: 'text-red-500 font-semibold',
}[s] ?? 'text-slate-600')

const inp = 'border border-slate-300 rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] bg-white'
const lbl = 'text-[12px] font-semibold text-slate-600 whitespace-nowrap'
const iconBtn = 'flex items-center gap-1 text-[12px] text-slate-600 hover:text-[#0097A7] transition-colors cursor-pointer select-none'

const fmtDate = iso => {
  if (!iso) return '—'
  const d = new Date(iso)
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
  return `${String(d.getDate()).padStart(2,'0')}-${months[d.getMonth()]}-${d.getFullYear()}`
}

const Spinner = ({ cls = 'w-4 h-4' }) => (
  <span className={`${cls} border-2 border-current/30 border-t-current rounded-full animate-spin inline-block`} />
)

const ALL_COLS = ['PO No', 'PO Date', 'PO Type', 'Supplier Name', 'Contact Person', 'Status', 'Remarks']

/* ── export helpers ── */
const buildRows = data => data.map(r => ({
  'PO No':          r.poNo || '',
  'PO Date':        fmtDate(r.poDate),
  'PO Type':        r.poType || '',
  'Supplier Name':  r.supplier?.supplierName || '',
  'Contact Person': r.contactPerson || '',
  'Status':         r.status || '',
  'Remarks':        r.remarks || '',
}))

const downloadBlob = (blob, filename) => {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url; a.download = filename
  document.body.appendChild(a); a.click()
  document.body.removeChild(a); URL.revokeObjectURL(url)
}

const doExcelExport = data => {
  const rows = buildRows(data)
  if (!rows.length) return
  const cols = Object.keys(rows[0])
  const lines = [cols.join(','), ...rows.map(r => cols.map(c => `"${String(r[c]).replace(/"/g,'""')}"`).join(','))]
  downloadBlob(new Blob(['﻿' + lines.join('\n')], { type: 'text/csv;charset=utf-8;' }), 'purchase-orders.csv')
}

const doDocExport = data => {
  const rows = buildRows(data)
  if (!rows.length) return
  const cols = Object.keys(rows[0])
  const thead = cols.map(c => `<th style="padding:5px 8px;background:#0097A7;color:#fff;font-size:11px;">${c}</th>`).join('')
  const tbody = rows.map((r, i) => `<tr style="${i%2?'background:#f8fafc;':''}">
    ${cols.map(c => `<td style="padding:4px 8px;border:1px solid #e2e8f0;font-size:11px;">${r[c]}</td>`).join('')}</tr>`).join('')
  const html = `<html><head><meta charset="utf-8"></head><body>
    <h2>Purchase Order List</h2>
    <table border="1" style="border-collapse:collapse;width:100%"><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
  </body></html>`
  downloadBlob(new Blob([html], { type: 'application/msword' }), 'purchase-orders.doc')
}

const doPrint = data => {
  const rows = buildRows(data)
  const cols = Object.keys(rows[0] || {})
  const thead = cols.map(c => `<th>${c}</th>`).join('')
  const tbody = rows.map((r, i) => `<tr class="${i%2?'alt':''}"><td>${cols.map(c=>r[c]).join('</td><td>')}</td></tr>`).join('')
  const win = window.open('', '_blank', 'width=1100,height=750')
  win.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Purchase Orders</title>
  <style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:11px;margin:16px}
  h2{font-size:15px}table{width:100%;border-collapse:collapse}
  th{background:#0097A7;color:#fff;padding:5px 7px;text-align:left;font-size:10px}
  td{padding:4px 7px;border-bottom:1px solid #e2e8f0;font-size:10px}
  tr.alt td{background:#f8fafc}@media print{@page{margin:1cm}}</style></head>
  <body><h2>Purchase Order List</h2>
  <table><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>
  </body></html>`)
  win.document.close(); win.focus()
  setTimeout(() => win.print(), 400)
}

export default function PurchaseOrderDetails() {
  const [fromDate, setFromDate]     = useState(thirtyDaysAgo)
  const [toDate, setToDate]         = useState(today)
  const [statusFilter, setStatusFilter] = useState('')
  const [allRows, setAllRows]       = useState([])
  const [rows, setRows]             = useState([])
  const [loading, setLoading]       = useState(true)
  const [searching, setSearching]   = useState(false)
  const [activeRow, setActiveRow]   = useState(null)

  // filter bar
  const [filterOpen, setFilterOpen] = useState(false)
  const [filterText, setFilterText] = useState('')

  // column settings
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [hiddenCols, setHiddenCols]     = useState(new Set())
  const settingsRef = useRef(null)

  // view modal
  const [viewPO, setViewPO]   = useState(null)
  const [approving, setApproving] = useState(false)
  const [rejecting, setRejecting] = useState(false)

  // delete
  const [deleteTarget, setDeleteTarget] = useState(null)
  const [deleting, setDeleting]         = useState(false)

  useEffect(() => {
    const handler = e => {
      if (settingsRef.current && !settingsRef.current.contains(e.target)) setSettingsOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  useEffect(() => {
    fetch(`${BASE}/api/purchase-master`)
      .then(r => r.json())
      .then(json => {
        if (json.success) { setAllRows(json.data); setRows(json.data) }
      })
      .catch(err => console.error('Error fetching POs:', err))
      .finally(() => setLoading(false))
  }, [])

  const handleSearch = () => {
    setSearching(true)
    setTimeout(() => {
      let result = allRows
      if (statusFilter) result = result.filter(r => r.status === statusFilter)
      result = result.filter(r => {
        const d = r.poDate ? r.poDate.split('T')[0] : ''
        return d >= fromDate && d <= toDate
      })
      setRows(result)
      setActiveRow(null)
      setFilterText('')
      setSearching(false)
    }, 0)
  }

  /* ── column visibility ── */
  const toggleCol = col => setHiddenCols(prev => {
    const next = new Set(prev); next.has(col) ? next.delete(col) : next.add(col); return next
  })
  const visibleCols = ALL_COLS.filter(c => !hiddenCols.has(c))

  /* ── live filter ── */
  const displayRows = filterText.trim()
    ? rows.filter(r => {
        const q = filterText.toLowerCase()
        return (
          (r.poNo || '').toLowerCase().includes(q) ||
          (r.poType || '').toLowerCase().includes(q) ||
          (r.supplier?.supplierName || '').toLowerCase().includes(q) ||
          (r.contactPerson || '').toLowerCase().includes(q) ||
          (r.status || '').toLowerCase().includes(q)
        )
      })
    : rows

  /* ── approve ── */
  const handleApprove = async po => {
    setApproving(true)
    try {
      const res = await fetch(`${BASE}/api/purchase-master/${po.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...po, items: po.details, status: 'Approval', updatedBy: 'Admin' }),
      })
      const json = await res.json()
      if (json.success) {
        const patch = r => r.id === po.id ? { ...r, status: 'Approval' } : r
        setAllRows(prev => prev.map(patch))
        setRows(prev => prev.map(patch))
        setViewPO(v => v ? { ...v, status: 'Approval' } : null)
      } else {
        alert(json.message || 'Approval failed')
      }
    } catch (err) {
      console.error('Approve error:', err)
      alert('Network error')
    } finally {
      setApproving(false)
    }
  }

  /* ── reject ── */
  const handleReject = async po => {
    setRejecting(true)
    try {
      const res = await fetch(`${BASE}/api/purchase-master/${po.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...po, items: po.details, status: 'Rejected', updatedBy: 'Admin' }),
      })
      const json = await res.json()
      if (json.success) {
        const patch = r => r.id === po.id ? { ...r, status: 'Rejected' } : r
        setAllRows(prev => prev.map(patch))
        setRows(prev => prev.map(patch))
        setViewPO(v => v ? { ...v, status: 'Rejected' } : null)
      } else {
        alert(json.message || 'Rejection failed')
      }
    } catch (err) {
      console.error('Reject error:', err)
      alert('Network error')
    } finally {
      setRejecting(false)
    }
  }

  /* ── edit ── */
  const handleEdit = (po, e) => {
    e.stopPropagation()
    localStorage.setItem('velson:po-edit', String(po.id))
    window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'PurchaseOrderEntry' } }))
  }

  /* ── delete ── */
  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return
    setDeleting(true)
    try {
      const res  = await fetch(`${BASE}/api/purchase-master/${deleteTarget.id}`, { method: 'DELETE' })
      const json = await res.json()
      if (json.success !== false) {
        const filter = r => r.id !== deleteTarget.id
        setAllRows(prev => prev.filter(filter))
        setRows(prev => prev.filter(filter))
        setActiveRow(null)
      }
    } catch (err) {
      console.error('Delete error:', err)
    } finally {
      setDeleting(false)
      setDeleteTarget(null)
    }
  }

  const headerDelete = () => {
    if (activeRow === null || !displayRows[activeRow]) return
    setDeleteTarget(displayRows[activeRow])
  }

  /* ── print ── */
  const handlePrint = () => doPrint(displayRows)

  const headerBg = s => s === 'Approval' ? 'bg-green-600' : s === 'Rejected' ? 'bg-red-500' : 'bg-[#0097A7]'

  const colSpanTotal = visibleCols.length + 4 // View + Edit + Delete + Print

  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden h-screen flex flex-col">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400 shrink-0">
        {/* <span className="hover:text-[#0097A7] cursor-pointer">Dashboard</span> */}
        {/* <ChevronRight className="w-3 h-3"/> */}
        <span className="hover:text-[#0097A7] cursor-pointer">Purchase</span>
        <ChevronRight className="w-3 h-3"/>
        <span className="text-[#0097A7] font-semibold">Purchase Order Details</span>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm flex flex-col flex-1 overflow-hidden">
        {/* Header */}
        <div className="bg-[#0097A7] px-4 py-2.5 flex items-center justify-between shrink-0">
          <h2 className="text-white font-semibold text-[14px]">Purchase Order Details</h2>
          <div className="flex gap-2">
            <button
              onClick={headerDelete}
              disabled={activeRow === null}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1 disabled:opacity-40"
            >
              <Trash2 className="w-3 h-3" /> Delete
            </button>
            <button
              onClick={handlePrint}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1"
            >
              <Printer className="w-3 h-3" /> Print
            </button>
            <button
              onClick={() => window.dispatchEvent(new CustomEvent('velson:navigate', { detail: { page: 'Dashboard' } }))}
              className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors flex items-center gap-1"
            >
              <X className="w-3 h-3" /> Close
            </button>
          </div>
        </div>

        {/* Filter bar */}
        <div className="px-4 py-3 border-b border-slate-200 flex flex-wrap items-center justify-between gap-3 bg-slate-50/50 shrink-0">
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-1.5">
              <label className={lbl}>From Date :</label>
              <input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className={inp} />
            </div>
            <div className="flex items-center gap-1.5">
              <label className={lbl}>To Date :</label>
              <input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className={inp} />
            </div>
            <div className="flex items-center gap-3">
              {STATUS_OPTIONS.map(opt => (
                <label key={opt.value} className="flex items-center gap-1 text-[12.5px] cursor-pointer whitespace-nowrap">
                  <input type="radio" name="poStatus" value={opt.value} checked={statusFilter === opt.value}
                    onChange={() => setStatusFilter(opt.value)} className="accent-[#0097A7]" />
                  {opt.label}
                </label>
              ))}
            </div>
            <button onClick={handleSearch} disabled={searching || loading}
              className="flex items-center gap-1.5 px-4 py-1 border border-[#0097A7] text-[#0097A7] bg-white hover:bg-[#0097A7]/10 rounded text-[12px] font-medium transition-colors shadow-sm disabled:opacity-70">
              <span className="w-2 h-2 rounded-full bg-red-500" />
              {searching ? 'Searching…' : 'Search'}
            </button>
          </div>

          {/* Export + utility */}
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-1.5">
              <span className="text-[12px] font-medium text-slate-500">LS</span>
              <input value={displayRows.length} readOnly className="w-10 text-center border border-slate-300 rounded text-[12px] py-0.5 bg-slate-50" />
            </div>
            <div className="h-4 w-px bg-slate-300" />
            <button onClick={() => doDocExport(displayRows)} className={iconBtn} title="Export as Word">
              <FileText className="w-4 h-4 text-[#0097A7]" /> Dos
            </button>
            <button onClick={() => doExcelExport(displayRows)} className={iconBtn} title="Export as CSV">
              <FileSpreadsheet className="w-4 h-4 text-[#0097A7]" /> Excel
            </button>
            <button onClick={handlePrint} className={iconBtn} title="Print">
              <FilePdf className="w-4 h-4 text-red-500" /> Pdf
            </button>
            <button
              onClick={() => { setFilterOpen(o => !o); if (filterOpen) setFilterText('') }}
              className={`${iconBtn} ${filterOpen ? 'text-[#0097A7]' : ''}`}
            >
              <Filter className={`w-4 h-4 ${filterOpen ? 'text-[#0097A7]' : 'text-blue-500'}`} /> Filter
            </button>
            <div className="relative" ref={settingsRef}>
              <button onClick={() => setSettingsOpen(o => !o)} className={`${iconBtn} ${settingsOpen ? 'text-[#0097A7]' : ''}`}>
                <Settings className="w-4 h-4 text-slate-700" /> Setting
              </button>
              {settingsOpen && (
                <div className="absolute right-0 top-7 bg-white border border-slate-200 rounded-lg shadow-xl z-50 p-3 min-w-[180px]">
                  <p className="text-[11px] font-bold text-slate-500 uppercase mb-2 tracking-wide">Show / Hide Columns</p>
                  {ALL_COLS.map(col => (
                    <label key={col} className="flex items-center gap-2 py-1 cursor-pointer hover:text-[#0097A7]">
                      <input type="checkbox" checked={!hiddenCols.has(col)} onChange={() => toggleCol(col)} className="accent-[#0097A7]" />
                      <span className="text-[12px] text-slate-700">{col}</span>
                    </label>
                  ))}
                  <button onClick={() => setHiddenCols(new Set())} className="mt-2 w-full text-[11px] py-1 bg-slate-100 hover:bg-slate-200 rounded text-slate-600 transition-colors">
                    Reset All
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Inline text filter */}
        {filterOpen && (
          <div className="px-3 py-2 border-b border-slate-200 bg-blue-50/40 flex items-center gap-3 shrink-0">
            <Filter className="w-3.5 h-3.5 text-blue-400 shrink-0" />
            <input autoFocus type="text" value={filterText} onChange={e => setFilterText(e.target.value)}
              placeholder="Search PO No, Supplier, Type, Status…"
              className="flex-1 border border-blue-200 rounded px-3 py-1 text-[12.5px] focus:outline-none focus:border-[#0097A7] bg-white" />
            {filterText && (
              <button onClick={() => setFilterText('')} className="text-slate-400 hover:text-slate-600">
                <X className="w-3.5 h-3.5" />
              </button>
            )}
            <span className="text-[11px] text-slate-400 shrink-0">{displayRows.length} result{displayRows.length !== 1 ? 's' : ''}</span>
          </div>
        )}

        {/* Table */}
        <div className="flex-1 overflow-auto relative">
          {loading ? (
            <div className="flex items-center justify-center h-32 gap-2.5 text-slate-500 text-[12px]">
              <Spinner cls="w-5 h-5 text-[#0097A7]" /> Loading…
            </div>
          ) : (
            <table className="w-full min-w-max text-[12px] text-left border-collapse">
              <thead className="bg-slate-800 text-white sticky top-0 z-10">
                <tr>
                  {visibleCols.map(h => (
                    <th key={h} className="p-2 font-medium border-x border-slate-700 whitespace-nowrap">{h}</th>
                  ))}
                  <th className="p-2 font-medium border-x border-slate-700 text-center">View</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Edit</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Delete</th>
                  <th className="p-2 font-medium border-x border-slate-700 text-center">Print</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 bg-white">
                {displayRows.length === 0 ? (
                  <tr>
                    <td colSpan={colSpanTotal} className="p-8 text-center text-slate-400 text-[12px]">
                      {filterText ? 'No matching records' : 'No purchase orders found'}
                    </td>
                  </tr>
                ) : displayRows.map((row, i) => (
                  <tr
                    key={row.id}
                    onClick={() => setActiveRow(i)}
                    className={`cursor-pointer transition-colors ${activeRow === i ? 'bg-[#0097A7]/20' : 'hover:bg-slate-50'}`}
                  >
                    {visibleCols.map(col => {
                      switch (col) {
                        case 'PO No':         return <td key={col} className="p-1.5 border-x border-slate-200 font-medium text-[#0097A7]">{row.poNo}</td>
                        case 'PO Date':       return <td key={col} className="p-1.5 border-x border-slate-200">{fmtDate(row.poDate)}</td>
                        case 'PO Type':       return <td key={col} className="p-1.5 border-x border-slate-200">{row.poType || '—'}</td>
                        case 'Supplier Name': return <td key={col} className="p-1.5 border-x border-slate-200 font-medium">{row.supplier?.supplierName || '—'}</td>
                        case 'Contact Person':return <td key={col} className="p-1.5 border-x border-slate-200">{row.contactPerson || '—'}</td>
                        case 'Status':        return <td key={col} className="p-1.5 border-x border-slate-200"><span className={statusColor(row.status)}>{row.status || '—'}</span></td>
                        case 'Remarks':       return <td key={col} className="p-1.5 border-x border-slate-200 text-slate-500">{row.remarks || '—'}</td>
                        default: return null
                      }
                    })}
                    {/* View */}
                    <td className="p-1.5 border-x border-slate-200 text-center">
                      <button onClick={e => { e.stopPropagation(); setViewPO(row) }}
                        className="text-[#0097A7] hover:text-[#007a87] transition-colors" title="View details">
                        <Eye className="w-3.5 h-3.5" />
                      </button>
                    </td>
                    {/* Edit */}
                    <td className="p-1.5 border-x border-slate-200 text-center">
                      <button onClick={e => handleEdit(row, e)}
                        className="text-amber-500 hover:text-amber-600 transition-colors" title="Edit">
                        <Pencil className="w-3.5 h-3.5" />
                      </button>
                    </td>
                    {/* Delete */}
                    <td className="p-1.5 border-x border-slate-200 text-center">
                      <button onClick={e => { e.stopPropagation(); setDeleteTarget(row) }}
                        className="text-red-500 hover:text-red-600 transition-colors" title="Delete">
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </td>
                    {/* Print */}
                    <td className="p-1.5 border-x border-slate-200 text-center">
                      <button onClick={e => { e.stopPropagation(); doPrint([row]) }}
                        className="text-purple-500 hover:text-purple-700 transition-colors" title="Print">
                        <Printer className="w-3.5 h-3.5" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="sticky bottom-0 bg-[#f4f6ce] font-semibold text-slate-800 border-t-2 border-slate-300">
                <tr>
                  <td colSpan={colSpanTotal} className="p-2 border-x border-slate-300">
                    Row : {displayRows.length}{filterText ? ` (filtered from ${rows.length})` : ''}
                  </td>
                </tr>
              </tfoot>
            </table>
          )}
        </div>
      </div>

      {/* ── View Modal ── */}
      {viewPO && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => { if (!approving && !rejecting) setViewPO(null) }} />
          <div className="relative bg-white rounded-xl shadow-2xl border border-slate-200 w-[700px] max-h-[88vh] overflow-hidden flex flex-col">
            {/* Modal header */}
            <div className={`px-5 py-3 flex items-center justify-between shrink-0 ${headerBg(viewPO.status)}`}>
              <div>
                <h3 className="text-white font-semibold text-[14px]">Purchase Order Details</h3>
                <p className="text-white/70 text-[11px] mt-0.5">{viewPO.poNo} &nbsp;·&nbsp; {viewPO.status}</p>
              </div>
              <button onClick={() => setViewPO(null)} disabled={approving || rejecting}
                className="text-white/80 hover:text-white transition-colors disabled:opacity-40">
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* PO info grid */}
            <div className="px-5 pt-4 pb-3 grid grid-cols-2 gap-x-6 gap-y-2 text-[12.5px] shrink-0 border-b border-slate-100">
              {[
                ['PO Number',       viewPO.poNo],
                ['PO Date',         fmtDate(viewPO.poDate)],
                ['ETA Date',        fmtDate(viewPO.etaDate)],
                ['PO Type',         viewPO.poType],
                ['Supplier',        viewPO.supplier?.supplierName],
                ['Contact Person',  viewPO.contactPerson],
                ['Contact No',      viewPO.contactNumber],
                ['GST No',          viewPO.gstNo],
                ['Supplier Ref No', viewPO.supplierRefNo],
                ['Status',          viewPO.status],
                ['Sub Total',       viewPO.subTotal != null ? `₹ ${Number(viewPO.subTotal).toFixed(2)}` : null],
                ['Grand Total',     viewPO.totalAmount != null ? `₹ ${Number(viewPO.totalAmount).toFixed(2)}` : null],
                ['Remarks',         viewPO.remarks],
                ['Created By',      viewPO.createdBy],
              ].map(([label, value]) => (
                <div key={label} className="flex gap-2">
                  <span className="w-32 font-semibold text-slate-500 shrink-0">{label}</span>
                  <span className="text-slate-400 shrink-0">:</span>
                  <span className={`text-slate-800 ${label === 'Status' ? statusColor(viewPO.status) : ''}`}>
                    {value || '—'}
                  </span>
                </div>
              ))}
            </div>

            {/* Items */}
            <div className="flex-1 overflow-y-auto px-5 py-3">
              <p className="text-[12px] font-semibold text-slate-600 mb-2">Items</p>
              {viewPO.details?.length > 0 ? (
                <table className="w-full text-[11.5px] border border-slate-200 rounded">
                  <thead className="bg-slate-100 sticky top-0">
                    <tr>
                      {['#','Item Code','Item Name','Description','UOM','Qty','Unit Price','Disc%','Amount','GST%','Net Amt'].map(h => (
                        <th key={h} className="px-2 py-1 text-left font-semibold text-slate-600 border-b border-slate-200 whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {viewPO.details.map((it, idx) => (
                      <tr key={idx} className={`border-b border-slate-100 ${idx % 2 === 1 ? 'bg-slate-50/50' : ''}`}>
                        <td className="px-2 py-1">{idx + 1}</td>
                        <td className="px-2 py-1">{it.itemCode || '—'}</td>
                        <td className="px-2 py-1 whitespace-nowrap">{it.itemName || '—'}</td>
                        <td className="px-2 py-1">{it.description || '—'}</td>
                        <td className="px-2 py-1">{it.uom || '—'}</td>
                        <td className="px-2 py-1">{it.qty ?? '—'}</td>
                        <td className="px-2 py-1">{it.unitPrice ?? '—'}</td>
                        <td className="px-2 py-1">{it.discPer ?? '—'}</td>
                        <td className="px-2 py-1">{it.amount ?? '—'}</td>
                        <td className="px-2 py-1">{it.gstPer ?? '—'}</td>
                        <td className="px-2 py-1 font-medium">{it.netAmt ?? '—'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p className="text-[12px] text-slate-400 italic">No items</p>
              )}
            </div>

            {/* Modal footer with Approve / Reject */}
            <div className="px-5 py-3 border-t border-slate-100 flex items-center justify-between shrink-0">
              <span className="text-[11.5px] text-slate-400">{viewPO.details?.length || 0} item(s)</span>
              <div className="flex gap-2">
                <button onClick={() => setViewPO(null)} disabled={approving || rejecting}
                  className="px-4 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-[12px] font-semibold rounded-lg border border-slate-200 transition-colors disabled:opacity-40">
                  Close
                </button>

                {viewPO.status === 'Pending' && (
                  <>
                    <button onClick={() => handleReject(viewPO)} disabled={approving || rejecting}
                      className="px-5 py-1.5 bg-red-500 hover:bg-red-600 text-white text-[12px] font-semibold rounded-lg transition-colors shadow-sm disabled:opacity-60 flex items-center gap-1.5">
                      {rejecting
                        ? <><span className="w-3 h-3 border-2 border-white/40 border-t-white rounded-full animate-spin inline-block" /> Rejecting…</>
                        : 'Reject'}
                    </button>
                    <button onClick={() => handleApprove(viewPO)} disabled={approving || rejecting}
                      className="px-5 py-1.5 bg-green-600 hover:bg-green-700 text-white text-[12px] font-semibold rounded-lg transition-colors shadow-sm disabled:opacity-60 flex items-center gap-1.5">
                      {approving
                        ? <><span className="w-3 h-3 border-2 border-white/40 border-t-white rounded-full animate-spin inline-block" /> Approving…</>
                        : 'Approve'}
                    </button>
                  </>
                )}

                {viewPO.status === 'Approval' && (
                  <span className="px-4 py-1.5 bg-green-100 text-green-700 text-[12px] font-semibold rounded-lg border border-green-200">
                    ✓ Approved
                  </span>
                )}
                {viewPO.status === 'Rejected' && (
                  <span className="px-4 py-1.5 bg-red-100 text-red-600 text-[12px] font-semibold rounded-lg border border-red-200">
                    ✗ Rejected
                  </span>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        message={`Delete purchase order ${deleteTarget?.poNo}? This action cannot be undone.`}
        onCancel={() => { if (!deleting) setDeleteTarget(null) }}
        onConfirm={handleDeleteConfirm}
        confirming={deleting}
      />
    </div>
  )
}

