    </div>`

  const logoUrl = `${window.location.origin}/velson-logo.png`
  let globalIdx = 0

  const pagesHtml = pages.map((pg, pi) => {
    const startIdx = globalIdx
    globalIdx += pg.items.length

    const headerHtml = pg.isFirst ? `
