      </div>` : ''

    return `<div class="page${pi > 0 ? ' brk' : ''}">
      ${headerHtml}
      <table class="items-tbl">
        <thead><tr>
          <th style="width:28px">S.No.</th>
          <th>DESCRIPTION OF GOODS</th>
          <th style="width:46px">TAX %</th>
          <th style="width:68px">HSN Code</th>
          <th style="width:44px">QTY</th>
