  const [pdfMenuRow, setPdfMenuRow] = useState(null)
  const pdfMenuRef = useRef(null)
  useEffect(() => {
    if (!pdfMenuRow) return
    const handler = (e) => {
      if (pdfMenuRef.current && !pdfMenuRef.current.contains(e.target)) setPdfMenuRow(null)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [pdfMenuRow])

  /* ── fetch ── */
  const fetchData = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await api.get('/api/quotation-master', { skipGlobalLoader: true })
      let data = res.data?.data ?? []
      if (fromDate) data = data.filter(r => r.quotationDate && r.quotationDate.slice(0, 10) >= fromDate)
      if (toDate)   data = data.filter(r => r.quotationDate && r.quotationDate.slice(0, 10) <= toDate)
      if (quotationNo.trim()) data = data.filter(r => r.quotationNo?.toLowerCase().includes(quotationNo.trim().toLowerCase()))
      if (statusFilter)       data = data.filter(r => r.status === statusFilter)
      setRows(data)
    } catch (err) {
      console.error('[QuotationDetails] fetch error:', err)
      setError('Failed to load quotations.')
    } finally {
      setLoading(false)
    }
  }, [fromDate, toDate, quotationNo, statusFilter])

  useEffect(() => { fetchData() }, [])

  /* ── delete ── */
  const confirmDelete = async () => {
    if (!deleteTarget) return
    setDeleteLoading(true)
    try {
      await api.delete(`/api/quotation-master/${deleteTarget.id}`, { loadingMessage: 'Deleting quotation...' })
      setRows(r => r.filter(x => x.id !== deleteTarget.id))
      toast.success(`Quotation ${deleteTarget.quotationNo} deleted.`)
      setDeleteTarget(null)
    } catch (err) {
      toast.error('Delete failed: ' + (err.response?.data?.message || err.message))
    } finally {
      setDeleteLoading(false)
    }
  }

  /* ── edit → navigate to entry page with the existing data ── */
  const handleEdit = (row) => {
    // Accepted quotations create a new revision; others are edited in-place
    const mode = row.status === 'Accepted' ? 'revision' : 'edit'
    navigate('/quotation/quotation-entry', { state: { editData: row, mode } })
  }

  /* ── accept / reject (superadmin) ── */
  const confirmAction = async () => {
    if (!actionTarget) return
    setActionLoading(true)
    try {
      const row = rows.find(x => x.id === actionTarget.id) ?? {}
      const payload = {
        customerRef:       row.customerRef      ?? null,
        currencyCode:      row.currencyCode     ?? 'INR',
        exchangeRate:      row.exchangeRate      ?? 1,
        modelRef:          row.modelRef         ?? null,
        taxType:           row.taxType          ?? null,
        quotationDate:     row.quotationDate    ?? null,
        validUntil:        row.validUntil       ?? null,
        revisionNo:        row.revisionNo       ?? 0,
        quotationType:     row.quotationType    ?? null,
        discountType:      row.discountType     ?? 'Dis_Per',
        showTotalsGrid:    row.showTotalsGrid   ?? false,
        specialDiscount:   row.specialDiscount  ?? 0,
        freightAmount:     row.freightAmount    ?? 0,
        taxPercent:        row.taxPercent       ?? 18,
        packingForwarding: row.packingForwarding ?? 0,
        subTotal:          row.subTotal         ?? 0,
        taxAmount:         row.taxAmount        ?? 0,
        totalAmount:       row.totalAmount      ?? 0,
        paymentTerms:      row.paymentTerms     ?? null,
        status:            actionTarget.action,
        items:             row.details          ?? [],
      }
      await api.put(`/api/quotation-master/${actionTarget.id}`, payload, { loadingMessage: 'Updating quotation...' })
      setRows(r => r.map(x => x.id === actionTarget.id ? { ...x, status: actionTarget.action } : x))
      toast.success(`Quotation ${actionTarget.quotationNo} ${actionTarget.action.toLowerCase()}.`)
      setActionTarget(null)
    } catch (err) {
      toast.error('Action failed: ' + (err.response?.data?.message || err.message))
    } finally {
      setActionLoading(false)
    }
  }

  const COLS = [
    { label: 'Quotation Number', w: 'w-40' },
    { label: 'Quotation Date',   w: 'w-36' },
    { label: 'Status',           w: 'w-32' },
    { label: 'Customer Name',    w: 'w-64' },
    { label: 'Total Amount',     w: 'w-36' },
    { label: 'View',             w: 'w-16' },
    { label: 'RPT',              w: 'w-16' },
    { label: 'PDF',              w: 'w-16' },
    { label: 'Edit',             w: 'w-16' },
    { label: 'Delete',           w: 'w-16' },
  ]

  return (
    <div className="bg-[#f4f6f8] min-h-full">
      <div className="px-6 py-6">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-[12px] text-slate-400 mb-5">
          {/* <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Dashboard</span> */}
          {/* <ChevronRight className="w-3 h-3" /> */}
          <span className="hover:text-[#0097A7] cursor-pointer transition-colors uppercase tracking-widest">Sales</span>
          <ChevronRight className="w-3 h-3" />
          <span className="text-[#0097A7] font-semibold uppercase tracking-widest">Quotation Details</span>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[850px]">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-slate-200 bg-white px-4 py-2.5">
            <div className="flex items-center gap-2">
              <div className="w-3.5 h-3.5 bg-red-700 rounded-sm" />
              <h2 className="text-[14px] font-black text-slate-800 uppercase tracking-tight">Quotation Details</h2>
            </div>
            <button
              onClick={() => onNavigate?.('Dashboard')}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-600 text-[11px] font-bold rounded-md transition-all shadow-sm"
            >
              <div className="w-4 h-4 bg-slate-400 rounded-full flex items-center justify-center">
                <X size={10} className="text-white" strokeWidth={3} />
              </div>
              Close
            </button>
          </div>

          <div className="p-5 flex-1 flex flex-col">
            {/* Filter Bar */}
            <div className="flex items-end justify-between gap-4 mb-6 bg-slate-50/50 p-5 rounded-xl border border-slate-100">
              <div className="flex items-end gap-4 w-full flex-wrap">
                <div className="flex-1 min-w-[130px]">
                  <Label>From Date</Label>
                  <Input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className="w-full" />
                </div>
                <div className="flex-1 min-w-[130px]">
                  <Label>To Date</Label>
                  <Input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className="w-full" />
                </div>
                <div className="flex-1 min-w-[130px]">
                  <Label>PDF Format</Label>
                  <select
                    value={pdfFormat}
                    onChange={e => setPdfFormat(e.target.value)}
                    className="px-4 py-2 text-[13px] border border-slate-200 rounded-lg bg-white text-slate-700 w-full focus:outline-none focus:border-[#0097A7]"
                  >
                    <option>Standard</option>
                    <option>Detailed</option>
                  </select>
                </div>
                <div className="flex-1 min-w-[150px]">
                  <Label>Quotation Number</Label>
                  <Input placeholder="Enter Quote No" value={quotationNo} onChange={e => setQuotationNo(e.target.value)} className="w-full" />
                </div>
                <div className="flex-1 min-w-[130px]">
                  <Label>Quotation Status</Label>
                  <select
                    value={statusFilter}
                    onChange={e => setStatusFilter(e.target.value)}
                    className="px-4 py-2 text-[13px] border border-slate-200 rounded-lg bg-white text-slate-700 w-full focus:outline-none focus:border-[#0097A7]"
                  >
                    <option value="">-- All --</option>
                    <option value="Draft">Draft</option>
                    <option value="Sent">Sent</option>
                    <option value="Accepted">Accepted</option>
                    <option value="Rejected">Rejected</option>
                  </select>
                </div>
                <button
                  onClick={fetchData}
                  disabled={loading}
                  className="flex items-center justify-center gap-2 px-8 py-2 bg-[#0097A7] hover:bg-[#007a87] disabled:opacity-60 text-white text-[12px] font-bold rounded-lg transition-all shadow-md active:scale-95 h-[38px] min-w-[120px]"
                >
                  {loading ? <Loader2 size={14} className="animate-spin" /> : null}
                  Search
                </button>
              </div>
            </div>

            {/* Tool Icons Bar */}
            <div className="flex items-center justify-end gap-5 mb-4 px-2 text-slate-500">
              <div className="flex items-center gap-1.5 border-r border-slate-200 pr-5">
                <span className="text-[11px] font-bold">LS</span>
                <span className="text-[12px] font-black text-[#0097A7]">{rows.length}</span>
              </div>
              <button className="flex items-center gap-1.5 hover:text-[#0097A7] transition-colors group" title="Dos">
                <Download size={16} />
                <span className="text-[11px] font-bold group-hover:text-[#0097A7]">Dos</span>
              </button>
              <button
                onClick={() => exportCSV(rows)}
                disabled={rows.length === 0}
                className="flex items-center gap-1.5 hover:text-emerald-600 transition-colors group disabled:opacity-40"
                title="Export Excel/CSV"
              >
                <FileSpreadsheet size={16} />
                <span className="text-[11px] font-bold group-hover:text-emerald-600">Excel</span>
              </button>
              <button className="flex items-center gap-1.5 hover:text-rose-600 transition-colors group" title="Pdf">
                <FileText size={16} />
                <span className="text-[11px] font-bold group-hover:text-rose-600">Pdf</span>
              </button>
              <button className="flex items-center gap-1.5 hover:text-[#0097A7] transition-colors group" title="Filter">
                <Filter size={16} />
                <span className="text-[11px] font-bold group-hover:text-[#0097A7]">Filter</span>
              </button>
              <button className="flex items-center gap-1.5 hover:text-[#0097A7] transition-colors group" title="Setting">
                <Settings size={16} />
                <span className="text-[11px] font-bold group-hover:text-[#0097A7]">Setting</span>
              </button>
            </div>

            {/* Table */}
            <div className="flex-1 border border-slate-200 rounded-lg overflow-hidden overflow-x-auto shadow-sm">
              <table className="w-full text-left border-collapse min-w-full bg-white">
                <thead className="bg-[#cbd5e1]/30 text-[11px] uppercase text-slate-600 font-bold border-b border-slate-300">
                  <tr>
                    {COLS.map((h, i) => (
                      <th key={i} className={`px-3 py-3 border-r border-slate-300 whitespace-nowrap ${h.w}`}>{h.label}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[12px]">
                  {loading ? (
                    <tr>
                      <td colSpan={COLS.length} className="py-8">
                        <SpinnerLoader message="Loading quotations…" />
                      </td>
                    </tr>
                  ) : error ? (
                    <tr><td colSpan={COLS.length} className="text-center py-16 text-red-400 text-[13px]">{error}</td></tr>
                  ) : rows.length === 0 ? (
                    <tr><td colSpan={COLS.length} className="text-center py-16 text-slate-400 text-[13px]">No records found.</td></tr>
                  ) : (
                    rows.map((row, i) => (
                      <tr key={row.id} className={`h-10 hover:bg-[#f0f9fa]/60 transition-colors ${i % 2 === 1 ? 'bg-slate-50/40' : ''}`}>
                        <td className="px-3 py-2 border-r border-slate-100 font-medium text-[#0097A7] whitespace-nowrap">{row.quotationNo}</td>
                        <td className="px-3 py-2 border-r border-slate-100 whitespace-nowrap">{fmt(row.quotationDate)}</td>
                        <td className="px-3 py-2 border-r border-slate-100"><StatusBadge status={row.status} /></td>
                        <td className="px-3 py-2 border-r border-slate-100">{row.customer?.customerName ?? '—'}</td>
                        <td className="px-3 py-2 border-r border-slate-100 text-right font-medium tabular-nums">{fmtAmt(row.totalAmount)}</td>
                        <td className="px-3 py-2 border-r border-slate-100 text-center">
                          <button
                            onClick={() => setViewRow(row)}
                            className="p-1.5 rounded hover:bg-cyan-50 text-slate-500 hover:text-[#0097A7] transition-colors"
                            title="View quotation"
                          >
                            <Eye size={14} />
                          </button>
                        </td>
                        <td className="px-3 py-2 border-r border-slate-100 text-center">
                          <button
                            onClick={() => openPrintWindow(row)}
                            className="p-1.5 rounded hover:bg-slate-100 text-slate-500 hover:text-[#0097A7] transition-colors"
                            title="Print report"
                          >
                            <Printer size={14} />
                          </button>
                        </td>
                        <td className="px-3 py-2 border-r border-slate-100 text-center">
                          <div
                            ref={pdfMenuRow === row.id ? pdfMenuRef : null}
                            className="relative inline-block"
                          >
                            <button
                              onClick={(e) => { e.stopPropagation(); setPdfMenuRow(pdfMenuRow === row.id ? null : row.id) }}
                              className="p-1.5 rounded hover:bg-rose-50 text-slate-500 hover:text-rose-600 transition-colors"
                              title="PDF"
                            >
                              <FileText size={14} />
                            </button>
                            {pdfMenuRow === row.id && (
                              <div className="absolute right-0 top-full mt-1 z-30 bg-white border border-slate-200 rounded-lg shadow-xl w-32 py-1 text-left">
                                {[
                                  { label: 'Format 1', fn: () => openFormat1Window(row) },
                                  { label: 'Format 2', fn: () => openFormat2Window(row) },
                                  { label: 'Format 3', fn: () => openFormat3Window(row) },
                                  { label: 'Format 4', fn: () => openFormat4Window(row) },
                                ].map(({ label, fn }) => (
                                  <button
                                    key={label}
                                    onClick={() => { fn(); setPdfMenuRow(null) }}
                                    className="w-full px-3 py-1.5 text-[12px] text-slate-600 hover:bg-[#f0f9fa] hover:text-[#0097A7] transition-colors"
                                  >
                                    {label}
                                  </button>
                                ))}
                              </div>
                            )}
                          </div>
                        </td>
                        <td className="px-3 py-2 border-r border-slate-100 text-center">
                          <button
                            onClick={() => handleEdit(row)}
                            className="p-1.5 rounded hover:bg-blue-50 text-slate-500 hover:text-blue-600 transition-colors"
                            title="Revise & edit"
                          >
                            <Pencil size={14} />
                          </button>
                        </td>
                        <td className="px-3 py-2 border-r border-slate-100 text-center">
                          <button
                            onClick={() => setDeleteTarget({ id: row.id, quotationNo: row.quotationNo })}
                            className="p-1.5 rounded hover:bg-red-50 text-slate-500 hover:text-red-500 transition-colors"
                            title="Delete"
                          >
                            <Trash2 size={14} />
                          </button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>

            {/* Footer */}
            <div className="mt-4 flex items-center justify-between px-2">
              <div className="flex items-center gap-1.5 opacity-30 hover:opacity-100 transition-opacity cursor-default">
                <FileBarChart size={14} className="text-[#0097A7]" />
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 italic">Quotation Audit & Estimation Analysis Console</span>
              </div>
              <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                Records: <span className="text-[#0097A7]">{rows.length}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ── View Quotation modal ── */}
      {viewRow && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="bg-white rounded-xl shadow-2xl border border-slate-200 w-full max-w-3xl max-h-[90vh] flex flex-col">
            {/* Modal header */}
            <div className="flex items-center justify-between px-5 py-3.5 border-b border-slate-200 shrink-0">
              <div>
                <p className="text-[14px] font-black text-slate-800 uppercase tracking-tight">
                  {viewRow.quotationNo}
                </p>
                <p className="text-[11px] text-slate-400 mt-0.5">
                  Rev: {viewRow.revisionNo ?? 0} &nbsp;|&nbsp; {fmt(viewRow.quotationDate)}
                </p>
              </div>
              <div className="flex items-center gap-3">
                <StatusBadge status={viewRow.status} />
                <button onClick={() => setViewRow(null)} className="p-1.5 rounded hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors">
                  <X size={16} />
                </button>
              </div>
            </div>

            {/* Modal body */}
            <div className="overflow-y-auto flex-1 px-5 py-4 space-y-4">
              {/* Customer / meta grid */}
              <div className="grid grid-cols-2 gap-x-8 gap-y-2 text-[12px]">
                <div className="space-y-1.5">
                  <div className="flex gap-2"><span className="text-slate-400 w-28 shrink-0">Customer</span><span className="font-semibold text-slate-700">{viewRow.customer?.customerName ?? '—'}</span></div>
                  <div className="flex gap-2"><span className="text-slate-400 w-28 shrink-0">Currency</span><span className="font-semibold text-slate-700">{viewRow.currencyCode ?? 'INR'}</span></div>
                  <div className="flex gap-2"><span className="text-slate-400 w-28 shrink-0">Model Ref</span><span className="font-semibold text-slate-700">{viewRow.modelRef ?? '—'}</span></div>
                  <div className="flex gap-2"><span className="text-slate-400 w-28 shrink-0">Customer Ref</span><span className="font-semibold text-slate-700">{viewRow.customerRef ?? '—'}</span></div>
                </div>
                <div className="space-y-1.5">
                  <div className="flex gap-2"><span className="text-slate-400 w-28 shrink-0">Tax Type</span><span className="font-semibold text-slate-700">{viewRow.taxType ?? '—'}</span></div>
                  <div className="flex gap-2"><span className="text-slate-400 w-28 shrink-0">Valid Until</span><span className="font-semibold text-slate-700">{fmt(viewRow.validUntil)}</span></div>
                  <div className="flex gap-2"><span className="text-slate-400 w-28 shrink-0">Quotation Type</span><span className="font-semibold text-slate-700">{viewRow.quotationType ?? '—'}</span></div>
                  <div className="flex gap-2"><span className="text-slate-400 w-28 shrink-0">Exchange Rate</span><span className="font-semibold text-slate-700">{viewRow.exchangeRate ?? '—'}</span></div>
                </div>
              </div>

              {/* Items table */}
              <div className="border border-slate-200 rounded-lg overflow-hidden">
                <table className="w-full text-left border-collapse text-[11.5px]">
                  <thead className="bg-slate-100 text-slate-500 uppercase font-bold">
                    <tr>
                      <th className="px-3 py-2 border-r border-slate-200 w-8">#</th>
                      <th className="px-3 py-2 border-r border-slate-200">Part No</th>
                      <th className="px-3 py-2 border-r border-slate-200">Item Name</th>
                      <th className="px-3 py-2 border-r border-slate-200">Description</th>
                      <th className="px-3 py-2 border-r border-slate-200 text-center w-14">Qty</th>
                      <th className="px-3 py-2 border-r border-slate-200 text-right w-24">Unit Price</th>
                      <th className="px-3 py-2 text-right w-24">Amount</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {(viewRow.details ?? []).length === 0 ? (
                      <tr><td colSpan={7} className="text-center py-6 text-slate-400">No items</td></tr>
                    ) : (viewRow.details ?? []).map((d, i) => (
                      <tr key={i} className={i % 2 === 1 ? 'bg-slate-50/50' : ''}>
                        <td className="px-3 py-1.5 border-r border-slate-100 text-center text-slate-400">{i + 1}</td>
                        <td className="px-3 py-1.5 border-r border-slate-100 font-medium text-[#0097A7]">{d.partNo ?? '—'}</td>
                        <td className="px-3 py-1.5 border-r border-slate-100">{d.itemName ?? '—'}</td>
                        <td className="px-3 py-1.5 border-r border-slate-100 text-slate-500">{d.description ?? '—'}</td>
                        <td className="px-3 py-1.5 border-r border-slate-100 text-center">{d.qty ?? '—'}</td>
                        <td className="px-3 py-1.5 border-r border-slate-100 text-right tabular-nums">{fmtAmt(d.unitPrice)}</td>
                        <td className="px-3 py-1.5 text-right tabular-nums font-medium">{fmtAmt(d.amount)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Totals */}
              <div className="flex justify-end">
                <div className="w-64 space-y-1 text-[12px]">
                  <div className="flex justify-between text-slate-500"><span>Sub Total</span><span className="tabular-nums">{fmtAmt(viewRow.subTotal)}</span></div>
                  <div className="flex justify-between text-slate-500"><span>Special Discount</span><span className="tabular-nums">{fmtAmt(viewRow.specialDiscount)}</span></div>
                  <div className="flex justify-between text-slate-500"><span>Freight</span><span className="tabular-nums">{fmtAmt(viewRow.freightAmount)}</span></div>
                  <div className="flex justify-between text-slate-500"><span>Tax ({viewRow.taxPercent ?? 0}%)</span><span className="tabular-nums">{fmtAmt(viewRow.taxAmount)}</span></div>
                  <div className="flex justify-between font-black text-[13px] text-[#0097A7] border-t border-slate-200 pt-1.5 mt-1">
                    <span>Grand Total</span>
                    <span className="tabular-nums">{fmtAmtWhole(viewRow.totalAmount)}</span>
                  </div>
                </div>
              </div>

              {/* Payment terms */}
              {viewRow.paymentTerms && (
                <div className="bg-slate-50 rounded-lg p-3 text-[11.5px] text-slate-600 border border-slate-100">
                  <p className="font-bold text-slate-500 uppercase tracking-wider text-[10px] mb-1">Payment Terms</p>
                  <p className="whitespace-pre-wrap">{viewRow.paymentTerms}</p>
                </div>
              )}
            </div>

            {/* Modal footer — Accept / Reject */}
            <div className="px-5 py-3.5 border-t border-slate-200 flex items-center justify-between shrink-0 bg-slate-50/60">
              <button
                onClick={() => setViewRow(null)}
                className="px-4 py-1.5 text-[12px] font-semibold rounded-lg border border-slate-200 bg-white hover:bg-slate-50 transition-colors"
              >
                Close
              </button>
              <div className="flex gap-2">
                <button
                  disabled={viewRow.status === 'Accepted' || viewRow.status === 'Rejected'}
                  onClick={() => { setViewRow(null); setActionTarget({ id: viewRow.id, quotationNo: viewRow.quotationNo, action: 'Accepted' }) }}
                  className="flex items-center gap-1.5 px-4 py-1.5 text-[12px] font-bold rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                >
                  <CheckCircle size={13} /> Accept
                </button>
                <button
                  disabled={viewRow.status === 'Accepted' || viewRow.status === 'Rejected'}
                  onClick={() => { setViewRow(null); setActionTarget({ id: viewRow.id, quotationNo: viewRow.quotationNo, action: 'Rejected' }) }}
                  className="flex items-center gap-1.5 px-4 py-1.5 text-[12px] font-bold rounded-lg bg-red-500 hover:bg-red-600 text-white transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                >
                  <XCircle size={13} /> Reject
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── Accept / Reject confirmation modal (superadmin) ── */}
      {actionTarget && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 w-[380px]">
            <div className="flex items-center gap-3 mb-4">
              <div className={`w-9 h-9 rounded-full flex items-center justify-center shrink-0 ${actionTarget.action === 'Accepted' ? 'bg-emerald-50' : 'bg-red-50'}`}>
                {actionTarget.action === 'Accepted'
                  ? <CheckCircle size={18} className="text-emerald-500" />
                  : <XCircle size={18} className="text-red-500" />}
              </div>
              <div>
                <p className="text-[13px] font-bold text-slate-800">
                  {actionTarget.action === 'Accepted' ? 'Accept' : 'Reject'} Quotation
                </p>
                <p className="text-[12px] text-slate-500 mt-0.5">
                  {actionTarget.action === 'Accepted' ? 'Accept' : 'Reject'}{' '}
                  <span className="font-semibold text-slate-700">{actionTarget.quotationNo}</span>? This cannot be undone.
                </p>
              </div>
            </div>
            <div className="flex gap-2 justify-end">
              <button
                onClick={() => setActionTarget(null)}
                disabled={actionLoading}
                className="px-4 py-1.5 text-[12px] font-semibold rounded-lg border border-slate-200 hover:bg-slate-50 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={confirmAction}
                disabled={actionLoading}
                className={`flex items-center gap-1.5 px-4 py-1.5 text-[12px] font-semibold rounded-lg text-white disabled:opacity-60 transition-colors ${actionTarget.action === 'Accepted' ? 'bg-emerald-500 hover:bg-emerald-600' : 'bg-red-500 hover:bg-red-600'}`}
              >
                {actionLoading ? <Loader2 size={13} className="animate-spin" /> : null}
                {actionTarget.action === 'Accepted' ? 'Accept' : 'Reject'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Delete confirmation modal ── */}
      {deleteTarget && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 w-[360px]">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-9 h-9 rounded-full bg-red-50 flex items-center justify-center shrink-0">
                <AlertTriangle size={18} className="text-red-500" />
              </div>
              <div>
                <p className="text-[13px] font-bold text-slate-800">Delete Quotation</p>
                <p className="text-[12px] text-slate-500 mt-0.5">
                  Delete <span className="font-semibold text-slate-700">{deleteTarget.quotationNo}</span>? This cannot be undone.
                </p>
              </div>
            </div>
            <div className="flex gap-2 justify-end">
              <button
                onClick={() => setDeleteTarget(null)}
                disabled={deleteLoading}
                className="px-4 py-1.5 text-[12px] font-semibold rounded-lg border border-slate-200 hover:bg-slate-50 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={confirmDelete}
                disabled={deleteLoading}
                className="flex items-center gap-1.5 px-4 py-1.5 text-[12px] font-semibold rounded-lg bg-red-500 hover:bg-red-600 text-white disabled:opacity-60 transition-colors"
              >
                {deleteLoading ? <Loader2 size={13} className="animate-spin" /> : null}
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useRef, useCallback } from 'react'
import { createPortal } from 'react-dom'
import { useLocation, useNavigate } from 'react-router-dom'
import api from '../services/api'
import { ChevronRight, Plus, Trash2, Send, X, RefreshCw, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import { SpinnerLoader } from '../components/LocalLoader'

/* ─── helpers ─────────────────────────────────────────────────────────────── */
const today = new Date().toISOString().split('T')[0]

const getFinancialYear = () => {
  const now = new Date()
  const month = now.getMonth() + 1
  const year = now.getFullYear()
  const y1 = month >= 4 ? year : year - 1
  return `${String(y1).slice(-2)}-${String(y1 + 1).slice(-2)}`
}

const PLACEHOLDER_QUOT_NO = `${getFinancialYear()}/Q-----`

const DEFAULT_PAYMENT_TERMS =
  '1. Add GST 18% Applicable Extra\n2. Product: Raw Materials,Machining & Hardening all are at your scope\n3.Inspection: At Your End\n4.If Any dimension MisMatch Or Rejection Found By Quality Control,debit Will Be Raised Against the Invoice and Material sent Back'

const TAX_PERCENT_OPTIONS = [ '18', '28']

const emptyItem = () => ({
  itemId: null, partNo: '', itemName: '', description: '',
  hsnCode: '', uom: '', qty: '', unitPrice: '', amount: '',
})

const emptyForm = () => ({
  customerId: '', customerName: '', customerAddress: '', contactPerson: '',
  contactNumber: '', gstNumber: '', customerRef: '',
  currencyCode: 'INR', exchangeRate: '0',
  modelRef: '', taxType: '', quotationType: '',
  quotationNo: PLACEHOLDER_QUOT_NO, financialYear: getFinancialYear(),
  quotationDate: today, validUntil: '', revisionNo: '0',
  discountType: 'Dis_Per', showTotalsGrid: false,
})

/* ─── style helpers ────────────────────────────────────────────────────────── */
const inp = (err = '') =>
  `w-full border rounded px-2 py-1 text-[12.5px] focus:outline-none focus:ring-1 transition-colors bg-white ${err ? 'border-red-400 focus:ring-red-300' : 'border-slate-300 focus:ring-[#0097A7] focus:border-[#0097A7]'}`
const lbl = 'text-[12px] font-semibold text-slate-600 whitespace-nowrap'

/* ─── component ────────────────────────────────────────────────────────────── */
export default function QuotationEntry() {
  const toast = useToast()
  const location = useLocation()
  const navigate = useNavigate()
  const pageData = location.state || null
  // 'revision' = Accepted quotation → new revision (POST)
  // 'edit'     = non-Accepted quotation → update in-place (PUT)
  const isRevisionMode = pageData?.mode === 'revision'

  /* master data */
  const [customers, setCustomers]     = useState([])
  const [currencies, setCurrencies]   = useState([])
  const [modelOptions, setModelOptions]   = useState([])
  const [taxTypeOptions, setTaxTypeOptions]         = useState([])
  const [quotationTypeOptions, setQuotationTypeOptions] = useState([])
  const [masterLoading, setMasterLoading]  = useState(true)

  /* form */
  const [form, setForm]     = useState(emptyForm)
  const [items, setItems]   = useState([emptyItem()])
  const [specialDiscount, setSpecialDiscount]       = useState('')
  const [freightAmount, setFreightAmount]           = useState('')
  const [taxPercent, setTaxPercent]                 = useState('18')
  const [packingForwarding, setPackingForwarding]   = useState('')
  const [paymentTerms, setPaymentTerms]             = useState(DEFAULT_PAYMENT_TERMS)
  const [uploadFile, setUploadFile]                 = useState(null)
  const [editModeId, setEditModeId]                 = useState(null)

  /* part autocomplete */
  const [partSuggestions, setPartSuggestions] = useState({})   // { rowIdx: Item[] }
  const [partLoading, setPartLoading]         = useState({})   // { rowIdx: bool }
  const searchTimers  = useRef({})
  const partInputRefs = useRef({})
  const editApplied   = useRef(false)

  /* submit */
  const [submitLoading, setSubmitLoading] = useState(false)

  const setField = (k, v) => setForm(f => ({ ...f, [k]: v }))

  /* ── load master data on mount ─────────────────────────────────────────── */
  useEffect(() => {
    const fetchAll = async () => {
      setMasterLoading(true)
      try {
        const [custRes, currRes, modelRes, taxRes, quotTypeRes, nextNoRes] = await Promise.allSettled([
          api.get('/api/customer-master', { skipGlobalLoader: true }),
          api.get('/api/reference-master/Currency', { skipGlobalLoader: true }),
          api.get('/api/reference-master/Vehicle_Type', { skipGlobalLoader: true }),
          api.get('/api/reference-master/Tax%20Type', { skipGlobalLoader: true }),
          api.get('/api/reference-master/Quotation_Type', { skipGlobalLoader: true }),
          api.get('/api/quotation-master/next-no', { skipGlobalLoader: true }),
        ])

        if (custRes.status === 'fulfilled') {
          setCustomers(custRes.value.data?.data || [])
        } else {
          console.error('[QuotationEntry] customer-master fetch error:', custRes.reason)
        }

        if (currRes.status === 'fulfilled') {
          setCurrencies(currRes.value.data?.data || [])
        } else {
          console.error('[QuotationEntry] Currency reference fetch error:', currRes.reason)
        }

        if (modelRes.status === 'fulfilled') {
          setModelOptions(modelRes.value.data?.data || [])
        } else {
          console.error('[QuotationEntry] Vehicle_Type reference fetch error:', modelRes.reason)
        }

        if (taxRes.status === 'fulfilled') {
          setTaxTypeOptions(taxRes.value.data?.data || [])
        } else {
          console.error('[QuotationEntry] Tax_Type reference fetch error:', taxRes.reason)
        }

        if (quotTypeRes.status === 'fulfilled') {
          setQuotationTypeOptions(quotTypeRes.value.data?.data || [])
        } else {
          console.error('[QuotationEntry] Quotation_type reference fetch error:', quotTypeRes.reason)
        }

        if (nextNoRes.status === 'fulfilled') {
          const { quotationNo, financialYear } = nextNoRes.value.data
          setForm(f => ({ ...f, quotationNo, financialYear }))
        } else {
          console.error('[QuotationEntry] next-no fetch error:', nextNoRes.reason)
        }
      } finally {
        setMasterLoading(false)
      }
    }
    fetchAll()
  }, [])

  /* ── pre-fill from revision/edit (triggered from QuotationDetails) ── */
  useEffect(() => {
    const ed = pageData?.editData
    if (!ed || masterLoading || customers.length === 0 || editApplied.current) return
    editApplied.current = true

    const c = customers.find(x => x.id === ed.customerId)
    const addrParts = c ? [c.address, c.address2, c.address3, c.address4, c.city, c.state, c.pinCode].filter(Boolean) : []

    const itemRows = ed.details?.length > 0
      ? ed.details.map(d => ({
          itemId:      d.itemId      ?? null,
          partNo:      d.partNo      ?? '',
          itemName:    d.itemName    ?? '',
          description: d.description ?? '',
          hsnCode:     d.hsnCode     ?? '',
          uom:         d.uom         ?? '',
          qty:         String(d.qty       ?? ''),
          unitPrice:   String(d.unitPrice ?? ''),
          amount:      String(d.amount    ?? ''),
        }))
      : [emptyItem()]

    const commonFields = {
      customerId:       String(ed.customerId ?? ''),
      customerName:     c?.customerName    ?? '',
      customerAddress:  addrParts.join(', '),
      customerRef:      ed.customerRef     ?? '',
      contactPerson:    c?.contactPerson   ?? '',
      contactNumber:    c?.mobile ?? c?.phone ?? '',
      gstNumber:        c?.gstNo           ?? '',
      currencyCode:     ed.currencyCode    ?? 'INR',
      exchangeRate:     String(ed.exchangeRate ?? 1),
      modelRef:         ed.modelRef        ?? '',
      taxType:          ed.taxType         ?? '',
      quotationDate:    ed.quotationDate   ? ed.quotationDate.slice(0, 10) : today,
      validUntil:       ed.validUntil      ? ed.validUntil.slice(0, 10)   : '',
      quotationType:    ed.quotationType   ?? '',
      discountType:     ed.discountType    ?? 'Dis_Per',
      showTotalsGrid:   Boolean(ed.showTotalsGrid),
    }

    // Both Case 1 and Case 2 update the existing quotation (PUT) -> Keep the SAME quotationNo
    setEditModeId(ed.id)

    setForm(f => ({
      ...f,
      ...commonFields,
      quotationNo:   ed.quotationNo   ?? f.quotationNo,
      financialYear: ed.financialYear ?? f.financialYear,
      // Case 2 (Accepted) -> bump revision. Case 1 (Draft) -> keep same revision.
      revisionNo:    isRevisionMode
                       ? String((parseInt(ed.revisionNo) || 0) + 1)
                       : String(ed.revisionNo ?? 0),
    }))

    setItems(itemRows)
    setSpecialDiscount(String(ed.specialDiscount   ?? ''))
    setFreightAmount(String(ed.freightAmount        ?? ''))
    setTaxPercent(String(ed.taxPercent              ?? '18'))
    setPackingForwarding(String(ed.packingForwarding ?? ''))
    setPaymentTerms(ed.paymentTerms || DEFAULT_PAYMENT_TERMS)
  }, [pageData, masterLoading, customers])

  /* ── customer select → auto-fill ───────────────────────────────────────── */
  const handleCustomerChange = useCallback((id) => {
    if (!id) {
      setForm(f => ({
        ...f,
        customerId: '', customerName: '', customerAddress: '',
        contactPerson: '', contactNumber: '', gstNumber: '', customerRef: '',
      }))
      return
    }
    const c = customers.find(x => String(x.id) === String(id))
    if (!c) return
    const addrParts = [c.address, c.address2, c.address3, c.address4, c.city, c.state, c.pinCode]
      .filter(Boolean)
    setForm(f => ({
      ...f,
      customerId:      String(c.id),
      customerName:    c.customerName || '',
      customerAddress: addrParts.join(', '),
      customerRef:     c.cCode || '',
      contactPerson:   c.contactPerson || '',
      contactNumber:   c.mobile || c.phone || '',
      gstNumber:       c.gstNo || '',
    }))
  }, [customers])

  /* ── item row helpers ──────────────────────────────────────────────────── */
  const setItemField = (idx, k, v) => {
    setItems(rows => rows.map((r, i) => {
      if (i !== idx) return r
      const updated = { ...r, [k]: v }
      if (k === 'qty' || k === 'unitPrice') {
        const q = parseFloat(k === 'qty' ? v : updated.qty) || 0
        const p = parseFloat(k === 'unitPrice' ? v : updated.unitPrice) || 0
        updated.amount = (q * p).toFixed(2)
      }
      return updated
    }))
  }

  const addRow    = () => setItems(r => [...r, emptyItem()])
  const removeRow = (idx) => setItems(r => r.filter((_, i) => i !== idx))

  /* ── part no autocomplete ──────────────────────────────────────────────── */
  const handlePartSearch = (idx, value) => {
    setItemField(idx, 'partNo', value)

    if (searchTimers.current[idx]) clearTimeout(searchTimers.current[idx])

    if (!value || value.length < 1) {
      setPartSuggestions(prev => ({ ...prev, [idx]: [] }))
      return
    }

    setPartLoading(prev => ({ ...prev, [idx]: true }))
    searchTimers.current[idx] = setTimeout(async () => {
      try {
        const res = await api.get('/api/item-master', {
          params: { search: value, limit: 20, page: 1 },
          skipGlobalLoader: true,
        })
        const suggestions = res.data?.data || []
        setPartSuggestions(prev => ({ ...prev, [idx]: suggestions }))
        console.log(`[QuotationEntry] part search "${value}" → ${suggestions.length} result(s)`)
      } catch (err) {
        console.error(`[QuotationEntry] part search error (row ${idx}):`, err)
        setPartSuggestions(prev => ({ ...prev, [idx]: [] }))
      } finally {
        setPartLoading(prev => ({ ...prev, [idx]: false }))
      }
    }, 300)
  }

  const selectPartItem = (idx, item) => {
    const unitPrice = item.rate ?? 0
    setItems(rows => rows.map((r, i) => {
      if (i !== idx) return r
      const qty = parseFloat(r.qty) || 0
      return {
        ...r,
        itemId:      item.id,
        partNo:      item.partNo      || '',
        itemName:    item.partName    || '',
        description: item.description || '',
        hsnCode:     item.hsnCode     || '',
        uom:         item.uom,                         // no unit name from API; keep existing
        unitPrice:   String(unitPrice),
        amount:      (qty * unitPrice).toFixed(2),
      }
    }))
    setPartSuggestions(prev => ({ ...prev, [idx]: [] }))
  }

  const clearPartSuggestions = (idx) => {
    setTimeout(() => setPartSuggestions(prev => ({ ...prev, [idx]: [] })), 200)
  }

  /* ── totals ─────────────────────────────────────────────────────────────── */
  const subTotal  = items.reduce((s, r) => s + (parseFloat(r.amount) || 0), 0)
  const specDisc  = parseFloat(specialDiscount) || 0
  const freight   = parseFloat(freightAmount)   || 0
  const pack      = parseFloat(packingForwarding) || 0
  const afterDisc = subTotal - specDisc
  const taxAmt    = afterDisc * (parseFloat(taxPercent) || 0) / 100
  const totalAmt  = afterDisc + taxAmt + freight + pack

  /* ── submit ─────────────────────────────────────────────────────────────── */
  const handleSubmit = async () => {
    if (!form.customerId) {
      toast.error('Please select a customer')
      return
    }
    if (!form.quotationNo || form.quotationNo.includes('-')) {
      // allow submit even with placeholder; backend validates
    }

    setSubmitLoading(true)
    try {
      const payload = {
        quotationNo:      form.quotationNo,
        financialYear:    form.financialYear,
        customerId:       form.customerId,
        customerRef:      form.customerRef,
        currencyCode:     form.currencyCode,
        exchangeRate:     form.exchangeRate,
        modelRef:         form.modelRef,
        taxType:          form.taxType,
        quotationDate:    form.quotationDate,
        validUntil:       form.validUntil || null,
        revisionNo:       form.revisionNo,
        quotationType:    form.quotationType,
        discountType:     form.discountType,
        showTotalsGrid:   form.showTotalsGrid,
        specialDiscount,
        freightAmount,
        taxPercent,
        packingForwarding,
        subTotal:         subTotal.toFixed(2),
        taxAmount:        taxAmt.toFixed(2),
        totalAmount:      totalAmt.toFixed(2),
        paymentTerms,
        status:           'Draft',
        createdBy:        'ADMIN',
        items:            items.filter(r => r.partNo || r.itemName),
      }

      let newId = null
      if (editModeId) {
        const res = await api.put(`/api/quotation-master/${editModeId}`, payload, { loadingMessage: 'Updating quotation...' })
        newId = res.data?.data?.id || editModeId
      } else {
        const res = await api.post('/api/quotation-master', payload, { loadingMessage: 'Saving quotation...' })
        newId = res.data?.data?.id
      }
      
      if (uploadFile && newId) {
        const formData = new FormData()
        formData.append('document', uploadFile)
        await api.post(`/api/quotation-master/${newId}/upload`, formData, {
          headers: { 'Content-Type': 'multipart/form-data' },
          loadingMessage: 'Uploading document...'
        })
      }

      toast.success(editModeId ? 'Quotation updated successfully!' : 'Quotation saved successfully!')

      /* fetch next quotation number for a fresh entry */
      try {
        const res = await api.get('/api/quotation-master/next-no', { skipGlobalLoader: true })
        const { quotationNo, financialYear } = res.data
        setForm({ ...emptyForm(), quotationNo, financialYear })
      } catch (err) {
        console.error('[QuotationEntry] next-no refresh error:', err)
        setForm(emptyForm())
      }
      setItems([emptyItem()])
      setSpecialDiscount('')
      setFreightAmount('')
      setPackingForwarding('')
      setPaymentTerms(DEFAULT_PAYMENT_TERMS)
      setEditModeId(null)
    } catch (err) {
      const msg = err.response?.data?.message || err.message
      console.error('[QuotationEntry] submit error:', err)
      toast.error(`Save failed: ${msg}`)
    } finally {
      setSubmitLoading(false)
    }
  }

  /* ── cancel / reset ────────────────────────────────────────────────────── */
  const handleCancel = async () => {
    try {
      const res = await api.get('/api/quotation-master/next-no', { skipGlobalLoader: true })
      const { quotationNo, financialYear } = res.data
      setForm({ ...emptyForm(), quotationNo, financialYear })
    } catch (err) {
      console.error('[QuotationEntry] next-no refresh error:', err)
      setForm(emptyForm())
    }
    setItems([emptyItem()])
    setSpecialDiscount('')
    setFreightAmount('')
    setPackingForwarding('')
    setPaymentTerms(DEFAULT_PAYMENT_TERMS)
    setUploadFile(null)
    setPartSuggestions({})
    setEditModeId(null)
  }

  /* ── render ─────────────────────────────────────────────────────────────── */
  return (
    <div className="p-4 space-y-4 w-full min-w-0 overflow-x-hidden">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-[12px] text-slate-400">
        <span
          onClick={() => navigate('/quotation/quotation-details')}
          className="hover:text-[#0097A7] cursor-pointer"
        >Quotation Details</span>
        <ChevronRight className="w-3 h-3" />
        <span className="text-[#0097A7] font-semibold">
          {isRevisionMode ? 'New Revision' : editModeId ? 'Edit Quotation' : 'Quotation Entry'}
        </span>
      </div>

      {/* Main form card */}
      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden relative">

        {/* Master-data loading overlay */}
        {masterLoading && (
          <div className="absolute inset-0 z-20 bg-white/75 flex items-center justify-center rounded">
            <SpinnerLoader size={20} message="Loading form data…" />
          </div>
        )}

        {/* Header bar */}
        <div className="bg-[--color-main] px-4 py-2.5 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <h2 className="text-white font-semibold text-[14px]">
              {isRevisionMode ? 'New Revision' : editModeId ? 'Edit Quotation' : 'Quotation Entry'}
            </h2>
            {isRevisionMode && (
              <span className="px-2 py-0.5 bg-blue-400 text-blue-900 text-[10px] font-bold rounded-full uppercase tracking-wide">
                Revision #{form.revisionNo} — {form.quotationNo}
              </span>
            )}
            {editModeId && !isRevisionMode && (
              <span className="px-2 py-0.5 bg-amber-400 text-amber-900 text-[10px] font-bold rounded-full uppercase tracking-wide">
                Editing #{form.quotationNo}
              </span>
            )}
          </div>
          <button onClick={handleCancel} className="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-[12px] rounded transition-colors">
            {editModeId || isRevisionMode ? 'Cancel' : 'Close'}
          </button>
        </div>

        <div className="p-4 space-y-3">
          {/* ── 3-column header grid ── */}
          <div className="grid grid-cols-3 gap-4">

            {/* Column 1 */}
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Customer Name:</label>
                <select
                  value={form.customerId}
                  onChange={e => handleCustomerChange(e.target.value)}
                  className={inp()}
                  disabled={masterLoading}
                >
                  <option value="">Select Customer</option>
                  {customers.map(c => (
                    <option key={c.id} value={c.id}>{c.customerName}</option>
                  ))}
                </select>
              </div>
              <div className="flex items-start gap-2">
                <label className={`${lbl} w-[130px] shrink-0 pt-1`}>Customer Address:</label>
                <textarea
                  rows={3}
                  value={form.customerAddress}
                  onChange={e => setField('customerAddress', e.target.value)}
                  className={inp()}
                />
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Customer Ref. No:</label>
                <input
                  value={form.customerRef}
                  onChange={e => setField('customerRef', e.target.value)}
                  className={inp()}
                />
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Currency:</label>
                <select
                  value={form.currencyCode}
                  onChange={e => setField('currencyCode', e.target.value)}
                  className={inp()}
                  disabled={masterLoading}
                >
                  {currencies.length > 0
                    ? currencies.map(c => (
                        <option key={c.id} value={c.description}>{c.description}</option>
                      ))
                    : ['INR', 'USD', 'EUR', 'GBP'].map(c => (
                        <option key={c} value={c}>{c}</option>
                      ))
                  }
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Show Totals Grid:</label>
                <input
                  type="checkbox"
                  checked={form.showTotalsGrid}
                  onChange={e => setField('showTotalsGrid', e.target.checked)}
                  className="w-4 h-4 accent-[#0097A7]"
                />
                <span className="text-[12px] text-slate-500">Show Totals Grid</span>
              </div>
            </div>

            {/* Column 2 */}
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Contact Person:</label>
                <input
                  value={form.contactPerson}
                  onChange={e => setField('contactPerson', e.target.value)}
                  className={inp()}
                />
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Contact Number:</label>
                <input
                  value={form.contactNumber}
                  onChange={e => setField('contactNumber', e.target.value)}
                  className={inp()}
                />
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>GST Number:</label>
                <input
                  value={form.gstNumber}
                  onChange={e => setField('gstNumber', e.target.value)}
                  className={inp()}
                />
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Validity Until:</label>
                <input
                  type="date"
                  value={form.validUntil}
                  onChange={e => setField('validUntil', e.target.value)}
                  className={inp()}
                />
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Model:</label>
                <select
                  value={form.modelRef}
                  onChange={e => setField('modelRef', e.target.value)}
                  className={inp()}
                  disabled={masterLoading}
                >
                  <option value="">Select Model</option>
                  {modelOptions.length > 0
                    ? modelOptions.map(m => (
                        <option key={m.id} value={m.description}>{m.description}</option>
                      ))
                    : ['V10', 'V20', 'V30', 'Consumables', 'VELSON TYPE', 'HM Series'].map(m => (
                        <option key={m} value={m}>{m}</option>
                      ))
                  }
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Ex.Rate:</label>
                <input
                  value={form.exchangeRate}
                  onChange={e => setField('exchangeRate', e.target.value)}
                  className={inp()}
                />
              </div>
            </div>

            {/* Column 3 */}
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Quotation Number:</label>
                <input
                  value={form.quotationNo}
                  readOnly
                  className={`${inp()} bg-slate-50`}
                />
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Quotation Date:</label>
                <input
                  type="date"
                  value={form.quotationDate}
                  onChange={e => setField('quotationDate', e.target.value)}
                  className={inp()}
                />
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Revision Number:</label>
                <input
                  value={form.revisionNo}
                  readOnly
                  className="border border-slate-300 rounded px-2 py-1 text-[12.5px] bg-slate-50 text-center w-16 focus:outline-none"
                />
                <button
                  onClick={() => setField('revisionNo', String(parseInt(form.revisionNo || '0') + 1))}
                  className="flex items-center gap-1 px-3 py-1 bg-[#0097A7] hover:bg-[#007a87] text-white text-[11px] font-semibold rounded shadow-sm transition-colors whitespace-nowrap"
                >
                  <RefreshCw className="w-3 h-3" /> Revision
                </button>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Quotation Type:</label>
                <select
                  value={form.quotationType}
                  onChange={e => setField('quotationType', e.target.value)}
                  className={inp()}
                  disabled={masterLoading}
                >
                  <option value="">Select Type</option>
                  {quotationTypeOptions.length > 0
                    ? quotationTypeOptions.map(t => (
                        <option key={t.id} value={t.description}>{t.description}</option>
                      ))
                    : ['Supply', 'Service', 'Supply & Service'].map(t => (
                        <option key={t} value={t}>{t}</option>
                      ))
                  }
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Tax Type:</label>
                <select
                  value={form.taxType}
                  onChange={e => {
                    const val = e.target.value
                    setField('taxType', val)
                    const u = val.toUpperCase()
                    if (u.includes('LOCAL'))      setTaxPercent('18')
                    else if (u.includes('INTER')) setTaxPercent('28')
                  }}
                  className={inp()}
                  disabled={masterLoading}
                >
                  <option value="">Select Tax Type</option>
                  {taxTypeOptions.length > 0
                    ? taxTypeOptions.map(t => (
                        <option key={t.id} value={t.description}>{t.description}</option>
                      ))
                    : ['GST', 'IGST', 'No Tax'].map(t => (
                        <option key={t} value={t}>{t}</option>
                      ))
                  }
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-[130px] shrink-0`}>Discount Type:</label>
                <div className="flex items-center gap-3">
                  {['Dis_Per', 'Dis_Amt'].map(v => (
                    <label key={v} className="flex items-center gap-1 text-[12.5px] cursor-pointer">
                      <input
                        type="radio" name="discountType" value={v}
                        checked={form.discountType === v}
                        onChange={() => setField('discountType', v)}
                        className="accent-[#0097A7]"
                      />
                      {v}
                    </label>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* ── Action buttons ── */}
        <div className="flex flex-wrap items-center justify-end gap-3 px-4 pb-4">
          <button
            onClick={addRow}
            className="flex items-center gap-1.5 px-4 py-2 bg-[#27ae60] hover:bg-[#229954] text-white text-[12.5px] font-medium rounded shadow-sm transition-colors"
          >
            <Plus className="w-4 h-4" /> Add Row
          </button>
          <button
            onClick={() => { if (items.length > 1) setItems(r => r.slice(0, -1)) }}
            className="flex items-center gap-1.5 px-4 py-2 bg-slate-700 hover:bg-slate-800 text-white text-[12.5px] font-medium rounded shadow-sm transition-colors"
          >
            <Trash2 className="w-4 h-4" /> Delete Row
          </button>
          <button
            onClick={handleCancel}
            className="flex items-center gap-1.5 px-4 py-2 bg-red-500 hover:bg-red-600 text-white text-[12.5px] font-medium rounded shadow-sm transition-colors"
          >
            <X className="w-4 h-4" /> Cancel
          </button>
          <button
            onClick={handleSubmit}
            disabled={submitLoading}
            className="flex items-center gap-1.5 px-5 py-2 bg-[#0097A7] hover:bg-[#007a87] disabled:opacity-60 text-white text-[12.5px] font-medium rounded shadow-sm transition-colors"
          >
            {submitLoading
              ? <><Loader2 className="w-4 h-4 animate-spin" /> {editModeId ? 'Updating…' : 'Saving…'}</>
              : <><Send className="w-4 h-4" /> {editModeId ? 'Update' : isRevisionMode ? 'Save Revision' : 'Submit'}</>
            }
          </button>
        </div>

        {/* ── Items grid ── */}
        <div className="p-2">
          <div className="bg-slate-700 px-3 py-1.5 rounded-t">
            <h3 className="text-white text-[13px] font-semibold">Items</h3>
          </div>
          <div className="overflow-x-auto border border-slate-200 rounded-b">
            <table className="min-w-full text-[12.5px]" style={{ overflow: 'visible' }}>
              <thead>
                <tr className="bg-slate-50 border-b border-slate-200">
                  <th className="px-2 py-1.5 text-center font-bold text-slate-600 text-[11px] uppercase w-8">
                    <input type="checkbox" className="accent-[#0097A7]" />
                  </th>
                  <th className="px-2 py-1.5 text-center font-bold text-slate-600 text-[11px] uppercase w-8">#</th>
                  {['Part No', 'Item Name', 'Description', 'HSN Code', 'UOM', 'Qty', 'Unit Price', 'Amount', 'Action'].map(h => (
                    <th key={h} className="px-2 py-1.5 text-center font-bold text-slate-600 text-[11px] uppercase whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {items.map((row, idx) => (
                  <tr key={idx} className={`border-b border-slate-100 ${idx % 2 === 1 ? 'bg-slate-50/50' : ''}`}
                    style={{ overflow: 'visible' }}>
                    <td className="px-2 py-1 text-center">
                      <input type="checkbox" className="accent-[#0097A7]" />
                    </td>
                    <td className="px-2 py-1 text-center text-slate-500">{idx + 1}</td>

                    {/* ── Part No with autocomplete ── */}
                    <td className="px-1 py-1" style={{ minWidth: 140 }}>
                      <div className="relative">
                        <input
                          ref={el => { partInputRefs.current[idx] = el }}
                          value={row.partNo}
                          onChange={e => handlePartSearch(idx, e.target.value)}
                          onBlur={() => clearPartSuggestions(idx)}
                          placeholder="Type to search…"
                          className={inp()}
                        />
                        {partLoading[idx] && (
                          <Loader2 className="absolute right-2 top-1/2 -translate-y-1/2 w-3 h-3 animate-spin text-slate-400" />
                        )}
                        {partSuggestions[idx]?.length > 0 && partInputRefs.current[idx] &&
                          createPortal(
                            <div
                              style={{
                                position: 'fixed',
                                top:  partInputRefs.current[idx].getBoundingClientRect().bottom,
                                left: partInputRefs.current[idx].getBoundingClientRect().left,
                                width: 256,
                                zIndex: 9999,
                              }}
                              className="bg-white border border-slate-200 rounded shadow-lg max-h-44 overflow-y-auto"
                            >
                              {partSuggestions[idx].map(item => (
                                <div
                                  key={item.id}
                                  onMouseDown={() => selectPartItem(idx, item)}
                                  className="px-2 py-1.5 text-[12px] hover:bg-[#0097A7] hover:text-white cursor-pointer border-b border-slate-100 last:border-0"
                                >
                                  <span className="font-semibold">{item.partNo}</span>
                                  {item.partName && (
                                    <span className="ml-1">— {item.partName}</span>
                                  )}
                                </div>
                              ))}
                            </div>,
                            document.body
                          )
                        }
                      </div>
                    </td>

                    <td className="px-1 py-1">
                      <input value={row.itemName} onChange={e => setItemField(idx, 'itemName', e.target.value)} className={inp()} />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.description} onChange={e => setItemField(idx, 'description', e.target.value)} className={inp()} />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.hsnCode} onChange={e => setItemField(idx, 'hsnCode', e.target.value)} className={inp()} />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.uom} onChange={e => setItemField(idx, 'uom', e.target.value)} className={inp()} />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.qty} onChange={e => setItemField(idx, 'qty', e.target.value)} className={inp()} />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.unitPrice} onChange={e => setItemField(idx, 'unitPrice', e.target.value)} className={inp()} />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.amount} readOnly className={`${inp()} bg-slate-50`} />
                    </td>
                    <td className="px-2 py-1 text-center">
                      <button
                        onClick={() => removeRow(idx)}
                        className="px-2 py-1 bg-red-500 hover:bg-red-600 text-white text-[11px] rounded transition-colors"
                      >
                        Remove
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* ── Bottom section ── */}
        <div className="grid grid-cols-2 gap-6 p-4">
          {/* Left: upload + payment terms */}
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <label className={`${lbl} w-36 shrink-0`}>Upload Document:</label>
              <div className="flex-1 flex gap-2 items-center">
                <input
                  type="file"
                  onChange={e => setUploadFile(e.target.files[0])}
                  className="text-[12px] text-slate-600 border border-slate-300 rounded px-2 py-1 w-full"
                />
                {uploadFile ? (
                  <button
                    type="button"
                    onClick={() => window.open(URL.createObjectURL(uploadFile), '_blank')}
                    className="px-3 py-1 bg-[#0097A7] text-white text-[11px] rounded hover:bg-[#007a87] transition-colors whitespace-nowrap shadow-sm"
                  >
                    Preview
                  </button>
                ) : (
                  pageData?.editData?.documentMimeType && (
                    <button
                      type="button"
                      onClick={() => window.open(`${api.defaults.baseURL || ''}/api/quotation-master/${pageData.editData.id}/download-document`, '_blank')}
                      className="px-3 py-1 bg-[#0097A7] text-white text-[11px] rounded hover:bg-[#007a87] transition-colors whitespace-nowrap shadow-sm"
                    >
                      View Attached
                    </button>
                  )
                )}
              </div>
            </div>
            <div className="flex items-start gap-2">
              <label className={`${lbl} w-36 shrink-0 pt-1`}>Payment Terms:</label>
              <textarea
                rows={5}
                value={paymentTerms}
                onChange={e => setPaymentTerms(e.target.value)}
                className="flex-1 border border-slate-300 rounded px-2 py-1 text-[12px] focus:outline-none focus:ring-1 focus:ring-[#0097A7] resize-none"
              />
            </div>
          </div>

          {/* Right: totals */}
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <label className={`${lbl} w-36 shrink-0`}>Special Discount:</label>
              <input value={specialDiscount} onChange={e => setSpecialDiscount(e.target.value)} className={`${inp()} !w-[150px] flex-none`} />
              <span className="text-[12px] text-slate-500 ml-auto">Sub Total:</span>
              <span className="text-[13px] font-semibold text-slate-700 w-24 text-right">{subTotal.toFixed(2)}</span>
            </div>
            <div className="flex items-center gap-2">
              <label className={`${lbl} w-36 shrink-0`}>Freight Amount:</label>
              <input value={freightAmount} onChange={e => setFreightAmount(e.target.value)} className={`${inp()} !w-[150px] flex-none`} />
              <span className="text-[12px] text-slate-500 ml-auto">After Discount:</span>
              <span className="text-[13px] font-semibold text-slate-700 w-24 text-right">{afterDisc.toFixed(2)}</span>
            </div>
            <div className="flex items-center gap-2">
              <label className={`${lbl} w-36 shrink-0`}>Tax (%):</label>
              <select value={taxPercent} onChange={e => setTaxPercent(e.target.value)} className={`${inp()} !w-[150px] flex-none`}>
                {TAX_PERCENT_OPTIONS.map(t => <option key={t}>{t}</option>)}
              </select>
              <span className="text-[12px] text-slate-500 ml-auto">Packing &amp; Forwarding:</span>
              <input value={packingForwarding} onChange={e => setPackingForwarding(e.target.value)} className={`${inp()} !w-[100px] flex-none`} />
            </div>
            <div className="flex items-center gap-2 justify-end">
              <span className="text-[12px] text-slate-500">Total Amount:</span>
              <span className="text-[14px] font-bold text-[#0097A7] w-24 text-right">{totalAmt.toFixed(2)}</span>
            </div>
          </div>
        </div>

        {/* ── GST Summary ── */}
        {(() => {
          const isInter = form.taxType?.toUpperCase().includes('INTER')
          const gst  = isInter ? 0 : taxAmt
          const igst  = isInter ? taxAmt : 0
          const rows = [
            ['GST Amount', gst.toFixed(2)],
            ['IGST Amount', igst.toFixed(2)],
            ['G.T. Before RoundOff', totalAmt.toFixed(2)],
            ['Grand Total', Math.round(totalAmt)],
          ]
          return (
            <div className="grid grid-cols-5 gap-3 border-t border-slate-200 p-3 mt-2">
              {rows.map(([label, val]) => (
                <div key={label} className="flex flex-col">
                  <span className="text-[11px] font-semibold text-slate-500">{label}</span>
                  <span className="text-[13px] font-bold text-slate-800">{val}</span>
                </div>
              ))}
            </div>
          )
        })()}
      </div>
    </div>
  )
}

import { useState } from 'react'
import {
  ChevronRight, X, Search, Download, FileSpreadsheet, FileJson, Filter, Settings, LayoutGrid, Trash2, ShieldAlert
} from 'lucide-react'

// ── Shared UI primitives (Consistent with design system) ──
const Label = ({ children }) => (
  <label className="block text-[11px] font-semibold text-slate-600 mb-1 uppercase tracking-wider whitespace-nowrap">
    {children}
  </label>
)

const Input = ({ type = 'text', value, onChange, className = "" }) => (
  <input
    type={type}
    value={value}
    onChange={onChange}
    className={`px-3 py-[6px] text-sm border border-slate-200 rounded-lg bg-white text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#0097A7]/25 focus:border-[#0097A7] transition-all duration-200 hover:border-slate-300 ${className}`}
  />
)

export default function RawMaterialIssuedDetails() {
  const [fromDate, setFromDate] = useState('2026-04-15')
  const [toDate, setToDate] = useState('2026-04-15')

  return (
    <div className="bg-[#f4f6f8] min-h-full">
      <div className="px-6 py-6">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-[12px] text-slate-400 mb-5">
          {/* <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Dashboard</span> */}
          {/* <ChevronRight className="w-3 h-3" /> */}
          <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Production</span>
          <ChevronRight className="w-3 h-3" />
          <span className="text-[#0097A7] font-semibold uppercase tracking-widest">Rawmaterial Issued Details</span>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[850px]">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-4 py-2.5">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-red-700 rounded-sm" />
              <h2 className="text-[13px] font-bold text-slate-700 uppercase tracking-tight">Rawmaterial Issued Details</h2>
            </div>
            <div className="flex items-center gap-3">
              <button className="flex items-center gap-1.5 px-4 py-1.5 bg-white hover:bg-rose-50 text-rose-600 text-[11px] font-bold rounded-lg border border-slate-200 transition-all shadow-sm group">
                <Trash2 size={16} className="group-hover:scale-110 transition-transform" /> Delete
              </button>
              <button className="flex items-center gap-1.5 px-3 py-1.5 bg-rose-500 hover:bg-rose-600 text-white text-[11px] font-bold rounded-lg transition-all shadow-sm">
                <X size={18} strokeWidth={2.5} /> Close
              </button>
            </div>
          </div>

          <div className="p-5 flex-1 flex flex-col">
            {/* Filter Bar */}
            <div className="flex items-center gap-8 mb-6 bg-slate-50/50 p-3 rounded-xl border border-slate-100">
              <div className="flex items-center gap-3">
                <Label>From Date :</Label>
                <Input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className="w-40" />
              </div>
              <div className="flex items-center gap-3">
                <Label>To Date :</Label>
                <Input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className="w-40" />
              </div>

              <button className="flex items-center gap-2 px-6 py-1.5 bg-white hover:bg-slate-50 text-slate-700 text-[12px] font-bold rounded-lg border border-slate-300 transition-all shadow-sm active:scale-95 group">
                <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse" />
                <Search size={16} className="text-[#0097A7] group-hover:scale-110 transition-transform" />
                Search
              </button>
            </div>

            {/* Toolbar */}
            <div className="flex items-center justify-end gap-4 mb-4">
              <div className="flex items-center gap-1 bg-slate-100 px-2 py-1 rounded-md">
                <span className="text-[11px] font-bold text-slate-500 uppercase mr-2">LS</span>
                <input className="w-8 bg-transparent text-center text-sm font-bold border-b border-slate-300 focus:outline-none" value="1" readOnly />
              </div>
              <div className="flex items-center gap-2 border-l border-slate-200 pl-4">
                {[
                  { icon: <Download size={14} />, label: 'Dos' },
                  { icon: <FileSpreadsheet size={14} />, label: 'Excel' },
                  { icon: <FileJson size={14} />, label: 'Pdf' },
                  { icon: <Filter size={14} />, label: 'Filter' },
                  { icon: <Settings size={14} />, label: 'Setting' },
                ].map(tool => (
                  <button key={tool.label} className="flex items-center gap-1 px-2 py-1 text-slate-400 hover:text-[#0097A7] transition-colors group">
                    {tool.icon}
                    <span className="text-[11px] font-bold uppercase group-hover:text-slate-600">{tool.label}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Table */}
            <div className="flex-1 border border-slate-200 rounded-xl overflow-hidden overflow-x-auto shadow-sm">
              <table className="w-full text-left border-collapse min-w-[1600px]">
                <thead className="bg-[#fcfdfe] text-[10.5px] uppercase text-slate-500 font-bold border-b border-slate-200">
                  <tr>
                    {[
                      'S.No', 'ID', 'Job No', 'Barcode', 'Part No', 'RM Barcode', 'RM Part', 'Issued Qty', 'Created By', 'Created Date'
                    ].map(h => (
                      <th key={h} className="px-3 py-2.5 border-r border-slate-200 whitespace-nowrap">{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[12px]">
                  {/* Empty Fill */}
                  {[...Array(25)].map((_, i) => (
                    <tr key={`empty-${i}`} className="h-9 hover:bg-slate-50/50 transition-colors">
                      {[...Array(10)].map((_, j) => (
                        <td key={j} className="border-r border-slate-50 last:border-r-0"></td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Footer Branding */}
            <div className="mt-4 flex items-center justify-end opacity-20 pointer-events-none">
              <div className="flex items-center gap-1">
                <ShieldAlert size={16} />
                <span className="text-[10px] font-bold uppercase tracking-widest text-slate-600 italic">Raw Material Issue Tracking Ledger</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { 
  ChevronRight, Search, RotateCcw, Edit2, Trash2, Printer, 
  X, Download, FileSpreadsheet, FileJson, Filter, Settings 
} from 'lucide-react'
import ConfirmDialog from '../components/ConfirmDialog'
import { useToast } from '../components/Toast'

// ── Shared UI primitives (Consistent with Item Master & Receipt Entry) ──
const Label = ({ children, required }) => (
  <label className="block text-[11px] font-semibold text-slate-600 mb-1 uppercase tracking-wider whitespace-nowrap">
    {required && <span className="text-red-500 mr-0.5">*</span>}
    {children}
  </label>
)

const Input = ({ placeholder, value, onChange, type = 'text', className = "" }) => (
  <input
    type={type}
    placeholder={placeholder}
    value={value}
    onChange={onChange}
    className={`px-3 py-[7px] text-sm border border-slate-200 rounded-lg bg-white text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-[#0097A7]/25 focus:border-[#0097A7] transition-all duration-200 hover:border-slate-300 ${className}`}
  />
)

export default function ReceiptDetails() {
  const toast = useToast()
  const [fromDate, setFromDate] = useState('')
  const [toDate, setToDate] = useState('')
  const [data, setData] = useState([])
  const [filteredData, setFilteredData] = useState([])
  const [selectedId, setSelectedId] = useState(null)
  const [confirmDelete, setConfirmDelete] = useState({ open: false, id: null })

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem('velson_receipts') || '[]')
    setData(saved)
    setFilteredData(saved)
  }, [])

  const handleSearch = () => {
    const start = new Date(fromDate)
    const end = new Date(toDate)
    const result = data.filter(r => {
      const d = new Date(r.date)
      return d >= start && d <= end
    })
    setFilteredData(result)
  }

  const handleDelete = () => {
    const next = data.filter(r => r.id !== confirmDelete.id)
    setData(next)
    setFilteredData(next)
    localStorage.setItem('velson_receipts', JSON.stringify(next))
    setConfirmDelete({ open: false, id: null })
    setSelectedId(null)
  }

  const handleExport = (type) => {
    toast.info(`Exporting ${filteredData.length} records as ${type}...`)
  }

  return (
    <div className="bg-[#f4f6f8] min-h-full">
      <ConfirmDialog 
        open={confirmDelete.open} 
        onConfirm={handleDelete} 
        onCancel={() => setConfirmDelete({ open: false, id: null })} 
      />

      <div className="px-6 py-6">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-[12px] text-slate-400 mb-5">
          {/* <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Dashboard</span> */}
          {/* <ChevronRight className="w-3 h-3" /> */}
          <span className="hover:text-[#0097A7] cursor-pointer transition-colors">Account</span>
          <ChevronRight className="w-3 h-3" />
          <span className="text-[#0097A7] font-semibold">Receipt Details</span>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-4 py-2.5">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-red-700 rounded-sm" />
              <h2 className="text-[13px] font-bold text-slate-700 uppercase tracking-tight">Receipt Details</h2>
            </div>
            <div className="flex items-center gap-2">
              {[
                { label: 'Edit',      icon: <Edit2 size={14} />,   bg: 'bg-green-500', action: () => selectedId ? toast.info(`Editing ID: ${selectedId}`) : toast.warning('Select a row first') },
                { label: 'Delete',    icon: <Trash2 size={14} />,  bg: 'bg-rose-500',  action: () => selectedId ? setConfirmDelete({ open: true, id: selectedId }) : toast.warning('Select a row first') },
                { label: 'PrintData', icon: <Printer size={14} />, bg: 'bg-slate-700', action: () => toast.info('Printing data...') },
                { label: 'Close',     icon: <X size={14} />,       bg: 'bg-slate-400',  action: () => toast.info('Closing page...') },
              ].map(btn => (
                <button 
                  key={btn.label} 
                  onClick={btn.action}
                  className={`flex items-center gap-1.5 px-3 py-1.5 ${btn.bg} hover:opacity-90 text-white text-[12px] font-semibold rounded-lg transition-all shadow-sm active:scale-95`}
                >
                  {btn.icon} {btn.label}
                </button>
              ))}
            </div>
          </div>

          <div className="p-4">
            {/* Filter Bar */}
            <div className="flex items-center gap-6 mb-6 pb-4 border-b border-slate-100">
              <div className="flex items-center gap-3">
                <Label>From Date</Label>
                <Input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} />
              </div>
              <div className="flex items-center gap-3">
                <Label>To Date</Label>
                <Input type="date" value={toDate} onChange={e => setToDate(e.target.value)} />
              </div>
              <button 
                onClick={handleSearch}
                className="flex items-center gap-2 px-6 py-2 bg-[#0097A7] hover:bg-[#007a87] text-white text-[13px] font-bold rounded-lg transition-all shadow-md active:scale-95"
              >
                <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                Search
              </button>
              
              <div className="ml-auto flex items-center gap-4">
                 <button onClick={() => window.location.reload()} className="flex items-center gap-1.5 text-slate-500 hover:text-[#0097A7] text-[12px] font-semibold transition-colors">
                   <RotateCcw size={16} /> Refresh
                 </button>
                 <button onClick={() => handleExport('Excel')} className="flex items-center gap-1.5 text-slate-500 hover:text-green-600 text-[12px] font-semibold transition-colors">
                   <FileSpreadsheet size={16} /> Excel
                 </button>
              </div>
            </div>

            {/* Table Toolbar */}
            <div className="flex items-center justify-end gap-4 mb-3">
               <div className="flex items-center gap-1 bg-slate-100 px-2 py-1 rounded-md">
                 <span className="text-[11px] font-bold text-slate-500 uppercase mr-2">LS</span>
                 <input className="w-8 bg-transparent text-center text-sm font-bold border-b border-slate-300 focus:outline-none" value={filteredData.length} readOnly />
               </div>
               <div className="flex items-center gap-2 border-l border-slate-200 pl-4">
                 {[
                   { icon: <Download size={14} />, label: 'Dos' },
                   { icon: <FileSpreadsheet size={14} />, label: 'Excel' },
                   { icon: <FileJson size={14} />, label: 'Pdf' },
                   { icon: <Filter size={14} />, label: 'Filter' },
                   { icon: <Settings size={14} />, label: 'Setting' },
                 ].map(tool => (
                   <button 
                    key={tool.label} 
                    onClick={() => handleExport(tool.label)}
                    className="flex items-center gap-1 px-2 py-1 text-slate-400 hover:text-[#0097A7] transition-colors group"
                   >
                     {tool.icon}
                     <span className="text-[11px] font-bold uppercase group-hover:text-slate-600">{tool.label}</span>
                   </button>
                 ))}
               </div>
            </div>

            {/* Main Table */}
            <div className="border border-slate-200 rounded-xl overflow-hidden shadow-sm">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 text-[11px] uppercase text-slate-500 font-bold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-3 border-r border-slate-200 w-16 text-center">S.No</th>
                    {[
                      'Rec NO','DATE','TYPE','LEDGER NAME','AMOUNT','PAY MODE','BANK','CREATED_BY'
                    ].map(h => (
                      <th key={h} className="px-4 py-3 border-r border-slate-200 whitespace-nowrap">{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {filteredData.length === 0 ? (
                    <tr>
                      <td colSpan={9} className="py-20 text-center text-slate-300 italic text-sm">
                        No receipt records found for the selected period.
                      </td>
                    </tr>
                  ) : (
                    filteredData.map((row, idx) => (
                      <tr 
                        key={row.id} 
                        onClick={() => setSelectedId(row.id)}
                        className={`cursor-pointer transition-colors ${selectedId === row.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
                      >
                        <td className="px-4 py-3 border-r border-slate-200 text-center text-slate-500">{idx + 1}</td>
                        <td className="px-4 py-3 border-r border-slate-200 font-semibold text-slate-800">{row.receiptNo}</td>
                        <td className="px-4 py-3 border-r border-slate-200">{row.date}</td>
                        <td className="px-4 py-3 border-r border-slate-200 uppercase text-[11px] font-bold">{row.receiptType}</td>
                        <td className="px-4 py-3 border-r border-slate-200 font-bold text-[#0097A7]">{row.partyName}</td>
                        <td className="px-4 py-3 border-r border-slate-200 text-right font-black text-rose-600">{parseFloat(row.amount).toFixed(2)}</td>
                        <td className="px-4 py-3 border-r border-slate-200 uppercase text-[11px] font-bold text-slate-500">{row.cashBank}</td>
                        <td className="px-4 py-3 border-r border-slate-200 font-bold text-slate-600">{row.bankName || '-'}</td>
                        <td className="px-4 py-3 border-r border-slate-200 text-slate-500">Admin</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>

            {/* Bottom Status Bar */}
            <div className="mt-4 flex items-center bg-slate-50 border border-slate-200 rounded-lg p-2 text-[12px] font-bold text-slate-600">
               <div className="px-4 border-r border-slate-200 whitespace-nowrap">
                 Row : <span className="text-[#0097A7] ml-1">{filteredData.length}</span>
               </div>
               <div className="flex-1 text-center">
                 {/* Empty spaces as in image */}
               </div>
               <div className="px-8 border-l border-slate-200 whitespace-nowrap">
                 <span className="text-slate-400 mr-2 uppercase text-[10px]">Total Amount</span>
                 <span className="text-[14px] text-[#0097A7]">
                   {filteredData.reduce((acc, r) => acc + parseFloat(r.amount), 0).toFixed(2)}
                 </span>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import api from '../services/api'
import { ChevronRight, ChevronDown, Search, Save, Edit2, Trash2, X, FileSpreadsheet, ChevronUp, Plus, Loader2 } from 'lucide-react'
import { useToast } from '../components/Toast'
import ConfirmDialog from '../components/ConfirmDialog'
import { SpinnerLoader } from '../components/LocalLoader'

export default function ReferenceMaster() {
  const toast = useToast()

  // ── Reference Types (dropdown) ─────────────────────────────
  const [refTypes,      setRefTypes]      = useState([])
  const [typesLoading,  setTypesLoading]  = useState(false)

  // ── Table / form state ─────────────────────────────────────
  const [tableData,     setTableData]     = useState([])
  const [refType,       setRefType]       = useState('')
  const [code,          setCode]          = useState('')
  const [description,   setDescription]   = useState('')
  const [search,        setSearch]        = useState('')
  const [editId,        setEditId]        = useState(null)
  const [tableOpen,     setTableOpen]     = useState(true)
  const [expandedId,    setExpandedId]    = useState(null)
  const [loading,       setLoading]       = useState(false)

  // ── Dialogs ────────────────────────────────────────────────
  const [confirmDelete,  setConfirmDelete]  = useState(false)
  const [showAddType,    setShowAddType]    = useState(false)
  const [newTypeName,    setNewTypeName]    = useState('')
  const [addTypeLoading, setAddTypeLoading] = useState(false)

  // ── Fetch reference types from DB ──────────────────────────
  const fetchRefTypes = useCallback(async () => {
    setTypesLoading(true)
    try {
      const res = await api.get('/api/reference-types')
      setRefTypes(res.data.data || [])
    } catch (err) {
      console.error('[ReferenceMaster] fetchRefTypes error:', err)
      toast.error('Failed to load reference types')
    } finally {
      setTypesLoading(false)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    fetchRefTypes()
  }, [fetchRefTypes])

  // ── Fetch rows for selected type ──────────────────────────
  const fetchReferenceData = useCallback(async (type) => {
    if (!type) { setTableData([]); setCode(''); return }
    setLoading(true)
    try {
      const res = await api.get(`/api/reference-master/${encodeURIComponent(type)}`)
      setTableData(res.data.data || [])
      setCode(res.data.nextCode || '')
      setDescription('')
      setEditId(null)
      setExpandedId(null)
    } catch (err) {
      console.error('[ReferenceMaster] fetchReferenceData error:', err)
      toast.error('Failed to fetch data')
    } finally {
      setLoading(false)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    let active = true
    const run = async () => {
      if (!refType) { setTableData([]); setCode(''); return }
      setLoading(true)
      try {
        const res = await api.get(`/api/reference-master/${encodeURIComponent(refType)}`)
        if (!active) return
        setTableData(res.data.data || [])
        setCode(res.data.nextCode || '')
        setDescription('')
        setEditId(null)
        setExpandedId(null)
      } catch (err) {
        console.error('[ReferenceMaster] fetch error:', err)
        if (active) toast.error('Failed to fetch data')
      } finally {
        if (active) setLoading(false)
      }
    }
    run()
    return () => { active = false }
  }, [refType]) // eslint-disable-line react-hooks/exhaustive-deps

  const handleRefTypeChange = (val) => {
    setRefType(val)
    setSearch('')
    setEditId(null)
    setExpandedId(null)
  }

  const handleRowClick = (r) => {
    setRefType(r.referenceType)
    setCode(r.code)
    setDescription(r.description)
    setEditId(r.id)
  }

  // ── Add new Reference Type (saves to DB) ──────────────────
  const handleAddType = async () => {
    const trimmed = newTypeName.trim()
    if (!trimmed) { toast.warning('Type name is required.'); return }

    const duplicate = refTypes.find(t => t.name.toLowerCase() === trimmed.toLowerCase())
    if (duplicate) { toast.warning(`"${trimmed}" already exists.`); return }

    setAddTypeLoading(true)
    try {
      await api.post('/api/reference-types', { name: trimmed })
      await fetchRefTypes()
      handleRefTypeChange(trimmed)
      setNewTypeName('')
      setShowAddType(false)
      toast.success(`"${trimmed}" added to Reference Types.`)
    } catch (err) {
      console.error('[ReferenceMaster] addType error:', err)
      toast.error(err?.response?.data?.error || 'Failed to add reference type.')
    } finally {
      setAddTypeLoading(false)
    }
  }

  // ── Save (create / update) ────────────────────────────────
  const handleSave = async () => {
    if (!refType)          { toast.warning('Reference Type is required.'); return }
    if (!code.trim())      { toast.warning('Code is required.'); return }
    if (!description.trim()) { toast.warning('Description is required.'); return }

    setLoading(true)
    try {
      if (editId) {
        await api.put(`/api/reference-master/${editId}`, {
          referenceType: refType,
          code: code.trim(),
          description: description.trim(),
        })
        toast.success('Record updated.')
      } else {
        const existing = tableData.find(r => r.code === code.trim())
        if (existing) {
          toast.warning('Code already exists for this Reference Type.')
          setLoading(false)
          return
        }
        await api.post('/api/reference-master', {
          referenceType: refType,
          code: code.trim(),
          description: description.trim(),
        })
        toast.success('Record saved.')
      }
      await fetchReferenceData(refType)
    } catch (err) {
      console.error('[ReferenceMaster] save error:', err)
      toast.error(err?.response?.data?.error || 'Failed to save record.')
      setLoading(false)
    }
  }

  const handleEdit = () => {
    if (!editId) { toast.warning('Click a row in the table to select a record first.'); return }
    toast.info('Edit the fields above and click Save.')
  }

  const handleDelete = () => {
    if (!editId) { toast.warning('Click a row in the table to select a record first.'); return }
    setConfirmDelete(true)
  }

  const handleConfirmDelete = async () => {
    setConfirmDelete(false)
    setLoading(true)
    try {
      await api.delete(`/api/reference-master/${editId}`)
      toast.success('Record deleted.')
      await fetchReferenceData(refType)
    } catch (err) {
      console.error('[ReferenceMaster] delete error:', err)
      toast.error(err?.response?.data?.error || 'Failed to delete record.')
      setLoading(false)
    }
  }

  const handleClear = () => {
    setEditId(null)
    setSearch('')
    setExpandedId(null)
    fetchReferenceData(refType)
  }

  const toggleExpand = (id, e) => {
    e.stopPropagation()
    setExpandedId(prev => prev === id ? null : id)
  }

  const codeSort = (a, b) => {
    const na = parseInt(a.code, 10)
    const nb = parseInt(b.code, 10)
    if (!isNaN(na) && !isNaN(nb)) return na - nb
    return (a.code || '').localeCompare(b.code || '')
  }

  const displayed = (tableData || [])
    .filter(r => {
      if (!search) return true
      const q = search.toLowerCase()
      return (
        (r.code        || '').toLowerCase().includes(q) ||
        (r.description || '').toLowerCase().includes(q) ||
        (r.updatedBy   || '').toLowerCase().includes(q)
      )
    })
    .sort(codeSort)

  const selectedRecord = (tableData || []).find(r => r.id === editId)

  return (
    <div className="bg-[#f4f6f8] min-h-full pb-6">
      <div className="px-6 py-6">

        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-[12px] text-slate-400 mb-5 uppercase font-bold tracking-tight">
          {/* <span>Dashboard</span>
          <ChevronRight size={12} /> */}
          <span>Master</span>
          <ChevronRight size={12} />
          <span className="text-[#0097A7]">Reference Master</span>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">

          {/* Module Header */}
          <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-4 py-2.5">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-red-700 rounded-sm" />
              <h2 className="text-[13px] font-bold text-slate-700 uppercase tracking-tight">Reference Master</h2>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => toast.info('Exporting Excel...')}
                className="flex items-center gap-1 px-3 py-1 text-emerald-600 hover:text-emerald-700 text-[11px] font-bold border border-emerald-300 rounded transition-all"
              >
                <FileSpreadsheet size={13} /> Excel
              </button>
              <button className="flex items-center gap-1 px-3 py-1 text-slate-500 hover:text-red-600 text-[11px] font-bold border border-slate-200 rounded hover:border-red-300 transition-all">
                <X size={13} /> Close
              </button>
            </div>
          </div>

          <div className="p-4 space-y-3">

            {/* ── Form ─────────────────────────────────────────────── */}
            <table className="border-collapse text-[12px]">
              <tbody>
                {/* Reference Type */}
                <tr>
                  <td className="pb-2 pr-3 whitespace-nowrap">
                    <span className="text-red-600 font-bold mr-1">*</span>
                    <span className="text-[11px] font-bold text-slate-700">Reference Type :</span>
                  </td>
                  <td className="pb-2">
                    <div className="flex items-center gap-1.5">
                      <div className="relative">
                        <select
                          value={refType}
                          onChange={e => handleRefTypeChange(e.target.value)}
                          disabled={typesLoading}
                          className="px-2 py-[4px] text-[12px] border border-slate-300 rounded bg-white text-slate-700 focus:outline-none focus:ring-1 focus:ring-[#0097A7] w-56 disabled:opacity-60"
                        >
                          <option value="">
                            {typesLoading ? 'Loading...' : 'select option'}
                          </option>
                          {refTypes.map(o => (
                            <option key={o.id} value={o.name}>{o.name}</option>
                          ))}
                        </select>
                        {typesLoading && (
                          <Loader2
                            size={11}
                            className="animate-spin absolute right-7 top-1/2 -translate-y-1/2 text-[#0097A7] pointer-events-none"
                          />
                        )}
                      </div>
                      <button
                        onClick={() => { setNewTypeName(''); setShowAddType(true) }}
                        title="Add new reference type"
                        className="flex items-center gap-0.5 px-2 py-[4px] text-[11px] font-bold text-white bg-[#0097A7] hover:bg-[#00838f] rounded border border-[#0097A7] transition-all active:scale-95 whitespace-nowrap"
                      >
                        <Plus size={11} /> Add
                      </button>
                    </div>
                  </td>
                </tr>

                {/* Code */}
                <tr>
                  <td className="pb-2 pr-3 whitespace-nowrap">
                    <span className="text-red-600 font-bold mr-1">*</span>
                    <span className="text-[11px] font-bold text-slate-700">Code :</span>
                  </td>
                  <td className="pb-2">
                    <input
                      type="text"
                      value={code}
                      onChange={e => setCode(e.target.value)}
                      className="px-2 py-[4px] text-[12px] border border-slate-300 rounded bg-white text-slate-700 focus:outline-none focus:ring-1 focus:ring-[#0097A7] w-56"
                    />
                  </td>
                </tr>

                {/* Description */}
                <tr>
                  <td className="pr-3 whitespace-nowrap">
                    <span className="text-red-600 font-bold mr-1">*</span>
                    <span className="text-[11px] font-bold text-slate-700">Description :</span>
                  </td>
                  <td>
                    <input
                      type="text"
                      value={description}
                      onChange={e => setDescription(e.target.value)}
                      onKeyDown={e => { if (e.key === 'Enter') handleSave() }}
                      className="px-2 py-[4px] text-[12px] border border-slate-300 rounded bg-white text-slate-700 focus:outline-none focus:ring-1 focus:ring-[#0097A7] w-56"
                    />
                  </td>
                </tr>
              </tbody>
            </table>

            {/* ── Toolbar ───────────────────────────────────────────── */}
            <div className="flex items-center gap-2 bg-[#6b7a8d] px-3 py-1.5 rounded">
              <span className="text-[11px] font-bold text-white whitespace-nowrap flex items-center gap-1">
                <Search size={12} /> Search
              </span>
              <input
                type="text"
                value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="Code / Description / Updated By"
                className="px-2 py-[3px] text-[12px] border border-slate-400 rounded bg-white text-slate-700 focus:outline-none w-52"
              />
              <button
                onClick={() => toast.info(`${displayed.length} record(s) found.`)}
                className="text-white hover:text-slate-200 transition-all"
                title="Search"
              >
                <Search size={14} />
              </button>

              <div className="ml-auto flex items-center gap-1.5">
                <button
                  onClick={handleSave}
                  disabled={loading}
                  className="flex items-center gap-1 px-3 py-[4px] bg-white hover:bg-slate-100 text-slate-700 text-[11px] font-bold rounded border border-slate-300 transition-all active:scale-95 disabled:opacity-60 disabled:cursor-not-allowed"
                >
                  {loading ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />} Save
                </button>
                <button
                  onClick={handleEdit}
                  disabled={loading}
                  className="flex items-center gap-1 px-3 py-[4px] bg-white hover:bg-slate-100 text-slate-700 text-[11px] font-bold rounded border border-slate-300 transition-all active:scale-95 disabled:opacity-60 disabled:cursor-not-allowed"
                >
                  <Edit2 size={12} /> Edit
                </button>
                <button
                  onClick={handleDelete}
                  disabled={loading}
                  className="flex items-center gap-1 px-3 py-[4px] bg-white hover:bg-slate-100 text-red-600 text-[11px] font-bold rounded border border-slate-300 transition-all active:scale-95 disabled:opacity-60 disabled:cursor-not-allowed"
                >
                  <Trash2 size={12} /> Delete
                </button>
                <button
                  onClick={handleClear}
                  disabled={loading}
                  className="flex items-center gap-1 px-3 py-[4px] bg-white hover:bg-slate-100 text-amber-600 text-[11px] font-bold rounded border border-slate-300 transition-all active:scale-95 disabled:opacity-60 disabled:cursor-not-allowed"
                >
                  <X size={12} /> Clear
                </button>
                <button
                  onClick={() => setTableOpen(v => !v)}
                  className="text-white hover:text-slate-200 ml-1 transition-all"
                  title={tableOpen ? 'Collapse table' : 'Expand table'}
                >
                  <ChevronUp size={16} className={`transition-transform ${tableOpen ? '' : 'rotate-180'}`} />
                </button>
              </div>
            </div>

            {/* ── Data Grid ─────────────────────────────────────────── */}
            {tableOpen && (
              <div className="border border-slate-200 rounded-xl overflow-hidden shadow-sm">
                <div className="overflow-x-auto max-h-[420px] overflow-y-auto">
                  <table className="w-full text-left border-collapse min-w-[580px]">
                    <thead className="sticky top-0 z-10 bg-[#4472C4] text-white text-[10px] uppercase font-bold">
                      <tr>
                        <th className="px-2 py-2.5 border-r border-blue-400 w-8 text-center"></th>
                        <th className="px-3 py-2.5 border-r border-blue-400 w-24 text-center">Code</th>
                        <th className="px-3 py-2.5 border-r border-blue-400">Description</th>
                        <th className="px-3 py-2.5 w-36 text-center">Updated By</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                      {loading ? (
                        <tr>
                          <td colSpan={4} className="px-0 py-0 border-none">
                            <SpinnerLoader message="Loading..." />
                          </td>
                        </tr>
                      ) : displayed.length === 0 ? (
                        <tr>
                          <td colSpan={4} className="px-4 py-8 text-center text-[12px] text-slate-400">
                            {refType
                              ? search
                                ? `No records match "${search}".`
                                : 'No records found. Use Save to add the first entry.'
                              : 'Select a Reference Type to load data.'}
                          </td>
                        </tr>
                      ) : (
                        displayed.flatMap((r, i) => {
                          const isSelected = editId === r.id
                          const isExpanded = expandedId === r.id
                          const rowBg = isSelected
                            ? 'bg-[#1565C0] text-white'
                            : i % 2 === 0
                            ? 'bg-white hover:bg-slate-50'
                            : 'bg-slate-50/50 hover:bg-slate-100/50'

                          const rows = [
                            <tr
                              key={r.id}
                              onClick={() => handleRowClick(r)}
                              className={`h-8 cursor-pointer text-[12px] transition-colors ${rowBg}`}
                            >
                              {/* Expand arrow */}
                              <td
                                className="px-2 py-1 border-r border-slate-100 text-center"
                                onClick={e => toggleExpand(r.id, e)}
                                title={isExpanded ? 'Collapse' : 'Expand'}
                              >
                                {isExpanded
                                  ? <ChevronDown size={12} className={`mx-auto ${isSelected ? 'text-white' : 'text-slate-400'}`} />
                                  : <ChevronRight size={12} className={`mx-auto ${isSelected ? 'text-white' : 'text-slate-400'}`} />
                                }
                              </td>
                              {/* Code */}
                              <td className={`px-3 py-1 border-r border-slate-100 text-center font-bold ${isSelected ? '' : 'text-slate-600'}`}>
                                {r.code}
                              </td>
                              {/* Description */}
                              <td className={`px-3 py-1 border-r border-slate-100 truncate max-w-[320px] ${isSelected ? '' : 'text-slate-700'}`}>
                                {r.description}
                              </td>
                              {/* Updated By */}
                              <td className={`px-3 py-1 text-center font-semibold ${isSelected ? '' : 'text-[#0097A7]'}`}>
                                {r.updatedBy || 'Admin'}
                              </td>
                            </tr>
                          ]

                          if (isExpanded) {
                            rows.push(
                              <tr key={`expand-${r.id}`} className="bg-blue-50 border-b border-blue-100">
                                <td colSpan={4} className="px-6 py-2 text-[11px] text-slate-500">
                                  <div className="flex flex-wrap gap-x-6 gap-y-1">
                                    <span><span className="font-bold text-slate-600">ID:</span> {r.id}</span>
                                    <span><span className="font-bold text-slate-600">Type:</span> {r.referenceType}</span>
                                    {r.createdAt && (
                                      <span>
                                        <span className="font-bold text-slate-600">Created:</span>{' '}
                                        {new Date(r.createdAt).toLocaleString()}
                                      </span>
                                    )}
                                    {r.updatedAt && (
                                      <span>
                                        <span className="font-bold text-slate-600">Last Updated:</span>{' '}
                                        {new Date(r.updatedAt).toLocaleString()}
                                      </span>
                                    )}
                                  </div>
                                </td>
                              </tr>
                            )
                          }

                          return rows
                        })
                      )}
                    </tbody>
                  </table>
                </div>

                {/* Footer */}
                <div className="border-t border-slate-200 bg-slate-50 px-3 py-1.5 text-[11px] font-bold text-slate-500 flex items-center gap-4">
                  <span>Row : {displayed.length}</span>
                  {editId && selectedRecord && (
                    <span className="text-[#0097A7]">
                      ● Selected: [{selectedRecord.code}] {selectedRecord.description}
                    </span>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ── Add Reference Type Modal ─────────────────────────────── */}
      {showAddType && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/30"
          onClick={e => { if (e.target === e.currentTarget && !addTypeLoading) setShowAddType(false) }}
        >
          <div className="bg-white rounded-xl shadow-xl border border-slate-200 w-80 overflow-hidden">
            <div className="flex items-center justify-between bg-[#0097A7] px-4 py-2.5">
              <div className="flex items-center gap-2">
                <Plus size={13} className="text-white" />
                <span className="text-[12px] font-bold text-white uppercase tracking-tight">Add Reference Type</span>
              </div>
              <button
                onClick={() => { if (!addTypeLoading) setShowAddType(false) }}
                disabled={addTypeLoading}
                className="text-white/80 hover:text-white transition-all disabled:opacity-50"
              >
                <X size={14} />
              </button>
            </div>
            <div className="p-4 space-y-3">
              <div>
                <label className="text-[11px] font-bold text-slate-600 block mb-1">
                  <span className="text-red-600 mr-1">*</span>Type Name
                </label>
                <input
                  type="text"
                  value={newTypeName}
                  onChange={e => setNewTypeName(e.target.value)}
                  onKeyDown={e => {
                    if (e.key === 'Enter' && !addTypeLoading) handleAddType()
                    if (e.key === 'Escape' && !addTypeLoading) setShowAddType(false)
                  }}
                  autoFocus
                  disabled={addTypeLoading}
                  placeholder="e.g. Payment_Mode"
                  className="w-full px-2 py-[5px] text-[12px] border border-slate-300 rounded bg-white text-slate-700 focus:outline-none focus:ring-1 focus:ring-[#0097A7] disabled:opacity-60"
                />
              </div>
              <div className="flex justify-end gap-2 pt-1">
                <button
                  onClick={() => setShowAddType(false)}
                  disabled={addTypeLoading}
                  className="px-3 py-[5px] text-[11px] font-bold text-slate-600 border border-slate-300 rounded hover:bg-slate-50 transition-all disabled:opacity-50"
                >
                  Cancel
                </button>
                <button
                  onClick={handleAddType}
                  disabled={addTypeLoading}
                  className="flex items-center gap-1 px-3 py-[5px] text-[11px] font-bold text-white bg-[#0097A7] hover:bg-[#00838f] rounded transition-all active:scale-95 disabled:opacity-60 disabled:cursor-not-allowed"
                >
                  {addTypeLoading
                    ? <><Loader2 size={11} className="animate-spin" /> Saving...</>
                    : <><Plus size={11} /> Create</>
                  }
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── Delete Confirmation ──────────────────────────────────── */}
      <ConfirmDialog
        open={confirmDelete}
        title="Confirm Delete"
        message={
          selectedRecord
            ? `Delete record [${selectedRecord.code}] "${selectedRecord.description}"? This action cannot be undone.`
            : 'Are you sure you want to delete this record? This action cannot be undone.'
        }
        onConfirm={handleConfirmDelete}
        onCancel={() => setConfirmDelete(false)}
      />
    </div>
  )
}

import { useState, useEffect } from 'react'
import * as XLSX from 'xlsx'
import { jsPDF } from 'jspdf'
import {
  ChevronRight, X, Trash2, Edit, Search, Printer, List, Download, FileSpreadsheet, Filter, Settings
} from 'lucide-react'
import { useToast } from '../components/Toast'
import api from '../services/api'


// ── Ultra-compact, premium UI primitives ──
const Label = ({ children, required }) => (
  <label className="inline-flex items-center text-[12.5px] font-bold text-slate-600 uppercase tracking-wider whitespace-nowrap">
    {required && <span className="text-red-500 font-bold mr-1">*</span>}
    {children}
  </label>
)

const Input = ({ placeholder, value, onChange, type = 'text', readOnly = false, className = "" }) => (
  <input
    type={type}
    placeholder={placeholder}
    value={value}
    onChange={onChange}
    readOnly={readOnly}
    className={`w-full px-2.5 py-1 text-[13px] h-[32px] border border-slate-300 rounded bg-white text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] transition-all duration-150 ${readOnly ? 'bg-slate-50 cursor-not-allowed text-slate-500 font-bold' : 'hover:border-slate-400'} ${className}`}
  />
)

const Select = ({ options, placeholder, value, onChange, className = "" }) => (
  <div className={`relative w-full ${className}`}>
    <select
      value={value}
      onChange={onChange}
      className="w-full px-2.5 py-1 pr-6 text-[13px] h-[32px] border border-slate-300 rounded bg-white text-slate-700 appearance-none focus:outline-none focus:ring-1 focus:ring-[#0097A7] focus:border-[#0097A7] transition-all duration-150 hover:border-slate-400 cursor-pointer"
    >
      <option value="">{placeholder}</option>
      {options.map(o => <option key={o} value={o}>{o}</option>)}
    </select>
    <div className="pointer-events-none absolute inset-y-0 right-1.5 flex items-center">
      <svg className="w-3 h-3 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
      </svg>
    </div>
  </div>
)

