                  )}
                  {errors.modelName && <p className="text-[11px] text-red-500 mt-0.5">{errors.modelName}</p>}
                </div>
              </div>
              <div className="flex items-center gap-2">
                <label className={`${lbl} w-36 shrink-0`}>Model Sub Type :</label>
                {loadingRefData ? (
