        return (
          <div key={pm.id} className="relative flex gap-4 items-start group">
            {/* Timeline connector line */}
            {idx < processes.length - 1 && (
              <div
                className={`absolute left-[15px] top-8 bottom-0 w-[2px] -mb-4 z-0 ${status === 'completed'
                    ? 'bg-emerald-250'
                    : status === 'qc'
